INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(63141, 'ptBR', 'A Aliança venceu!', '', 19865),
(63142, 'ptBR', 'O quê? Você não tá conseguindo ver a luta?', '', 19865),
(63143, 'ptBR', 'A Horda venceu!', '', 19865),
(63144, 'ptBR', 'Não, dá pra ver direitinho!', '', 19865),
(63145, 'ptBR', 'Esse grupo é horrível!', '', 19865),
(63146, 'ptBR', 'Terrível!', '', 19865),
(63147, 'ptBR', 'Que nojo!', '', 19865),
(63148, 'ptBR', 'Encontro você aqui amanhã?', '', 19865),
(63149, 'ptBR', 'Sem dúvida!', '', 19865),
(63150, 'ptBR', 'Ô idiota, você tá dormindo no meio da luta?', '', 19865),
(63151, 'ptBR', 'Idiota, eu? Você que tá vendo a luta!', '', 19865),
(63152, 'ptBR', 'Finalmente! Vi um grupo bom!', '', 19865),
(63153, 'ptBR', 'A batalha pela Bacia Arathi está prestes a começar.', '', 19865),
(63154, 'ptBR', 'A batalha começou!', '', 19865),
(63155, 'ptBR', 'Então a gente pode parar de vir aqui?', '', 19865),
(63156, 'ptBR', 'Você acha que toda essa luta tá sendo educativa pra esse grupo?', '', 19865),
(63157, 'ptBR', 'Claro, assim eles vão começar a ler livros!', '', 19865),
(63158, 'ptBR', 'A Aliança capturou a bandeira!', '', 19865),
(63159, 'ptBR', 'A Horda capturou a bandeira!', '', 19865),
(63160, 'ptBR', 'Pode pagar, eles passaram pelos cervejantes!', '', 19865),
(63161, 'ptBR', 'O dobro ou nada no próximo grupo?', '', 19865),
(63162, 'ptBR', 'A Aliança está perto da vitória!', '', 19865),
(63163, 'ptBR', 'Gostei desse último grupo!', '', 19865),
(63164, 'ptBR', 'E o que eles têm pra se gostar?', '', 19865),
(63165, 'ptBR', 'A Horda está perto da vitória!', '', 19865),
(63166, 'ptBR', 'Achei que fosse o último grupo!', '', 19865),
(63167, 'ptBR', 'Acho que vou precisar de mais um drinque!', '', 19865),
(63168, 'ptBR', 'Por que você diz isso?', '', 19865),
(63169, 'ptBR', 'A Aliança venceu!', '', 19865),
(63170, 'ptBR', 'Tô começando a gostar desses caras!', '', 19865),
(63171, 'ptBR', 'A Horda venceu!', '', 19865),
(63172, 'ptBR', 'Vocês acham que dá pra voltar à vida, após a morte?', '', 19865),
(63173, 'ptBR', 'Claro! Aquele grupo ressuscitou umas trinta vezes!', '', 19865),
(63174, 'ptBR', 'Bem, vejo você aqui amanhã!', '', 19865),
(63175, 'ptBR', 'A não ser que eu dê sorte e apague!', '', 19865),
(63176, 'ptBR', 'O que que você tá fazendo aqui? V-vá embora!', '', 19865),
(63177, 'ptBR', 'Sabe o que é o melhor deste grupo?', '', 19865),
(63178, 'ptBR', 'O quê?', '', 19865),
(63179, 'ptBR', 'Eles abriram os portões, então podemos fugir!', '', 19865),
(63180, 'ptBR', 'Sempre que eu acho um grupo péssimo, uma coisa ótima acontece!', '', 19865),
(63181, 'ptBR', 'Que coisa?', '', 19865),
(63182, 'ptBR', 'A batalha pelo Templo de Kotmogu está prestes a começar.', '', 19865),
(63183, 'ptBR', 'Eles saem!', '', 19865),
(63184, 'ptBR', 'Ahhh, esse grupo me leva longe.', '', 19865),
(63185, 'ptBR', 'Se você ainda tá vendo, não foi longe o suficiente!', '', 19865),
(63186, 'ptBR', 'A batalha começou!', '', 19865),
(63187, 'ptBR', 'Esses caras não são tão ruins.', '', 19865),
(63188, 'ptBR', 'A Aliança está perto da vitória!', '', 19865),
(63189, 'ptBR', 'Também não são tão bons.', '', 19865),
(63190, 'ptBR', 'A Horda está perto da vitória!', '', 19865),
(63192, 'ptBR', 'A Aliança venceu!', '', 19865),
(63193, 'ptBR', 'A Horda venceu!', '', 19865),
(63194, 'ptBR', 'Desculpa!', '', 19865),
(63195, 'ptBR', 'É culpa sua que isso aconteceu!', '', 19865),
(63196, 'ptBR', 'AFASTEM-SE!', '', 19865),
(63197, 'ptBR', 'Fiquem longe de mim!', '', 19865),
(63198, 'ptBR', 'Vou me esconder até vocês irem embora!', '', 19865),
(63199, 'ptBR', 'Eu não quero mais ver vocês!', '', 19865),
(63200, 'ptBR', 'A batalha pela Bacia Arathi está prestes a começar.', '', 19865),
(63201, 'ptBR', 'A Aliança está perto da vitória!', '', 19865),
(63202, 'ptBR', 'A Aliança venceu!', '', 19865),
(63203, 'ptBR', 'A batalha começou!', '', 19865),
(63204, 'ptBR', 'A Horda capturou a bandeira!', '', 19865),
(63205, 'ptBR', 'A Horda está perto da vitória!', '', 19865),
(63206, 'ptBR', 'A Horda venceu!', '', 19865),
(63207, 'ptBR', 'Acho que esse grupo vai melhorar com a idade!', '', 19865),
(63208, 'ptBR', 'Eles vão ter mais experiência?', '', 19865),
(63209, 'ptBR', 'Não, a minha vista vai estar pior!', '', 19865),
(63210, 'ptBR', 'É... Esse curador parece que é bom em tudo!', '', 19865),
(63211, 'ptBR', 'Só não é bom em escolher grupos!', '', 19865),
(63212, 'ptBR', 'Tem alguma coisa errada com esses hozens que acabamos de ver!', '', 19865),
(63213, 'ptBR', 'A batalha pela Bacia Arathi está prestes a começar.', '', 19865),
(63214, 'ptBR', 'Por quê?', '', 19865),
(63215, 'ptBR', 'A batalha pela Bacia Arathi está prestes a começar.', '', 19865),
(63216, 'ptBR', 'A Aliança está perto da vitória!', '', 19865),
(63217, 'ptBR', 'Porque esses caras sobreviveram a eles!', '', 19865),
(63218, 'ptBR', 'Sabe de uma coisa? Eu invejo esses caras.', '', 19865),
(63219, 'ptBR', 'A Aliança está perto da vitória!', '', 19865),
(63220, 'ptBR', 'Por quê?', '', 19865),
(63221, 'ptBR', 'Porque eles estão sempre junto daquela “anja” da cura gostosona!', '', 19865),
(63222, 'ptBR', 'Esses caras têm muita dificuldade pra arranjar armadura!', '', 19865),
(63223, 'ptBR', 'Por quê?', '', 19865),
(63224, 'ptBR', 'Ninguém nunca tira a roupa perto deles!', '', 19865),
(63225, 'ptBR', 'A Aliança venceu!', '', 19865),
(63226, 'ptBR', 'Esses caras são Aliança ou Horda?', '', 19865),
(63227, 'ptBR', 'E isso importa?', '', 19865),
(63228, 'ptBR', 'A Aliança está perto da vitória!', '', 19865),
(63229, 'ptBR', 'Quero saber pra que lado vou parar de torcer!', '', 19865),
(63230, 'ptBR', 'Eu acho... Eu acho que aquela druidesa tá de olho em mim! Em você não, meu filho, em mim. Compreendeu?', '', 19865),
(63231, 'ptBR', 'A batalha começou!', '', 19865),
(63232, 'ptBR', 'Aquela sacerdotisa acertou meu coração, meu filho!', '', 19865),
(63233, 'ptBR', 'A batalha começou!', '', 19865),
(63234, 'ptBR', 'A Horda está perto da vitória!', '', 19865),
(63235, 'ptBR', 'A Horda está perto da vitória!', '', 19865),
(63236, 'ptBR', 'Por que aquele mago não usou uma arma com mais intelecto?', '', 19865),
(63237, 'ptBR', 'A Horda venceu!', '', 19865),
(63238, 'ptBR', 'Porque ele não queria que ela fosse mais esperta que ele!', '', 19865),
(63239, 'ptBR', 'A Horda venceu!', '', 19865),
(63240, 'ptBR', 'De quantos forasteiros se precisa pra pintar uma muralha?', '', 19865),
(63241, 'ptBR', 'Não sei, quantos?', '', 19865),
(63242, 'ptBR', 'Depende de quão forte você tacar eles!', '', 19865),
(63243, 'ptBR', 'Você acha que aqueles mortos-vivos passaram inteiros?', '', 19865),
(63244, 'ptBR', 'Não, eles não tinham estômago pra isso!', '', 19865),
(63245, 'ptBR', 'Aquele paladino me ofereceu salvação eterna!', '', 19865),
(63246, 'ptBR', 'E o que você respondeu?', '', 19865),
(63247, 'ptBR', 'Bênção dos Reis, por favor.', '', 19865),
(63248, 'ptBR', 'Aquele xamã sabia mesmo qual era o lugar dele!', '', 19865),
(63249, 'ptBR', 'E que lugar seria esse?', '', 19865),
(63250, 'ptBR', 'Terralém!', '', 19865),
(63251, 'ptBR', 'Sabe o que é uma piada?', '', 19865),
(63252, 'ptBR', 'O quê?', '', 19865),
(63253, 'ptBR', 'As armas desse cara!', '', 19865),
(63254, 'ptBR', 'Estou escutando alguma coisa...', '', 19865),
(63255, 'ptBR', 'Detenham-nos!', '', 19865),
(63256, 'ptBR', 'Que desperdício...', '', 19865),
(63257, 'ptBR', 'Vasculhem o cadáver!', '', 19865),
(63258, 'ptBR', 'Matem todos!', '', 19865),
(63259, 'ptBR', 'Tudo será queimado. Ninguém pode saber da vergonha da Cruzada Escarlate!', '', 19865),
(63260, 'ptBR', 'Você também virará cinzas!', '', 19865),
(63261, 'ptBR', 'Minha fogueira... Extinta...', '', 19865),
(63262, 'ptBR', 'Queima! QUEIMA!', '', 19865),
(63263, 'ptBR', 'Morra pelo fogo!', '', 19865),
(63264, 'ptBR', 'Sopro do Dragão!', '', 19865),
(63265, 'ptBR', 'Minha agonia infinita será sua, também!', '', 19865),
(63266, 'ptBR', 'Temos fome de vingança.', '', 19865),
(63267, 'ptBR', 'Seria este... o fim, afinal...?', '', 19865),
(63268, 'ptBR', 'Mais... Mais almas!', '', 19865),
(63269, 'ptBR', 'Busquem um receptáculo... e voltem!', '', 19865),
(63270, 'ptBR', 'Tomem um corpo, e executem uma vingança terrível!', '', 19865),
(63271, 'ptBR', 'Os mortos furiosos... Não descansam!', '', 19865),
(63272, 'ptBR', 'Não... as águas... Eu devo... resistir... Não posso... temer...', '', 19865),
(63273, 'ptBR', 'Seu lugar não é aqui! As águas devem ser protegidas... Eu os expulsarei ou irei matar vocês!', '', 19865),
(63274, 'ptBR', 'Proteger... as águas...', '', 19865),
(63275, 'ptBR', 'Eu agradeço, forasteiros. Eu fui libertado.', '', 19865),
(63276, 'ptBR', 'Morra nas trevas.', '', 19865),
(63277, 'ptBR', 'A noite cerca você...', '', 19865),
(63278, 'ptBR', 'Eu lhe asseguro que $p é $go melhor lutador:a melhor lutadora; que eu já vi. $gEle:ela; ajudará a preparar sua aldeia.', '', 19865),
(63279, 'ptBR', 'Não...!', '', 19865),
(63280, 'ptBR', 'Me perdoe!', '', 19865),
(63281, 'ptBR', 'Pra começar, os aldeões precisam de descanso. Nós podemos lhe oferecer proteção por tempo suficiente para lhes permitir repouso.', '', 19865),
(63282, 'ptBR', '$p também pode ensinar aos aldeões como se defender.', '', 19865),
(63283, 'ptBR', 'Tudo o que nós pedimos é ajuda para procurar o Profeta Khar''zul. Você conhece as ilhas próximas melhor do que nós. Seu conhecimento seria inestimável.', '', 19865),
(63284, 'ptBR', 'Medo... assolador!', '', 19865),
(63285, 'ptBR', 'Fuja deste lugar... ou morra!', '', 19865),
(63286, 'ptBR', 'Promessas, promessas! Não há nada que o senhor possa fazer para nos salvar. Os Zandalari são impiedosos!', '', 19865),
(63287, 'ptBR', 'Mesmo se pudéssemos nos defender, eles nos superam em número! Não há maneira de vencermos!', '', 19865),
(63288, 'ptBR', 'O dia se torna noite...', '', 19865),
(63289, 'ptBR', 'As trevas se adensam...', '', 19865),
(63290, 'ptBR', 'A luz fenece...', '', 19865),
(63291, 'ptBR', 'A noite... se torna dia!', '', 19865),
(63292, 'ptBR', 'A luz do sol... resplandece...', '', 19865),
(63293, 'ptBR', 'Uma vez mais... a aurora...', '', 19865),
(63294, 'ptBR', '', 'Você é sempre tão negativo, Hou!', 19865),
(63295, 'ptBR', '', 'Isso pode não ser verdade, Hou. O Andarilho das Lendas parece confiante. O que sua proteção irá nos custar?', 19865),
(63296, 'ptBR', '', 'Muito bem. Se o senhor nos ajudar a expulsar os Zandalari, nós ajudaremos você a encontrar o Profeta.', 19865),
(63297, 'ptBR', 'Vou acabar com você.', '', 19865),
(63298, 'ptBR', 'Sou invencível. Venço todos os homens.', '', 19865),
(63299, 'ptBR', 'Minhas mãos estão rubras... com seu sangue!', '', 19865),
(63300, 'ptBR', 'Se morrer, morreu.', '', 19865),
(63301, 'ptBR', 'Nada se compara à minha espada!', '', 19865),
(63302, 'ptBR', 'Técnica perfeita!', '', 19865),
(63303, 'ptBR', 'Mas... minha lenda!', '', 19865),
(63304, 'ptBR', 'A minha lenda começa AGORA!', '', 19865),
(63305, 'ptBR', 'E pensar que vocês chegaram até aqui, só para morrer. Honrarei vocês com mortes rápidas.', '', 19865),
(63306, 'ptBR', 'Suas luzes se apagarão. As trevas vão cercar você. E você temerá as sombras que se movem nelas.', '', 19865),
(63307, 'ptBR', 'Você saberá o que é o medo!', '', 19865),
(63308, 'ptBR', 'Afoguem-se em terror!', '', 19865),
(63309, 'ptBR', 'Fuujam!', '', 19865),
(63310, 'ptBR', 'Encolham-se de terror!', '', 19865),
(63311, 'ptBR', 'Você acha que é fácil assim conquistar seus medos?', '', 19865),
(63312, 'ptBR', 'O pavor se levanta! Ele busca a luz. Ele tem fome.', '', 19865),
(63313, 'ptBR', '', 'O que o senhor planeja fazer para nos salvar, Andarilho das Lendas?', 19865),
(63314, 'ptBR', 'Pela glória de Gurthan!', '', 19865),
(63315, 'ptBR', 'Este é o poder dos Harthak!', '', 19865),
(63316, 'ptBR', 'Por Kargesh!', '', 19865),
(63317, 'ptBR', 'É hora de morrer!', '', 19865),
(63318, 'ptBR', 'OH HO HO! Essa doeu, hein, mané?', '', 19865),
(63319, 'ptBR', 'AI! Eh-heheheh.', '', 19865),
(63320, 'ptBR', 'Os espíritos sejam louvados!', '', 19865),
(63321, 'ptBR', 'O medo nubla minha mente. Eu... não posso resistir.', '', 19865),
(63322, 'ptBR', 'Você enfrenta seu medo. Um momento... de paz.', '', 19865),
(63323, 'ptBR', 'Trouxe bombas suficientes... para todos vocês!', '', 19865),
(63324, 'ptBR', 'Busque abrigo enquanto destruo vocês como comanda o Sha!', '', 19865),
(63325, 'ptBR', 'Eu... me estourei...', '', 19865),
(63326, 'ptBR', 'O poder é forte demais. Me força a destruir vocês.', '', 19865),
(63327, 'ptBR', 'Você enfrenta seu medo. Um momento... de paz.', '', 19865),
(63328, 'ptBR', 'Busque abrigo enquanto destruo vocês como comanda o Sha!', '', 19865),
(63329, 'ptBR', 'Sou uma brasa, mantídeo!', '', 19865),
(63330, 'ptBR', 'Você cabum!', '', 19865),
(63331, 'ptBR', 'Ninguém pode suportar o medo. Você perecerá.', '', 19865),
(63332, 'ptBR', 'Busque abrigo enquanto destruo vocês como comanda o Sha!', '', 19865),
(63333, 'ptBR', 'Você enfrenta seu medo. Um momento... de paz.', '', 19865),
(63334, 'ptBR', 'Não hesite em nada, pois eu não vou hesitar!', '', 19865),
(63335, 'ptBR', 'Você precisa treinar mais!', '', 19865),
(63336, 'ptBR', 'Você precisa trabalhar sua técnica!', '', 19865),
(63337, 'ptBR', 'Não serei enjaulado de novo. Os Shado-pans não puderam me deter. Nem você o fará!', '', 19865),
(63338, 'ptBR', 'Enquanto a violência habitar seus corações... Eu... voltarei...', '', 19865),
(63339, 'ptBR', 'Outra morte violenta...', '', 19865),
(63340, 'ptBR', 'O Sha do Ódio fugiu do meu corpo... e do monastério. Sou grato a vocês, forasteiros. Os shado-pans estão em dívida com vocês. Agora, temos muito trabalho a fazer...', '', 19865),
(63341, 'ptBR', 'Taran Zhu e os Shado-pans são MEUS. Avance e morra pela minha mão, como todos os que se opuserem a mim nos dias vindouros!', '', 19865),
(63342, 'ptBR', 'O ódio consumirá e conquistará tudo!', '', 19865),
(63343, 'ptBR', 'Não... NÃO!', '', 19865),
(63344, 'ptBR', 'Sinta raiva por sua derrota.', '', 19865),
(63345, 'ptBR', 'Alimente-me com seu ódio!', '', 19865),
(63346, 'ptBR', 'Já que vocês não vieram para aprender, serão usados para ensinar uma lição.', '', 19865),
(63347, 'ptBR', 'Eu farei o que Pa''valak não fez!', '', 19865),
(63348, 'ptBR', 'Você pode ter chegado até aqui. Você pode ter escavado um caminho através do meu exército, mas eu... eu vou matar você, e construirei a ponte.', '', 19865),
(63349, 'ptBR', 'A... ponte...', '', 19865),
(63350, 'ptBR', 'Sai da minha frente.', '', 19865),
(63351, 'ptBR', 'Voltem ao trabalho! Eu quero essa ponte pronta ao amanhecer!', '', 19865),
(63352, 'ptBR', 'Gritos e latidos ecoam pelo salão.', '', 19865),
(63353, 'ptBR', 'Vasculhe a ilha e procure cerveja para jogar no caldeirão de Bô, mas deixe alguém perto para proteger Bô!', '', 19865),
(63354, 'ptBR', 'Fede com eles, Fedo!', '', 19865),
(63355, 'ptBR', 'Galeros$go:a; fedegou o Fedo?', '', 19865),
(63356, 'ptBR', 'Galeros$go:a; vai ficá bagaraiad$go:a;!', '', 19865),
(63357, 'ptBR', 'Fede com eles!', '', 19865),
(63358, 'ptBR', 'AHHHHH!', '', 19865),
(63359, 'ptBR', 'Galeros$go:a; é grande bagarai$gdor:dora; de hozen!', '', 19865),
(63360, 'ptBR', 'Olá, viajante! Você está impressionado com os hozens. Ouso dizer que eles estão começando a ter medo de você.', '', 19865),
(63361, 'ptBR', 'Ora vejam só – um troll de verdade! Você é bem como as histórias contavam. E deu uma bela lição nos hozens.', '', 19865),
(63362, 'ptBR', '%s está com raiva!!', '', 19865),
(63363, 'ptBR', 'Você deve ser um dos que saiaram daquela nave que caiu dos céus. Tenho MUITAS perguntas para você, mas aqui não é lugar para conversar.', '', 19865),
(63364, 'ptBR', 'Por favor, me encontre na Gruta das Palavras, no alto do morro, quando você puder conversar!', '', 19865),
(63365, 'ptBR', '<Pinte algo sexy.>', '<Pinte algo sexy.>', 19865),
(63366, 'ptBR', '<Pinte algo abstrato.>', '<Pinte algo abstrato.>', 19865),
(63367, 'ptBR', '<Pinte algo heroico.>', '<Pinte algo heroico.>', 19865),
(63368, 'ptBR', 'Ah! Arrá! Consegui ver pelo que sua Aliança luta.', '', 19865),
(63369, 'ptBR', 'Eu prefiro ir atrás de coisas mais graúdas, é claro, mas, pelo jeito, o seu povo e o meu não são tão diferentes assim.', '', 19865),
(63370, 'ptBR', 'O que temos aqui? Grandes massas vermelhas e azuis colidindo com violência sobre um campo verde.', '', 19865),
(63371, 'ptBR', 'O que isso significa? Vejo muito conflito em seu coração.', '', 19865),
(63372, 'ptBR', 'Entendo. Um dos grandes guerreiros da sua Aliança, não é? Você escolheu um leão como insígnia.', '', 19865),
(63373, 'ptBR', 'Seu povo é forte e feroz. Mas lembre-se, o leão só mata quando tem fome.', '', 19865),
(63374, 'ptBR', 'Aqui estão eles, isso, isso. Viu como é fácil fazer amigos aqui?', '', 19865),
(63375, 'ptBR', 'Lembre-se de que, em Pandária, nem todos os aliados precisam ser conquistados na base da espada.', '', 19865),
(63376, 'ptBR', 'Bem... meus pássaros gostaram de você. Vou seguir a orientação deles.', '', 19865),
(63377, 'ptBR', 'Receba minhas boas-vindas! Como posso ajudar?', '', 19865),
(63378, 'ptBR', 'Você chegou tarde demais! O Rei Trovão vai se erguer e tomar essa terra de vocês!', '', 19865),
(63379, 'ptBR', 'Para onde foram levados os restos do Rei Trovão?', 'Para onde foram levados os restos do Rei Trovão?', 19865),
(63380, 'ptBR', '$p! Você nos salvou! Nós iremos para algum lugar seguro.', '$p! Você nos salvou! Nós iremos para algum lugar seguro.', 19865),
(63381, 'ptBR', 'Os yaungóis são tão poderosos... talvez precisemos da proteção do seu povo.', 'Os yaungóis são tão poderosos... talvez precisemos da proteção do seu povo.', 19865),
(63382, 'ptBR', 'Meu lar... será que ainda existe? Eu vou voltar e descobrir!', 'Meu lar... será que ainda existe? Eu vou voltar e descobrir!', 19865),
(63383, 'ptBR', 'Eu... eu vi minha vida passar diante dos meus olhos!', 'Eu... eu vi minha vida passar diante dos meus olhos!', 19865),
(63384, 'ptBR', '$gUm forasteiro:Uma forasteira;... me salvou?', '$gUm forasteiro:Uma forasteira;... me salvou?', 19865),
(63385, 'ptBR', 'Eu... estou vivo? Eu estou vivo! Estou vivo!', 'Eu... estou viva? Eu estou viva! Estou viva!', 19865),
(63386, 'ptBR', 'A sua serpente não irá além do Arboreto. Volte para o Arboreto agora mesmo!', 'A sua serpente não irá além do Arboreto. Volte para o Arboreto agora mesmo!', 19865),
(63387, 'ptBR', 'Como nos encontraram? Preparem as armas. Temos que sair deste desfiladeiro!', '', 19865),
(63388, 'ptBR', 'Pela imperatriz!', '', 19865),
(63389, 'ptBR', 'Niuzao cairá!', '', 19865),
(63390, 'ptBR', 'O templo será nosso!', '', 19865),
(63391, 'ptBR', 'Você é tol$go:a; em se opor à imperatriz!', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(63392, 'ptBR', 'Toda Pandária se ajoelhará perante a imperatriz!', '', 19865),
(63393, 'ptBR', 'Você está se aventurando fora da área de treinamento! Volte para o Arboreto ou ao Mar das Agulhas de Jade antes que seja arremessad$go:a; da montaria!', 'Você está se aventurando fora da área de treinamento! Volte para o Arboreto ou ao Mar das Agulhas de Jade antes que seja arremessad$go:a; da montaria!', 19865),
(63394, 'ptBR', 'O Vizir Imperial Zor''lok inala Feromônios do Zelo', '', 19865),
(63395, 'ptBR', 'Vocês estão prontos para exibir suas habilidades marciais aqui, diante do Olho do Tigre?', '', 19865),
(63396, 'ptBR', 'Prontos pra próxima luta? Acertem o gongo e QUEBREM! O! PAU!', '', 19865),
(63397, 'ptBR', 'Fogo!', '', 19865),
(63398, 'ptBR', 'Pela imperatriz!', '', 19865),
(63399, 'ptBR', 'Destruam o templo!', '', 19865),
(63400, 'ptBR', 'Mostre a eles a força dela!', '', 19865),
(63401, 'ptBR', '$GUm fededor:Uma fededora; de hozen! Corre!', '', 19865),
(63402, 'ptBR', 'Corre! É $Go fedido fededor:a fedida fededora; de hozen!', '', 19865),
(63403, 'ptBR', 'Você não pode voltar agora.$B$BAinda estão lutando lá dentro.', '', 19865),
(63404, 'ptBR', 'A luta acabou.$B$BQuer voltar pra dentro agora?', '', 19865),
(63405, 'ptBR', 'Entrar na arena.', 'Entrar na arena.', 19865),
(63406, 'ptBR', 'FEDO FEDIDO FEDORENTO!', '', 19865),
(63407, 'ptBR', 'Obrigado, meus netos.', '', 19865),
(63408, 'ptBR', 'Obrigado, $r.', 'Obrigada, $r.', 19865),
(63409, 'ptBR', 'Minha mente está livre. Obrigado, $r!', 'Minha mente está livre. Obrigada, $r!', 19865),
(63410, 'ptBR', 'Você não nos destruirá, sha!', 'Você não nos destruirá, sha!', 19865),
(63411, 'ptBR', 'Fora, lacaios da dúvida!', 'Fora, lacaios da dúvida!', 19865),
(63412, 'ptBR', 'Nós vamos dissipá-los desta terra!', 'Nós vamos dissipá-los desta terra!', 19865),
(63413, 'ptBR', 'É bom ver $gum:uma; $c do nosso lado!', 'É bom ver $gum:uma; $c do nosso lado!', 19865),
(63414, 'ptBR', 'Rechace-os!', 'Rechace-os!', 19865),
(63415, 'ptBR', 'Retorne à terra!', 'Retorne à terra!', 19865),
(63416, 'ptBR', '', 'Você quer fazer parte da tripulação do Molúria? Então vai ter que começar de baixo como todo mundo.', 19865),
(63417, 'ptBR', 'Amante de jinyus!', '', 19865),
(63418, 'ptBR', 'Essasss armasss. Preciso delas!', '', 19865),
(63419, 'ptBR', 'Rendam-ssse!', '', 19865),
(63420, 'ptBR', 'Que armadura faissscante. Me dá ela aqui!', '', 19865),
(63421, 'ptBR', 'Saaaangue...', '', 19865),
(63422, 'ptBR', 'Renda-se, sangue quente!', '', 19865),
(63423, 'ptBR', 'Suas armas são fracas!', '', 19865),
(63424, 'ptBR', 'A Bomba de Barril está ficando instável!', '', 19865),
(63425, 'ptBR', '|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t Garalon se eleva no ar e prepara |cFFFF0000|Hspell:128555|h[Massive Crush]|h|r!', '|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t Garalon se eleva no ar e prepara |cFFFF0000|Hspell:128555|h[Massive Crush]|h|r!', 19865),
(63426, 'ptBR', '[PH - finja que tem um vídeo fantabuloso aqui.]CABUM! Você explodiu um monte de yaungóis! Olha só, eles estão fugindo!', '', 19865),
(63427, 'ptBR', '[PH]Lin está perseguindo eles. Oh, não! Lin!', '', 19865),
(63428, 'ptBR', '[PH]Um chefão yaungol selvagem aparece (de detrás do portão) e ruge para você. Prepare-se para lutar com o chefão!', '', 19865),
(63429, 'ptBR', 'Você se importa? Estamos tentando tirar uma foto aqui.', '', 19865),
(63430, 'ptBR', 'Mal posso esperar pra mandar essa foto pra minha namorada em casa. Ela vai pirar!', '', 19865),
(63431, 'ptBR', 'Vejamos aqui...$B$B”Como calcular o f-stop certo. O valor-f é a distância focal dividida pelo diâmetro ''efetivo'' da abertura do diafragma."$B$BMinha cabeça tá doendo.', 'Vejamos aqui...$B$B”Como calcular o f-stop certo. O valor-f é a distância focal dividida pelo diâmetro ''efetivo'' da abertura do diafragma."$B$BMinha cabeça tá doendo.', 19865),
(63432, 'ptBR', 'Graças à pequena fortuna que fizemos na temporada passada eu pude encomendar esta câmera invocada!', 'Graças à pequena fortuna que fizemos na temporada passada eu pude encomendar esta câmera invocada!', 19865),
(63433, 'ptBR', 'Eu ando me focando em fotografia agora, sabe.', 'Eu ando me focando em fotografia agora, sabe.', 19865),
(63434, 'ptBR', 'Dá pra se apressar? Meus braços estão ficando cansados!', 'Dá pra se apressar? Meus braços estão ficando cansados!', 19865),
(63435, 'ptBR', 'Tira logo essa foto!', 'Tira logo essa foto!', 19865),
(63436, 'ptBR', 'Espere um segundo! Não dá pra apressar a arte!', 'Espere um segundo! Não dá pra apressar a arte!', 19865),
(63437, 'ptBR', '“...focalizar na distância hiperfocal garante nitidez máxima de metade desta distância até o infinito..."', '“...focalizar na distância hiperfocal garante nitidez máxima de metade desta distância até o infinito..."', 19865),
(63438, 'ptBR', 'Ei, qual será a "distância hiperfocal" agora, na sua opinião?', 'Ei, qual será a "distância hiperfocal" agora, na sua opinião?', 19865),
(63439, 'ptBR', 'Estou pronto para partir. Vamos!', 'Estou pronta para partir. Vamos!', 19865),
(63440, 'ptBR', 'Recarregar!', '', 19865),
(63441, 'ptBR', '', 'Cavaleiros se aproximam!', 19865),
(63442, 'ptBR', 'Quem é aquela pessoa?', 'Quem é aquela pessoa?', 19865),
(63443, 'ptBR', 'Minha nossa, o que é aquela coisa?', 'Minha nossa, o que é aquela coisa?', 19865),
(63444, 'ptBR', 'Eu nunca vi uma coisa dessas antes.', 'Eu nunca vi uma coisa dessas antes.', 19865),
(63445, 'ptBR', 'Você está aqui para ver a Serpente de Jade?', 'Você está aqui para ver a Serpente de Jade?', 19865),
(63446, 'ptBR', 'Uau... tantas armas.', 'Uau... tantas armas.', 19865),
(63447, 'ptBR', 'Aquilo é algum tipo de grômulo?', 'Aquilo é algum tipo de grômulo?', 19865),
(63448, 'ptBR', 'Isso... Isso é um troll? Como nas histórias?', 'Isso... Isso é um troll? Como nas histórias?', 19865),
(63449, 'ptBR', 'Que roupas esquisitas você tem.', 'Que roupas esquisitas você tem.', 19865),
(63450, 'ptBR', 'Você parece... diferente.', 'Você parece... diferente.', 19865),
(63451, 'ptBR', 'Que roupas esquisitas você tem.', 'Que roupas esquisitas você tem.', 19865),
(63452, 'ptBR', 'Você é de Kun-Lai?', 'Você é de Kun-Lai?', 19865),
(63453, 'ptBR', 'Você veio da tartaruga?', 'Você veio da tartaruga?', 19865),
(63454, 'ptBR', 'Quem é aquela pessoa?', 'Quem é aquela pessoa?', 19865),
(63455, 'ptBR', 'De quantas armas você precisa?', 'De quantas armas você precisa?', 19865),
(63456, 'ptBR', 'Apresse-se, $p! Use os barris para derrotar as monstruosidades!', '', 19865),
(63457, 'ptBR', 'Certo, vamos ao monastério.', 'Certo, vamos ao monastério.', 19865),
(63458, 'ptBR', 'O que ele está fazendo ali?', 'O que ele está fazendo ali?', 19865),
(63459, 'ptBR', 'Não ligue pros dois idiotas lá fora. Eles andam empolgados com uma modinha chamada "tubaronagem".$B$BAposto que eles vão ter vergonha dessas fotos daqui a alguns meses.', '', 19865),
(63460, 'ptBR', 'Isso vai ser muito épico!', '', 19865),
(63461, 'ptBR', 'Você veio na hora certa, Arauto do Despertar. Os Adjuntos teriam me destruído enquanto eu dormia.', '', 19865),
(63462, 'ptBR', 'Mesmo em meus sonhos, eu ouvia os pensamentos malignos deles... DELA.', '', 19865),
(63463, 'ptBR', 'Você pode usar o tubarão num segundo, só espere a sua vez!', '', 19865),
(63464, 'ptBR', 'Podemos usar o balão. Sigam-me!', '', 19865),
(63465, 'ptBR', 'A Imperatriz teme a própria ruína, mas o medo que ela sente a condenará. Ela já está além dos limites da sanidade.', '', 19865),
(63466, 'ptBR', 'Há muitos crimes do império a serem punidos. Não temos tempo a perder, Arauto do Despertar. Encontre-me lá fora.', '', 19865),
(63467, 'ptBR', 'Agradeça os seus anciãos. Nós não iremos desapontar você.', '', 19865),
(63468, 'ptBR', 'Você tem cara de quem pode nos dar algum lucro.$B$BQue tal uma lutinha na Arena da Aniquilação, $gamigo:amiga;?', '', 19865),
(63469, 'ptBR', 'Arranquem a carne dos ossos deles!', '', 19865),
(63470, 'ptBR', 'Não deixem nada para trás!', '', 19865),
(63471, 'ptBR', 'Façam com que temam os Zandalari!', '', 19865),
(63472, 'ptBR', 'Comam eles, minhas feras!', '', 19865),
(63473, 'ptBR', 'Será que os invasores vão parar algum dia?', 'Será que os invasores vão parar algum dia?', 19865),
(63474, 'ptBR', 'A crueldade deles não parece ter fim.', 'A crueldade deles não parece ter fim.', 19865),
(63475, 'ptBR', 'Eu me sinto como se estivesse aqui há dias...', 'Eu me sinto como se estivesse aqui há dias...', 19865),
(63476, 'ptBR', 'Eu vou morrer antes de ver a aldeia ser tomada!', 'Eu vou morrer antes de ver a aldeia ser tomada!', 19865),
(63477, 'ptBR', 'Eu vim substituir você. Vá descansar com sua família.', 'Você está exausta. Vá descansar e prepare-se para a batalha vindoura.', 19865),
(63478, 'ptBR', 'Eu vou morrer antes de ver a aldeia ser tomada!', '', 19865),
(63479, 'ptBR', 'Eu me sinto como se estivesse aqui há dias...', '', 19865),
(63480, 'ptBR', 'A crueldade deles não parece ter fim.', 'A crueldade deles não parece ter fim.', 19865),
(63481, 'ptBR', 'Olá, $r. O Andarilho das Lendas Cho me contou tuuuuuuuuuuuuudo sobre você. Ou pelo menos as coisas mais importantes. O pessoal por aqui pode ser um pouco pé atrás com você, então é melhor você conhecer o lado bom deles primeiro.', '', 19865),
(63482, 'ptBR', 'Outr$go:a; $gestranho:estranha;? O seu tipo gosta de uma boa cerveja? Se sim, experimente uma Reserva Áurea Cevada!', '', 19865),
(63483, 'ptBR', 'Então, estranh$go:a;, você é do tipo louco e selvagem que nem os hozens?$b$bOu é $gquieto e pensativo:quieta e pensativa; como os jinyus?', 'Então, estranh$go:a;, você é do tipo louco e selvagem que nem os hozens?$b$bOu é $gquieto e pensativo:quieta e pensativa; como os jinyus?', 19865),
(63484, 'ptBR', 'Você veio de além da muralha?', 'Você veio de além da muralha?', 19865),
(63485, 'ptBR', 'De onde você veio?', 'De onde você veio?', 19865),
(63486, 'ptBR', 'Uau. Você parece... hum... bem... diferente do que eu esperava. Existem mais como você?', 'Uau. Você parece... hum... bem... diferente do que eu esperava. Existem mais como você?', 19865),
(63487, 'ptBR', 'Que cores interessantes você esta vestindo. Você que teceu o que está usando?', 'Que cores interessantes você esta vestindo. Você que teceu o que está usando?', 19865),
(63488, 'ptBR', 'Existem mais como você?', 'Existem mais como você?', 19865),
(63489, 'ptBR', 'Opa, olá, estranh$go:a;. Você parece uma criatura com histórias para contar.', 'Opa, olá, estranh$go:a;. Você parece uma criatura com histórias para contar.', 19865),
(63490, 'ptBR', 'Que queixo interessante você tem. E uma coloração... De onde você veio?', 'Que queixo interessante você tem. E uma coloração... De onde você veio?', 19865),
(63491, 'ptBR', 'Humm. Que armadura...', '', 19865),
(63492, 'ptBR', '$gUm estranho:Uma estranha;? Ora, vejam só. Eu me pergunto de onde veio.', '$gUm estranho:Uma estranha;? Ora, vejam só. Eu me pergunto de onde veio.', 19865),
(63493, 'ptBR', 'Que criatura estranha e curiosa. Você veio até a minha cidade com boas intenções?', '', 19865),
(63494, 'ptBR', 'Outr$go:a; estranh$go:a;? E tão... estranh$go:a;.', '', 19865),
(63495, 'ptBR', 'Aquela pobre criatura. Tão magra... deve estar faminta.', '', 19865),
(63496, 'ptBR', 'É $go:a; tal estranh$go:a; que Cho comentou. Me pergunto se existem mais del$ge:a;.', '', 19865),
(63497, 'ptBR', 'Boas-vindas, estranh$go:a;. Tinha muito tempo que não via alguém viajar por aqui.', '', 19865),
(63498, 'ptBR', 'Eu imagino de onde você veio... De algum lugar onde faltam bebidas de qualidade? Hum?', '', 19865),
(63499, 'ptBR', 'Que traje esquisito que você está vestindo.', '', 19865),
(63500, 'ptBR', 'U$gm:ma; estranh$go:a;? Aqui? Não começa nenhuma confusão na nossa cidade.', '', 19865),
(63501, 'ptBR', 'Você veio da Tartaruga?', 'Você veio da Tartaruga?', 19865),
(63502, 'ptBR', 'A sua família é grande?', 'A sua família é grande?', 19865),
(63503, 'ptBR', 'Você já viu alguma vez a muralha a oeste daqui?', 'Você já viu alguma vez a muralha a oeste daqui?', 19865),
(63504, 'ptBR', 'Você é $gum:uma; guerreir$go:a;? Pode me ensinar a lutar?', 'Aposto que meu pai acaba com você. Ele é o maior monge que já existiu.', 19865),
(63505, 'ptBR', 'Por que você é tão magricela?', 'Por que você é tão magricela?', 19865),
(63506, 'ptBR', 'Sua roupa é engraçada.', 'Sua roupa é engraçada.', 19865),
(63507, 'ptBR', 'Quem raspou todo o seu pelo?', 'Quem raspou todo o seu pelo?', 19865),
(63508, 'ptBR', 'Você é um grômulo? Cadê sua mochila?', 'Você é um grômulo? Cadê sua mochila?', 19865),
(63509, 'ptBR', 'Você é $gum:uma; yaungol? Ouvi dizer que os yaungóis são malvados.', 'Você é $gum:uma; yaungol? Ouvi dizer que os yaungóis são malvados.', 19865),
(63510, 'ptBR', 'Por que você é tão rosa e sem pelo?', 'Por que você é tão rosa e sem pelo?', 19865),
(63511, 'ptBR', 'Você tem orelhas molengas!', 'Por que suas orelhas estão balançando?', 19865),
(63512, 'ptBR', 'Você tem orelhas molengas!', 'Por que suas orelhas estão balançando?', 19865),
(63513, 'ptBR', 'Parece que você tá com raiva. O tempo todo.', 'Parece que você tá com raiva. O tempo todo.', 19865),
(63514, 'ptBR', 'Que que aconteceu com a sua mochila, grômulo?', 'Você tá verde. Tá doente?', 19865),
(63515, 'ptBR', 'Você é $Gum:uma; mogu?', 'Você anda que nem $gum:uma; mogu!', 19865),
(63516, 'ptBR', 'Você é $gum:uma; $gtroll:trolesa;? Ouvi dizer que os trolls são malignos.', 'Você é $gum:uma; $gtroll:trolesa;? Como nos livros de histórias?', 19865),
(63517, 'ptBR', '', 'Vou na frente. Vejo vocês do outro lado... Espero.', 19865),
(63518, 'ptBR', '|TInterface\\Icons\\ability_warlock_everlastingaffliction.blp:20|t%s é afetado por |cFFFF0000|Hspell:123011|h[Aterrorizar]|h|r! Remova o feitiço de %s!', '', 19865),
(63519, 'ptBR', 'Hah! O que diz você ao mestre espadachim, Tenwu da Fumaça Vermelha?', '', 19865),
(63520, 'ptBR', '', 'Então, vamos andando?', 19865),
(63521, 'ptBR', 'O dia está bom para uma caçada.', '', 19865),
(63522, 'ptBR', 'O Senhor das Lâminas Ta''yak marca $n para um |cFFFF0000|Hspell:122949|h[Golpe Oculto]|h|r!', '', 19865),
(63523, 'ptBR', 'Será que a agonia um dia para?', '', 19865),
(63524, 'ptBR', 'No que que esse mundo está se tornando! Não dá mais nem pra morrer quieto, os caranguejos não deixam!', '', 19865),
(63525, 'ptBR', 'Eu ainda não morri, seu bicho carniceiro!', '', 19865),
(63526, 'ptBR', 'Que adequado. O pescador comido pelos peixes...', '', 19865),
(63527, 'ptBR', 'Oi!', 'Oi!', 19865),
(63528, 'ptBR', '$gO estranho:A estranha; tá aqui!', '$gO estranho:A estranha; tá aqui!', 19865),
(63529, 'ptBR', 'Eu vi primeiro!', 'Eu vi primeiro!', 19865),
(63530, 'ptBR', 'Você é um duende barbudo?', 'Você é $Gum:uma; duende?', 19865),
(63531, 'ptBR', 'Sou quase do seu tamanho!', 'Sou quase do seu tamanho!', 19865),
(63532, 'ptBR', 'Agradeço. Se importaria se eu acompanhasse você para me vingar?', 'Agradeço. Se importaria se eu acompanhasse você para me vingar?', 19865),
(63533, 'ptBR', 'UAU! Eu sou maior que você!', 'UAU! Eu sou maior que você!', 19865),
(63534, 'ptBR', 'Tem outros grômulos vindo?', 'Tem outros grômulos vindo?', 19865),
(63535, 'ptBR', 'Cho disse que você é "rumano". É tipo um hozen?', 'Cho disse que você é "rumano". É tipo um hozen?', 19865),
(63536, 'ptBR', 'Por que você é tão magricela?', 'Por que você é tão magricela?', 19865),
(63537, 'ptBR', 'Por que você é tão verde?', 'Por que você é tão verde?', 19865),
(63538, 'ptBR', 'Por que você faz tantos barulhos furiosos?', 'Por que você faz tantos barulhos furiosos?', 19865),
(63539, 'ptBR', 'Andem com esses suprimentos!', '', 19865),
(63540, 'ptBR', 'Camarada, esta é a Flor da Manhã! O coração da vida pandarênica aqui na Floresta de Jade. Se você quer causar uma boa impressão, tenho certeza de que muitos destes cidadãos estão precisando de alguma ajuda.', '', 19865),
(63541, 'ptBR', 'Agora preciso ir embora. Toya está coletando jade para meu experimento. Quando ele terminar eu gostaria que você as trouxesse para mim no Agouro do Imperador para que possamos averiguar que segredos a história escondeu de nós.', '', 19865),
(63542, 'ptBR', 'Chegou na hora certa. Eu já estou de saída. Mas fique e aproveite a cidade enquanto Toya recolhe o jade que precisamos.', '', 19865),
(63543, 'ptBR', 'Até mais tarde!', 'Até mais tarde!', 19865),
(63544, 'ptBR', 'Tchau!', 'Tchau!', 19865),
(63545, 'ptBR', 'Vou brincar.', 'Vou brincar.', 19865),
(63546, 'ptBR', 'Cuidado com o escorpião, ele pode parecer amigável mas ele é uma fera em batalha!', 'Cuidado com o escorpião, ele pode parecer amigável mas ele é uma fera em batalha!', 19865),
(63547, 'ptBR', 'Você está de olho no meu gato?', 'Você está de olho no meu gato?', 19865),
(63548, 'ptBR', 'Olá, camarada $gpescador:pescadora;! Você já está aqui há muito tempo? Eu e meu amigão "Gancho Grande" aqui viajamos por toda parte procurando o próximo peixe!$b$bNós chegamos aqui por acidente e os nativos foram bem liberais com seus suprimentos e bebidas... por isso decidimos ficar por um tempo!', '', 19865),
(63549, 'ptBR', 'Está trabalhando para os pescadores? Olha só essas recompensas!', '', 19865),
(63550, 'ptBR', 'O Palácio Mogu''shan, uma masmorra de nível 87-89 no Vale das Flores Eternas, está disponível para testes. Espere até seu grupo estar completo para então se teleportar para esta masmorra. Pedras de Encontro ainda não estão disponíveis para esta masmorra.\n\nPara deixar o Palácio Mogu''shan, simplesmente atravesse a saída normal de dentro da masmorra e você será $gteleportado:teleportada; para Dalaran. Se você morrer e libertar seu espírito, você se teleportará a partir desse PNJ.', '', 19865),
(63551, 'ptBR', '%s ativa suas armadilhas de |cFFFF0404|Hspell:119311|h[Corrente de Lâminas]|h|r!', '', 19865),
(63552, 'ptBR', 'Estou no meu grupo e pronto para me teleportar para o Palácio Mogu''shan!', 'Estou no meu grupo e pronta para me teleportar para o Palácio Mogu''shan!', 19865),
(63553, 'ptBR', 'Leve-me de volta ao Palácio Mogu''shan!', 'Leve-me de volta ao Palácio Mogu''shan!', 19865),
(63554, 'ptBR', '%s ativa sua armadilha de |cFFFF0404|Hspell:120142|h[Besta]|h|r!', '', 19865),
(63555, 'ptBR', '%s ativa sua armadilha de |cFFFF0404|Hspell:119374|h[Machado Redemoinho]|h|r!', '', 19865),
(63556, 'ptBR', 'Nós nos ergueremos novamente!', '', 19865),
(63557, 'ptBR', 'Por favor, leve-me ao Terraço de Gurthan.', 'Por favor, leve-me ao Terraço de Gurthan.', 19865),
(63558, 'ptBR', 'Informações sobre suas viagens chegaram até mim. Você veleja nos ventos da mudança.', '', 19865),
(63559, 'ptBR', 'Estou curioso: na sua terra natal alguma vez houve paz?', '', 19865),
(63560, 'ptBR', 'E o que está achando da nossa terra? Você está aprendendo?', '', 19865),
(63561, 'ptBR', 'A arte do Soco Pelo ao Vento foi passada de geração a geração na minha família, desde os dias negros.$b$bDizem que o primeiro uso do soco foi durante os dias negros do império mogu, e ajudou os pandarens a conquistarem a liberdade.', '', 19865),
(63562, 'ptBR', 'A sua visita é como uma rajada de vento antes da tempestade.', '', 19865),
(63563, 'ptBR', 'Me disseram que você foi $gum convidado:uma convidada; dos hozens da floreste e sobreviveu. Suspeito que veremos coisas interessantes de você nos próximos dias.$b$bEu saúdo você, viajante, em nossa humilde casa.', '', 19865),
(63564, 'ptBR', 'É melhor o vento soprando do que ele preso... entendeu? Fiz uma piada.', '', 19865),
(63565, 'ptBR', 'Então você é a criatura que deu aos jinyus a coragem necessária para se manterem firmes contra os hozens.$b$bTal coragem é uma coisa que não vemos há algum tempo. Eu saúdo você em nossa humilde casa.', '', 19865),
(63566, 'ptBR', 'Você lutou bem hoje, $p. Que você honre o seu título.', '', 19865),
(63567, 'ptBR', '%s lança |cFFFF0000|Hspell:107140|h[Mortalha Magnética]|h|r.  Reúnam-se para liberar a energia curativa!', '', 19865),
(63568, 'ptBR', 'Então... você é $go estranho:a estranha; de quem Cho estava falando.$b$bBem-vind$go:a; a Flor da Manhã. Sou Peiji Áurea Cevada, e minha família faz as melhores cervejas de Pandária.$b$bDiferente dos Lúpulo Errante, que continuam se esgueirando por aí e acabando com o nome dos cervejeiros. Eu acho que até vi o mais novo de olho na minha filha. Isso não pode acontecer! Os Áurea Cevada e os Lúpulo Errante não se misturam.', '', 19865),
(63569, 'ptBR', 'Vou continuar procurando jade. Você poderia perguntar por aí e ver se alguém pode ajudar.', '', 19865),
(63570, 'ptBR', 'Hozen só dar nome nome a bom fedido.$b$bDe repente um dia te chamem de $n $n.', '', 19865),
(63571, 'ptBR', 'Nós estamos condenados!', '', 19865),
(63572, 'ptBR', 'Apressem-se, anciãos! Escondam-se!', '', 19865),
(63573, 'ptBR', 'Eu juro que vi a jovem Syra Áurea Cevada dando umas "olhadas" para o meu menino. Não posso aceitar isso.', '', 19865),
(63574, 'ptBR', 'Que bom que você está aqui! Jogue fora essa vara de pescar e nos ajude!', 'Que bom que você está aqui! Jogue fora essa vara de pescar e nos ajude!', 19865),
(63575, 'ptBR', 'Kovok parece ter suportado bem os anos de hibernação.', '', 19865),
(63576, 'ptBR', 'Indo para Kun-Lai? Entre no barco e lhe darei uma carona.', '', 19865),
(63577, 'ptBR', 'Vejo que você é $gum:uma; camarada $gpescador:pescadora;! Eu tenho bastante equipamento dos pescadores aqui, me avise se precisar de algo!', '', 19865),
(63578, 'ptBR', 'Minha pesquisa precisa continuar.', '', 19865),
(63579, 'ptBR', 'Não, não, não! Eu não posso parar agora. Minhas mutações precisam viver!', '', 19865),
(63580, 'ptBR', 'Eu cobri suas mãos com um preparado especial, Arauto do Despertar. Sempre que você derrotar um inimigo, o cadáver será infectado com uma toxina especial. Observe os resultados e use isto a seu favor.', '', 19865),
(63581, 'ptBR', 'Todas as criaturas têm uma finalidade, Arauto do Despertar, mas é preciso matá-las para descobrir qual seja!', '', 19865),
(63582, 'ptBR', 'Que o âmbar proteja e nutra você, Arauto do Despertar.', '', 19865),
(63583, 'ptBR', 'Que minha força seja a sua força. Você roubará um pouco da vida dos seus oponentes a cada golpe seu que causar dano.', '', 19865),
(63584, 'ptBR', 'Eu cobri suas armas com um soro especial. Injete-o em seus inimigos. Injeções demais farão com que os sistemas deles se sobrecarreguem.', '', 19865),
(63585, 'ptBR', 'Venha, Arauto. Vamos encontrar nossos inimigos.', '', 19865),
(63586, 'ptBR', 'Quantos anos se passaram desde que comecei a dormir? Esta vess, o palácio, minha Imperatriz. Tudo mudou.', '', 19865),
(63587, 'ptBR', 'Essa praga branca é obra do sha? Agora eu vejo que doença se espalha por nossa civilização. Os infectados devem ser expurgados!', '', 19865),
(63588, 'ptBR', 'Apenas olhe para os mantídeos lá embaixo. A Imperatriz deu a ordem de ataque cedo demais! Outro sinal de suas delírios caóticos.', '', 19865),
(63589, 'ptBR', 'Por que eles já estão se preparando para o ataque? A hora ainda não chegou.', '', 19865),
(63590, 'ptBR', 'Viajar pelas estradas do vale é estranho. O terreno é tão plano e é tão quente por aqui...$b$bSinto saudades de Kun-Lai.', '', 19865),
(63591, 'ptBR', 'Alguma coisa os impele. Eles estão com medo.', '', 19865),
(63592, 'ptBR', 'Não importa. Até eu posso sentir a maldade que nubla suas mentes. Vamos dar um fim a essa loucura.', '', 19865),
(63593, 'ptBR', 'Eu vejo que meu sono foi breve. Eu reconheço Mel''jarak, senhor dos céus. Outrora meu irmão. Agora, já não mais.', '', 19865),
(63594, 'ptBR', 'Eu vejo que meu sono foi breve. Eu reconheço Ta''yak ali em frente ao palácio. O campeão das lâminas da Imperatriz. Na minha época, ele era invicto.', '', 19865),
(63595, 'ptBR', 'Eu vejo que meu sono foi breve. Eu reconheço Un''sok ali embaixo. Vejo que ele agora se chama Talha-âmbar. Ha! A perícia dele nunca ultrapassou a minha.', '', 19865),
(63596, 'ptBR', 'Eu vejo que meu sono foi breve. Eu reconheço Zor''lok, a voz da Imperatriz. Seu cachorrinho obediente.', '', 19865),
(63597, 'ptBR', 'Estou pronta para voar, Xaril.', 'Estou pronta para voar, Xaril.', 19865),
(63598, 'ptBR', 'Consertar o dano causado por Kor''ik levará tempo, mas pode ser feito.', '', 19865),
(63599, 'ptBR', 'Você ouve leves cliques vindos do oeste...', '', 19865),
(63600, 'ptBR', 'Um barulho alto de passos emanar ao longe...', '', 19865),
(63601, 'ptBR', 'A gema se estilhaça!', '', 19865),
(63603, 'ptBR', 'Você vê um fraco cintilar ao longo da parede leste...', '', 19865),
(63604, 'ptBR', 'Onde posso encontrar o Assistente Buzaki?', 'Onde posso encontrar o Assistente Buzaki?', 19865),
(63605, 'ptBR', 'Algo mais que eu possa fazer?', 'Algo mais que eu possa fazer?', 19865),
(63606, 'ptBR', 'Galeritos galerados!', '', 19865),
(63607, 'ptBR', 'Fedentino FEDORENTO!', '', 19865),
(63608, 'ptBR', 'Fedeu, fedorento!', '', 19865),
(63609, 'ptBR', 'O ingrediente final, um segredo passado de geração em geração na minha família, vem lá da Selva de Krasarang. Eu enviei o Assistente Buzaki para coletá-lo pra mim há alguns dias. Eu soube que ele chegou à Taberna nas Nuvens noite passada. Você pode ir pela Passagem Antiga e ver o que está atrasando ele? É melhor que ele não esteja dormindo na taberna!', '', 19865),
(63610, 'ptBR', 'Ânimo, companheiros!', '', 19865),
(63611, 'ptBR', 'Tem Horda para matar, rapazes! Posso sentir o cheiro deles!', '', 19865),
(63612, 'ptBR', 'É vencer ou morrer, galera! Não tem volta!', '', 19865),
(63613, 'ptBR', 'Meia-dúzia de macacos não são páreos para a Aliança!', '', 19865),
(63614, 'ptBR', 'Para trás, selvagens! Reivindico esta terra em nome da Aliança!', '', 19865),
(63615, 'ptBR', 'Aguente, homens! Reforços estão a caminho!', '', 19865),
(63616, 'ptBR', 'Fedeu, galer-', '', 19865),
(63617, 'ptBR', 'Conceda-me sua ajuda, Malik. [Aprimoramento Klaxxi]', 'Conceda-me sua ajuda, Malik. [Aprimoramento Klaxxi]', 19865),
(63618, 'ptBR', 'O truque, Arauto, é ser como a água. Não resista à força do inimigo, simplesmente flua junto com ela. Deixe que os golpes dele resvalem por você. Então VOCÊ O EMPALA.', '', 19865),
(63619, 'ptBR', 'Precisa de um tambor?', '', 19865),
(63620, 'ptBR', 'Me envie para Flor da Manhã.', 'Me envie para Flor da Manhã.', 19865),
(63621, 'ptBR', 'Obrigado, $p! Pensei que era o meu fim.', '', 19865),
(63622, 'ptBR', 'Eu entrei em pânico quando vi todos aqueles sauroks e encalhei o barco.', '', 19865),
(63623, 'ptBR', 'Preciso levar isso ao Mestre Cervejeiro Buf antes que o festival comece. Obrigado de novo por me salvar, $p!', '', 19865),
(63624, 'ptBR', 'Ah! Ótimo! Você conseguiu. É hora de ensinar a esses "piratas" hozens a não saquear nossas aldeias.', '', 19865),
(63625, 'ptBR', 'Você tem certeza de que está tudo pronto pra sair?', 'Você tem certeza de que está tudo pronto pra sair?', 19865),
(63626, 'ptBR', 'O âmbar oferece descanso a um paragão, Arauto. Se você ficar estiver à beira da morte, ele se ativará sozinho.', '', 19865),
(63627, 'ptBR', 'Não tenha piedade! Renove-se com o cheiro de sangue! Quanto mais você atacar, mas vida você ganhará.', '', 19865),
(63628, 'ptBR', '', 'Parece que ele está apenas inconsciente. Eu acho que consigo acordá-lo.', 19865),
(63629, 'ptBR', '', 'Vamos voltar ao festival, $p. Passe lá em casa mais tarde, estou preparando algo especial!', 19865),
(63630, 'ptBR', '', 'Mestre-cervejeiro! Grupos de batedores Bataari foram vistos perto da aldeia!', 19865),
(63631, 'ptBR', 'Ei, aqueles ali são... EI! Você os trouxe de volta!', '', 19865),
(63632, 'ptBR', 'Você me salvou! Que $gherói:heroína;!', 'Você me salvou! Que $gherói:heroína;!', 19865),
(63633, 'ptBR', 'Eu sempre soube que $gum:uma; $pc podia bater num yaungol!', 'Eu sempre soube que $gum:uma; $pc podia bater num yaungol!', 19865),
(63634, 'ptBR', 'De... de onde você veio? Obrigado!', 'De... de onde você veio? Obrigada!', 19865),
(63635, 'ptBR', '', 'O ar é tão puro aqui.', 19865),
(63636, 'ptBR', '', 'Cresci na Ilha Errante. O espaço lá é muito limitado. Não tem lugar para caçar e não tem predadores de verdade para tal.$b$bMas aqui... aqui temos grandes mushans e lobos e todo tipo de predador. É o sonho de um caçador se tornando realidade.', 19865),
(63637, 'ptBR', '', 'Primeira vez em Pandária? Pra mim também. Lembro de histórias que me contavam sobre esse lugar. Tão legais!', 19865),
(63638, 'ptBR', '', 'Conheci os Rosarães na Selva do Espinhaço. Tenho encontrado com eles de vez em quando aqui e ali. Finalmente conquistei meu lugar nesse safári!', 19865),
(63639, 'ptBR', '', 'Oh! Eu acho que reconheço você. Você é da Ilha Errante, não é?$b$bNão é estranho estar em Pandária?$b$bSempre pensei que esse lugar não passava de uma lenda. Não consigo acreditar que isto realmente existe!', 19865),
(63640, 'ptBR', '', 'Há tanta vida aqui. E tanto espaço.$b$bLá na Ilha Errante, nunca havia espaço para que os predadores crescessem o suficiente para caçar.', 19865),
(63641, 'ptBR', '', 'Ah, ótimo! Você encontrou o safári. Aquela selva é um pouco difícil de atravessar sem um pouco de senso de direção.$b$bEsses mogus continuam no caminho da minha caça.', 19865),
(63642, 'ptBR', '|Tinterface/Icons/creatureportrait_bubble.blp:20|t%s lança |cFFFF0000|Hspell:124653|h[Casco d''Água]|h|r! Use os Jorros d''Água para estourar!', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(63643, 'ptBR', 'Um caçador caça. Um artista faz arte.$b$bEstou aqui para capturar a ferocidade da caça através da minha arte.$b$bEstamos em terras estranhas, e há poucos no nosso mundo que estejam familiarizados com essas criaturas estranhas que caçamos.$b$BAtravés da minha arte, provarei o seu sucesso e o sucesso dos Rosarães.', '', 19865),
(63644, 'ptBR', '', 'Beba, $p. Quero ver esse frasco vazio antes de você mergulhar um dedo no mar.', 19865),
(63645, 'ptBR', '', 'Pronto. Tem gosto de alga marinha e lixo quente, não é?', 19865),
(63646, 'ptBR', '', '$gBem-vindo:Bem-vinda; à Taverna do Vento Norte.', 19865),
(63647, 'ptBR', '', 'Saudações, a$gamigo:amiga;! Você quer um quarto para pernoitar?', 19865),
(63648, 'ptBR', 'Você pode me ajudar a ir pra água, Tart?', 'Você pode me ajudar a ir pra água, Tart?', 19865),
(63649, 'ptBR', 'Eu nunca pensei que teria de pegar em armas novamente...', '', 19865),
(63650, 'ptBR', 'Eu quase consegui me convencer da tolice de que Zouchin estava protegida das trevas do mundo.', '', 19865),
(63651, 'ptBR', 'Eu me aposentei das batalhas para viver em paz com a minha família. Parece que as batalhas não vão deixar que eu me aposente assim tão fácil.', '', 19865),
(63652, 'ptBR', 'Eu já fui um grande guerreiro. Espero que a idade avançada não tenha afetado demais a minha perícia.', '', 19865),
(63653, 'ptBR', 'Preparar essa aldeia não significa apenas colocar armas nãos mãos das pessoas. Precisamos ensiná-las a usar as armas com confiança.', '', 19865),
(63654, 'ptBR', '', 'Obrigada de novo, $p! Eu darei isto ao Mestre Cervejeiro Buf agora mesmo.', 19865),
(63655, 'ptBR', 'Anduin... corra...', '', 19865),
(63656, 'ptBR', '', 'Nos encontramos novamente, forasteir$go:a; de além das brumas.', 19865),
(63657, 'ptBR', '', 'Esta batalha custou bastante caro. Meu próprio renascimento irá levar vários anos.', 19865),
(63658, 'ptBR', '', 'Aprenda com isso, forasteiro.', 19865),
(63659, 'ptBR', '', 'Eu não sei por que as brumas se abriram. Mas eu sei que há um motivo.', 19865),
(63660, 'ptBR', '', 'Está claro que você não veio para trazer sua guerra a estas terras. Há uma escuridão escondida aqui em Pandária - você viu isso por conta própria!', 19865),
(63661, 'ptBR', '', 'Mas tenho certeza de que as brumas se abriram por um motivo. VOCÊ é esse motivo. Encontre o seu propósito aqui.', 19865),
(63662, 'ptBR', '', 'Você pode aprender muito sobre esta terra no Vale dos Quatro Ventos.', 19865),
(63663, 'ptBR', '', 'Temos um outro visitante do outro lado das brumas aqui. "Chen Malte do Trovão" é o seu nome. Ele é um pandaren, mas de origem diferente.', 19865),
(63664, 'ptBR', '', 'Caminhe com Chen. Faça amigos entre o povo daqui. Com o tempo você encontrará suas respostas.', 19865),
(63665, 'ptBR', '', 'Adeus, forasteiro. Da próxima vez que nos virmos, espero poder chamar você de "camarada".', 19865),
(63666, 'ptBR', 'Use os canhões! Derrube os mantídeos!', '', 19865),
(63667, 'ptBR', '<O sinalizador zumbe suavemente.>', '', 19865),
(63668, 'ptBR', '', 'Socorro!', 19865),
(63669, 'ptBR', '', 'Eles vão me devorar!', 19865),
(63670, 'ptBR', '', 'Tire eles de perto de mim!', 19865),
(63671, 'ptBR', '', 'Eu sou jovem demais para morrer!', 19865),
(63672, 'ptBR', '', 'Eu não sou comida!', 19865),
(63673, 'ptBR', '', 'Alguém me salve!', 19865),
(63674, 'ptBR', '', 'Socorro! Socorro!', 19865),
(63675, 'ptBR', '', 'Ahhhh!', 19865),
(63676, 'ptBR', 'Eu preciso de outro tubarão!', 'Eu preciso de outro tubarão!', 19865),
(63677, 'ptBR', 'Você quer capturar um tubarão?', 'Você quer capturar um tubarão?', 19865),
(63678, 'ptBR', '', 'Obrigado, $p! Eles iam me comer!', 19865),
(63679, 'ptBR', '', 'Os vermingues estão comendo os cereais!', 19865),
(63680, 'ptBR', '', '$n, você pode me ajudar a me livrar desses vermingues?', 19865),
(63681, 'ptBR', '', 'Pegue esses vermingues!', 19865),
(63682, 'ptBR', '', 'Sai!', 19865),
(63683, 'ptBR', '', 'Sai daí!', 19865),
(63684, 'ptBR', '', 'Salve o cereal, $p!', 19865),
(63685, 'ptBR', '', 'Pegue esses vermingues, $p!', 19865),
(63686, 'ptBR', '', 'É a Matriarca do Covil! Cuidado, $p!', 19865),
(63687, 'ptBR', 'Os Shado-Pans enviam um lacaio para fazer o trabalho deles? Talvez Shan Bu estivesse errado sobre eles...', '', 19865),
(63688, 'ptBR', 'Haha! Você... já... falhou...', '', 19865),
(63689, 'ptBR', '', 'Ainda tem mais vermingues nos silos! Você pode assustar eles pra mim, $p?', 19865),
(63690, 'ptBR', 'Precisa descansar dos inimigos? Você veio ao lugar certo e à pessoa certa.', '', 19865),
(63691, 'ptBR', 'Oh... Acho que perdi minha espada.', '', 19865),
(63692, 'ptBR', 'Quando a Cisão rasgou os continentes de Azeroth, nós pandarens pensamos que o resto do mundo havia sido completamente destruído.', '', 19865),
(63693, 'ptBR', 'Mas à medida que passavam os séculos, um jovem explorador decidiu ver o que havia lá fora. Seu nome era Liu Lang. E ele saiu para descobrir o mundo... nas costas de uma tartaruga!', '', 19865),
(63694, 'ptBR', 'Nós celebramos sua coragem com estátua e canções, mas se você estivesse na praia no dia em que ele partiu... bem, tenho certeza de que ele parecia bem ridículo, de fato.', '', 19865),
(63695, 'ptBR', 'Oh, como os pandarens riram dele. Mas Liu Lang era mais esperto do que eles pensavam. Tartarugas marinhas sempre retornam à praia onde nasceram. E assim, apesar das brumas que envolviam nossa terra, ele sempre conseguia voltar pra casa.', '', 19865),
(63696, 'ptBR', 'A cada intervalo de alguns anos ele voltava - com histórias de cidades misteriosas na areia, nômades vivendo em planícies verdejantes sem fim, um grande império sob o gelo e um reino mágico recoberto em ouro.', '', 19865),
(63697, 'ptBR', 'A cada vez que ele voltava, mais e mais pandarens respondiam ao chamado de Liu Lang e se juntavam a ele em sua tartaruga, cada vez maior. Eles eram os mais bravos entre nós: Os exploradores. Os aventureiros.', '', 19865),
(63698, 'ptBR', 'E essa é a lição de Liu Lang, meu amigo. Todos riem do explorador. Eles sempre riem... até que ele retorna.', '', 19865),
(63699, 'ptBR', 'Grandes eventos frequentemente têm origens humildes. Perceba: um lago plácido. Parado. A água como uma lâmina de vidro.', '', 19865),
(63700, 'ptBR', 'Até eu atirar uma pedra. Um gesto tão pequeno... Mas logo as ondas ocupam o lago inteiro!', '', 19865),
(63701, 'ptBR', 'Os jinyus também tem origens humildes. Outrora criaturas primitivas, eles tiveram a felicidade de viver perto de fontes mágicas no Vale.', '', 19865),
(63702, 'ptBR', 'A magia das fontes expandiu suas mentes e corpos, até que eles se tornaram uma das grandes culturas ancestrais de Pandária.', '', 19865),
(63703, 'ptBR', 'Os mais sábios entre os jinyus podem falar com os rios, assim como você ou eu consultaríamos nossos anciãos.', '', 19865),
(63704, 'ptBR', 'Nas águas murmurantes eles ouvem o futuro.', '', 19865),
(63705, 'ptBR', 'Os jinyus e seus parláguas se postam no centro dos principais eventos da história de Pandária.', '', 19865),
(63706, 'ptBR', 'Sua visão construiu impérios, libertou escravos e avisou ao nosso Último Imperador da Cisão que estraçalhou Azeroth há dez mil anos.', '', 19865),
(63707, 'ptBR', 'Pense a respeito: a menor voz pode mudar o mundo. Pense nisso, camarada, da próxima vez que você decidir atirar pedras!', '', 19865),
(63708, 'ptBR', 'Ah, meu pupilo. Você deseja estudar os mantídeos? Esteja avisado: a fronteira pandarênica está cheia de túmulos de pupilos.', '', 19865),
(63709, 'ptBR', 'Os mantídeos são professores severos.', '', 19865),
(63710, 'ptBR', 'A cada geração, os mantídeos enxameiam a muralha do Espinhaço da Serpente em grandes números. Eles matam muitos pandarens, e nós matamos outro tanto deles. E no entanto, a cada geração eles renovam o ataque. Por que eles fazem isso?', '', 19865),
(63711, 'ptBR', 'Nós pandarens não sabemos.', '', 19865),
(63712, 'ptBR', 'Nossos antigos textos indicam que os mantídeos sempre existiram. Eles são mais velhos que os mogus. De onde eles vieram?', '', 19865),
(63713, 'ptBR', 'Nós pandarens não sabemos.', '', 19865),
(63714, 'ptBR', 'Talvez, se você conseguir fazer amigos entre os mantídeos e conquistar uma reputação entre eles, eles lhe ensinem seus segredos. Mas eu estou avisando:', '', 19865),
(63715, 'ptBR', 'Ninguém jamais fez amizade com os mantídeos.', '', 19865),
(63716, 'ptBR', 'Eis aqui o que sabemos: Ao massacrar nosso povo, matando milhares de pandarens, geração após geração, eles nos ensinaram o valor da vida. Uma dádiva preciosa mas fugaz. Apagada facilmente em um único instante.', '', 19865),
(63717, 'ptBR', 'Foi isso que os mantídeos nos ensinaram.', '', 19865),
(63718, 'ptBR', 'O que você mais teme no mundo? Você conquistou seu medo... ou seu medo conquistou você?', '', 19865),
(63719, 'ptBR', 'Nos dias antigos, antes da Cisão do mundo, os imperadores mogus governavam Pandária. Meu povo foi feito de escravo, e eles tinham medo.', '', 19865),
(63720, 'ptBR', 'Os mogus eram mestres da dor e da tortura, da magia negra e das armas brutais. Nenhum pandaren, hozen ou jinyu podia resistir ao poder que eles comandavam. E meu povo teve medo.', '', 19865),
(63721, 'ptBR', 'Foram os mogus que construíram o Espinhaço da Serpente. Os pobres escravos infelizes foram enviados para ajudar na construção e defesa da muralha e para servir de comida aos mantídeos. E meu povo teve medo.', '', 19865),
(63722, 'ptBR', 'À medida que o império crescia, os mogus começaram a fazer experimentos com os segredos do Vale. Eles criaram terríveis armas de carne viva e pedra. E meu povo teve medo.', '', 19865),
(63723, 'ptBR', 'Em sua audácia, os mogus nunca imaginaram a queda que os esperava, nem que ela seria causada não por seus inimigos, e sim pelos oprimidos. O dia em que um escravo se revoltou...', '', 19865),
(63724, 'ptBR', '... e parou de ter medo.', '', 19865),
(63725, 'ptBR', 'Fogo! O mais mágico dos elementos. Ele nos aquece, cozinha nossa comida. É a lareira que cria um verdadeiro lar. Nas mãos certas, o fogo pode moldar o ferro em espadas e arados. Se não for controlado, o fogo pode destruir cidades.', '', 19865),
(63726, 'ptBR', 'O fogo é o instrumento da mudança.', '', 19865),
(63727, 'ptBR', 'Há muito tempo, um grupo de robustos caçadores nômades vagava pelo mundo. Por um lance do destino, eles estavam em Pandária quando a cisão separou os continentes de Azeroth. Os andarilhos se viram presos nas Estepes de Taolong, uma terra árida e perigosa.', '', 19865),
(63728, 'ptBR', 'Aqueles nobres caçadores encontraram uma maneira de sobreviver sozinhos. O fogo foi a chave. Eles extraíram petróleo do chão e o usaram para aquecer suas casas, cozinhar a comida e queimar os inimigos. Eles ficaram FORTES.', '', 19865),
(63729, 'ptBR', 'Das chamas do destino, os yaungóis nasceram. Eles sobreviveram além da muralha, pois recusaram-se a se submeter a uma lei que não fosse a deles.', '', 19865),
(63730, 'ptBR', 'O destino foi cruel com os yaungóis? É como perguntar se o fogo é bom ou ruim.', '', 19865),
(63731, 'ptBR', 'O destino é como o fogo. Ele pode nos moldar ou destruir.', '', 19865),
(63732, 'ptBR', 'Só o que importa é o que você faz com ele.', '', 19865),
(63733, 'ptBR', 'Ah! Você quer aprender sobre Shaohao, nosso último e maior imperador? Camarada, eu não tenho tempo para contar todas as aventuras dele, mas o que ele fez há dez mil anos ainda ressoa até hoje.', '', 19865),
(63734, 'ptBR', 'Nós sabemos que ele purgou as próprias dúvidas na Floresta de Jade. Que ele se purificou do desespero na Selva de Krasarang. Que ele superou o medo nas Estepes de Taolong. E que ele derrotou a ira, o ódio e a violência no alto das montanhas Kun-Lai.', '', 19865),
(63735, 'ptBR', 'Isto é sabido. E há templos marcando cada um destes locais sagrados.', '', 19865),
(63736, 'ptBR', 'Mas eu quero que você se imagine neste mesmo vale no dia em que ele voltou de sua jornada. Imagine estar aqui quando os portões se abriram para ele. Na época nosso imperador já era uma criatura de pura luz desprovida de dúvida, de medo ou de ódio...', '', 19865),
(63737, 'ptBR', 'Dizem que todas as árvores do vale floresceram quando ele entrou, e continuam a florescer até hoje.', '', 19865),
(63738, 'ptBR', 'Quem dera pudéssemos todos viver como nosso tão santo imperador. Que pudéssemos nos livrar de todos os fardos e existir em harmonia com o cosmos. ESSA, eu creio, foi a mensagem dele para nós... antes de ele se unir à terra, e esconder Pandária do terror da Cisão.', '', 19865),
(63739, 'ptBR', 'Obrigado, querido imperador.', '', 19865),
(63740, 'ptBR', 'Um dia, um pai se fartou do comportamento do filhote. "Você age como um hozen!", o pai ralhou. Mas seu filho ainda se comportava mal.', '', 19865),
(63741, 'ptBR', 'Para ensinar uma lição a ele, o pai arrastou o filhote para a floresta, para que ele visse como viviam os hozens. "Você viu como são os hozens?", ele perguntou. "Você quer viver daquele jeito?"', '', 19865),
(63742, 'ptBR', 'Os hozens são bem vivazes, porém sua vida é curta - poucos hozens passam do vigésimo aniversário. Seus líderes têm 14 ou 15 anos. O quão maduro você era aos 15 anos? Medite nisso!', '', 19865),
(63743, 'ptBR', 'Depois disso o pai perguntou ao filhote o que ele aprendera.', '', 19865),
(63744, 'ptBR', '"Eu aprendi que nós trabalhamos e labutamos na nossa fazendinha, mas que os hozens vivem como se o mundo inteiro fosse o seu jardim", respondeu o filhote. "Eu aprendi que nós vivemos à luz de uma só vela, mas que os hozens aproveitam a luz das estrelas. Eu aprendi que eu tenho que ir pra escola todos os dias, mas que os hozens aprendem fazendo".', '', 19865),
(63745, 'ptBR', 'E o filhote concluiu: "Eu gostaria muito de viver feito um hozen!"', '', 19865),
(63746, 'ptBR', 'Então quem foi mais sábio? O pai ou o filhote?', '', 19865),
(63747, 'ptBR', 'Isso, camarada, é você quem decide.', '', 19865),
(63748, 'ptBR', 'Já faz muito tempo desde que alguém ousou me desafiar.', '', 19865),
(63749, 'ptBR', 'Vejo você na arena.', '', 19865),
(63750, 'ptBR', 'Não se contenha.', '', 19865),
(63751, 'ptBR', 'Você luta bem! Não pare agora.', '', 19865),
(63752, 'ptBR', 'PENA-BRANCA?! Nããão!', '', 19865),
(63753, 'ptBR', 'Você... me... superou...', '', 19865),
(63754, 'ptBR', 'Você é realmente impressionante. Seria uma honra lutar junto a você.', '', 19865),
(63755, 'ptBR', 'Meus cumprimentos, camarada. Eu não lembro a última vez em que alguém me venceu assim tão facilmente.', '', 19865),
(63756, 'ptBR', 'Niuzao... precisamos salvá-lo!', '', 19865),
(63757, 'ptBR', 'Certo. Vamos.', 'Certo. Vamos.', 19865),
(63758, 'ptBR', 'Ahahaha, o grande Niuzao. A força do oeste. Celestial Divino. Protetor dos fracos.', '', 19865),
(63759, 'ptBR', 'O sha do medo, que estava sob sua custódia, escapou.', '', 19865),
(63760, 'ptBR', 'Você tem os poderes de um deus, mas foi derrotado!', '', 19865),
(63761, 'ptBR', 'O manto de um deus deve ser um fardo pesado.', '', 19865),
(63762, 'ptBR', 'Deixe seu dever de lado e descanse.', '', 19865),
(63763, 'ptBR', 'Você carrega o fardo de um povo inteiro em seus ombros. E como eles recompensaram você?', '', 19865),
(63764, 'ptBR', 'Você sofre em silêncio por um povo que não demonstra nenhum apreço por você.', '', 19865),
(63765, 'ptBR', 'Eu venci a competição de Arremesso de Cerveja por seis anos seguidos! Se você quiser, posso arremessar essa cerveja por toda a aldeia e fazer um strike! É só apontar a direção. Que tal?', 'Eu venci a competição de Arremesso de Cerveja por seis anos seguidos! Se você quiser, posso arremessar essa cerveja por toda a aldeia e fazer um strike! É só apontar a direção. Que tal?', 19865),
(63766, 'ptBR', 'Com certeza! Eu adoraria ver isso!', 'Com certeza! Eu adoraria ver isso!', 19865),
(63767, 'ptBR', 'Não, obrigado...', 'Não, obrigada...', 19865),
(63768, 'ptBR', 'Eu JAMAIS me renderei!', '', 19865),
(63769, 'ptBR', 'Matriarca Mordida Gelada começa a evocar Filhotes Mordida Gelada.', 'Matriarca Mordida Gelada começa a evocar Filhotes Mordida Gelada.', 19865),
(63770, 'ptBR', 'O Vizir Imperial Zor''lok voa para uma das suas plataformas!', '', 19865),
(63771, 'ptBR', '|TInterface\\Icons\\ability_warrior_battleshout.blp:20|tO Vizir Imperial Zor''lok dispara |cFFFF0000|Hspell:122336|h[Anéis Sônicos]|h|r pelo aposento!', '', 19865),
(63772, 'ptBR', '|TInterface\\Icons\\spell_druid_stamedingroar.blp:20|tO Vizir Imperial Zor''lok |cFFFF0000|Hspell:122852|h[Inala]|h|r um forte sopro!', '', 19865),
(63773, 'ptBR', '|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|tO Vizir Imperial Zor''lok |cFFFF0000|Hspell:122761|h[Exala]|h|r fortemente na direção de |cFFFF0000$n|r!', '', 19865),
(63774, 'ptBR', '|TInterface\\Icons\\warrior_disruptingshout.blp:20|tO Vizir Imperial Zor''lok grita usando |cFFFF0000|Hspell:122713|h[Força e Verve]|h|r!', '', 19865),
(63775, 'ptBR', '|Tinterface/Icons/trade_archaeology_delicatemusicbox.blp:20|tO Vizir Imperial Zor''lok canta a |cFFFF0000|Hspell:123791|h[Canção da Imperatriz]|h|r, causando dano em todos os jogadores até que eles o enfrentem em combate próximo!', '', 19865),
(63776, 'ptBR', '|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|tO Vizir Imperial Zor''lok usa a voz para |cFFFF0000|Hspell:122740|h[Converte]|h|r membros do saque para lutar do lado dele!', '', 19865),
(63779, 'ptBR', '|TInterface\\Icons\\ability_warrior_bladestorm.blp:20|tO Senhor do Vento Mel''jarak começa a lançar |cFFF00000|Hspell:121896|h[Lâmina Rodopiante]|h|r!', '|TInterface\\Icons\\ability_warrior_bladestorm.blp:20|tO Senhor do Vento Mel''jarak começa a lançar |cFFF00000|Hspell:121896|h[Lâmina Rodopiante]|h|r!', 19865),
(63780, 'ptBR', 'Mas o quê...?! Isto não é a carta de navegação, é uma carta! É a letra da Arie?', '', 19865),
(63781, 'ptBR', 'Caro Molúria, se você está lendo isso, significa que finalmente criou coragem para mandar alguém atrás da velha missão. Bom, você chegou tarde demais.', '', 19865),
(63782, 'ptBR', '"Nós sabemos que o Salta-Névoa não foi feito para se arriscar tão longe da muralha. Nós sabemos que era pra ser um trabalho de rotina na costa da Floresta de Jade."', '', 19865),
(63783, 'ptBR', 'O que era pra ter sido uma semana de pesca fácil se tornou uma sequência de desventuras que nos encalhou no ponto mais perigoso do continente e quase nos matou a todos, porque você não parava de ir atrás das suas intuições.', '', 19865),
(63784, 'ptBR', 'Nós só queríamos dizer: Obrigado.', '', 19865),
(63785, 'ptBR', 'Obrigado por perseguir a fortuna em horizontes distantes. Obrigado por sonhar. E mais do que tudo, obrigado por nos levar junto.', '', 19865),
(63786, 'ptBR', 'Nós sempre seremos sua tripulação, Molúria. Com ou sem navio. Nós seguiríamos você pra qualquer parte.', '', 19865),
(63787, 'ptBR', 'Sinceramente, de todo o pessoal. Até do Cachorro.', '', 19865),
(63788, 'ptBR', 'Uau...', '', 19865),
(63789, 'ptBR', 'Quer me dar licença um instante, $p? Eu... caiu um negócio no meu olho. Nos dois.', '', 19865),
(63790, 'ptBR', 'Comandante, estamos recebendo um sinal de socorro da Aliança.', 'Comandante, estamos recebendo um sinal de socorro da Aliança.', 19865),
(63791, 'ptBR', 'Pare!', 'Pare!', 19865),
(63792, 'ptBR', 'Estão atirando em nós, senhor!', 'Estão atirando em nós, senhor!', 19865),
(63793, 'ptBR', 'Ugh! Fomos atingidos!', 'Ugh! Fomos atingidos!', 19865),
(63794, 'ptBR', 'O sistema está travado, Comandante! Não consigo controlar o avião!', 'O sistema está travado, Comandante! Não consigo controlar o avião!', 19865),
(63795, 'ptBR', 'O quê? Isso... é TERRA?', 'O quê? Isso... é TERRA?', 19865),
(63796, 'ptBR', '', 'Isso vai ensinar esses vermingues a tentar me comer!', 19865),
(63797, 'ptBR', '', 'Preciso mandar esses cereais ao Mestre Cervejeiro Buf para começarmos o festival. Vejo você lá, $p!', 19865),
(63798, 'ptBR', 'Pode me chamar de louco, mas eu adoro o calor! Eu sempre me senti um pária na tundra, mas acho que esse clima daqui vai ser ótimo pra mim!', 'Pode me chamar de louco, mas eu adoro o calor! Eu sempre me senti um pária na tundra, mas acho que esse clima daqui vai ser ótimo pra mim!', 19865),
(63799, 'ptBR', 'O que você está fazendo tão longe de casa?', 'O que você está fazendo tão longe de casa?', 19865),
(63800, 'ptBR', 'Bom, as coisas estavam ficando complicadas lá no norte. O problema com o Flagelo foi resolvido, mas estamos constantemente nos mudando e procurando comida. Eu achei que já era hora de sair e encontrar novos locais de pesca!$b$bDepois de quase um mês no mar, eu vim parar aqui. Ainda bem que eu estoquei alguns caixotes de arenque em conserva para a viagem!', 'Bom, as coisas estavam ficando complicadas lá no norte. O problema com o Flagelo foi resolvido, mas estamos constantemente nos mudando e procurando comida. Eu achei que já era hora de sair e encontrar novos locais de pesca!$b$bDepois de quase um mês no mar, eu vim parar aqui. Ainda bem que eu estoquei alguns caixotes de arenque em conserva para a viagem!', 19865),
(63801, 'ptBR', 'Eu estudei por anos para dominar a arte da explosão de chi e ficaria honrado em lutar ao seu lado. Você quer minha ajuda?', '', 19865),
(63802, 'ptBR', 'A honra é minha. Para o seu posto!', 'A honra é minha. Para o seu posto!', 19865),
(63803, 'ptBR', 'Não, obrigado...', 'Não, obrigada...', 19865),
(63804, 'ptBR', 'Você foi $gselecionado:selecionada; pelo |cFFFF4809|Hspell:116784|h[Coração do Medo]|h|r !', 'Você foi $gselecionado:selecionada; pelo |cFFFF4809|Hspell:116784|h[Coração do Medo]|h|r !', 19865),
(63805, 'ptBR', 'O âmbar congela para formar uma |cFFFF0404|Hspell:125803|h[Armadilha de Âmbar]|h|r !', 'O âmbar congela para formar uma |cFFFF0404|Hspell:125803|h[Armadilha de Âmbar]|h|r !', 19865),
(63806, 'ptBR', '<O cachorro olha pra você sem entender nada.>', '', 19865),
(63807, 'ptBR', 'ZzzZZzzzz', 'ZzzZZzzzz', 19865),
(63808, 'ptBR', 'ACORDE! Precisamos defender a aldeia, pegue o seu morteiro e nos ajude!', 'ACORDE! Precisamos defender a aldeia, pegue o seu morteiro e nos ajude!', 19865),
(63809, 'ptBR', 'Eles não parecem ser de grande ajuda, é melhor deixá-los dormir.', 'Eles não parecem ser de grande ajuda, é melhor deixá-los dormir.', 19865),
(63810, 'ptBR', '%s nada com empolgação pelas saídas de água morna.', '', 19865),
(63811, 'ptBR', '%s se esfrega contra a proa do Salta-Névoa e choraminga.', '', 19865),
(63812, 'ptBR', '%s olha ao redor cautelosamente antes de deixar sua marca no cadáver da baleia.', '', 19865),
(63813, 'ptBR', '', 'Existem quatro Celestiais Majestosos que regem esta terra.$b$bYu''lon, a Serpente de Jade, vivificador do leste.$b$bChi-Ji, a Garça Vermelha, a esperança do sul.$b$bXuen, o Tigre Branco, cuja força mantém o norte.$b$bE Niuzao, o Boi Negro, que se ergue imponente a oeste.$b$bRecentemente, com o advento dos shas, problemas surgiram no templo de cada um deles. E eles precisam da sua ajuda, $r.', 19865),
(63814, 'ptBR', 'Os Shado-Pans mantêm eterna vigília, encarcerando a energia negra do sha que foi selado na terra há muito tempo atrás.$b$bInfelizmente, o sha escapou da prisão, e agora precisa ser derrotado mais uma vez.', '', 19865),
(63815, 'ptBR', 'Belo dia para pescar, não acha?  Você é $gum:uma; pescado$gr:ra;, $n?  Tenho essa isca de pesca antiga que, se você quiser, funciona que é uma beleza nas águas daqui.', '', 19865),
(63816, 'ptBR', 'Eu adoraria. Agradeço.', 'Eu adoraria. Agradeço.', 19865),
(63817, 'ptBR', 'O Lótus Dourado está encarregado da defesa do Vale das Flores Eternas.$b$bSe quiser nos ajudar, derrote os inimigos do Lótus Dourado que estão ocupando o Vale.$B$BVocê também pode falar com Anji Luz Outonal no acampamento de treinamento da Guarnição do Sol Poente para receber mais tarefas.', '', 19865),
(63818, 'ptBR', 'Os peixes estão mordendo como loucos no Krasarang!$b$bEu ainda estaria no mar, puxando um dos grandes, mas voltei aqui para vender esse que peguei hoje de manhã. Tenho muitas bocas famintas para alimentar!', '', 19865),
(63819, 'ptBR', 'Você já esteve no Vale dos Quatro Ventos?$b$bNós fazendeiros ouvimos falar sobre a crise aqui no vale, e nossos lavradores estão trabalhando duro plantando para todos os refugiados.$b$bSe você quiser passar um tempo na cidade, visite-nos em Meia Colina!', '', 19865),
(63820, 'ptBR', 'Ei você. Não acho que você vá querer entrar nesse túnel a pé. Os sauroks estão com tudo hoje, e eles são bastante territoriais.', '', 19865),
(63821, 'ptBR', 'A centelha de vida fenece.', '', 19865),
(63822, 'ptBR', 'O que era deixou de existir.', '', 19865),
(63823, 'ptBR', 'Contramedidas bem-sucedidas.', '', 19865),
(63824, 'ptBR', 'Aproxime-se! Sinta o poder dos titãs!', '', 19865),
(63825, 'ptBR', 'Utilizando energia reserva.', '', 19865),
(63826, 'ptBR', 'Yaungóis!? Agora!?', '', 19865),
(63827, 'ptBR', 'Deixe a energia consumir você!', '', 19865),
(63828, 'ptBR', 'Conduítes desativados.', '', 19865),
(63829, 'ptBR', 'Eles devem estar atrás da Touro Vermelho de Kun-Lai! $p, investigue essas histórias e prepare as defesas da aldeia! Eles não vão pegar a cerveja sem luta!', '', 19865),
(63830, 'ptBR', 'Eu defenderei a cerveja até ela ficar pronta. Então poderemos usá-la contra os atacantes Bataari! O resto de vocês, protejam-se!', '', 19865),
(63831, 'ptBR', 'Vórtice de Energia diminuindo.', '', 19865),
(63832, 'ptBR', 'Redirecionando energia.', '', 19865),
(63833, 'ptBR', 'Conduíte de Energia ativo, fluxo de energia estável.', '', 19865),
(63834, 'ptBR', 'Hei Feng prepara-se para pousar!', '', 19865),
(63835, 'ptBR', 'A existência termina... Eu me torno nada...', '', 19865),
(63836, 'ptBR', '', 'Desde os dias obscuros do antigo reino, nós pandarens nos voltamos para a arte mística da cervejaria para manter nossos espíritos e nossa força elevados.$b$bMesmo enquanto conversamos, mestres cervejeiros vagam pelo mundo, buscando ingredientes raros e poderosos para fabricar as melhores cervejas.$b$bAqueles que buscam os melhores mestres cervejeiros e os ajudam podem receber itens saborosos. Ao menos, você beberá bastante cerveja!', 19865),
(63837, 'ptBR', 'Eu peguei isso de um goblin, ele disse que com isso dá para parar qualquer coisa. Quer tentar?', 'Eu peguei isso de um goblin, ele disse que com isso dá para parar qualquer coisa. Quer tentar?', 19865),
(63838, 'ptBR', 'Claro! Eu vou tentar então.', 'Claro! Eu vou tentar então.', 19865),
(63839, 'ptBR', 'Sem chance, o sr. pode ficar com ela, Sr. Derpa.', 'Sem chance, o sr. pode ficar com ela, Sr. Derpa.', 19865),
(63840, 'ptBR', 'Estou... vivo? Obrigado... muito obrigado!', 'Estou... viva? Obrigada... muito obrigada!', 19865),
(63841, 'ptBR', 'Os Shado-Pans mantêm eterna vigília, encarcerando a energia negra do sha que foi selado na terra há muito tempo atrás.$b$bInfelizmente, o sha escapou da prisão, e agora precisa ser derrotado mais uma vez.', '', 19865),
(63842, 'ptBR', '', 'O Lótus Dourado está encarregado da defesa do Vale das Flores Eternas.$b$bSe quiser nos ajudar, derrote os inimigos do Lótus Dourado que estão ocupando o Vale.$B$BVocê também pode falar com Anji Luz Outonal no acampamento de treinamento da Guarnição do Sol Poente para receber mais tarefas.', 19865),
(63843, 'ptBR', 'Existem quatro Celestiais Majestosos que regem esta terra.$b$bYu''lon, a Serpente de Jade, vivificador do leste.$b$bChi-Ji, a Garça Vermelha, a esperança do sul.$b$bXuen, o Tigre Branco, cuja força mantém o norte.$b$bE Niuzao, o Boi Negro, que se ergue imponente a oeste.$b$bRecentemente, com o advento dos shas, problemas surgiram no templo de cada um deles. E eles precisam da sua ajuda, $r.', '', 19865),
(63844, 'ptBR', '', 'Diga-me, $r, você já teve vontade de pescar?$b$bSe for o caso, você pode visitar os Pescadores, lá na Selva de Krasarang.', 19865),
(63845, 'ptBR', 'Sou membro dos Lavradores, os fazendeiros trabalhadores de Pandária. Se você quiser saber mais sobre nós, estamos na Meia Colina, no Vale dos Quatro Ventos.', '', 19865),
(63846, 'ptBR', 'Desde os dias obscuros do antigo reino, nós pandarens nos voltamos para a arte mística da cervejaria para manter nossos espíritos e nossa força elevados.$b$bMesmo enquanto conversamos, mestres cervejeiros vagam pelo mundo, buscando ingredientes raros e poderosos para fabricar as melhores cervejas.$b$bAqueles que buscam os melhores mestres cervejeiros e os ajudam podem receber itens saborosos. Ao menos, você beberá bastante cerveja!', '', 19865),
(63847, 'ptBR', 'Com sorte, dessa vez nós não teremos problemas.', '', 19865),
(63848, 'ptBR', 'Já esteve alguma vez em Kun-Lai? É lindo. Grandes fazendas floridas. Lindas montanhas. E absolutamente nada de perigoso.', '', 19865),
(63849, 'ptBR', 'Bem... sim. Existem problemas com os hozens.', '', 19865),
(63850, 'ptBR', 'As lanças são só pra impressionar. Desde que a gente não saia do barco, faça contato visual ou seja atingido por uma lança, vamos ficar bem.', '', 19865),
(63851, 'ptBR', 'É seguro. Eu trouxe o Andarilho das Lendas Cho e seus companheiros estranhos por este caminho não tem muito tempo.', '', 19865),
(63852, 'ptBR', 'Você mereceu. Balançando o incenso no rosto dele... espere um pouco. Tem alguma coisa errada nisso.', '', 19865),
(63853, 'ptBR', 'Aqueles são refugiados? O que está acontecendo aqui? Isso é luta que estou ouvindo?', '', 19865),
(63854, 'ptBR', 'Essas pessoas são fazendeiros, não guerreiros! Eles podem precisar da nossa ajuda!', '', 19865),
(63855, 'ptBR', 'Sim, e os tigres.', '', 19865),
(63856, 'ptBR', 'Hozen ataca grômulos.', '', 19865),
(63857, 'ptBR', 'Tigres.', '', 19865),
(63858, 'ptBR', 'Sauroks são muito perigosos.', '', 19865),
(63859, 'ptBR', 'Muitos sauroks vivem na Passagem Antiga.', '', 19865),
(63860, 'ptBR', 'O "orc" tentou me socar.', '', 19865),
(63861, 'ptBR', 'Eu não consigo encontrar meu escudo e já procurei por toda a aldeia! Gostaria de poder ajudar, mas sem meu escudo eu não sirvo pra nada!', 'Eu não consigo encontrar meu escudo e já procurei por toda a aldeia! Gostaria de poder ajudar, mas sem meu escudo eu não sirvo pra nada!', 19865),
(63862, 'ptBR', '... Seu escudo está nas suas costas. Agora levante-se e NOS AJUDE!', '... Seu escudo está nas suas costas. Agora levante-se e NOS AJUDE!', 19865),
(63863, 'ptBR', 'Sinto muito, mas eu também não vi seu escudo. Talvez seja melhor assim...', 'Sinto muito, mas eu também não vi seu escudo. Talvez seja melhor assim...', 19865),
(63864, 'ptBR', 'HAH! Você encontrou! Agora vamos contra-atacar!', 'HAH! Você encontrou! Agora vamos contra-atacar!', 19865),
(63865, 'ptBR', 'Que embaraçoso. Para a batalha!', 'Que embaraçoso. Para a batalha!', 19865),
(63866, 'ptBR', 'Que lugar improvável pra encontrar o meu escudo... Enfim! Vamos à luta!', 'Que lugar improvável pra encontrar o meu escudo... Enfim! Vamos à luta!', 19865),
(63867, 'ptBR', 'A Escadaria Oculta está sob proteção da Madame Goya.', 'A Escadaria Oculta está sob proteção da Madame Goya.', 19865),
(63868, 'ptBR', 'Há muito mais a ser encontrado na Taberna nas Nuvens.', 'Há muito mais a ser encontrado na Taberna nas Nuvens.', 19865),
(63869, 'ptBR', 'A Taberna serve àqueles que não fazem muitas perguntas.', 'A Taberna serve àqueles que não fazem muitas perguntas.', 19865),
(63870, 'ptBR', 'Hei Feng dá uma Respiração Profunda! Vá para trás dele!', '', 19865),
(63871, 'ptBR', 'Boas-vindas, $p. Estamos observando você há algum tempo.$b$bVocê é a rajada de vento que anuncia a tempestade de mudanças.', '', 19865),
(63872, 'ptBR', 'Dizem que você serviu ao meu irmão nas Estepes de Taolong. Como vai aquele rapaz? Ele algum dia contou como perdeu o olho?', '', 19865),
(63873, 'ptBR', 'Boas-vindas, $p. Estamos observando suas realizações desde que você chegou em nossa terra.', 'Boas-vindas, $p. Estamos observando suas realizações desde que você chegou em nossa terra.', 19865),
(63874, 'ptBR', 'Os sauroks impedem que este lugar seja visita de outra forma que não voando.$b$bÉ claro, assim é muito complicado escapar para tomar uma na Taberna nas Nuvens.', 'Os sauroks impedem que este lugar seja visita de outra forma que não voando.$b$bÉ claro, assim é muito complicado escapar para tomar uma na Taberna nas Nuvens.', 19865),
(63875, 'ptBR', 'Tenha cuidado com a minha águia. Ela morde.', 'Tenha cuidado com a minha águia. Ela morde.', 19865),
(63876, 'ptBR', 'As estradas da montanha podem ser perigosas.', 'As estradas da montanha podem ser perigosas.', 19865),
(63877, 'ptBR', 'Nunca pergunte ao Mestre Falcoeiro Norung sobre o tapa-olho dele. Você jamais ouvirá o fim da história.', 'Nunca pergunte ao Mestre Falcoeiro Norung sobre o tapa-olho dele. Você jamais ouvirá o fim da história.', 19865),
(63878, 'ptBR', 'Nós teremos que trabalhar rápido, Arauto. Este local não é seguro.', '', 19865),
(63879, 'ptBR', 'Sua mente é forte, Arauto. Ainda estou lutando para me comunicar com você. Dominál-$go:a; seria quase impossível...', '', 19865),
(63880, 'ptBR', 'Seus pensamentos me intrigam. Há um propósito em suas ações. Sua complexidade é impressionante.', '', 19865),
(63881, 'ptBR', 'Sua inteligência virá a calhar tanto quanto sua perícia em batalha. Eu vejo muito potencial em uma mente como a sua, Arauto.', '', 19865),
(63882, 'ptBR', 'Chegamos. Com esta arma nós dizimaremos o exército da Imperatriz!', '', 19865),
(63883, 'ptBR', 'Eu sei mexer com redes, posso prender os yaungóis nojentos nelas.', '', 19865),
(63884, 'ptBR', 'Muito bem, vamos prendê-los!', 'Muito bem, vamos prendê-los!', 19865),
(63885, 'ptBR', 'Está bem, segure essas redes.', 'Está bem, segure essas redes.', 19865),
(63886, 'ptBR', 'Hei Feng está pousando!', '', 19865),
(63887, 'ptBR', 'Eu já sei pegar peixe, agora vou aprender a pegar yaungóis!', '', 19865),
(63888, 'ptBR', 'Eu e minhas redes fiéis não fracassaremos com a aldeia!', '', 19865),
(63889, 'ptBR', 'Boas-vindas ao Trono do Conhecimento. Nunca houve um armazém de informações e sabedoria maior sobre os dias antigos de Pandária que esse lugar.', '', 19865),
(63890, 'ptBR', '', 'Você deve ser $n.$b$bEstava esperando por você.', 19865),
(63891, 'ptBR', 'Eu gostaria de uma carona para o Morro Bagarai.', 'Eu gostaria de uma carona para o Morro Bagarai.', 19865),
(63892, 'ptBR', 'Que assim seja. Farei eu mesmo!', '', 19865),
(63893, 'ptBR', 'Eu sou uno com a névoa e curo os necessitados.', 'Eu sou una com a névoa e curo os necessitados.', 19865),
(63894, 'ptBR', 'Nós precisamos da sua ajuda.', 'Nós precisamos da sua ajuda.', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(63895, 'ptBR', 'Não precisamos das suas habilidades de cura.', 'Não precisamos das suas habilidades de cura.', 19865),
(63896, 'ptBR', 'Obrigado, $p. Você salvou todos nós.', '', 19865),
(63897, 'ptBR', 'Já tiramos o que precisamos do intrometido Andarilho das Lendas.', '', 19865),
(63898, 'ptBR', 'Lembre-se, é nos momentos mais escuros que a luz brilha mais forte.', '', 19865),
(63899, 'ptBR', 'Bom trabalho, heróis!', '', 19865),
(63900, 'ptBR', 'Intrusos invadiram o templo!', '', 19865),
(63901, 'ptBR', 'LAGARTO FRACOTE! Seu couro adornará o trono do Rei Trovão!', '', 19865),
(63902, 'ptBR', 'TUNG! Jogarei seu cadáver para suas feras inúteis!', '', 19865),
(63903, 'ptBR', 'Teurgo inútil! Como ousa falhar com o Rei Trovão?!', '', 19865),
(63904, 'ptBR', 'CAPITÃO RO-GU?! Impossível! Quem imaginou que você esmoreceria agora...', '', 19865),
(63905, 'ptBR', 'Eu, General Zhun, arauto do glorioso Rei Trovão Lei Shen, desafio você!', '', 19865),
(63906, 'ptBR', 'Ro-Gu, Tung, Fon, Hithiss: Guardem os artefatos... com suas VIDAS!', '', 19865),
(63907, 'ptBR', 'No fundo, no fundo, sempre soube que eu era um lenhador!', 'No fundo, no fundo, sempre soube que eu era um lenhador!', 19865),
(63908, 'ptBR', 'Você parece ser u$gm:ma; artes$gão:ã;, $pc. Você acha que consegue dar conta de ser marceneiro? Se sim, tenho algo que poderá ajudar.', '', 19865),
(63909, 'ptBR', 'Eu gostaria de uma carona para a Aldeia Barbatana de Pérola.', 'Eu gostaria de uma carona para a Aldeia Barbatana de Pérola.', 19865),
(63910, 'ptBR', 'Olá de novo, $n. Como minha isca vem lhe tratando?', '', 19865),
(63911, 'ptBR', 'Olá de novo, $n. Como meu machado vem lhe tratando?', '', 19865),
(63912, 'ptBR', 'Até a próxima, $n.', '', 19865),
(63913, 'ptBR', 'Você tem minha eterna gratidão. Achei que estivesse condenado.', '', 19865),
(63914, 'ptBR', '', 'Existem tantas histórias incríveis a serem descobertas. Tanta história. Não é fascinante?', 19865),
(63915, 'ptBR', 'Jurô: MATE-O!', '', 19865),
(63916, 'ptBR', 'Obrigado! Nenhum de nós esperava sobreviver... Ajudarei você tanto quanto puder!', '', 19865),
(63917, 'ptBR', 'Eles já arrastaram e mataram os outros. Sinto muito... Não tenho mais forças...', '', 19865),
(63918, 'ptBR', 'Obrigado! Por favor, salve o... Andarilho das Lendas Fu... se puder... Eu... falhei... ...', '', 19865),
(63919, 'ptBR', 'Nós entramos em um lugar perigoso, meu sorte-sim. Aqui, os sauroks se tornaram muito furiosos e atacam todos os barcos que passam. Nós precisamos ficar atentos.', '', 19865),
(63920, 'ptBR', 'O General Zhun pretende entregar os antigos artefatos do Templo Kotmogu ao seu cruel mestre, o Rei Trovão. Não podemos permitir que isso aconteça!', '', 19865),
(63921, 'ptBR', 'Por favor, você PRECISA mantê-los longe das mãos do general! Eu voltarei ao Vale das Flores Eternas, para falar com o Lótus Dourado. Outra vez, muito obrigado!', '', 19865),
(63922, 'ptBR', '<Mishi olha você com expectativa.>', '', 19865),
(63923, 'ptBR', 'Hoje, os shado-pans dão as boas-vindas a você.', '', 19865),
(63924, 'ptBR', 'Sua perseverança nos fortalece. Sua coragem nos conduz. Sua honra nos inspira.', '', 19865),
(63925, 'ptBR', 'Deste dia em diante, você caminhará como um de nós.', '', 19865),
(63926, 'ptBR', 'Receba nossas boas-vindas aos shado-pans!', '', 19865),
(63927, 'ptBR', 'Eu não falharei com você ou com a aldeia.', 'Eu não falharei com você ou com a aldeia.', 19865),
(63928, 'ptBR', 'Meu dever é vigiar o poço. É um trabalho importante!', '', 19865),
(63929, 'ptBR', 'Meus amigos dizem que eu sou meio lento, mas eu corro mais rápido que todos eles!', '', 19865),
(63930, 'ptBR', 'O poço é muito importante. Que bom que eles me pediram pra vigiá-lo.', '', 19865),
(63931, 'ptBR', 'Koa, eles disseram. "Vá vigiar o poço!”. Foi o que eles disseram.', '', 19865),
(63932, 'ptBR', 'Por que está todo mundo com medo? Eu não vou deixar os trolls chegarem perto do nosso poço! Eu sou um bom vigia!', '', 19865),
(63933, 'ptBR', 'Oi, eu sou Koa! Você quer ser $gmeu amigo:minha amiga;?', '', 19865),
(63934, 'ptBR', 'Eu posso fazer com que você obtenha vida da morte.', '', 19865),
(63935, 'ptBR', 'Estou gostando da ideia.', 'Estou gostando da ideia.', 19865),
(63936, 'ptBR', 'Eu prefiro não me meter com a morte.', 'Eu prefiro não me meter com a morte.', 19865),
(63937, 'ptBR', 'Nós todos vamos morrer!', 'Por que eles estão nos atacando?!', 19865),
(63938, 'ptBR', 'Como nós iremos sobreviver?!', 'Quem irá nos salvar?!', 19865),
(63939, 'ptBR', 'Alguma coisa tá acontecendo aqui. Apenas falta clareza quanto à natureza exata.', 'Alguma coisa tá acontecendo aqui. Apenas falta clareza quanto à natureza exata.', 19865),
(63940, 'ptBR', 'Este capacete é mágico, quer experimentar? A gente tem um monte!', 'Este capacete é mágico, quer experimentar? A gente tem um monte!', 19865),
(63941, 'ptBR', 'Mas com cer-te-za!', 'Mas com cer-te-za!', 19865),
(63942, 'ptBR', 'Não, obrigado, eu preciso ficar em forma pra invasão.', 'Não, obrigado, eu preciso ficar em forma pra invasão.', 19865),
(63943, 'ptBR', 'Essa parada normalmente é calma. Agora, veja só. De onde vieram todos esses yaungóis?', '', 19865),
(63944, 'ptBR', 'Se você seguir para o noroeste, procure o Bazar dos Grômulos. Muitos berloques e sorte-sins interessantes estão à venda por lá. Que a boa sorte seja encontrada por aqueles que a procuram.', '', 19865),
(63945, 'ptBR', 'Um Yeti de Guerra Bataari se aproxima vindo da Passagem Antiga!', '', 19865),
(63946, 'ptBR', 'Um Yeti de Guerra Bataari se aproxima vindo da Ponte!', '', 19865),
(63947, 'ptBR', 'Um Yeti de Guerra Bataari se aproxima vindo do Oeste!', '', 19865),
(63948, 'ptBR', 'Tem centeio?', '', 19865),
(63949, 'ptBR', 'Hora de acordar.', '', 19865),
(63950, 'ptBR', 'Eu adoro o Festival da Cerveja da Lua. Espero por ele todos os anos.', 'Eu adoro o Festival da Cerveja da Lua. Espero por ele todos os anos.', 19865),
(63951, 'ptBR', 'Iaque. Iaque nunca muda.', '', 19865),
(63952, 'ptBR', 'Seu iaque está em outro estábulo.', '', 19865),
(63953, 'ptBR', 'É perigoso ir sozinho?', '', 19865),
(63954, 'ptBR', 'Você poderia por favor me mostrar o caminho de volta para Kunlai?', '', 19865),
(63955, 'ptBR', 'Talvez você possa rolar um barril.', '', 19865),
(63956, 'ptBR', 'Você pode morrer de disenteria aqui.', '', 19865),
(63957, 'ptBR', 'Eu sou só uma patética criatura feita de carne e cerveja.', '', 19865),
(63958, 'ptBR', 'Um belo dia, uma bela cerveja e um belo peixe, se melhorar estraga!', '', 19865),
(63959, 'ptBR', 'Ponha mais coisa no treco onde entra mais coisa.', '', 19865),
(63960, 'ptBR', 'Eu não interajo com os Pandarens sempre, mas quando eu interajo... é pela cerveja!', '', 19865),
(63961, 'ptBR', 'Uma pena sentar em algo tão bonito.', '', 19865),
(63962, 'ptBR', 'Eu venci a competição de Arremesso de Cerveja por seis anos seguidos! Eu sou o mais forte em Pandária.', 'Eu venci a competição de Arremesso de Cerveja por seis anos seguidos! Eu sou o mais forte em Pandária.', 19865),
(63963, 'ptBR', 'É assim que é quando se sonha?', '', 19865),
(63964, 'ptBR', 'O festival da Cerveja da Lua é uma excelente oportunidade para descansar dos estudos.', '', 19865),
(63965, 'ptBR', 'Dez anos. Eu escovei iaques sem falta por dez anos.', '', 19865),
(63966, 'ptBR', 'Duas teorias ao discutir com iaque. Nenhuma funciona.', '', 19865),
(63967, 'ptBR', 'Eu só vim aqui pegar uns nabos, eu juro!', '', 19865),
(63968, 'ptBR', '', 'É bom ver o mundo fora do monastério.', 19865),
(63969, 'ptBR', 'Eu ia montar um grupo e chamar o Místico Chapéu de Pássaro, mas você o dispensou.', '', 19865),
(63970, 'ptBR', 'Eu acho que o iaque começou a se mexer.', '', 19865),
(63971, 'ptBR', 'Aqueles yaungóis tem espadas retas. Espadas. Retas.', '', 19865),
(63972, 'ptBR', 'Ai ai. Mais baixo. Mais baixo.', '', 19865),
(63973, 'ptBR', 'Eu sou cavalga-iaque. Esse aqui é meu iaque.', '', 19865),
(63974, 'ptBR', 'Não há nada em toda Pandária que possa parar o estouro da Grande Expedição de Iaques. Reze para nunca ver um.', '', 19865),
(63975, 'ptBR', 'Não é minha intenção criar uma legislação contra você.', '', 19865),
(63976, 'ptBR', 'Será que a cauda do iaque ajuda a manter o equilíbrio?', '', 19865),
(63977, 'ptBR', 'Eu vou rolando, rolando, pelos portões de Mogu''shan.', '', 19865),
(63978, 'ptBR', 'Eu só preciso de um minuto. Espera, isso saiu meio esquisito.', '', 19865),
(63979, 'ptBR', 'Pro Derpa Derpa, só a melhor cerveja.', 'Pro Derpa Derpa, só a melhor cerveja.', 19865),
(63980, 'ptBR', 'Eu perdi meu escudo nas minhas viagens. Tudo o que eu queria era uma Cerveja, mas agora tudo o que eu quero é meu escudo de volta.', 'Eu perdi meu escudo nas minhas viagens. Tudo o que eu queria era uma Cerveja, mas agora tudo o que eu quero é meu escudo de volta.', 19865),
(63981, 'ptBR', 'É só apontar a direção que eu mando os barris voando!', 'É só apontar a direção que eu mando os barris voando!', 19865),
(63982, 'ptBR', 'Como posso ajudar?', 'Como posso ajudar?', 19865),
(63983, 'ptBR', 'Eu preciso de suprimentos para lições de culinária.', 'Eu preciso de suprimentos para lições de culinária.', 19865),
(63984, 'ptBR', 'Olá, camarada. Com fome?', 'Olá, camarada. Com fome?', 19865),
(63985, 'ptBR', 'O carregador já está congelado há um bom tempo. Você vê uma faísca de luz de alguma coisa no pacote que ele carregava.', '', 19865),
(63986, 'ptBR', 'Pegar o item do pacote.', 'Pegar o item do pacote.', 19865),
(63987, 'ptBR', 'Eu vou atualizar meu diário.', '', 19865),
(63988, 'ptBR', 'Eu me sinto como um chouriço.', '', 19865),
(63989, 'ptBR', 'Eu me sinto como se tivesse perdido um oitavo de alguma coisa.', '', 19865),
(63990, 'ptBR', 'Proa atingida!', 'Proa atingida!', 19865),
(63991, 'ptBR', 'Estou queimando sua aldeia [$P].', '', 19865),
(63992, 'ptBR', '', '', 19865),
(63993, 'ptBR', '', 'Ah, nós sabíamos que você conseguiria!', 19865),
(63994, 'ptBR', 'Bom trabalho. Acho que você aprendeu alguma coisa comigo.', '', 19865),
(63995, 'ptBR', '', 'Vamos sair para um drinque!', 19865),
(63996, 'ptBR', 'Este pobre carregador já está congelado há algum tempo.', '', 19865),
(63997, 'ptBR', 'Bebidas!', 'Bebidas!', 19865),
(63998, 'ptBR', 'Vamos lá, Mishi!', 'Vamos lá, Mishi!', 19865),
(63999, 'ptBR', 'Vocês sangrarão!', '', 19865),
(64000, 'ptBR', 'Que armas brilhantes. Dá elas pra mim!', '', 19865),
(64001, 'ptBR', 'Enfrente-me, sangue quente!', '', 19865),
(64002, 'ptBR', 'Sssssim... um desafio.', '', 19865),
(64003, 'ptBR', 'Somos mais fortes agora! Você vai morrer!', '', 19865),
(64005, 'ptBR', 'Somos os mestres da Escadaria, agora!', '', 19865),
(64006, 'ptBR', 'Eu vou comer a sua cabeça!', '', 19865),
(64007, 'ptBR', 'Não existe lugar para sangues quente na nossa Escadaria!', '', 19865),
(64008, 'ptBR', '', 'Acho que não.', 19865),
(64009, 'ptBR', 'Você não nos derrotará.', '', 19865),
(64010, 'ptBR', 'Fui enviado para sabotar a reconstrução da ponte dos Sik''thik, mas você lutou com eles como $gum:uma; verdadeir$go:a; $c. Você tem a oportunidade de eliminar o líder deles!', '', 19865),
(64011, 'ptBR', 'E quem é você para nos impedir?', '', 19865),
(64012, 'ptBR', 'Talvez tenhamos... atacado... muito cedo...', '', 19865),
(64013, 'ptBR', 'Mande-me de volta Tenwu.', 'Mande-me de volta Tenwu.', 19865),
(64014, 'ptBR', 'Bombordo atingido!', 'Bombordo atingido!', 19865),
(64015, 'ptBR', 'Estibordo atingido!', 'Estibordo atingido!', 19865),
(64016, 'ptBR', 'A Escadaria Oculta será nossa novamente em breve!', '', 19865),
(64017, 'ptBR', 'O sha fez os pandarens ficarem fracos! Agora, é a hora de expulsá-los da Escadaria Oculta para sempre!', '', 19865),
(64018, 'ptBR', 'Esses viajantes estão bons para serem roubados! Peguem as coisas deles! Peguem tudo deles!!!', '', 19865),
(64019, 'ptBR', 'Roubem tudo! Roubem tudooo!', '', 19865),
(64020, 'ptBR', 'Sou o "perito em recuperação" de nossa dama, Madame Goya. É a vontade dela que orienta o fluxo e o refluxo da viagem por esta estrada.$b$bÉ minha função garantir que certos tipos inescrupulosos não se aproveitem da hospitalidade dela.', '', 19865),
(64021, 'ptBR', 'Fique alerta. Os Piratas Ungá Ingô são temíveis. Mas que cerveja boa que eles fazem!', '', 19865),
(64022, 'ptBR', 'Precisamos de mais cerveja. Um bom lugar pra procurar deve ser o navio pirata a sudoeste daqui.', '', 19865),
(64023, 'ptBR', 'Precisamos de mais cerveja. Um bom lugar pra procurar é a noroeste daqui. Acho que estão fazendo um luau lá.', '', 19865),
(64024, 'ptBR', 'Precisamos de mais cerveja. A caverna a oeste daqui, ao longo da praia, talvez tenha alguma estocada.', '', 19865),
(64025, 'ptBR', 'Precisamos de mais cerveja. Eu acho que vi hozens bebendo cerveja no pico da montanha a sudeste daqui.', '', 19865),
(64026, 'ptBR', 'Quem deixaria uma pilha de bombas e um canhão perto de cerveja? Oh, bem. O lixo de um hozen é a defesa de praia de um mestre cervejeiro.', '', 19865),
(64027, 'ptBR', 'Oh, não! Capitão Fedô? Eu pensei que ele era apenas uma lenda!', '', 19865),
(64028, 'ptBR', 'Parece que os hozens espalharam a cerveja em canecas e barris pela ilha.', '', 19865),
(64029, 'ptBR', 'Eles estão vindo do oceano! Use o canhão!', '', 19865),
(64030, 'ptBR', 'Os hozens estão roubando nossa cerveja!', '', 19865),
(64031, 'ptBR', 'Os... toleteiros... pegaram minha cerveja...', '', 19865),
(64032, 'ptBR', 'Popa atingida!', 'Popa atingida!', 19865),
(64033, 'ptBR', 'Vocês podem tomar nossas vidas... mas vocês nunca... vão tomar... nossa cerveja...', '', 19865),
(64034, 'ptBR', 'Galerosos... vão pagar.', '', 19865),
(64035, 'ptBR', 'Eu morro fazendo o que gosto!', '', 19865),
(64036, 'ptBR', 'Galerosos...  zabumbaram... Ba-Bam...', '', 19865),
(64037, 'ptBR', 'Os mantídeos estão sob o MEU comando, tolos. Vejam como ela sucumbe a mim.', '', 19865),
(64038, 'ptBR', 'O que é aquilo?', '', 19865),
(64039, 'ptBR', 'Não pare de jogar! Acho que eles estão começando a ir embora.', '', 19865),
(64040, 'ptBR', 'O QUÊ?! O que é que não vai mais existir?!', '', 19865),
(64041, 'ptBR', 'Rápido! Pegue um barril e comece a jogar como se sua vida dependesse disso!', '', 19865),
(64042, 'ptBR', 'Você não vai mais sair!', '', 19865),
(64043, 'ptBR', 'Cuidado!', '', 19865),
(64044, 'ptBR', 'Feitiço Sauroken.', '', 19865),
(64045, 'ptBR', 'Muita má sorte.', '', 19865),
(64046, 'ptBR', 'Um sorte-sim seria sábio e jogaria barris agora.', '', 19865),
(64047, 'ptBR', 'Não é boa sorte viajar em um barco barris explosivos a bordo.', '', 19865),
(64048, 'ptBR', 'Sauroks Listranegra são muito perigosos e poderosos.', '', 19865),
(64049, 'ptBR', 'Pra trás! Rastejantes!', '', 19865),
(64050, 'ptBR', 'Hah! Vocês não esperavam por essa, seus beiço de lagarto!', '', 19865),
(64051, 'ptBR', 'Toma essa, seus rastejantes de língua partida!', '', 19865),
(64052, 'ptBR', 'Ah! Saurok a bordo! Saurok a bordo!', '', 19865),
(64053, 'ptBR', '', '$p, me fale se precisar de ajuda na defesa da cidade!', 19865),
(64054, 'ptBR', '', 'Nós recebemos muitos visitantes de toda Pandária. Com certeza eles poderão nos ajudar com os invasores.', 19865),
(64055, 'ptBR', 'Fale-me sobre a Cerveja da Selva de Krasarang.', 'Fale-me sobre a Cerveja da Selva de Krasarang.', 19865),
(64056, 'ptBR', 'Conte-me sobre Briaw Shan.', 'Conte-me sobre Briaw Shan.', 19865),
(64057, 'ptBR', 'Fale-me dos fogos de artifício do festival.', 'Fale-me dos fogos de artifício do festival.', 19865),
(64058, 'ptBR', 'Fale-me dos discípulos de Tian.', 'Fale-me dos discípulos de Tian.', 19865),
(64059, 'ptBR', 'Fale-me dos canhões avariados.', 'Fale-me dos canhões avariados.', 19865),
(64060, 'ptBR', 'Fale-me dos atiradores de elite do Vale.', 'Fale-me dos atiradores de elite do Vale.', 19865),
(64061, 'ptBR', 'Fale-me dos tecelões da névoa de Tian.', 'Fale-me dos tecelões da névoa de Tian.', 19865),
(64062, 'ptBR', 'Fale-me dos aldeões joviais.', 'Fale-me dos aldeões joviais.', 19865),
(64063, 'ptBR', 'Fale-me sobre Cianz.', 'Fale-me sobre Cianz.', 19865),
(64064, 'ptBR', 'Fale-me dos escudeiros Xuen.', 'Fale-me dos escudeiros Xuen.', 19865),
(64065, 'ptBR', 'Fale-me de Derpa Derpa.', 'Fale-me de Derpa Derpa.', 19865),
(64066, 'ptBR', 'Fale-me dos pescadores de Binan.', 'Fale-me dos pescadores de Binan.', 19865),
(64067, 'ptBR', '', 'A Cerveja Selvagem de Krasarang é muito volátil, $n! Podemos colocar os barris perto de onde os yaungóis terão de passar para explodi-los. Pegue um barril e eu usarei um marcador para indicar onde devemos colocá-lo.', 19865),
(64068, 'ptBR', '', 'Briaw Shan é um arremessador de cerveja campeão, $n. Ele pode arremessar um barril e fazê-lo se arrebentar em cima dos yaungóis! Eu o vi na estalagem hoje mais cedo. Vá ver se ele pode ajudar!', 19865),
(64069, 'ptBR', '', 'Temos barris de fogos de artifício por toda a cidade para as celebrações do festival, $n. Coloque alguns nos locais certos, dê uma pancada neles e eles destruirão tudo. Pegue um barril e eu marcarei os locais onde os colocaremos.', 19865),
(64070, 'ptBR', '', 'Há alguns discípulos de Tian celebrando a Carveja da Lua, $n! Com certeza eles poderão usar seu treinamento para nos ajudar. Fale com ele e veja se eles podem deter os yaungóis!', 19865),
(64071, 'ptBR', '', 'Há alguns canhões danificados dentro dos celeiros e atrás da estalagem, $n. Se você conseguir consertá-los, os aldeões podem usá-los para estourar os yaungóis!', 19865),
(64072, 'ptBR', '', 'Há alguns atiradores de elite do Vale que pararam para passar a noite na cidade, $n. Eles defenderam o Portal do Sol Poente contra os mantídeos por anos com seus morteiros. Veja se você consegue acordá-los!', 19865),
(64073, 'ptBR', '', '$n, há alguns Tecelãos da Névoa aqui, vindos do monastério Tian. As habilidades deles nos permitiram lutar por ainda mais tempo! Peça a eles que nos ajudem em nossa luta.', 19865),
(64074, 'ptBR', '', 'Há alguns aldeões joviais na cidade dizendo que inventaram um capacete que os torna melhor em tudo. Eu não acredito muito nisso, mas usar capacete sempre é bom, né? Fale com eles e veja se eles podem emprestar um.', 19865),
(64075, 'ptBR', '', 'Cianz vem abençoar nosso festival todo ano, $n. Ele não lutará na batalha, mas talvez haja algo que ele possa fazer para nos ajudar. Pergunte se há algo que ele possa fazer.', 19865),
(64076, 'ptBR', '', 'Os escudeiros Xuen vêm do Templo do Tigre Branco todo ano, $n. Eles podem bloquear o avanço yaungol e impedi-los de entrar na aldeia. Fale com eles e veja se podem nos ajudar.', 19865),
(64077, 'ptBR', '', 'Derpa Derpa vem pra cidade de vez em quando pra tentar vender uns trecos estranhos que ele encontra perto do Monte Kun-Lai. Fale com ele e veja se ele tem algo que sirva de arma.', 19865),
(64078, 'ptBR', '', 'Os pescadores de Binan são capazes de pegar até um hozen ensaboado nas redes, $n. Com certeza eles poderão pegar alguns yaungóis para nós. Fale com eles sobre defender nossa aldeia!', 19865),
(64079, 'ptBR', 'Existem outras defesas?', 'Existem outras defesas?', 19865),
(64080, 'ptBR', 'A Touro Vermelho de Kun-Lai está pronta, $n! Você está $gpronto:pronta; para a melhor cerveja de Pandária? Já vou avisando que beber essa cerveja deixa a gente com vontade de chutar as coisas. O que é bom, pois tem um monte de yaungol por aí merecendo uns chutes.', '', 19865),
(64081, 'ptBR', 'Me dê um pouco, rápido! Antes que os yaungóis peguem tudo!', 'Me dê um pouco, rápido! Antes que os yaungóis peguem tudo!', 19865),
(64082, 'ptBR', 'A Touro Vermelho de Kun-Lai está pronta, $p! Agora vamos usá-la para chutar bunda de yaungol!', '', 19865),
(64083, 'ptBR', 'Vá falar com o Mestre Cervejeiro Buf e pegue a Touro Vermelho de Kun-Lai com ele!', '', 19865),
(64084, 'ptBR', 'Você vai pagar por essa perturbação.', '', 19865),
(64085, 'ptBR', 'Como você se atreve a pisar no vale?', '', 19865),
(64086, 'ptBR', 'Você vai se arrepender dessa intrusão.', '', 19865),
(64087, 'ptBR', 'Sua morte não será rápida nem indolor!', '', 19865),
(64088, 'ptBR', 'Sua raça não pode entrar no vale!', '', 19865),
(64089, 'ptBR', 'Você não é $Gbem-vindo:bem-vinda; aqui!', '', 19865),
(64090, 'ptBR', 'Você será $go primeiro:a primeira; de muitos a morrer!', '', 19865),
(64091, 'ptBR', 'Sua vida será um sacrifício adequado ao nosso imperador!', '', 19865),
(64092, 'ptBR', 'Nós reconstruiremos nosso império sobre os cadáveres de nossos inimigos!', '', 19865),
(64093, 'ptBR', 'Você servirá ou morrerá!', '', 19865),
(64094, 'ptBR', 'Sua fraqueza é uma ofensa!', '', 19865),
(64095, 'ptBR', 'Minha morte não $go:a; salvará do que irá acontecer...', '', 19865),
(64096, 'ptBR', 'Sua vitória durará pouco...', '', 19865),
(64097, 'ptBR', 'Quando dois grandes impérios se reunirem, o mundo se esfacelará em redor deles...', '', 19865),
(64098, 'ptBR', 'Você chegou tarde demais...', '', 19865),
(64099, 'ptBR', 'Minha morte não lhe serviu de nada!', '', 19865),
(64100, 'ptBR', 'O que será que o mar vai nos trazer hoje?', '', 19865),
(64101, 'ptBR', 'Sinistros, não são? Nunca vi isso antes, mas venho pegando vários deles o dia todo.', '', 19865),
(64102, 'ptBR', 'Vocês não vão tomar nossas terras!', 'Vocês não vão tomar nossas terras!', 19865),
(64103, 'ptBR', 'Vocês tão mexendo com o império errado!', 'Vocês tão mexendo com o império errado!', 19865),
(64104, 'ptBR', 'Essa terra é pra ser dos Zandalari!', 'Essa terra é pra ser dos Zandalari!', 19865),
(64105, 'ptBR', 'Nossos impérios irão tomar o que é nosso.', 'Nossos impérios irão tomar o que é nosso.', 19865),
(64106, 'ptBR', '|TInterface\\Icons\\spell_fire_volcano.blp:20|t%s começa a lançar |cFFFF0000|Hspell:125391|h[Linha de Fogo]|h|r!', '', 19865),
(64107, 'ptBR', 'Uma excrescência Âmbar se infiltra nas feridas de %s, recuperando sua vitalidade!', '', 19865),
(64108, 'ptBR', '%s sucumbe em uma pilha e morre repentinamente.', '', 19865),
(64109, 'ptBR', 'A estátua parece estar segurando alguma coisa...', '', 19865),
(64110, 'ptBR', 'Pegar o item da mão dele.', 'Pegar o item da mão dele.', 19865),
(64111, 'ptBR', 'CHEGA DE DESCULPAS, IMPERATRIZ! Elimine esses cretinos ou eu mesmo a matarei!', '', 19865),
(64112, 'ptBR', 'O Faz-guerra Qobi derrubou os machados. Pegue um!', '', 19865),
(64113, 'ptBR', '|TInterface\\Icons\\inv_misc_dust.blp:20|t%s começa a |cFFFF0000|Hspell:124359|h[Entocar]|h|r!', '', 19865),
(64114, 'ptBR', 'URRUUUUU!', '', 19865),
(64115, 'ptBR', 'Gostaria de curar e reviver meus mascotes de batalha.', 'Gostaria de curar e reviver meus mascotes de batalha.', 19865),
(64116, 'ptBR', 'O que você acha do meu bicho?', 'O que você acha do meu bicho?', 19865),
(64117, 'ptBR', 'Tenho uma tarefa pra você.', 'Tenho uma tarefa pra você.', 19865),
(64118, 'ptBR', 'Seus bárbaros, vocês vão pensar duas vezes antes de atacar nossa aldeia de novo!', '', 19865),
(64119, 'ptBR', '', 'Você VAI nos contar onde os restos estão escondidos!', 19865),
(64120, 'ptBR', 'Escolha uma dessas varas fabulosas e dê um puxão COM CUIDADO na linha. Isso deve ajudar a prender o anzol no que quer que esteja se debatendo na outra ponta.', '', 19865),
(64121, 'ptBR', 'Ora, isso é meio incomum... Cuide disso e depois dê um puxão em outra linha.', '', 19865),
(64122, 'ptBR', 'Grrr... seja lá o que for, é grande. Continue trabalhando bem as linhas e eu vou pousar essa belezoca!', '', 19865),
(64123, 'ptBR', 'O que... em nome de... Mazu... HRRGHHH!!', '', 19865),
(64124, 'ptBR', 'A cerveja dos sonhos que você experimentou mais cedo pode expandir a sua consciência e mostrar eventos que acontecem por entre essas terras. Vou lhe ensinar como utilizá-la adequadamente e encontraremos o seu príncipe!$b$bMas primeiro, me ajude a criar um lote fresco.', '', 19865),
(64125, 'ptBR', 'O Chefe de Convés disse que você precisava de ajuda.', 'O Chefe de Convés disse que você precisava de ajuda.', 19865),
(64126, 'ptBR', 'Uma boa cerveja dos sonhos é MUITO poderosa. Ela requer uma mente focada para conseguir qualquer tipo de clareza vinda das visões.', '', 19865),
(64127, 'ptBR', 'Agora, CENTRE-SE. Você pode se concentrar ou relaxar, mas, acima de tudo, fique no seu centro.', '', 19865),
(64128, 'ptBR', 'Ah, que bom. Vejo que você não se distrai fácil. Nós, pandarens, nos concentramos muito no momento, às vezes para nosso mal.', '', 19865),
(64129, 'ptBR', 'Desculpe, isso assustou você? Nós, pandarens, valorizamos a calma em quaisquer circunstâncias.', '', 19865),
(64130, 'ptBR', 'Que tal... AGORA?', '', 19865),
(64131, 'ptBR', 'Ora, veja só você! Um retrato da serenidade. Eu sabia que ia gostar de você.', '', 19865),
(64132, 'ptBR', 'Mung-Mung é um tolete grande e fedorento sem você! Mung-Mung está em débito contigo. Talvez você e Yoon não sejam tão masca-caca, afinal.', '', 19865),
(64133, 'ptBR', 'Sabe do que mais? Eu vou mostrar a eles que também posso me tornar um mestre fazendeiro!$B$BVou fazer com que essa fazenda seja uma das mais prósperas do vale!$B$BMas isso é muito trabalho para um pandaren só. O que você diz? Pode me ajudar?', '', 19865),
(64134, 'ptBR', 'O que você vai fazer, Fazendeiro Yoon?', 'O que você vai fazer, Fazendeiro Yoon?', 19865),
(64135, 'ptBR', 'Foi uma gentileza das grandes você ter me ajudado, $r. Estou em débito contigo.', '', 19865),
(64136, 'ptBR', 'Ei estranh$go:a;... Você tem alguma moeda para dar a um viajante com sede?', '', 19865),
(64137, 'ptBR', 'Paga um drinque prum peixe?', '', 19865),
(64138, 'ptBR', 'O que $Go:a; traz ao meu poço hoje, $girmão:irmã;?', '', 19865),
(64139, 'ptBR', 'As águas tão falando de boa sorte hoje, $n.', '', 19865),
(64140, 'ptBR', 'Ei camarada, tem umash moedash pra dar prum pobre jinyu?', '', 19865),
(64141, 'ptBR', 'Tô morrendo de sede, colega.', '', 19865),
(64142, 'ptBR', 'Amig$go:a; de jinyu, venha se sentar comigo um instante.', '', 19865),
(64143, 'ptBR', 'Ei amig$go:a;, poderia se sentar comigo e tomar uma cerveja?', '', 19865),
(64144, 'ptBR', 'Olha, é $gmeu bom amigo:minha grande amiga; $n! Estou me sentindo mais lúcido hoje. Talvez porque eu tenha cortado um pouco do goró.', '', 19865),
(64145, 'ptBR', 'Você sabe, decidi que gosto de você como amig$go:a;. Me faz pensar que posso ter outros amigos também.', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(64146, 'ptBR', 'As emoções negativas assumem um estranho poder aqui em Pandária. Mas isso você descobrirá na hora certa.', '', 19865),
(64147, 'ptBR', '', 'Realmente devo uma a vocês. Quer saber? Vou falar com o meu pai sobre deixar vocês fazerem parte do Sindicato dos Lavradores.', 19865),
(64148, 'ptBR', 'Isso – está sentindo? Sua alma em perfeito silêncio.', '', 19865),
(64149, 'ptBR', 'Ah não! Você agitou alguns caranguejos!', 'Ah não! Você agitou alguns caranguejos!', 19865),
(64150, 'ptBR', 'Ah não! Você agitou algumas aranhas!', 'Ah não! Você agitou algumas aranhas!', 19865),
(64151, 'ptBR', '', 'Nós viajamos para onde o vento nos leva, bondos$go:a; $r. Gostaria de ouvir um pouco?', 19865),
(64152, 'ptBR', '', 'Em nossas viagens, nós cantamos muitas músicas, mas existem muitas outras a serem cantadas.', 19865),
(64153, 'ptBR', 'Eu convoco asss águas de minha terra... TRAGAM MEUS INIMIGOS ATÉ MIM!', '', 19865),
(64154, 'ptBR', 'Meu povo e eu estamos estudando os rios e lagos das redondezas. Nunca antes vimos uma água tão revitalizante.', '', 19865),
(64155, 'ptBR', 'Achamos que as qualidades únicas da água no Vale são a razão principal da abundância na região.', '', 19865),
(64156, 'ptBR', 'A água nessa lagoa é bastante... horrível.', '', 19865),
(64157, 'ptBR', 'Infelizmente nosso irmão Be Bum não está bem desde que a família dele morreu.', '', 19865),
(64158, 'ptBR', 'Be Bum é de uma tribo diferente da nossa. Ele veio do norte, e não fala muito do que o trouxe até aqui.', '', 19865),
(64159, 'ptBR', 'Nosso irmão ali afoga as mágoas em apatia e vinho em vez de trabalho pesado.', '', 19865),
(64160, 'ptBR', 'Uau! Essa cerveja é bem forte!', '', 19865),
(64161, 'ptBR', 'Essa comida é deliciosa. Não quero sair daqui nunca.', '', 19865),
(64162, 'ptBR', 'O Mestre Jiying diz que temos que continuar nossa pesquisa, mas é bom relaxar de vez em quando.', '', 19865),
(64163, 'ptBR', '<O grande gato nem vira as orelhas para você, mesmo com você passando a mão entre os pelos dele.>', '', 19865),
(64164, 'ptBR', '<O pássaro enorme voa para longe de você.>', '', 19865),
(64165, 'ptBR', 'Nós tivemos sorte de encontrar esses outros sobreviventes da Horda. Eu não percebi que nossos irmãos tinham atracado em outros pontos desta terra.', '', 19865),
(64166, 'ptBR', 'Não sei, $r. Esses vegetaizões não tão com cara boa. Como é que eles podem comer isso desse jeito? Onde é que tá a CARNE?', '', 19865),
(64167, 'ptBR', '', 'Dezco nos enviou na frente para conhecermos a região. Talvez tenhamos encontrado um caminho para a grande cura que apareceu na visão de Leza.', 19865),
(64168, 'ptBR', '', 'Os nativos insistem que as grandes águas curativas que procuramos estão numa... Cervejaria Malte do Trovão. Acho que teremos que investigar isso.', 19865),
(64169, 'ptBR', '', 'Esse troll reclama da comida, mas ele come mais que todo mundo!', 19865),
(64170, 'ptBR', '', 'Você viu a muralha a oeste? Eu me pergunto o que deve ter do outro lado dela.', 19865),
(64171, 'ptBR', '', 'Todas as coisas aqui... tudo tão... tão... diferente!', 19865),
(64172, 'ptBR', 'O Almirante Taylor nos enviou aqui para procurar o jovem príncipe. Você sabia que eles fabricam CERVEJA aqui?', '', 19865),
(64173, 'ptBR', 'Estamos dando duro atrás do príncipe Anduin. Só paramos pra comer e beber alguma coisa.', '', 19865),
(64174, 'ptBR', 'Eles dizem que existe mais de cinco mil cervejas em Pandária. Eu não vou embora daqui enquanto não experimentar todas!', '', 19865),
(64175, 'ptBR', 'Pegue uma bebida e junte-se a nós, $r!', '', 19865),
(64176, 'ptBR', '', 'Eu adoro ouvir Kol falando sobre receitas deliciosas. Eu não sabia que havia tantas maneiras de grelhar carne.', 19865),
(64177, 'ptBR', '', 'Você já experimentou a comida do Kol? Eu não consigo parar de comer.', 19865),
(64178, 'ptBR', '', 'Ele sempre diz que gosta do meu sotaque, e eu vivo perguntando: que sotaque?', 19865),
(64179, 'ptBR', 'Ei, $c, olha só você por aqui! Também foi $genviado:enviada; para procurar o jovem príncipe?', '', 19865),
(64180, 'ptBR', 'Os nativos tem um estilo de vida idílico. Faz eu me perguntar se deferia aposentar a varinha e pegar na enxada.', '', 19865),
(64181, 'ptBR', 'Sou um negociante de varinhas por vocação. Para sua sorte – e minha –, a maior parte das minhas varinhas sobreviveu ao naufrágio!', '', 19865),
(64182, 'ptBR', 'Um homem sábio descansa quando está cansado.', '', 19865),
(64183, 'ptBR', 'A melhor cerveja de toda Pandária é feita bem aqui no Vale, na Cervejaria Malte do Trovão.$b$bBem, pelo menos eu acho.', '', 19865),
(64184, 'ptBR', 'Encha seu copo de alegria e você beberá alegria. Encha seu copo de tristeza e você beberá tristeza.$b$bEscolha a sua cerveja com sabedoria, meu amigo.', '', 19865),
(64185, 'ptBR', 'Aaaahhh, eu acredito que felicidade é ter a barriga cheia.$b$bEncha a barriga de comida boa e encherá sua alma de calor.', '', 19865),
(64186, 'ptBR', 'É bom poder aproveitar as frutas da terra, mas não exagere.', '', 19865),
(64187, 'ptBR', 'A maior sorte do mundo para você, $r! Meu irmão e eu viemos de muito longe para compartilhar seus sorte-sims!', '', 19865),
(64188, 'ptBR', 'Muita boa sorte para você, $r! Meu irmão e eu viemos de muito longe para compartilhar nossos sorte-sins!', '', 19865),
(64189, 'ptBR', 'Grômulos possuem bom olfato. Podem dizer a diferença entre boa e má sorte pelo cheiro. Você tem cheirinho de boa sorte.', '', 19865),
(64190, 'ptBR', 'Por favor, vamos manter a civilidade enquanto somos convidados aqui. Eu suspeito que nossos anfitriões não reagirão bem a derramamento de sangue.', '', 19865),
(64191, 'ptBR', 'Não sei, $r. Esses vegetaizões não tão com cara boa. Como é que eles podem comer isso desse jeito? Onde é que tá a CARNE?', '', 19865),
(64192, 'ptBR', '', 'Não vamos derramar sangue num lugar tão bonito, $girmão:irmã;.', 19865),
(64193, 'ptBR', '', 'Nossa busca nos levou por vastos oceanos e selvas profundas, e no entanto viemos nos encontrar aqui, entre tantos lugares. Parece que nosso conflito é inevitável, não importa onde nós vamos.', 19865),
(64194, 'ptBR', '', 'Estou de olho em você, $r.', 19865),
(64195, 'ptBR', 'Ei, feios$go:a;, eu te daria um soco agora mesmo... se eu achasse que poderia te acertar! De qualquer jeito, você sabia que eles fazem CERVEJA por aqui?', '', 19865),
(64196, 'ptBR', 'Invés de derramarmos sangue, que tal apaziguarmos nossas diferenças... em uma batalha de DANÇA?', '', 19865),
(64197, 'ptBR', '', 'Calma aí, aqui não é lugar de começar briga. Senão ninguém vai aproveitar essa comida.', 19865),
(64198, 'ptBR', 'Ei, $r, não tente nada esquisito! Eu tenho um monte de varinhas nas mangas e não tenho medo de usá-las!', '', 19865),
(64199, 'ptBR', '', 'Música faz bem à mente, ao corpo e à alma!', 19865),
(64200, 'ptBR', 'Está aqui para aproveitar a vista?', 'Está aqui para aproveitar a vista?', 19865),
(64201, 'ptBR', 'Pode sentir o cheiro do vento, estranh$go:a;? Ele traz mudanças.', 'Pode sentir o cheiro do vento, estranh$go:a;? Ele traz mudanças.', 19865),
(64202, 'ptBR', 'Daqui, nós meditamos sobre as maravilhas de Pandária.', 'Daqui, nós meditamos sobre as maravilhas de Pandária.', 19865),
(64203, 'ptBR', 'Quando estiver perto do precipício, não se esqueça de respirar.', 'Quando estiver perto do precipício, não se esqueça de respirar.', 19865),
(64204, 'ptBR', 'Bem-vind$go:a; ao Mirante da Serpente. Por acaso você trouxe uma pipa?', 'Bem-vind$go:a; ao Mirante da Serpente. Por acaso você trouxe uma pipa?', 19865),
(64205, 'ptBR', 'Os fazendeiros dos campos ao redor trazem trigo, e nós moemos todos os tipos de grão aqui.$b$bAlguns dos grãos serão transformados em comida, outros vendidos, mas a maior parte é enviada para a Cervejaria Malte do Trovão para... isso mesmo... cerveja!', '', 19865),
(64206, 'ptBR', 'Esse é um lugar de paz. Nós observamos, nós meditamos, nós trabalhamos em nossos artesanatos e nós estamos contentes.', 'Esse é um lugar de paz. Nós observamos, nós meditamos, nós trabalhamos em nossos artesanatos e nós estamos contentes.', 19865),
(64207, 'ptBR', 'Você já esteve em Flor da Manhã? Por acaso você pegou um barril extra de Áurea Cevada enquanto esteve por lá?$b$bNão é muito fácil conseguir que entreguem aqui.', 'Você já esteve em Flor da Manhã? Por acaso você pegou um barril extra de Áurea Cevada enquanto esteve por lá?$b$bNão é muito fácil conseguir que entreguem aqui.', 19865),
(64208, 'ptBR', 'A Serpente de Jade! Ela... ela quebrou.', 'A Serpente de Jade! Ela... ela quebrou.', 19865),
(64209, 'ptBR', '', 'Eu disse ao meu filho, eu disse Dion, não leve os iaques ao campo quando estiver chovendo. E o que ele fez? Ele levou os iaques ao campo quando estava chovendo.$b$bNão é surpresa nenhuma que agora todos os iaques estejam doentes!$b$bAhhh! Como eu fui criar um filho tão desobediente?', 19865),
(64210, 'ptBR', '', 'Meu filho não come o suficiente. Olhe só para ele! Tão mirrado e magriço! Eu tenho que dar mais comida a ele.', 19865),
(64211, 'ptBR', '', 'Por que meu filho tem que ser tão pequeno? Eu queria um filho alto e forte.$b$bEu disse pra ele não deixar ninguém pular por cima dele quando ele era filhote. Avisei que ele ia ficar baixinho.$b$bE o que ele faz? Deixa todo mundo pular por cima dele! O dia todo! Aff!', 19865),
(64212, 'ptBR', '', 'Meu filho Dion disse que a mamãe faz o melhor bolinho de todo o vale!$b$bOooohohohohoh. Esse é o meu menino.', 19865),
(64213, 'ptBR', '', 'Mamãe adora laranja, mas elas são difíceis de encontrar no vale.$b$bEu pedi ao meu filho que comprasse algumas laranjas no mercado, e então lhe dei umas moedas de bronze.$b$bO que ele fez? Me compra uns feijões!$b$bNós não somos fazendeiros! Somos pastores de iaque! O que eu faço com esses feijões agora, me diz aí?', 19865),
(64214, 'ptBR', 'Os hozens e os jinyus sempre brigaram, mas nunca dessa forma...', 'Os hozens e os jinyus sempre brigaram, mas nunca dessa forma...', 19865),
(64215, 'ptBR', '', 'Meu filho Dion está no campo o dia inteiro. Ele trabalha muito. Ele deixa a Mamãe orgulhosa.', 19865),
(64216, 'ptBR', 'A Serpente de Jade... o que ela fará agora?', 'A Serpente de Jade... o que ela fará agora?', 19865),
(64217, 'ptBR', 'O que isso significa? O fim da paz em Pandária? Estamos amaldiçoados?', 'O que isso significa? O fim da paz em Pandária? Estamos amaldiçoados?', 19865),
(64218, 'ptBR', '', 'Você veio ver a Mamãe? Ah, sente um pouco!$b$bDeixa eu te falar, ouvi uma fofoca outro dia.$b$bOuvi dizer que Gina Garra de Barro e o pai dela, Haohan Garra de Barro, não se dão bem!$b$bEle queria casar a menina com o Fazendeiro Fung à força, mas ela não aceitou! Ela preferia tocar o mercadinho dela, ela disse.$b$bÓ só! Essas meninas de hoje em dia, todas perdidas, né? Não querem se casar com um jovem bonito e fazer família.$b$bPrincipalmente aquele Fung... um partidão! Tão bonito, e planta uns vegetais tão grandões...$b$bPor que eu não tenho um filho tão bonitão assim?!', 19865),
(64219, 'ptBR', '', 'Ah, quando meu filho vai conhecer uma mocinha de boa família? Tudo o que ele faz é ficar com esses iaques o dia inteiro!$b$bQue garota vai querer um iaqueiro xexelento, hein? Ai ai, Mamãe se preocupa tanto...', 19865),
(64220, 'ptBR', '', 'Ah, olá, $r!$b$bAqui é onde mantemos toda a nossa história e nosso conhecimento agrícola.$b$bTemos registros do clima local e resultados de colheitas, notas detalhadas de toda e qualquer semente e planta que cresce no vale e até mesmo um banco de sementes para todas as plantas que nós podemos um dia precisar plantar.$b$bEsse conhecimento é sagrado para nós. Se um desastre algum dia atingir essa terra, nossas sementes devem ser salvas.', 19865),
(64221, 'ptBR', 'Opa, como vamos, viajante? Estou trabalhando pesado na minha próxima obra-prima!', '', 19865),
(64222, 'ptBR', 'A estátua da Serpente de Jade foi destruída? Como isso pode ter acontecido?', 'A estátua da Serpente de Jade foi destruída? Como isso pode ter acontecido?', 19865),
(64223, 'ptBR', '', 'Você também não ama olhar os passarinhos? Eu gostaria de poder voar...', 19865),
(64224, 'ptBR', '', 'Os fazendeiros rezam pela chuva, mas não eu! É horrível para os negócios. Olha só o mercado! Está encharcado!', 19865),
(64225, 'ptBR', '', 'Está chovendo iaques e mushans hoje! Bem, eu tenho um mercado para cuidar, com chuva ou sol!', 19865),
(64226, 'ptBR', 'Olhe o céu, $n! Está chovendo! Deve ser bom para as plantações, né?', '', 19865),
(64227, 'ptBR', 'Uau, olha só essa tempestade! Bem, plantação gosta de água, certo?', '', 19865),
(64228, 'ptBR', 'A estátua da Serpente de Jade foi destruída? Como isso pode ter acontecido?', 'A estátua da Serpente de Jade foi destruída? Como isso pode ter acontecido?', 19865),
(64229, 'ptBR', 'O que é esse "sha"? De onde ele vem?', 'O que é esse "sha"? De onde ele vem?', 19865),
(64230, 'ptBR', 'Você vai nos ajudar a curar a terra?', 'Você vai nos ajudar a curar a terra?', 19865),
(64231, 'ptBR', 'Pobres hozens e jinyus! Sabíamos que eles não se davam bem, mas chegar a esse ponto...', 'Pobres hozens e jinyus! Sabíamos que eles não se davam bem, mas chegar a esse ponto...', 19865),
(64232, 'ptBR', 'Todos os jinyus e hozens pereceram naquela batalha? Há sobreviventes?', 'Todos os jinyus e hozens pereceram naquela batalha? Há sobreviventes?', 19865),
(64233, 'ptBR', 'Você nos ajudará a lutar contra o sha?', 'Você nos ajudará a lutar contra o sha?', 19865),
(64234, 'ptBR', 'Tanto... perdido.$b$bE temo, $n, que este seja apenas o começo.', '', 19865),
(64235, 'ptBR', 'Eu não tenho nada pra falar com você. Só vou falar com $p.', '', 19865),
(64236, 'ptBR', 'Ãhn? O que você disse?', '', 19865),
(64237, 'ptBR', '', 'Nós vamos ver um tubarão?', 19865),
(64238, 'ptBR', 'Se houver tempo.', '', 19865),
(64239, 'ptBR', 'O baú antigo está coberto de poeira...', '', 19865),
(64240, 'ptBR', '', 'Aonde nós vamos?', 19865),
(64241, 'ptBR', '', 'Está na hora de pegar o peixe no mercado.', 19865),
(64242, 'ptBR', '', 'Falta muito?', 19865),
(64243, 'ptBR', 'Estamos quase chegando. Só falta mais um pouco.', '', 19865),
(64244, 'ptBR', '', 'Me carrega, papai?', 19865),
(64245, 'ptBR', 'Não, doçura. Preciso de você com pernas fortes e boas. Você quer ser forte como eu um dia, não é?', '', 19865),
(64246, 'ptBR', '', 'UAU! Eu não sabia que era assim aqui atrás.', 19865),
(64247, 'ptBR', '', 'Oohhhh, não é medonho? Você acha que tem fantasma aqui?', 19865),
(64248, 'ptBR', '', 'Eeeeeeeca! O que é ESSA COISA?', 19865),
(64249, 'ptBR', '', 'Aqui está! O tesouro do Velho Cardo!', 19865),
(64250, 'ptBR', '', 'Wooooowwwww!', 19865),
(64251, 'ptBR', '', 'Pelos funis saltitantes! Nós achamos! Nós realmente achamos! É o tesouro esquecido do Velho Cardo! Rapaz, rapaz, rapaz!!!', 19865),
(64252, 'ptBR', '', 'A donzela? Humm, eu lembro que era assim que meu pai costumava chamar aquele rio ao norte. Fora isso, não tenho a menor ideia.', 19865),
(64253, 'ptBR', 'O que ecoa e é escuro? É simples! Uma caverna!', '', 19865),
(64254, 'ptBR', 'Hummm, eu simplesmente não sei, $r. Tudo o que posso entender é a parte sobre o vale – que é aqui! O Vale dos Quatro Ventos!', '', 19865),
(64255, 'ptBR', 'Ah, eu OUVI falar da escadaria dos ancestrais. É como o pessoal chama as montanhas ao norte.', '', 19865),
(64256, 'ptBR', 'Você pode fazer alguma coisa com essas pistas?', 'Você pode fazer alguma coisa com essas pistas?', 19865),
(64257, 'ptBR', 'Já ouviu falar de uma donzela rindo atrás de um leque?', 'Já ouviu falar de uma donzela rindo atrás de um leque?', 19865),
(64258, 'ptBR', 'Ondo encontro a escadaria dos ancestrais?', 'Ondo encontro a escadaria dos ancestrais?', 19865),
(64259, 'ptBR', 'Onde alguém pode sussurrar segredos na escuridão ecoante?', 'Onde alguém pode sussurrar segredos na escuridão ecoante?', 19865),
(64260, 'ptBR', 'Acha que consegue me encarar? A maioria das garotas odeia cobras, mas eu acho que elas são fofas!', 'Acha que consegue me encarar? A maioria das garotas odeia cobras, mas eu acho que elas são fofas!', 19865),
(64261, 'ptBR', 'Minha família e eu estamos trazendo peixe fresco dos Pescadores para a cidade. Gostaria de comprar alguns?', '', 19865),
(64262, 'ptBR', '', 'É uma longa caminhada da cidade até Sri-La, mas faz bem ao espírito. E certamente ajuda a trazer o pequeno Aerial para um pouco de ar livre.', 19865),
(64263, 'ptBR', '', 'Eu não devo falar com estranhos.', 19865),
(64264, 'ptBR', '5.0 Culinária - Culinária Estudante Padrão 1', '', 19865),
(64265, 'ptBR', '', 'Está vendo aquele peixão ali embaixo, $n?', 19865),
(64266, 'ptBR', '', 'Não tenta me enganar! Meu pai sempre disse que tenho olhos nas costas!', 19865),
(64267, 'ptBR', '', 'Qui queu posso fazê procê, $n?', 19865),
(64268, 'ptBR', '', 'Uebaaaaaaaaaa!! Eu ainda não acredito que encontramos o tesouro do Velho Cardo. Eu acho que todas essas histórias não eram verdade afinal, mas eu gosto de contá-las mesmo assim!', 19865),
(64269, 'ptBR', 'Me conte a história do Velho Cardo.', 'Me conte a história do Velho Cardo.', 19865),
(64270, 'ptBR', '', 'Agora, eles dizem que quem quer que coloque a mão naquele mapa poderá encontrar o tal tesouro perdido...', 19865),
(64271, 'ptBR', 'Ah sim? Conte-me mais.', 'Ah sim? Conte-me mais.', 19865),
(64272, 'ptBR', 'Agora vá, transmita minhas técnicas para os iniciantes.', '', 19865),
(64273, 'ptBR', 'Não toleraremos aqueles que liberaram o sha em nossa terra.', '', 19865),
(64274, 'ptBR', 'Nós prendemos o sha novamente, e a sua espécie cairá perante a nós da mesma forma.', '', 19865),
(64275, 'ptBR', 'Uma vez eu vi um peixe tão grande que você poderia jurar que era um tubarão. Imagina só...', '', 19865),
(64276, 'ptBR', 'Você, um pescador? Com esses braços pelancudos e essa armadura pesada?', '', 19865),
(64277, 'ptBR', 'Bem-vind$go:a; à costa de Pandária! Onde tudo que pode aparecer boiando até a costa já apareceu ou aparecerá!', '', 19865),
(64278, 'ptBR', 'Que tipo de isca você usa? Eu conheci um pandaren uma vez que usava o seu próprio braço como isca.$b$bA gente chamava ele de Faz-lámen.$b$bDizem que ele se aposentou e foi para o sul.', '', 19865),
(64279, 'ptBR', 'Você já viu um kraken? O Venho Jin diz já ter conseguido pescar um, uma vez, mas deixou ir porque parecia ter um gosto muito "rústico".$b$bA gente tem uma aposta em andamento: será que ele vai achar outro algum dia?', '', 19865),
(64280, 'ptBR', 'E aí, como são os peixes no lugar de onde você vem?', '', 19865),
(64281, 'ptBR', 'Normalmente essas praias são cobertas de névoas. Parece que elas ficaram limpas por algum motivo.', '', 19865),
(64282, 'ptBR', '', 'Eu conheci um monge uma vez que era especializado em um estilo de luta-pesca. Era bastante limitado, mas ele conseguia fazer um ensopado de peixe incrível.', 19865),
(64283, 'ptBR', '', 'Nov$go:a; por aqui? É como falamos para as crianças: não entre na água sem um punhado de iscas e uma estratégia de fuga.', 19865),
(64284, 'ptBR', '', 'Uma das crianças jura por tudo que há de sagrado que viu uma mistura de tubarão com polvo outro dia.$b$bEu sei que existem muitas coisas estranhas no oceano, mas isso parece louco demais para mim.', 19865),
(64285, 'ptBR', '', 'Você provavelmente viu os navios naufragados nas nossas praias. Algum desses seria o seu?$b$bAs névoas muitas vezes nos trazem uns "presentes" assim.', 19865),
(64286, 'ptBR', '', 'Os Cavalga-serpentes enviaram você? Aquelas serpentes continuam roubando nossas melhores pescas.', 19865),
(64287, 'ptBR', '', 'Pesque aqui por tempo suficiente e você verá de tudo. Uma vez, vi uma morsa com pernas e braços. E ainda por cima ela também falava!', 19865),
(64288, 'ptBR', '', 'Como é o mar lá nas suas bandas?', 19865),
(64289, 'ptBR', '', 'Eu muitas vezes fico pensando sobre os jinyus daqui. Mas eles sabem como pescar e melhor que o resto de nós, então quem sou eu para julgar.', 19865),
(64290, 'ptBR', 'Você é o meu professor favorito da vida toda!', 'Você é a minha professora favorita da vida toda!', 19865),
(64291, 'ptBR', 'Quando eu crescer, quero ser o melhor chef de Pandária!', 'Quando eu crescer, quero ser a melhor chef de Pandária!', 19865),
(64292, 'ptBR', '', 'Uau, isso é tão legal! Uma caçada ao tesouro na vida real!', 19865),
(64293, 'ptBR', 'Você não acha que eu serei um ótimo cozinheiro?', 'Você não acha que eu serei uma ótima cozinheira?', 19865),
(64294, 'ptBR', 'O que vamos aprender agora?', 'O que vamos aprender agora?', 19865),
(64295, 'ptBR', 'Eu faço o possível para ser um bom estudante.', 'Eu faço o possível para ser uma boa estudante.', 19865),
(64296, 'ptBR', '', 'Aquela coisa é realmente muito assustadora. Você salvou nossas vidas, $n!', 19865),
(64297, 'ptBR', 'Fofoca - Opção 1 - Teste - HW', 'Fofoca - Opção 1 - Teste - HW', 19865),
(64298, 'ptBR', 'Fofoca - Opção 2 - Teste - HW', 'Fofoca - Opção 2 - Teste - HW', 19865),
(64299, 'ptBR', '', 'Então... quer falar sobre isso?', 19865),
(64300, 'ptBR', 'Não.', '', 19865),
(64301, 'ptBR', '', 'Tem certeza? Ouvi dizer que acontece com todo mundo em algum momento.', 19865),
(64302, 'ptBR', 'Reles aprendizes.', '', 19865),
(64303, 'ptBR', 'Deviam ter treinado mais.', '', 19865),
(64304, 'ptBR', 'Uma só técnica não é o suficiente.', '', 19865),
(64305, 'ptBR', 'Eles falharam no teste. Você também falhará?', '', 19865),
(64306, 'ptBR', 'Eles se aproximam? Ótimo. Que pena que meus alunos não estejam aqui para aprender com a minha exibição de destreza marcial...', '', 19865),
(64307, 'ptBR', '', 'Conseguimos sair vivos! Rapaz, rapaz, espera até nossos amigos ouvirem isso! Eles não vão acreditar! Te vejo mais tarde, $n!', 19865),
(64308, 'ptBR', '', 'Isso é... impressionante, $n! Essas anotações oferecem conhecimentos inestimáveis para nossos fazendeiros. Nós estamos em débito com o Velho Cardo por manter tais registros, e com você por recuperá-los. Obrigada!', 19865),
(64309, 'ptBR', 'Você foi afetado pela |cFFFF0404|Hspell:116417|h[Ressonância Arcana]|h|r !', 'Você foi afetado pela |cFFFF4809|Hspell:116417|h[Ressonância Arcana]|h|r !', 19865),
(64310, 'ptBR', 'O Salta-Névoa Jr. está nas docas a sudeste daqui. Vamos!', '', 19865),
(64311, 'ptBR', 'Vá para o canhão arpoardor!', '', 19865),
(64312, 'ptBR', 'Mire nos sacos de flutuação que estão na proa, a bombordo e estibordo e na popa...', '', 19865),
(64313, 'ptBR', 'Err... desculpe... deixe eu me explicar melhor.', '', 19865),
(64314, 'ptBR', 'Atire na cara daquela coisa! E dos lados! E no traseiro! Entendeu? As partes moles!', '', 19865),
(64315, 'ptBR', 'Belo tiro!', '', 19865),
(64316, 'ptBR', 'Ha ha, e que tal essa, sua lula velhusca?', '', 19865),
(64317, 'ptBR', 'Mazu, guie meu braço...', '', 19865),
(64318, 'ptBR', 'HURGHH!!!', '', 19865),
(64319, 'ptBR', 'Continue assim!', '', 19865),
(64320, 'ptBR', 'É isso aí! Volta lá pro fundo!', '', 19865),
(64321, 'ptBR', 'Acho que ele tá vazando!', '', 19865),
(64322, 'ptBR', 'Isso sim é arpoaria de qualidade!', '', 19865),
(64323, 'ptBR', 'Mais visitantes! Ah.', '', 19865),
(64324, 'ptBR', 'Não sei ao certo como cheguei aqui. Mas... a boa sorte favorece os de mente aberta.', '', 19865),
(64325, 'ptBR', '', 'Nunca subestime a importância da cura.', 19865),
(64326, 'ptBR', '', 'A cura mudou a maré de muitas batalhas.', 19865),
(64327, 'ptBR', '', 'Bem-vind$go:a; ao Refúgio Pata de Trovão. Aqui nós praticamos nossa arte de cura através da focalização do chi.', 19865),
(64328, 'ptBR', '', 'Se existe uma coisa na vida que se pode aprender é que sempre há mais a aprender.', 19865),
(64329, 'ptBR', 'Bem-vind$go:a; ao Refúgio Pata de Trovão. Não deixe a armadura lhe enganar. Nós treinamos a cura por aqui.', 'Bem-vind$go:a; ao Refúgio Pata de Trovão. Não deixe a armadura lhe enganar. Nós treinamos a cura por aqui.', 19865),
(64330, 'ptBR', 'As coisas são bem calmas por aqui normalmente. Nós só temos problemas com os grupos de caça dos sauroks, de vez em quando. E os sauroks tendem a aparecer apenas durante tempestades fortes.', 'As coisas são bem calmas por aqui normalmente. Nós só temos problemas com os grupos de caça dos sauroks, de vez em quando. E os sauroks tendem a aparecer apenas durante tempestades fortes.', 19865),
(64331, 'ptBR', 'Você conheceu a Mestra Cervejeira Blanche? Ela vagueia pelas estradas ao sul e leste daqui. Ela é conhecida por nos visitar com algumas das melhores cervejas que produz.', 'Você conheceu a Mestra Cervejeira Blanche? Ela vagueia pelas estradas ao sul e leste daqui. Ela é conhecida por nos visitar com algumas das melhores cervejas que produz.', 19865),
(64332, 'ptBR', 'Estou tentando aprender como curar. O problema é que você precisa se machucar para poder ser curado.', 'Estou tentando aprender como curar. O problema é que você precisa se machucar para poder ser curado.', 19865),
(64333, 'ptBR', 'Alguém estava dizendo que eu estava "curando demais" no outro dia. Isso me deu um nó na cabeça.', 'Alguém estava dizendo que eu estava "curando demais" no outro dia. Isso me deu um nó na cabeça.', 19865),
(64334, 'ptBR', 'Estou aprendendo como diminuir a dor de alguém. Bacana, né?', 'Estou aprendendo como diminuir a dor de alguém. Bacana, né?', 19865),
(64335, 'ptBR', 'Não posso falar. Preciso me... concentrar.', 'Não posso falar. Preciso me... concentrar.', 19865),
(64336, 'ptBR', 'Eu não sabia que existiam tantas formas de se preparar chá.', 'Eu não sabia que existiam tantas formas de se preparar chá.', 19865),
(64337, 'ptBR', 'Mal... Mal posso respirar. Devo minha vida a você.', 'Mal... Mal posso respirar. Devo minha vida a você.', 19865),
(64338, 'ptBR', 'Pobre Ninito... sua andança inquieta finalmente teve um fim.', '', 19865),
(64339, 'ptBR', 'Eles vieram sem fazer alarde. Não havia nada que os guardas pudessem ter feito.', 'Eles vieram sem fazer alarde. Não havia nada que os guardas pudessem ter feito.', 19865),
(64340, 'ptBR', 'Parece que existe perigo em viver em um lugar tão bonito...', 'Parece que existe perigo em viver em um lugar tão bonito...', 19865),
(64341, 'ptBR', 'Os mogus não vão nos espantar daqui. Este é o nosso lar agora.', 'Os mogus não vão nos espantar daqui. Este é o nosso lar agora.', 19865),
(64342, 'ptBR', 'Sobrevivi graças a você... Não vou me esquecer disso.', 'Sobrevivi graças a você... Não vou me esquecer disso.', 19865),
(64343, 'ptBR', 'Eu conheço você! Você salvou meu irmão há menos de uma semana! Você é um verdadeiro herói!', 'Eu conheço você! Você salvou meu irmão há menos de uma semana! Você é uma verdadeira heroína!', 19865),
(64344, 'ptBR', 'Eu achei que era o fim... que eu ia morrer. Obrigado.', 'Eu achei que era o fim... que eu ia morrer. Obrigada.', 19865),
(64345, 'ptBR', 'Espere! Alguém hostil se aproxima!', '', 19865),
(64346, 'ptBR', 'Um dos outros iniciados fez uma pegadinha comigo no outro dia. Ele disse que eu devia cheirar um pouco da "névoa curativa" dele. Não tinha nada de curativa aquela névoa dele.', 'Um dos outros iniciados fez uma pegadinha comigo no outro dia. Ele disse que eu devia cheirar um pouco da "névoa curativa" dele. Não tinha nada de curativa aquela névoa dele.', 19865),
(64347, 'ptBR', 'Inimigos se aproximam!', '', 19865),
(64348, 'ptBR', 'Eu lhe devo a minha vida.', 'Eu lhe devo a minha vida.', 19865),
(64349, 'ptBR', 'Estou do seu lado, amig$go:a;.', 'Estou do seu lado, amig$go:a;.', 19865),
(64350, 'ptBR', 'Você merece minha ajuda. Para onde?', 'Você merece minha ajuda. Para onde?', 19865),
(64351, 'ptBR', 'Prepare-se para a batalha, Arauto!', '', 19865),
(64352, 'ptBR', 'Obrigado.', 'Obrigado.', 19865),
(64353, 'ptBR', 'Você tem meu agradecimento, amigo$go:a;. Deixe-me lutar ao seu lado.', 'Você tem meu agradecimento, amigo$go:a;. Deixe-me lutar ao seu lado.', 19865),
(64354, 'ptBR', 'Tempo demais nesta jaula. Vou mostrar a esses mogus o que eu acho do cativeiro deles...', 'Tempo demais nesta jaula. Vou mostrar a esses mogus o que eu acho do cativeiro deles...', 19865),
(64355, 'ptBR', 'Ainda bem que você me salvou a tempo, $gherói:heroína;.', 'Ainda bem que você me salvou a tempo, $gherói:heroína;.', 19865),
(64356, 'ptBR', 'A defesa do vale nunca irá se render!', 'A defesa do vale nunca irá se render!', 19865),
(64357, 'ptBR', 'Hummmm! Tô sentindo o cheiro de uma ovelha deliciosa!', '', 19865),
(64358, 'ptBR', 'Vida longa ao Lótus Dourado!', 'Vida longa ao Lótus Dourado!', 19865),
(64359, 'ptBR', 'Pela vontade dos Celestiais!', 'Pela vontade dos Celestiais!', 19865),
(64360, 'ptBR', 'Hora de beliscar uma carne de ovelha!', '', 19865),
(64361, 'ptBR', 'Permaneceremos juntos. Nós não vamos cair!', 'Permaneceremos juntos. Nós não vamos cair!', 19865),
(64362, 'ptBR', 'O Lótus Dourado nunca se renderá.', 'O Lótus Dourado nunca se renderá.', 19865),
(64363, 'ptBR', 'O vale nunca cairá nas mãos dos mogus!', 'O vale nunca cairá nas mãos dos mogus!', 19865),
(64364, 'ptBR', 'Os Shao-Tiens marcham para a morte!', 'Os Shao-Tiens marcham para a morte!', 19865),
(64365, 'ptBR', 'Rendam-se ou morram!', 'Rendam-se ou morram!', 19865),
(64366, 'ptBR', 'A sua postura está errada. Seu pé está totalmente desequilibrado. Sua cabeça está muito virada.$b$bVolte aqui quando tiver aprendido tudo o que pode aprender.', '', 19865),
(64367, 'ptBR', 'Você vai queimar sob o poder dos Shao-Tien!', 'Você vai queimar sob o poder dos Shao-Tien!', 19865),
(64368, 'ptBR', 'Nós vamos cobrir o vale com os seus corpos ensanguentados!', 'Nós vamos cobrir o vale com os seus corpos ensanguentados!', 19865),
(64369, 'ptBR', 'Seus olhos não podem ver o que está bem na sua frente. Sem dúvida é resultado de seus péssimos hábitos alimentares.', '', 19865),
(64370, 'ptBR', 'A sua alma será minha para tortura eterna!', 'A sua alma será minha para tortura eterna!', 19865),
(64371, 'ptBR', 'O retorno do Imperador irá amaldiçoar toda a sua raça!', 'O retorno do Imperador irá amaldiçoar toda a sua raça!', 19865),
(64372, 'ptBR', 'Vou espremer a vida do seu crânio!', 'Vou espremer a vida do seu crânio!', 19865),
(64373, 'ptBR', 'Vou cravar sua cabeça numa lança, $r!', 'Vou cravar sua cabeça numa lança, $r!', 19865),
(64374, 'ptBR', 'Nem a morte vai libertar você do meu poder!', 'Nem a morte vai libertar você do meu poder!', 19865),
(64375, 'ptBR', 'Sua luta é inútil e lamentável!', 'Sua luta é inútil e lamentável!', 19865),
(64376, 'ptBR', 'Você se move como uma iaque prenha. Você não está pront$go:a; para ser treinad$go:a; aqui.', '', 19865),
(64377, 'ptBR', 'Para correr na água, é preciso correr muito rápido.', '', 19865),
(64378, 'ptBR', '', 'Os Shao-Tien se interessaram bastante por essas ruínas. Eles pretendem recuperar o poder dessas profundezas. Eu pretendo espalhar os corpos deles por toda parte.', 19865),
(64379, 'ptBR', '', 'Esses aprendizes são fracos. Não estão prontos para caminharem no muro, muito menos para enfrentar mantídeos ou mogus cara a cara. Precisamos de algum tempo até podermos realmente depender deles.', 19865),
(64380, 'ptBR', '', 'Todos nós servimos Leven em excursões além da muralha. Nós afiamos nossas espadas em inúmeros mantídeos e yaungóis. Esses mogus acham que somos fracos, mas esse erro de julgamento custará muito para eles.', 19865),
(64381, 'ptBR', 'Colocar os pés no Ermo do Medo me ensinou como é importante conhecer o terreno e compreender os movimentos do inimigo. Seja o objetivo a vitória ou apenas a sobrevivência, a melhor rota é sempre estar dois passos a frente do oponente.', '', 19865),
(64382, 'ptBR', 'Pode ser difícil para um veterano endurecido se acostumar a uma vida mais calma, mas é nosso dever. Esses camponeses não desejam guerra, portanto nós não a traremos à porta deles se pudermos evitar.', '', 19865),
(64383, 'ptBR', 'Ele não é magnífico?', '', 19865),
(64384, 'ptBR', 'Tantas bocas para alimentar, e sem ingredientes suficiente para alimentá-las!', '', 19865),
(64385, 'ptBR', 'Venha até mim, Kovok.', '', 19865),
(64386, 'ptBR', 'Um dos meus ancestrais teve parte na revolta no Tu Shen, e agora descansa em uma cova. Gostaria de mostrar meu respeito, se pudesse, mas os espíritos ali não conhecem a paz.', '', 19865),
(64387, 'ptBR', 'É importante que os aprendizes conheçam a dor da derrota, para que possam apreciar o valor da vitória.', '', 19865),
(64388, 'ptBR', '<He olha para você severamente.>', '', 19865),
(64389, 'ptBR', '<Os olhos de He se acendem ao que você se aproxima.>', '', 19865),
(64390, 'ptBR', '<He olha para você sem expressão.>', '', 19865),
(64391, 'ptBR', 'Eu gosto de pensar que sou como o cérebro e a beleza nessa operação. Anji é o músculo. E a segunda metade da beleza.$b$bNós temos muita beleza.', '', 19865),
(64392, 'ptBR', 'Eu não amo aranhas. Ou estátuas que se movem. Ou duendes que roubam coisas. Existem muitas coisas que eu não gosto nessas ruínas. Mas, felizmente, Anji está aqui para manter minha beleza intacta!', '', 19865),
(64393, 'ptBR', 'Não há um só lugar nesse vale onde os Shao-Tien possam se esconder de nós. Eles subestimam a tenacidade dos Shado-Pan.', '', 19865),
(64394, 'ptBR', 'As ameaças crescentes do retorno dos mogus e dos enxames de mantídeos a oeste trouxeram mais aprendizes que o normal. Isso é bom. Eles serão necessários.', '', 19865),
(64395, 'ptBR', 'Os mogus são uma ameaça potente, mas não são nada comparados aos horrores que eu e meus homens enfrentamos no Ermo do Medo. Eu não tenho dúvidas que poderemos proteger o vale.', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(64396, 'ptBR', '', 'Somos tão novos neste vale quanto você. Viemos quando os portões abriram, após perdermos nossos lares em Kun-Lai. Há muito a se construir, muito a se consertar.', 19865),
(64397, 'ptBR', '', 'Imagino se nossos destinos estão, de alguma forma, amaldiçoados. Os horrores que passamos parecem nunca acabar.$b$bAlgumas vezes, tudo o que se pode fazer é tentar manter o bom humor e, talvez, uma leve apreciação pelas viradas caprichosas da fortuna, sejam elas boas ou ruins.', 19865),
(64398, 'ptBR', 'A terra mais produtiva em toda Pandária! Um homem esperto pode ficar rico por aqui!', '', 19865),
(64399, 'ptBR', 'Uma vila em crescimento é um ótimo local para se ganhar a vida. Tantas mercadorias necessárias, tantas mercadorias a serem vendidas. Eu acho que posso enriquecer e ser feliz aqui, sem dúvida!', '', 19865),
(64400, 'ptBR', 'Não ouvi nada além de lendas sobre a imensa beleza e quietude deste vale, muito antes que qualquer um de nós pudesse nele entrar. Agora que estamos aqui, existe todo tipo de fera tentando esmagar nossos crânios ou morder nossos pés.$b$bEntão, as lendas são mentiras ou nós somos uma péssima companhia? Eu humildemente me excluo dessa última possibilidade, pois considerar tal ideia seria bobagem.', '', 19865),
(64401, 'ptBR', 'Bem, isso tudo é deveras aterrorizante, não é? E essas armadilhas então, nem um pouco hospitaleiras. Os mogus precisam desesperadamente de alguns conselhos de decoração.', '', 19865),
(64402, 'ptBR', 'Muitas vezes me preocupo com a questão: se as flores nesse vale são realmente eternas, seria bem perigoso se novas flores brotassem, não? Nós estaríamos nadando em um mar de flores sufocantes, por mais cheirosas e macias que fossem.$b$bPrefiro não correr riscos e esmagar as menores com minha bota, apenas para manter o equilíbrio, sabe?', '', 19865),
(64403, 'ptBR', 'Rook trata amigos bem.', '', 19865),
(64404, 'ptBR', 'Rook quer esmagar mogu, mas camponeses não tão seguros! Se Rook manter camponeses seguros, tu ajuda a esmagar mogu?', '', 19865),
(64405, 'ptBR', 'Por que os antigos mogus construíram pilares e paredes partidas por aqui? Por que não fazer construções inteiras, como todo mundo mais? Mogus burros.', '', 19865),
(64406, 'ptBR', '', 'Nessas ruínas estão muitos segredos dos mogus. Todo esse vale foi deles um dia, e alguns cantos dele ainda não foram pisados por pés de pandarens.', 19865),
(64407, 'ptBR', '', 'Os mogus são captores cruéis. Não devemos perder nem um segundo se um dos nossos bravos guerreiros cair nas mãos deles.', 19865),
(64408, 'ptBR', '', 'Nos momentos mais sombrios, aquele que tem o espírito paciente e a mão tranquilizadora possui o maior valor.', 19865),
(64409, 'ptBR', '', 'Eu choro pela sorte desta vila. Os momentos difíceis parecem não ter fim e, com os mogus no vale, parece que demorará bastante até que os ventos mudem.', 19865),
(64410, 'ptBR', 'Os reflexos desenvolvidos no ringue da sobrevivência são aquilo que mantém esses aprendizes vivos do outro lado da muralha. Lá, as ameaças são bem menos piedosas.', '', 19865),
(64411, 'ptBR', '', 'Já era hora de você perguntar! Estava imaginando quando o Fazendeiro Yoon iria me notar. Vá em frente, vou logo que acabar minhas tarefas de hoje no mercado.', 19865),
(64412, 'ptBR', '', 'A Fazenda Sol Cantante precisa da minha ajuda? Encontrarei você lá assim que terminar aqui no mercado.', 19865),
(64413, 'ptBR', 'Acho que as galinhas não vão ligar se eu fizer uma visitinha. Vou lá encontrar com você mais tarde, depois de terminar meus afazeres no mercado.', '', 19865),
(64414, 'ptBR', 'Acho que poderia deixar Mung-Mung cuidando das coisas por um tempo e dar uma olhada na fazenda do Yoon. Vou apenas terminar meus negócios aqui no mercado.', '', 19865),
(64415, 'ptBR', 'Sério? O lago inteiro, só para mim? Já tô indo, logo que eu acabar essa cerveja... hic!', '', 19865),
(64416, 'ptBR', '', 'Bom, certo, acho que posso ir até aquela fazenda de vez em quando. Mas não posso ir até lá agora. Tenho algumas coisas a terminar no mercado primeiro.', 19865),
(64417, 'ptBR', 'Eu estava imaginando quando você ia perguntar. É claro, mas não posso hoje. Quando terminar meus negócios no mercado, estarei aí.', '', 19865),
(64418, 'ptBR', '', 'Meu pai sempre disse que era para ajudar um vizinho em necessidade. Eu só preciso resolver algumas coisas aqui no mercado primeiro. Vou pra lá assim que puder!', 19865),
(64419, 'ptBR', '', 'Claro, acho que posso ajudar um pouco! Não posso deixar o mercado hoje, mas estarei lá o mais rápido que puder.', 19865),
(64420, 'ptBR', 'Ok, chefe! Tchi Tchi tem coisa pra fazer no mercado hoje, e vai pra lá daqui a pouco.', '', 19865),
(64421, 'ptBR', 'Um saurok corre com parte do tesouro por uma escadaria oculta!', '', 19865),
(64422, 'ptBR', 'Nem todos os paragões foram escolhidos pela perícia físcia, Arauto.', '', 19865),
(64423, 'ptBR', 'Uma linda criatura, não concorda? Não deixe que o tamanho engane você. Mesmo jovens, os Kunchong são letais.$b$bAntes da minha descoberta os Kunchong eram usados como armas, sem maior preocupação quanto à sua inteligência,. Nós lutamos para controlá-los até que me ocorreu que nós ainda não os compreendíamos completamente.$b$bAo formar um vínculo com as criaturas nós já não precisávamos forçar o controle. Em vez disso, fizemos uma parceria.$b$bKovok foi o próximo passo em meu experimento.', '', 19865),
(64424, 'ptBR', '$n foi capturado em uma Prisão de Âmbar. Liberte-os!', '$n foi capturado em uma Prisão de Âmbar. Liberte-os!', 19865),
(64425, 'ptBR', '|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|tO Senhor do Vento Mel''jarak começa a lançar |cFFF00000|Hspell:122407|h[Chuva de Lâminas]|h|r!', '', 19865),
(64426, 'ptBR', 'O Senhor do Vento Mel''jarak sente que mais de 4 de seus aliados estão incapacitados e os liberta!', '', 19865),
(64427, 'ptBR', 'Mas o quê...', '', 19865),
(64428, 'ptBR', 'LEVIATÃ!!', '', 19865),
(64429, 'ptBR', 'Precisamos avisar os outros!', '', 19865),
(64430, 'ptBR', 'Aaaaggghhhh!!', '', 19865),
(64431, 'ptBR', 'Proteger os grômulos não é o que eu sonhava para o futuro, mas paga bem. Além disso, você vê muitas coisas estranhas nas estradas da montanha.', 'Proteger os grômulos não é o que eu sonhava para o futuro, mas paga bem. Além disso, você vê muitas coisas estranhas nas estradas da montanha.', 19865),
(64432, 'ptBR', 'Você veio das terras baixas? Não costumamos ver gente de lá por aqui.', 'Você veio das terras baixas? Não costumamos ver gente de lá por aqui.', 19865),
(64433, 'ptBR', 'O que traz você ao topo da montanha?', 'O que traz você ao topo da montanha?', 19865),
(64434, 'ptBR', 'Grômulos normalmente têm shado-pans protegendo eles. Acho que deve ser perigoso, lá no Espinhaço da Serpente.', 'Grômulos normalmente têm shado-pans protegendo eles. Acho que deve ser perigoso, lá no Espinhaço da Serpente.', 19865),
(64435, 'ptBR', 'Você ouviu o sha? Continuamos a ouvir vozes no vento. Não é bom. Não é nada bom.', 'Você ouviu o sha? Continuamos a ouvir vozes no vento. Não é bom. Não é nada bom.', 19865),
(64436, 'ptBR', 'Os hozens das montanhas estão assolando. Cuidado ao viajar pelas estradas.$b$bÉ provavelmente uma questão de tempo antes que eles descubram que os shado-pans não estão aqui e decidam vir em nossa direção.', 'Os hozens das montanhas estão assolando. Cuidado ao viajar pelas estradas.$b$bÉ provavelmente uma questão de tempo antes que eles descubram que os shado-pans não estão aqui e decidam vir em nossa direção.', 19865),
(64437, 'ptBR', 'Uma vez, vi uma criatura estranha no Bazar dos Grômulos. Parecia um jinyu corcunda, mas era malvado e disse algo, tipo "Mrggmrmrgmgmgl".$b$bAcho que um daqueles grômulos trouxe do litoral.', 'Uma vez, vi uma criatura estranha no Bazar dos Grômulos. Parecia um jinyu corcunda, mas era malvado e disse algo, tipo "Mrggmrmrgmgmgl".$b$bAcho que um daqueles grômulos trouxe do litoral.', 19865),
(64438, 'ptBR', 'Não tem tido Shado-Pan por esses lados ultimamente. Isso não pode ser bom.$b$bDeveríamos ter ainda alguns anos até o próximo enxame de mantídeos.', 'Não tem tido Shado-Pan por esses lados ultimamente. Isso não pode ser bom.$b$bDeveríamos ter ainda alguns anos até o próximo enxame de mantídeos.', 19865),
(64439, 'ptBR', '', 'Você é doce como açúcar, $n.', 19865),
(64440, 'ptBR', '', 'Querid$go:a;, você é tão legal comigo!', 19865),
(64441, 'ptBR', '', 'É uma gentileza sua lembrar de mim, querid$go:a;.', 19865),
(64442, 'ptBR', '', 'É tão vermelho! Você sabia que é a minha cor favorita?', 19865),
(64443, 'ptBR', '', 'Minha nossa, é tão lindo. Como sabia que eu gosto de joias?', 19865),
(64444, 'ptBR', '', 'Agradeço, $N. Uma garota nunca tem rubis suficientes.', 19865),
(64445, 'ptBR', '', 'Não precisava! Mas fico feliz que trouxe.', 19865),
(64446, 'ptBR', '', 'Você não é um amorzinho, $gquerido:flor;?', 19865),
(64447, 'ptBR', '', 'Ah raios, você vai me mimar demais!', 19865),
(64448, 'ptBR', '|TInterface\\Icons\\inv_misc_uncutgemnormal.blp:20|t$n foi capturado em uma |cFFF00000|Hspell:121881|h[Prisão de Âmbar]|h|r!', '', 19865),
(64449, 'ptBR', '', 'Não sou boa com essa coisa de emoções, mas obrigada.', 19865),
(64450, 'ptBR', '', 'Obrigada, $c. Você me honra.', 19865),
(64451, 'ptBR', '', 'Obrigada, $n. Estou lhe devendo uma.', 19865),
(64452, 'ptBR', '', 'Você é muito $gbondoso:bondosa;, $c. Como posso lhe retribuir?', 19865),
(64453, 'ptBR', '', 'Não precisava, $c. Obrigada.', 19865),
(64454, 'ptBR', '', 'Uma moça fica com fome depois de caçar tantos inimigos. Obrigada.', 19865),
(64455, 'ptBR', '', 'Oh, parece delicioso. Agradeço, $c.', 19865),
(64456, 'ptBR', '', 'Hummm... uma guerreira precisa se manter forte. Obrigada.', 19865),
(64457, 'ptBR', '', 'Essa vigília não acaba nunca, mas eu posso sempre fazer uma pausa para uma boquinha!', 19865),
(64458, 'ptBR', 'Posso cumê? Acho que só tem um jeito de saber...', '', 19865),
(64459, 'ptBR', 'A sua consciência está se expandindo. Concentre-se em quem você está procurando. O príncipe – o jovem leão. Ele está aqui, não é? Viaje pelo tempo e espaço... abra os olhos da sua alma. Está vendo ele?', '', 19865),
(64460, 'ptBR', 'Hummm, issho me dá algo para concentrar na minha próxima previsão.', '', 19865),
(64461, 'ptBR', 'Issho é muito maneiro, $n. Brigado, cumpaji.', '', 19865),
(64462, 'ptBR', 'Goshtei muito, $n. Brigado.', '', 19865),
(64463, 'ptBR', 'Brigado por lembrar de mim, camarada. Ninguém maish lembra.', '', 19865),
(64464, 'ptBR', 'Você é tão legal, $gsinhô:mocinha;... hic!', '', 19865),
(64465, 'ptBR', 'Essa maçã parece deliciosa. Brigado!', '', 19865),
(64466, 'ptBR', 'Uma maçã pra mim? Brigado!', '', 19865),
(64467, 'ptBR', 'O que é issho? Um tomate? Uma romã? Ah! Uma maçã!', '', 19865),
(64468, 'ptBR', 'Queima!', '', 19865),
(64469, 'ptBR', 'Issho é uma maçã? Tu deve tá felish em me ver... hic!', '', 19865),
(64470, 'ptBR', 'Ah, tá com uma cara deliciosa! Vai descer muito bem com a minha gelada.', '', 19865),
(64471, 'ptBR', 'Um oráculo precisa de comida para prever o futuro. Brigado!', '', 19865),
(64472, 'ptBR', 'Minha família costumava fazer issho... Eles se foram, mas eu ainda amo esse prato.', '', 19865),
(64473, 'ptBR', 'Ah, não precisava! Obrigado.', '', 19865),
(64474, 'ptBR', 'Mas não tenho nada para te dar em troca! Ah, bacana, obrigado mesmo assim.', '', 19865),
(64475, 'ptBR', 'É muita gentileza sua, $r.', '', 19865),
(64476, 'ptBR', 'Acho que isso sempre pode ser útil. Obrigado.', '', 19865),
(64477, 'ptBR', 'Não mereço algo tão legal assim. Imagino que você vá insistir.', '', 19865),
(64478, 'ptBR', 'Não posso negar, mas você não precisava. Obrigado, $r.', '', 19865),
(64479, 'ptBR', 'Meu filho adorava encontrar essas penas.', '', 19865),
(64480, 'ptBR', 'Essas penas me trazem memórias do meu filho. Obrigado, $r.', '', 19865),
(64481, 'ptBR', 'Meu filho adorava essa penas porque elas são azuis como o céu. Ele sempre disse que iria voar, um dia.', '', 19865),
(64482, 'ptBR', 'Obrigado, $n. Meu filho iria gostar de ver isso.', '', 19865),
(64483, 'ptBR', 'É muito legal, $n. Obrigado.', '', 19865),
(64484, 'ptBR', 'Você deve ser $gum cozinheiro:uma cozinheira; de mão cheia, $n. Isso está com uma cara boa.', '', 19865),
(64485, 'ptBR', 'Obrigado por se lembrar de um velho solitário, $n.', '', 19865),
(64486, 'ptBR', 'Não precisava!', '', 19865),
(64487, 'ptBR', 'Ohhh, é para mim? Obrigado.', '', 19865),
(64488, 'ptBR', 'Você com certeza sabe como deixar um pandaren feliz. Obrigado!', '', 19865),
(64489, 'ptBR', 'Quanta generosidade. Obrigado!', '', 19865),
(64490, 'ptBR', 'Acho que esse presente é aceitável. Obrigado, $n.', '', 19865),
(64491, 'ptBR', 'Não esperava nada menos, $r. Obrigado.', '', 19865),
(64492, 'ptBR', 'Este é um presente bem legal, $n! Muito obrigado.', '', 19865),
(64493, 'ptBR', 'Corram ou queimem!', '', 19865),
(64494, 'ptBR', 'Bife de Tigre? É meu favorito! Como sabia disso?', '', 19865),
(64495, 'ptBR', 'Dizem que a melhor forma de entrar no Sindicato dos Lavradores é através do estômago do líder. Sacou?', '', 19865),
(64496, 'ptBR', 'Nós vamos queimar tudo!', '', 19865),
(64497, 'ptBR', 'Você ousa enfrentar o fogo dos yaungóis?', '', 19865),
(64498, 'ptBR', '', 'Você com certeza sabe como temperar o coração de uma velha garota! Obrigada!', 19865),
(64499, 'ptBR', '', 'Você parece estar do meu lado, né, $r? Bom para você!', 19865),
(64500, 'ptBR', 'Morra! Aceite seu destino!', '', 19865),
(64501, 'ptBR', '', 'Faça isso de novo e talvez eu tenha que gostar de você!', 19865),
(64502, 'ptBR', 'Você não escapará ao seu destino!', '', 19865),
(64503, 'ptBR', '', 'Um presente para a velha Gina? Você é um doce.', 19865),
(64504, 'ptBR', '', 'Bem, só por isso, você pode aparecer no meu mercado a qualquer momento.', 19865),
(64505, 'ptBR', '', 'É um presente muito bom esse que você acabou de me dar. Obrigada.', 19865),
(64506, 'ptBR', '', 'Uma linda flor para mim? Ah, pare.', 19865),
(64507, 'ptBR', '', 'É uma flor muito bonita. Obrigada, $n.', 19865),
(64508, 'ptBR', '', 'Como sabia que eu gosto de flores?', 19865),
(64509, 'ptBR', 'Vocês não podem resistir ao fogo dos yaungóis!', '', 19865),
(64510, 'ptBR', '', 'Foi você quem fez essa Sopa Névoa Rodopiante? O cheiro está maravilhoso.', 19865),
(64511, 'ptBR', 'Vocês queimarão junto com suas terras!', '', 19865),
(64512, 'ptBR', '', 'Você sabia que existe duas formas de conquistar o coração de Gina? Uma é sendo um bom cliente no meu mercado, e a outra é com Sopa Névoa Rodopiante!', 19865),
(64513, 'ptBR', '', 'Oh, parece delicioso. Agradeço, $N.', 19865),
(64514, 'ptBR', 'Esse é um presente muito legal, $r. Obrigado.', '', 19865),
(64515, 'ptBR', 'Como posso lhe retribuir essa bondade?', '', 19865),
(64516, 'ptBR', 'Ei, você não é tão ruim no final das contas, $r.', '', 19865),
(64517, 'ptBR', 'Estou começando a gostar de você, $r.', '', 19865),
(64518, 'ptBR', 'Continue assim e talvez eu compartilhe meu segredo de como cultivar tantos vegetais.', '', 19865),
(64519, 'ptBR', 'Essa torrada parece deliciosa. Espero que você quem tenha feito.', '', 19865),
(64520, 'ptBR', 'Nada como uma torrada feita em casa! Deliciosa!', '', 19865),
(64521, 'ptBR', 'Esta terra é nossa agora!', '', 19865),
(64522, 'ptBR', 'Minha mãe sempre me disse que essas flores dão sorte.', '', 19865),
(64523, 'ptBR', 'Estas são terras dos yaungóis!', '', 19865),
(64524, 'ptBR', 'É muito gentil da sua parte compartilhar uma flor da sorte como essa comigo.', '', 19865),
(64525, 'ptBR', 'Nós reivindicamos suas terras pra nós!', '', 19865),
(64526, 'ptBR', 'Alguns caras podem perguntar por que eu gosto tanto de flores. Apenas aprecio a beleza dessa terra.', '', 19865),
(64527, 'ptBR', '', 'Tem certeza disso, $n? Uau, obrigada!', 19865),
(64528, 'ptBR', 'Ahh, como é bom sentir o sal no pêlo de novo.', '', 19865),
(64529, 'ptBR', '', 'Ah não, não tenho nada para lhe dar em troca! Nah...', 19865),
(64530, 'ptBR', '', 'Tu é muito legal, $n. Estou feliz por conhecer alguém como você.', 19865),
(64531, 'ptBR', '', 'Papai sempre disse que estatuetas de gatinhos dão boa sorte!', 19865),
(64532, 'ptBR', '', 'Jade representa boa sorte, você sabia? Obrigada por me dar isso.', 19865),
(64533, 'ptBR', '', 'Ter um pedacinho de jade é como ter um talismã contra os espíritos malignos. Agradeço por este gatinho! Ele me manterá segura.', 19865),
(64534, 'ptBR', '', 'Ah, você é muito gentil, $n.', 19865),
(64535, 'ptBR', '', 'É uma gentileza sua lembrar de mim.', 19865),
(64536, 'ptBR', 'Nosso lar foi roubado! Então nós roubaremos o de vocês!', '', 19865),
(64537, 'ptBR', '', 'Dentre todos os habitantes destas terras, você deu isso a mim? Eu não sei o que dizer, exceto que estou muito honrada.', 19865),
(64538, 'ptBR', 'Morra!', '', 19865),
(64539, 'ptBR', '', 'Como você sabia que eu gosto de gatos?', 19865),
(64540, 'ptBR', 'Você ousa me desafiar?!', '', 19865),
(64541, 'ptBR', 'Oohh, um belo presente para Tchi Tchi! Obrigado!', '', 19865),
(64542, 'ptBR', 'Para Tchi Tchi? Não precisava!', '', 19865),
(64543, 'ptBR', 'Tchi Tchi adora presentes! Obrigado!', '', 19865),
(64544, 'ptBR', 'Pena para Tchi Tchi? Obrigado.', '', 19865),
(64545, 'ptBR', 'Chefe... isso é muito legal. Obrigado.', '', 19865),
(64546, 'ptBR', 'Você ser bem legal, chefe. Obrigado.', '', 19865),
(64547, 'ptBR', 'Desafio aceito!', '', 19865),
(64548, 'ptBR', 'Você não pode nos deter!', '', 19865),
(64549, 'ptBR', 'Outro escravo para nossos campos!', '', 19865),
(64550, 'ptBR', 'Você se atreve a desafiar os yaungóis?', '', 19865),
(64551, 'ptBR', 'Eu a vi, sabe.$B$BMazu. A deusa do mar.$B$BFoi durante a pior tempestade da minha vida. Eu era jovem, inexperiente. Caí no mar e tudo ficou escuro. Era o meu fim.$B$BEntão ela apareceu diante de mim, clara como uma tarde de verão. Bela como não dá nem pra imaginar... conchas ao redor do pescoço e pérolas cingindo os quadris. Ela sorriu e esticou o braço esguio.$B$BDepois disso eu só me lembro do Cachorro me carregando nas costas, já na superfície, e a tripulação me puxando pra dentro. Eu nunca o tinha visto antes. A tripulação falou que ele saiu do nada. Mas eu sei de onde ele veio.', '', 19865),
(64552, 'ptBR', 'Esses campos são nossos agora.', '', 19865),
(64553, 'ptBR', 'Morra!', '', 19865),
(64554, 'ptBR', 'Renda-se!', '', 19865),
(64555, 'ptBR', 'Nãããããããão!!! OVELHITAAAAAAAAA!', '', 19865),
(64556, 'ptBR', 'Enfrente o seu destino!', '', 19865),
(64557, 'ptBR', 'Boa sorte para você, $gamigo:amiga;!', '', 19865),
(64558, 'ptBR', 'Você ousa me desafiar?', '', 19865),
(64559, 'ptBR', 'Raaaaaaar!', '', 19865),
(64560, 'ptBR', 'Ah! Um desafio!', '', 19865),
(64561, 'ptBR', 'Morra!', '', 19865),
(64562, 'ptBR', 'Tema a ira dos yaungóis!', '', 19865),
(64563, 'ptBR', 'Tchi Tchi é seu conhecido.', '', 19865),
(64564, 'ptBR', 'Tchi Tchi é seu colega.', '', 19865),
(64565, 'ptBR', 'Tchi Tchi é seu amigo.', '', 19865),
(64566, 'ptBR', 'Tchi Tchi é seu bom amigo.', '', 19865),
(64567, 'ptBR', 'Tchi Tchi é seu melhor amigo. Talvez você devesse falar com ele e ver se ele pode ajudar na fazenda.', '', 19865),
(64568, 'ptBR', 'Você e Ella são conhecidos.', '', 19865),
(64569, 'ptBR', 'Você e Ella são camaradas.', '', 19865),
(64570, 'ptBR', 'Você e Ella são $gamigos:amigas;.', '', 19865),
(64571, 'ptBR', 'Você e Ella são $gbons:boas; amig$gos:as;.', '', 19865),
(64572, 'ptBR', 'Você e Ella são melhores amig$gos:as;. Talvez ela esteja disposta a ajudar o Fazendeiro Yoon por um tempo.', '', 19865),
(64573, 'ptBR', 'Você e Peixe são camaradas.', '', 19865),
(64574, 'ptBR', 'Você e Peixe são $gamigos:amigas;.', '', 19865),
(64575, 'ptBR', 'Você e Peixe são $gbons:boas; amig$gos:as;.', '', 19865),
(64576, 'ptBR', 'Você é melhor amig$go:a; de Peixe. Com o conhecimento dela sobre animais, ela provavelmente seria uma boa ajuda na fazenda.', '', 19865),
(64577, 'ptBR', 'De alguma forma, você e o Fazendeiro Fung se tornaram camaradas.', '', 19865),
(64578, 'ptBR', 'De alguma forma, você e o Fazendeiro Fung se tornaram amigos.', '', 19865),
(64579, 'ptBR', 'De alguma forma, você e o Fazendeiro Fung se tornaram bons amigos.', '', 19865),
(64580, 'ptBR', 'De alguma forma, você e o Fazendeiro Fung se tornaram melhores amigos. Ele provavelmente adoraria ajudar na Fazenda Sol Cantante.', '', 19865),
(64581, 'ptBR', 'Você e Gina são camaradas.', '', 19865),
(64582, 'ptBR', 'Você e Gina são $gamigos:amigas;.', '', 19865),
(64583, 'ptBR', 'Você e Gina são $gbons:boas; amig$gos:as;.', '', 19865),
(64584, 'ptBR', 'Você e Gina são melhores amig$gos:as;. Ela adora se meter na vida dos outros, então não há dúvidas de que ela ajudaria na fazenda.', '', 19865),
(64585, 'ptBR', 'Você e Haohan são camaradas.', '', 19865),
(64586, 'ptBR', 'Você e Haohan são amigos.', '', 19865),
(64587, 'ptBR', 'Você e Haohan bons amigos.', '', 19865),
(64588, 'ptBR', 'Quando você e Haohan tiverem uma amizade como a de vocês, não há dúvidas de que o próprio líder do Sindicato dos Lavradores aparecerá para dar uma mãozinha.', '', 19865),
(64589, 'ptBR', 'Você e Be Bum, o Ébrio, são camaradas.', '', 19865),
(64590, 'ptBR', 'Você e Be Bum, o Ébrio, são amigos.', '', 19865),
(64591, 'ptBR', 'Você e Be Bum, o Ébrio, são bons amigos.', '', 19865),
(64592, 'ptBR', 'Você e Be Bum, o Ébrio, passaram por muitos ciclos de colheita juntos. Quem mais além dele seria um trunfo na sua fazenda?', '', 19865),
(64593, 'ptBR', 'Você e o Velho Pata do Monte são camaradas.', '', 19865),
(64594, 'ptBR', 'Você e o Velho Pata do Monte são amigos.', '', 19865),
(64595, 'ptBR', 'Você e o Velho Pata do Monte são bons amigos.', '', 19865),
(64596, 'ptBR', 'Você fez muito pelo Velho Pata do Monte, e aquele velhote deve estar sentindo a sua falta. Você devia pedir a ele ajuda na sua fazenda.', '', 19865),
(64597, 'ptBR', 'Você e Sho são camaradas.', '', 19865),
(64598, 'ptBR', 'Você e Sho são amigos.', '', 19865),
(64599, 'ptBR', 'Você e Sho são bons amigos.', '', 19865),
(64600, 'ptBR', 'Você provou sua amizade à Sho. Ela disse que cuidaria de você, caso você algum dia precise. Mas você pode apenas pedir para ela olhar a sua plantação.', '', 19865),
(64601, 'ptBR', 'Você e Tina são camaradas.', '', 19865),
(64602, 'ptBR', 'Você e Tina são amig$gos:as;.', '', 19865),
(64603, 'ptBR', 'Você e Tina são $gbons:boas; amig$gos:as;.', '', 19865),
(64604, 'ptBR', 'Nas palavras de Tina, você é $gum amigão:uma amigona;. Ela provavelmente adoraria visitar a sua fazenda.', '', 19865),
(64605, 'ptBR', 'As Lâminas de Vento correm para ajudar seus aliados capturados!', 'As Lâminas de Vento correm para ajudar seus aliados capturados!', 19865),
(64606, 'ptBR', 'Saudações, jovem amig$go:a;.', '', 19865),
(64607, 'ptBR', 'Como um morsano chegou em Pandária?', 'Como um morsano chegou em Pandária?', 19865),
(64608, 'ptBR', 'Chegou o momento, $gmeu:minha; amig$go:a; $c, de falarmos de outras coisas. De caranguejos e mares e tartarugas com árvores...', '', 19865),
(64609, 'ptBR', 'Chegou o momento, $gmeu:minha; amig$go:a; $r, de falarmos de outras coisas. De hozens e grômulos e como a minha barriga ronca...', '', 19865),
(64610, 'ptBR', 'Chegou o momento, $gmeu:minha; amig$go:a;, de falarmos de outras coisas. De mogus e trolls e trolls do rio jinyu...', '', 19865),
(64611, 'ptBR', 'Chegou o momento, $gmeu:minha; amig$go:a;, de falarmos de outras coisas. De yetis e iaques e ataques aleatórios de tubarão...', '', 19865),
(64612, 'ptBR', '', 'Não se assuste, $n.$b$bEstou projetando meu eu-sonho aqui para ajudar nos esforços contra os mogus.', 19865),
(64613, 'ptBR', 'Ela é linda, não é? Eu a pesquei há alguns anos. Parece muito com ela... Me pergunte a história qualquer hora dessas.', '', 19865),
(64614, 'ptBR', 'Esquece.', 'Esquece.', 19865),
(64615, 'ptBR', '', 'Olá, $r! Que tipo de musica gostaria de escutar hoje?', 19865),
(64616, 'ptBR', 'Fale-me sobre a estátua, Molúria.', 'Fale-me sobre a estátua, Molúria.', 19865),
(64617, 'ptBR', 'Você pode tocar uma música?', 'Você pode tocar uma música?', 19865),
(64618, 'ptBR', 'Eu quero ouvir "Um Brinde a você".', 'Eu quero ouvir "Um Brinde a você".', 19865),
(64619, 'ptBR', 'Eu quero ouvir "Festa Patusca".', 'Eu quero ouvir "Festa Patusca".', 19865),
(64620, 'ptBR', 'Eu quero ouvir "O Bambuzal".', 'Eu quero ouvir "O Bambuzal".', 19865),
(64621, 'ptBR', 'Eu quero ouvir "A Canção de Liu Lang".', 'Eu quero ouvir "A Canção de Liu Lang".', 19865),
(64622, 'ptBR', 'Eu quero ouvir "A volta de Liu Lan pra casa".', 'Eu quero ouvir "A volta de Liu Lan pra casa".', 19865),
(64623, 'ptBR', 'Eu quero ouvir "O Templo das Cinco Auroras".', 'Eu quero ouvir "O Templo das Cinco Auroras".', 19865),
(64624, 'ptBR', '', 'Gostaria de ouvir PH The Rains of Castamere.', 19865),
(64625, 'ptBR', 'O Senhor do Vento Mel''jarak sente que um aliado está incapacitado e o liberta!', '', 19865),
(64626, 'ptBR', 'O Senhor do Vento Mel''jarak sente que mais de 2 de seus aliados estão incapacitados e os liberta!', '', 19865),
(64627, 'ptBR', 'Tem mais um pra você!', '', 19865),
(64628, 'ptBR', 'Obrigado, deixe isso em qualquer lugar.', '', 19865),
(64629, 'ptBR', 'Você purificou a alma de Gu Golpe da Nuvem. Os Shado-Pan agradecem.', '', 19865),
(64630, 'ptBR', 'O Mestre Monte de Neve fala muito bem sobre como você consegue se manter em uma luta.', '', 19865),
(64631, 'ptBR', 'O Lorde Taran Zhu viajou para oeste além da muralha caçando o Sha do Ódio. Espero que a busca esteja indo bem.', '', 19865),
(64632, 'ptBR', 'O controle do Sha sobre o nosso povo foi quebrado graças a você. Você tem nossa gratidão.', '', 19865),
(64633, 'ptBR', 'Você prestou um ótimo serviço aos shado-pans, $p.', 'Você prestou um ótimo serviço aos shado-pans, $p.', 19865),
(64634, 'ptBR', '', 'Saudações novamente, $c. Estive observando você.', 19865),
(64635, 'ptBR', 'Você demonstrou grande coragem, $p. Os Shado-Pan agradecem.', 'Você demonstrou grande coragem, $p. Os Shado-Pan agradecem.', 19865),
(64636, 'ptBR', 'Sua perícia em artes marciais é incomparável. Há muito que gostaria de aprender com você.', 'Sua perícia em artes marciais é incomparável. Há muita coisa que eu gostaria de aprender com você.', 19865),
(64637, 'ptBR', 'Você realmente é $gum:uma; mestre em lutas marciais. Você me honra com sua presença.', 'Você realmente é $gum:uma; mestre em lutas marciais. Você me honra com sua presença.', 19865),
(64638, 'ptBR', '', 'Shu é valioso para nós. Precisamos encontrá-lo, mas ele tem a personalidade de uma criança, então não podemos assustá-lo quando o encontrarmos.$b$bVou meditar sobre onde ele pode estar e como é a melhor forma de abordá-lo. Seja paciente, amig$go:a;.', 19865),
(64639, 'ptBR', '', 'Tenha paciência com o Shu. Ele age como uma criança, mas ele é um ancião, e bastante poderoso.', 19865),
(64640, 'ptBR', 'Maçãs, maçãs fresquinhas, quem vai querer!', '', 19865),
(64641, 'ptBR', 'As maiores, mais suculentas e adoráveis maçãs do vale! Consiga uma aqui!', '', 19865),
(64642, 'ptBR', 'Compre algumas maçãs! Uma maçã por dia e você não entra numa fria!', '', 19865),
(64643, 'ptBR', 'Então é pra... sei lá, você quer que eu role isso pra longe?', '', 19865),
(64644, 'ptBR', 'Eeepa... está se mexendo?', '', 19865),
(64645, 'ptBR', 'Pois bem.', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(64646, 'ptBR', 'Suponho que você saiba algo sobre o que acabou de acontecer.', '', 19865),
(64647, 'ptBR', 'Sabe o que mais, esqueça. Eu nem quero saber. Vou voltar pras minhas linhas.', '', 19865),
(64648, 'ptBR', 'Tu vai sangrar, cara.', '', 19865),
(64649, 'ptBR', 'Tu num vai deter os Zandalari, cara.', '', 19865),
(64650, 'ptBR', 'Bom. Meu raptor tá cum fome.', '', 19865),
(64651, 'ptBR', 'Tu vai enfrentar os Zandalari agora. Não um traidorzinho Lançanegra.', '', 19865),
(64652, 'ptBR', 'Tu cutucou os trolls errados.', '', 19865),
(64653, 'ptBR', 'Cuidado com o lado que escolhe, colega.', '', 19865),
(64654, 'ptBR', 'A gente vai te enterrar aqui.', '', 19865),
(64655, 'ptBR', 'Zandalar se erguerá novamente.', '', 19865),
(64656, 'ptBR', 'Tu num vai deter a gente, cara.', '', 19865),
(64657, 'ptBR', 'Experimenta as magias dos Zandalari!', '', 19865),
(64658, 'ptBR', 'Tremei, tolos! O gafanhoto despertou!', '', 19865),
(64659, 'ptBR', 'WHARRGARBL!!!', '', 19865),
(64660, 'ptBR', 'Tu vai ser meu troféu novo.', '', 19865),
(64661, 'ptBR', 'Zandalar vai trazer de volta os antigos hábitos.', '', 19865),
(64662, 'ptBR', 'Tu num consegue acabar com Zandalar e mogus!', '', 19865),
(64663, 'ptBR', 'Ughh... <tosse> O gafanhoto está bem! <tosse> <tosse>', '', 19865),
(64664, 'ptBR', 'Os Klaxxi chamam...', '', 19865),
(64665, 'ptBR', '', 'Pão fresco!', 19865),
(64666, 'ptBR', '', 'Parece que você se vira bem na água. Continue trabalhando assim.', 19865),
(64667, 'ptBR', '', 'A febre agora são os Caranguejos Imperadores. Eles são puro ouro azul.', 19865),
(64668, 'ptBR', 'O Senhor do Vento Mel''jarak chama reforços!', '', 19865),
(64669, 'ptBR', '', 'Nós encalhamos aqui depois que o Molúria nos tirou de curso. Ele pensou que poderia nos enganar. Hah!$B$Bmas a gente está feliz que ele tenha tentado. Ninguém aqui gosta dessa história de "dia de trabalho fácil".', 19865),
(64670, 'ptBR', '', 'Bem-vind$go:a; ao Mercado de Meia Colina, $r.', 19865),
(64671, 'ptBR', '', 'Bem-vind$go:a; ao Mercado de Meia Colina, onde os preços são sempre justos!', 19865),
(64672, 'ptBR', '', 'Há quanto tempo, $n. $GBem-vindo:Bem-vinda; de volta.', 19865),
(64673, 'ptBR', 'Deseja algo para beber, $r?', '', 19865),
(64674, 'ptBR', 'O que gostaria de beber hoje, $n?', '', 19865),
(64675, 'ptBR', 'Trabalhar na lavoura deve dar muita sede, né, $n?', '', 19865),
(64676, 'ptBR', 'Eu desafio você.', 'Eu desafio você.', 19865),
(64677, 'ptBR', '3... 2... 1! LUTEM!', '', 19865),
(64678, 'ptBR', 'O impensável aconteceu: Nosso cerco de Theramore fracassou.', '', 19865),
(64679, 'ptBR', '', 'Lámen! Eu te disse para não pegar pesado no tempero!', 19865),
(64680, 'ptBR', '', 'Uau, Lámen, o que você está colocando na sopa?', 19865),
(64681, 'ptBR', '', 'Hummm, a sopa está deliciosa! Bom trabalho, Lámen!', 19865),
(64682, 'ptBR', 'Tudo pronto? Vamo ver do que você é capaz.', '', 19865),
(64683, 'ptBR', 'Vamos!', 'Vamos!', 19865),
(64684, 'ptBR', 'Você é o plano de contingência. Sua missão é infiltrar-se na Ilha Theramore.', '', 19865),
(64685, 'ptBR', '', '$gBem-vindo:Bem-vinda; à minha muralha, $c.$B$BAgora vamos chutar a bunda dos mantídeos!', 19865),
(64686, 'ptBR', 'Ah, foi por pouco. Mas mantenha-se focado. A harmonia interior é crucial para sobreviver nestas terras. Tente de novo! A paciência é uma virtude dos pandarens.', '', 19865),
(64687, 'ptBR', 'Mantenha a centelha no centro!', '', 19865),
(64688, 'ptBR', 'Não seja pego na mira do demolidor.', '', 19865),
(64689, 'ptBR', 'Tem um hozen na sua cara! Pule para que ele saia!', '', 19865),
(64690, 'ptBR', 'Ai, ai! Uma nova urgência fortaleceu sua determinação. Meu trabalho aqui acabou.', '', 19865),
(64691, 'ptBR', 'Aqueles que participam dos cenários dos Cervejeiros serão lembrados. E, caso você encontre itens raros na sua aventura como cervejeir$go:a;, eles serão seus!', '', 19865),
(64692, 'ptBR', 'A maior cervejaria em Pandária é a Cervejaria Malte do Trovão, no Vale dos Quatro Ventos. Você pode começar por lá se estiver procurando aventuras.$b$bOs mestres cervejeiros são andarilhos por natureza, e podem ser encontrados vagando por toda a terra, buscando ingredientes raros ou preparando novas cervejas.$B$BO Mestre Cervejeiro Tzu enfrenta inimigos no cenário da Vila Rocha Verde.$b$bO Mestre Cervejeiro Bo procura sabores tropicais no cenário de Ungá Ingô.$b$bO Mestre Cervejeiro Buf celebra a festa da lua no cenário do Festival da Cerveja da Lua, e a Mestre Cervejeira Blanche está fermentando algo incrível na Tempestade Cervejeira.', '', 19865),
(64693, 'ptBR', 'Existem recompensas por ajudar os mestres cervejeiros?', 'Existem recompensas por ajudar os mestres cervejeiros?', 19865),
(64694, 'ptBR', 'Onde posso encontrar mestres cervejeiros necessitados de ajuda?', 'Onde posso encontrar mestres cervejeiros necessitados de ajuda?', 19865),
(64695, 'ptBR', 'Qual mestre cervejeiro você gostaria ajudar hoje?', '', 19865),
(64696, 'ptBR', 'Fila para Tempestade Cervejeira.', 'Fila para Tempestade Cervejeira.', 19865),
(64697, 'ptBR', 'Você conseguiu tudo? Muito bem! Venha comigo.', '', 19865),
(64698, 'ptBR', 'Fila para batalha Festival da Cerveja da Lua.', 'Fila para batalha Festival da Cerveja da Lua.', 19865),
(64699, 'ptBR', 'Para que a cerveja dos sonhos mostre o que se procura, é preciso atingir um estado de paz interior. Vou lhe mostrar como.', '', 19865),
(64700, 'ptBR', 'Fila para Ungá Ingô.', 'Fila para Ungá Ingô.', 19865),
(64701, 'ptBR', 'Fila para Aldeia Rocha Verde.', 'Fila para Aldeia Rocha Verde.', 19865),
(64702, 'ptBR', 'Beba para começar, camarada.', '', 19865),
(64703, 'ptBR', 'Fale-me mais sobre Cenário: Tempestade Cervejeira.', 'Fale-me mais sobre Cenário: Tempestade Cervejeira.', 19865),
(64704, 'ptBR', 'Fale-me mais sobre Cenário: Ungá Ingô.', 'Fale-me mais sobre Cenário: Ungá Ingô.', 19865),
(64705, 'ptBR', 'Fale-me mais sobre Cenário: Festival da Cerveja da Lua.', 'Fale-me mais sobre Cenário: Festival da Cerveja da Lua.', 19865),
(64706, 'ptBR', 'Fale-me mais sobre Cenário: Aldeia Rocha Verde.', 'Fale-me mais sobre Cenário: Aldeia Rocha Verde.', 19865),
(64707, 'ptBR', 'A Mestre Cervejeira Blanche está tentando fazer uma Cerveja Explosiva em meio a uma tempestade, mas alguns inimigos estão atrapalhando.', '', 19865),
(64708, 'ptBR', 'Eu voltarei a Klaxxi''vess para me encontrar com o conselho. Por favor tome conta de Kovok.', '', 19865),
(64709, 'ptBR', 'Resgate a Cerveja Selvagem das garras dos piratas hozens malvados de Ungá Ingô.', '', 19865),
(64710, 'ptBR', 'Vamos ver se você é tudo isso que você fala.', 'Vamos ver se você é tudo isso que você fala.', 19865),
(64711, 'ptBR', 'Resgate os aldeões da Rocha Verde dos arteiros (e perigosos) habitantes da floresta.', '', 19865),
(64712, 'ptBR', 'Prepare algo delicioso e defenda-se dos atacantes yaungóis.', '', 19865),
(64713, 'ptBR', '<Tenwu boceja>\n\nEstou esperando...', '', 19865),
(64714, 'ptBR', 'Me larguem, caranguejos insolentes!', '', 19865),
(64715, 'ptBR', 'Vô te dá de comê pros corvo!', 'Vô te dá de comê pros corvo!', 19865),
(64716, 'ptBR', 'Se eu ajudar os Pescadores, o que eu ganharia com isso?', 'Se eu ajudar os Pescadores, o que eu ganharia com isso?', 19865),
(64717, 'ptBR', 'Onde posso encontrar os Pescadores?', 'Onde posso encontrar os Pescadores?', 19865),
(64718, 'ptBR', '', 'A melhor pesca pode ser encontrada no Cais dos Pescadores, a sudeste da Selva de Krasarang. Todos são bem-vindos para nos visitar e pegar sua vara de pesca!', 19865),
(64719, 'ptBR', '', 'Como assim, o que você ganharia com isso? Que tipo de pergunta é essa?$b$bO prazer de pescar aquele maior peixão do mar não é suficiente? E a sensação do sol nas costas e a água salgada do oceano espirrando no rosto? E quanto a abrir uma cerveja gelada enquanto se reclina e conversa com os amigos?$b$BIsso não é suficiente?!?!$b$bDeixa eu te dizer, o seu futuro na vida como pescad$gor:ora; trará recompensas incomparáveis!$b$bVocê pode melhorar as suas habilidades em pesca, para começar. Fique habilidos$go:a; o bastante e você poderá comprar varas de pescar poderosas.$b$bUm pescador respeitado pode conseguir um mascote peixe especial e uma montaria pernalta marítima. E até mesmo uma jangada de pesca particular!', 19865),
(64720, 'ptBR', 'VITÓRIA!', '', 19865),
(64721, 'ptBR', 'Saudações, $r.$b$bVejo de relance que você $gum:uma; grande aventureir$go:a;.$b$bPor toda essa terra, há criptas obscuras e vastos castelos, todos repletos de terríveis e poderosos inimigos. Eles guardam muitos segredos, mas também... possuem ótimas recompensas.$b$bOs mais bravos heróis podem se aventurar para tentar esses encontros, mas tome cuidado! Você estaria correndo contra o tempo e testando suas habilidades contra outros heróis!$b$bEstá preparad$go:a; para o desafio?', '', 19865),
(64722, 'ptBR', 'Ah, por onde começar?$b$bPrimeiro, a vida de um fazendeiro envolve plantar sementes e colher as safras. As colheitas que você vende podem ser usadas na culinária, vendidas na casa de leilão, trocada entre os compradores ou trocadas por carne e peixe. Eu ouvi até mesmo que sementes raras podem ser plantadas para obter itens raros... e talvez até mesmo mascotinhas!$b$bE então, você ainda tem toda Meia Colina para explorar! A melhor forma de fazer amizade com o pessoal daqui é dando presentes, e, quando se tornarem amigos, eles podem lhe dar uns presentes bem legais em retorno.$b$bSempre tem muita coisa para ser feita por esses campos, e um par de mãos extra certamente é bem-vindo.', '', 19865),
(64723, 'ptBR', 'Bem, os Lavradores não vão ficar enchendo você de joias ou preparando você para a guerra.$b$bAh, a vida de um fazendeiro é um pouquinho diferente.$b$bSe você perseverar, vai conhecer um pessoal bem legal. Você vai poder construir sua própria fazenda, plantar os vegetais que quiser e curtir o fruto do seu trabalho.$b$bEntão, se isso interessar, você deverá ir a Meia Colina e ver com seus próprios olhos!', '', 19865),
(64724, 'ptBR', 'Por que eu deveria ajudar os Lavradores?', 'Por que eu deveria ajudar os Lavradores?', 19865),
(64725, 'ptBR', 'Que tipo de coisa posso fazer com os Lavradores?', 'Que tipo de coisa posso fazer com os Lavradores?', 19865),
(64726, 'ptBR', 'A Ordem da Serpente das Nuvens jurou defender a Floresta de Jade. Nós treinamos no Arboreto, ao norte do Templo da Serpente de Jade, na Floresta de Jade.', '', 19865),
(64727, 'ptBR', 'Não há honra maior que galgar as fileiras da Ordem da Serpente das Nuvens.$b$bQuando você se provar capaz, estará livre para vagar pela terra com sua serpente voadora de montaria.$B$BVocê também aprenderá a habilidade Montaria de Serpente das Nuvens, que permitirá que você cavalgue qualquer serpente das nuvens de montaria em Pandária.', '', 19865),
(64728, 'ptBR', 'Quando você entrar para a Ordem da Serpente das Nuvens, você começará uma jornada para ser $gum:uma; cavalga-serpentes.$b$bVocê vai criar um filhote de serpente desde o ovo, treiná-lo todos os dias e observar o crescimento dele até a vida adulta.', '', 19865),
(64729, 'ptBR', 'O que significa entrar para a Ordem da Serpente das Nuvens?', 'O que significa entrar para a Ordem da Serpente das Nuvens?', 19865),
(64730, 'ptBR', 'Qual é a recompensa pela ascenção na Ordem da Serpente das Nuvens?', 'Qual é a recompensa pela ascenção na Ordem da Serpente das Nuvens?', 19865),
(64731, 'ptBR', 'Lutar contra o leviatã foi divertido, mas acho que já tivemos aventura pra vida inteira. Boa viagem, $p. Volte quando quiser!', '', 19865),
(64732, 'ptBR', 'Mazu tem sido boa comigo. As águas dela me sustentaram e seus ventos me carregaram para lugares distantes. O que mais eu poderia querer da vida?', '', 19865),
(64733, 'ptBR', '', 'Precisa de um pouco de sorte ao seu lado, $r? Todo mundo precisa de um pouco de sorte para melhorar um pouco as coisas!$b$bNão se preocupe, posso ajudar a ajustar as probabilidades ao seu favor!', 19865),
(64734, 'ptBR', 'Yu''lon, a Serpente de Jade, mantém vigília no leste. Infelizmente, o templo dela foi tomado pelo sha da dúvida.$b$bO templo necessita da nossa ajuda. Devemos fazer o possível para manter o sha longe!', '', 19865),
(64735, 'ptBR', '', 'Isso sim é que é manejar um arpão, hein!', 19865),
(64736, 'ptBR', 'Xuen, o Tigre Branco, protege contra os ventos gelados do norte.$b$BHoje, ele busca testar os maiores campeões da terra em uma série de provas.$b$bSe você se acha mereced$gor:ora;, viaje até o norte, para o Templo do Tigre Branco, e participe do desafio!', '', 19865),
(64737, 'ptBR', 'Chi-Ji protege o Templo da Garça Vermelha ao sul.$b$bEla está tentando reorganizar o local, depois que o surgimento dos shas instaurou o caos na região.$b$bSe você deseja ajudá-la, viaje até o Berço de Chi-Ji, na Selva de Krasarang.', '', 19865),
(64738, 'ptBR', 'Niuzao, o Boi Negro, resiste firme contra os inimigos do outro lado da muralha.$b$bEle precisa desesperadamente de ajuda para enfrentar a invasão dos mantídeos.$b$bSe quiser ajudar, viaje para oeste, para o templo nas Estepes de Taolong.', '', 19865),
(64739, 'ptBR', 'Ao defender os quatro templos, você ganhará grande prestígio com os Celestiais Majestosos. Será concedido a você a capacidade de comprar itens de grande poder.$b$bCom isso, você irá ajudar a defender essas terras de alguns dos nossos maiores inimigos.', '', 19865),
(64740, 'ptBR', 'Por que eu devo ajudar os Celestiais Majestosos?', 'Por que eu devo ajudar os Celestiais Majestosos?', 19865),
(64741, 'ptBR', 'Como posso ajudar os Celestiais Majestosos hoje?', 'Como posso ajudar os Celestiais Majestosos hoje?', 19865),
(64742, 'ptBR', '', 'O Vale das Flores Eternas corre grande perigo, $r.$B$BGarrosh Grito Infernal corrompeu as águas de nosso Vale sagrado com o Coração de Y''Shaarj, uma relíquia sombria de um mal ancestral. Os efeitos desse ato... bem... você mesm$go:a; pode ver aqui no Vale.$B$BAgora resquícios do sha ameaçam nossa própria existência. Não temos outra alternativa senão lutar.', 19865),
(64743, 'ptBR', '', 'O Vale das Flores Eternas corre grande perigo, $r.$B$BGarrosh Grito Infernal corrompeu as águas de nosso Vale sagrado com o Coração de Y''Shaarj, uma relíquia sombria de um mal ancestral. Os efeitos desse ato... bem... você mesm$go:a; pode ver aqui no Vale.$B$BAgora resquícios do sha ameaçam nossa própria existência. Não temos outra alternativa senão lutar.', 19865),
(64744, 'ptBR', '', 'É claro. É justo recompensar aqueles que arriscam a vida pela nossa causa.$b$bAo ajudar a defender o vale, você não apenas manterá nossas fronteiras a salvo como receberá acesso aos nossos vastos armazéns de tesouros poderosos.', 19865),
(64745, 'ptBR', 'Receberei alguma recompensa por ajudar a defender o vale?', 'Receberei alguma recompensa por ajudar a defender o vale?', 19865),
(64746, 'ptBR', 'Como posso ajudar o Lótus Dourado?', 'Como posso ajudar o Lótus Dourado?', 19865),
(64747, 'ptBR', 'Por favor, leve-me até Zan''vess.', 'Por favor, leve-me até Zan''vess.', 19865),
(64748, 'ptBR', 'Por favor, leve-me até Kypari Zar.', 'Por favor, leve-me até Kypari Zar.', 19865),
(64749, 'ptBR', 'Os Shado-Pans são uma ordem de elite, enviados para lidar com os problemas em Pandária. Existem muitas formas de ganhar a estima deles.$b$bOs Shado-Pans estão ocupados lidando com as erupções do sha em várias áreas do Monte Kun-Lai. Ajude-os, e você abrirá as portas da nossa irmandade.$b$bO Monastério Shado-pan está com problemas. Talvez você possa oferecer ajuda aos nossos irmãos por lá.$b$bO Sha do Ódio ronda os campos de Kun-Lai, ao norte. Derrote-o, e você ganhará bastante respeito na nossa ordem.$b$bPara terminar, um grande contingente de Shado-Pans foi enviado para perseguir o Sha do Ódio nos Estepes de Taolong.$b$bVocê poderá encontrar os Shado-Pans por lá, com bastante trabalho a ser feito.', '', 19865),
(64750, 'ptBR', 'O Shado-Pan é uma ordem ancestral que aceita e treina apenas a elite e os melhores.$b$bSe você se provar útil, poderá encontrar muitos itens poderosos à disposição.', '', 19865),
(64751, 'ptBR', 'Por que eu devo ajudar os Shado-Pans?', 'Por que eu devo ajudar os Shado-Pans?', 19865),
(64752, 'ptBR', 'Como posso ajudar os Shado-Pans?', 'Como posso ajudar os Shado-Pans?', 19865),
(64753, 'ptBR', 'Os Andarilhos das Lendas viajam o mundo, descobrindo novas lendas e recontando as antigas.$b$bNós exploramos a rica história dos locais e pessoas em Pandária.$b$bSe você quiser ouvir uma dessas histórias, fale com o Andarilho das Lendas Cho no Trono do Conhecimento, acima da entrada do Palácio Mogu''shan, aqui no Vale das Flores Eternas.', '', 19865),
(64754, 'ptBR', 'Os Andarilho das Lendas enviarão você para explorar áreas significativas de Pandária e reaver artefatos culturais.$b$bQuando você encontrar todos os artefatos que fazem parte de uma coleção, você poderá ouvir toda a história do início ao fim.$b$bEncontre todos os artefatos e colecione todos os livros para se tornar $gum:uma; Andarilh$go:a; das Lendas!$b$bSe você quiser se tornar $gum:uma; pesquisad$gor:ora;, fale com o Andarilho das Lendas Cho no Trono do Conhecimento.', '', 19865),
(64755, 'ptBR', 'A jornada é a própria recompensa, jovem. Busque prazer no contar da história, e você irá obter riquezas sem comparação.$b$bAh, sim, mais uma coisa. Aqueles que sobem de posto entre os Andarilhos das Lendas recebem um presente muito especial – a habilidade de cavalgar as nuvens.', 'A jornada é a própria recompensa, jovem. Busque prazer no contar da história, e você irá obter riquezas sem comparação.$b$bAh, sim, mais uma coisa. Aqueles que sobem de posto entre os Andarilhos das Lendas recebem um presente muito especial – a habilidade de cavalgar as nuvens.', 19865),
(64756, 'ptBR', 'Por que eu devo ajudar os Andarilhos das Lendas?', 'Por que eu devo ajudar os Andarilhos das Lendas?', 19865),
(64757, 'ptBR', 'Como posso ajudar os Andarilhos das Lendas?', 'Como posso ajudar os Andarilhos das Lendas?', 19865),
(64758, 'ptBR', '', 'Acabei de voltar da muralha.$b$bLá, ouvi rumores de que uma facção chamada Klaxxi, além do Espinhaço da Serpente. Teoricamente, eles são um conselho de mantídeos anciãos que se separaram do Império Mantídeo e, agora, trabalham desafiando diretamente a rainha dos mantídeos.$b$bVi com meus próprios olhos a força que esses mantídeos possuem.$b$bSe esses rumores forem verdade, então talvez exista uma forma de se aliar a esses... Klaxxi... e juntos impedirmos o enxame mantídeo.', 19865),
(64759, 'ptBR', '', 'É um mistério para mim, $r. Se você quer descobrir, é maluc$go:a; e idiota!$b$bMas eu acho que não tem outra forma de conhecer os Klaxxi a não ser ultrapassando a muralha e indo para o Ermo do Medo.', 19865),
(64760, 'ptBR', '', 'Eu não sei, $r.$b$bSabemos muito pouco sobre os Klaxxi. Eles parecem ser bastante cruéis, então talvez sua única recompensa seja uma morte rápida.$b$bPor outro lado, a civilização deles é bem vasta e avançada. Se você se aproximar do jeito certo, talvez eles lhe concedam um poder desconhecido.$b$bSó tem um jeito de descobrir.', 19865),
(64761, 'ptBR', 'Como vou ser recompensad$go:a; por ajudar os Klaxxi?', 'Como vou ser recompensad$go:a; por ajudar os Klaxxi?', 19865),
(64762, 'ptBR', 'Como posso ajudar os Klaxxi?', 'Como posso ajudar os Klaxxi?', 19865),
(64763, 'ptBR', '', 'A serpente está aqui!', 19865),
(64764, 'ptBR', '', 'Ji terminou a montagem. Use os fogos para derrubar o dragão.', 19865),
(64765, 'ptBR', '', 'Você é ágil. Mantenha o ritmo!', 19865),
(64766, 'ptBR', '', 'É assim que se faz!', 19865),
(64767, 'ptBR', '', 'Você conseguiu! Rápido, vamos atacar enquanto ele está no chão.', 19865),
(64768, 'ptBR', '', 'Derrubamos! Vamos acabar com isso.', 19865),
(64769, 'ptBR', '', 'Incrível! Você pode lutar ao meu lado sempre que quiser.', 19865),
(64772, 'ptBR', 'Eu vim com o iaque. Se um sorte-sim é sábio o suficiente para comprar, serei sábio o suficiente para vender meus produtos a ele.', '', 19865),
(64773, 'ptBR', 'Eu deixo os sorte-sins ainda mais sortudos. Me traga um item e vou mudar a sua sorte para melhor servi-l$go:a;... mas por um preço.', '', 19865),
(64774, 'ptBR', 'Estamos cercando o Templo Niuzao.$b$bVocê é conhecid$go:a; para nós, $n. Sua ajuda é necessária mais uma vez.', '', 19865),
(64775, 'ptBR', 'Eu tenho um iaque para você!', '', 19865),
(64776, 'ptBR', 'Saudações, viajante.', '', 19865),
(64777, 'ptBR', 'O que é o Vale das Flores Eternas?', 'O que é o Vale das Flores Eternas?', 19865),
(64778, 'ptBR', '', 'Nós lutamos com mantídeos, yaungóis e mogus. Os inimigos nos cercam de todos os lados.\n\nEstou aqui para garantir que não haja surpresas.', 19865),
(64779, 'ptBR', 'Aarrr... galerosos!', '', 19865),
(64780, 'ptBR', 'Alá... toleteiros!', '', 19865),
(64781, 'ptBR', 'Oh - claro que você não ouviu falar do Vale.$b$bHá doze mil anos, ele era o centro do poder dos Mogus, o coração do império. Diz a lenda que havia fontes sagradas lá, fonte da magia Mogu que os permitia torcer e moldar a carne. Mas elas também propiciavam milagres de cura. Quer dizer, se você acreditar nas histórias.$b$bApós a revolução dos pandarens, os Celestiais concordaram em isolar o Vale para que o poder das fontes nunca pudesse ser usado para o mal.', '', 19865),
(64782, 'ptBR', 'Eiaaaaarrr!', '', 19865),
(64783, 'ptBR', 'Vô cascá tua pandurra!', '', 19865),
(64784, 'ptBR', 'Você está no menu!', '', 19865),
(64785, 'ptBR', 'Cozinha maravilhosa do Fedentinho!', '', 19865),
(64786, 'ptBR', 'Guisado de galerito, tá na mão!', '', 19865),
(64787, 'ptBR', 'Eu quero é hozenar!', '', 19865),
(64788, 'ptBR', 'Galerosos vão levar na palhaça!', '', 19865),
(64789, 'ptBR', 'Dança galerito! Dança!', '', 19865),
(64790, 'ptBR', 'Ba-ba-BUUM!', '', 19865),
(64791, 'ptBR', 'Ba-ba-ba-BAM!', '', 19865),
(64792, 'ptBR', 'Galerosos vão levar BUMBA na zabumba!', '', 19865),
(64793, 'ptBR', 'Tenho um presente pra você.', '', 19865),
(64794, 'ptBR', 'Diga "oi" pro "adeusinho"!', '', 19865),
(64795, 'ptBR', 'Quem está no Vale agora?', 'Quem está no Vale agora?', 19865),
(64796, 'ptBR', 'Sua mente foi envenenada com |cFFFF0404|Hspell:124862|h[Visões de Macabras]|h|r !', 'Sua mente foi envenenada com |cFFFF0404|Hspell:124862|h[Visões de Macabras]|h|r !', 19865),
(64797, 'ptBR', 'Quase ninguém. Ele é protegido por um grupo chamado "O Lótus Dourado". Membros do Lótus Dourado são escolhidos a dedo pelos Celestiais para vigiar o Vale, e seu número é bem reduzido.$b$bEu tenho ouvido histórias sobre o Vale desde que era um filhote. Dá pra acreditar que um lugar assim exista mesmo?$b$bVocê acha que as histórias sobre as fontes são verdadeiras? Eu queria ver com meus próprios olhos!', '', 19865),
(64798, 'ptBR', 'Mas que raio é aquilo?', '', 19865),
(64799, 'ptBR', 'Oh! Você não vai pegar meu filho tão mole!', '', 19865),
(64800, 'ptBR', 'Você esqueceu com quem está lutando?', '', 19865),
(64801, 'ptBR', 'Permita que eu lhe mostre como um Rosarães caça!', '', 19865),
(64802, 'ptBR', 'Bom, ruim, eu sou o cara com a arma.', '', 19865),
(64803, 'ptBR', 'Ninguém se mete com o MEU menino!', '', 19865),
(64804, 'ptBR', 'Tira aquela coisa nojenta da cabeça do meu menino!', '', 19865),
(64805, 'ptBR', 'Cuidado com essas névoas! Essa coisa parece venenosa.', '', 19865),
(64806, 'ptBR', 'É uma melancolia obscura, com certeza. Tenha cuidado!', '', 19865),
(64807, 'ptBR', 'Você sabe o que é aquela coisa?', '', 19865),
(64808, 'ptBR', 'Da próxima vez que a gente for caçar, cubra esses seus olhos brilhantes. Eles te denunciam.', '', 19865),
(64809, 'ptBR', 'Mirem no olho!', '', 19865),
(64810, 'ptBR', 'Não fica no fogo, colega!', '', 19865),
(64811, 'ptBR', '$p, aqui perto do final da ponte.', '', 19865),
(64812, 'ptBR', 'Trabalho de mestre.$b$bNão teríamos conseguido sem você.', '', 19865),
(64813, 'ptBR', '', 'Ao defender os quatro templos, você ganhará grande prestígio com os Celestiais Majestosos. Será concedido a você a capacidade de comprar itens de grande poder.$b$bCom isso, você irá ajudar a defender essas terras de alguns dos nossos maiores inimigos.', 19865),
(64814, 'ptBR', '', 'Yu''lon, a Serpente de Jade, mantém vigília no leste. Infelizmente, o templo dela foi tomado pelo sha da dúvida.$b$bO templo necessita da nossa ajuda. Devemos fazer o possível para manter o sha longe!', 19865),
(64815, 'ptBR', '', 'Xuen, o Tigre Branco, protege contra os ventos gelados do norte.$b$BHoje, ele busca testar os maiores campeões da terra em uma série de provas.$b$bSe você se acha mereced$gor:ora;, viaje até o norte, para o Templo do Tigre Branco, e participe do desafio!', 19865),
(64816, 'ptBR', '', 'Chi-Ji protege o Templo da Garça Vermelha ao sul.$b$bEla está tentando reorganizar o local, depois que o surgimento dos shas instaurou o caos na região.$b$bSe você deseja ajudá-la, viaje até o Berço de Chi-Ji, na Selva de Krasarang.', 19865),
(64817, 'ptBR', '', 'Niuzao, o Boi Negro, resiste firme contra os inimigos do outro lado da muralha.$b$bEle precisa desesperadamente de ajuda para enfrentar a invasão dos mantídeos.$b$bSe quiser ajudar, viaje para oeste, para o templo nas Estepes de Taolong.', 19865),
(64818, 'ptBR', 'É claro. É justo recompensar aqueles que arriscam a vida pela nossa causa.$b$bAo ajudar a defender o vale, você não apenas manterá nossas fronteiras a salvo como receberá acesso aos nossos vastos armazéns de tesouros poderosos.', '', 19865),
(64819, 'ptBR', 'O Vale das Flores Eternas corre grande perigo, $r.$B$BGarrosh Grito Infernal corrompeu as águas de nosso Vale sagrado com o Coração de Y''Shaarj, uma relíquia sombria de um mal ancestral. Os efeitos desse ato... bem... você mesm$go:a; pode ver aqui no Vale.$B$BAgora resquícios do sha ameaçam nossa própria existência. Não temos outra alternativa senão lutar.', '', 19865),
(64820, 'ptBR', 'Não há mais nada a ser feito pelo vale no momento, $n. Os mogus desapareceram logo após você ter matado o líder deles. Estamos a salvo, graças a você.', '', 19865),
(64821, 'ptBR', '', 'Os Andarilhos das Lendas viajam o mundo, descobrindo novas lendas e recontando as antigas.$b$bNós exploramos a rica história dos locais e pessoas em Pandária.$b$bSe você quiser ouvir uma dessas histórias, fale com o Andarilho das Lendas Cho no Trono do Conhecimento, acima da entrada do Palácio Mogu''shan, aqui no Vale das Flores Eternas.', 19865),
(64822, 'ptBR', '', 'Os Andarilho das Lendas enviarão você para explorar áreas significativas de Pandária e reaver artefatos culturais.$b$bQuando você encontrar todos os artefatos que fazem parte de uma coleção, você poderá ouvir toda a história do início ao fim.$b$bEncontre todos os artefatos e colecione todos os livros para se tornar $gum:uma; Andarilh$go:a; das Lendas!$b$bSe você quiser se tornar $gum:uma; pesquisad$gor:ora;, fale com o Andarilho das Lendas Cho no Trono do Conhecimento.', 19865),
(64823, 'ptBR', '', 'A jornada é a própria recompensa, jovem. Busque prazer no contar da história, e você irá obter riquezas sem comparação.$b$bAh, sim, mais uma coisa. Aqueles que sobem de posto entre os Andarilhos das Lendas recebem um presente muito especial – a habilidade de cavalgar as nuvens.', 19865),
(64824, 'ptBR', 'O Shado-Pan é uma ordem ancestral que aceita e treina apenas a elite e os melhores.$b$bSe você se provar útil, poderá encontrar muitos itens poderosos à disposição.', '', 19865),
(64825, 'ptBR', 'Os Shado-Pans são uma ordem de elite, enviados para lidar com os problemas em Pandária. Existem muitas formas de ganhar a estima deles.$b$bOs Shado-Pans estão ocupados lidando com as erupções do sha em várias áreas do Monte Kun-Lai. Ajude-os, e você abrirá as portas da nossa irmandade.$b$bO Monastério Shado-pan está com problemas. Talvez você possa oferecer ajuda aos nossos irmãos por lá.$b$bO Sha do Ódio ronda os campos de Kun-Lai, ao norte. Derrote-o, e você ganhará bastante respeito na nossa ordem.$b$bPara terminar, um grande contingente de Shado-Pans foi enviado para perseguir o Sha do Ódio nos Estepes de Taolong.$b$bVocê poderá encontrar os Shado-Pans por lá, com bastante trabalho a ser feito.', '', 19865),
(64826, 'ptBR', 'Queimem os navios deles. Matem o mestre de voo. Sabotem as máquinas de guerra. E resgatem nosso espião!', '', 19865),
(64827, 'ptBR', 'Acabei de voltar da muralha.$b$bLá, ouvi rumores de que uma facção chamada Klaxxi, além do Espinhaço da Serpente. Teoricamente, eles são um conselho de mantídeos anciãos que se separaram do Império Mantídeo e, agora, trabalham desafiando diretamente a rainha dos mantídeos.$b$bVi com meus próprios olhos a força que esses mantídeos possuem.$b$bSe esses rumores forem verdade, então talvez exista uma forma de se aliar a esses... Klaxxi... e juntos impedirmos o enxame mantídeo.', '', 19865),
(64828, 'ptBR', 'É um mistério para mim, $r. Se você quer descobrir, é maluc$go:a; e idiota!$b$bMas eu acho que não tem outra forma de conhecer os Klaxxi a não ser ultrapassando a muralha e indo para o Ermo do Medo.', '', 19865),
(64829, 'ptBR', 'Eu não sei, $r.$b$bSabemos muito pouco sobre os Klaxxi. Eles parecem ser bastante cruéis, então talvez sua única recompensa seja uma morte rápida.$b$bPor outro lado, a civilização deles é bem vasta e avançada. Se você se aproximar do jeito certo, talvez eles lhe concedam um poder desconhecido.$b$bSó tem um jeito de descobrir.', '', 19865),
(64830, 'ptBR', 'Espalhem o caos enquanto nos reagrupamos. Os olhos de Grito Infernal estão sobre vocês!', '', 19865),
(64831, 'ptBR', 'Ji Pata de Fogo abraça você calorosamente.', '', 19865),
(64832, 'ptBR', '', 'A Ordem da Serpente das Nuvens jurou defender a Floresta de Jade. Nós treinamos no Arboreto, ao norte do Templo da Serpente de Jade, na Floresta de Jade.', 19865),
(64833, 'ptBR', '', 'Não há honra maior que galgar as fileiras da Ordem da Serpente das Nuvens.$b$bQuando você se provar capaz, estará livre para vagar pela terra com sua serpente voadora de montaria.$B$BVocê também aprenderá a habilidade Montaria de Serpente das Nuvens, que permitirá que você cavalgue qualquer serpente das nuvens de montaria em Pandária.', 19865),
(64834, 'ptBR', '', 'Quando você entrar para a Ordem da Serpente das Nuvens, iniciará uma jornada para se tornar $gum:uma; cavalga-serpentes.$b$bVocê vai criar um filhote de serpente desde o ovo, treiná-lo todos os dias e observar o crescimento dele até a vida adulta.', 19865),
(64835, 'ptBR', 'O barril explode, apagando as chamas de %s!', '', 19865),
(64836, 'ptBR', 'Bem, os Lavradores não vão ficar enchendo você de joias ou preparando você para guerra.$b$bÉ uma vida mais calma, mas boa. Pergunte ao Dooka, ele sabe!$b$bVocê pode ter a sua própria fazenda, plantar suas sementes e desfrutar de toda comida que você plantou! Essa é a parte favorita do Dooka! Se isso interessar, vai até Meia Colina pra ver com seus próprios olhos!', '', 19865),
(64837, 'ptBR', 'Ah, onde Dooka começa?!$b$bPrimeiro, fazendeiro planta semente e colhe as plantas. Vegetais podem ser usados na culinária, vendidos no mercado, trocados com outros vendedores e várias outras coisas. Eu ouvi até mesmo que sementes raras podem ser plantadas pra colher itens especiais... como um pequeno mascote!$b$bEntão, tem todo mundo aqui em Meia Colina para conhecer! As pessoas daqui são bem legais, até mesmo pra um macaco como eu. Você dá presentes pra eles, e eles podem te dar presentes legais também!$b$bSempre tem bastante coisa pra fazer nesses campos!', '', 19865),
(64838, 'ptBR', 'A artilharia mantídea está aqui, apressem-se, heróis!', '', 19865),
(64839, 'ptBR', 'A melhor pesca pode ser encontrada no Cais dos Pescadores, a sudeste da Selva de Krasarang. Todos são bem-vindos para nos visitar e pegar sua vara de pesca!', '', 19865),
(64840, 'ptBR', 'Como assim, o que você ganharia com isso? Que tipo de pergunta é essa?$B$BO prazer de pescar aquele maior peixão do mar não é suficiente? E a sensação do sol nas costas e a água salgada do oceano espirrando no rosto? E quanto a abrir uma cerveja gelada enquanto se reclina e conversa com os amigos?$B$BIsso não é suficiente?!?!$b$bDeixa eu te dizer, o seu futuro na vida como pescad$gor:ora; trará recompensas incomparáveis!$B$BVocê pode melhorar as suas habilidades em pesca, para começar. Fique habilidos$go:a; o bastante e você poderá comprar varas de pescar poderosas.$B$BUm pescador respeitado pode conseguir um mascote peixe especial e uma montaria pernalta marítima. E até mesmo uma jangada de pesca particular!', '', 19865),
(64841, 'ptBR', '', 'Aqueles que participam dos cenários dos Cervejeiros serão lembrados. E, caso você encontre itens raros na sua aventura como cervejeir$go:a;, eles serão seus!', 19865),
(64842, 'ptBR', '', 'A maior cervejaria em Pandária é a Cervejaria Malte do Trovão, no Vale dos Quatro Ventos. Você pode começar por lá se estiver procurando aventuras.$b$bOs mestres cervejeiros são andarilhos por natureza, e podem ser encontrados vagando por toda a terra, buscando ingredientes raros ou preparando novas cervejas.$B$BO Mestre Cervejeiro Tzu enfrenta inimigos no cenário da Vila Rocha Verde.$b$bO Mestre Cervejeiro Bo procura sabores tropicais no cenário de Ungá Ingô.$b$bO Mestre Cervejeiro Buf celebra a festa da lua no cenário do Festival da Cerveja da Lua, e a Mestre Cervejeira Blanche está fermentando algo incrível na Tempestade Cervejeira.', 19865),
(64843, 'ptBR', '', 'A Mestre Cervejeira Blanche está tentando fazer uma Cerveja Explosiva em meio a uma tempestade, mas alguns inimigos estão atrapalhando.', 19865),
(64844, 'ptBR', '', 'Resgate a Cerveja Selvagem das garras dos piratas hozens malvados de Ungá Ingô.', 19865),
(64845, 'ptBR', '', 'Prepare algo delicioso e defenda-se dos atacantes yaungóis.', 19865),
(64846, 'ptBR', '', 'Resgate os aldeões da Rocha Verde dos arteiros (e perigosos) habitantes da floresta.', 19865),
(64847, 'ptBR', '', 'Qual mestre cervejeiro você gostaria ajudar hoje?', 19865),
(64848, 'ptBR', '', 'Graças a Shen-zin Su por você estar aqui. Preciso de ajuda!', 19865),
(64849, 'ptBR', '', 'Saia da frente quando ele erguer a arma. Ele é mais forte do que parece.', 19865),
(64850, 'ptBR', '', 'Ele chamou reforços! Vou manter ele ocupado e você cuida dos outros.', 19865),
(64852, 'ptBR', '', 'Ele está ficando cansado. Continue assim.', 19865),
(64853, 'ptBR', '', 'Ah, não sei o que faria sem você. Que bom que você veio.', 19865),
(64855, 'ptBR', 'Arqueiros de Gelo Shado-Pan aparecem nos telhados!', '', 19865),
(64856, 'ptBR', 'Tivemos a sorte de achar o Vale depois que abriram os portões. Buscávamos refúgio, e encontramos um abrigo seguro.$b$bVocê está perdid$go:a;? Posso ajudar você a encontrar alguma coisa?', 'Tivemos a sorte de achar o Vale depois que abriram os portões. Buscávamos refúgio, e encontramos um abrigo seguro.$b$bVocê está perdid$go:a;? Posso ajudar você a encontrar alguma coisa?', 19865),
(64857, 'ptBR', 'Tivemos a sorte de achar o Vale depois que abriram os portões. Buscávamos refúgio, e encontramos um abrigo seguro.$b$bVocê está perdid$go:a;? Posso ajudar você a encontrar alguma coisa?', 'Tivemos a sorte de achar o Vale depois que abriram os portões. Buscávamos refúgio, e encontramos um abrigo seguro.$b$bVocê está perdid$go:a;? Posso ajudar você a encontrar alguma coisa?', 19865),
(64858, 'ptBR', '', 'Eu mesmo não faria melhor.$B$BBem, acho que não.', 19865),
(64859, 'ptBR', 'Os navios estão em chamas! Tropas, para o porto!', '', 19865),
(64860, 'ptBR', '', '$p, aqui, perto da saída.', 19865),
(64861, 'ptBR', 'A casa de leilões está no segundo andar, à esquerda conforme você entra.$b$BVou marcar a localização no seu mapa.', 'A casa de leilões está no segundo andar, à esquerda conforme você entra.$b$BVou marcar a localização no seu mapa.', 19865),
(64862, 'ptBR', 'O banco fica no segundo andar, à direita conforme você entra.$b$BVou marcar a localização no seu mapa.', 'O banco fica no segundo andar, à direita conforme você entra.$b$BVou marcar a localização no seu mapa.', 19865),
(64863, 'ptBR', 'O mestre de voo está localizado no terraço principal, no topo das escadas, antes de entrar no prédio principal.$b$BVou marcar a localização no seu mapa.', 'O mestre de voo está localizado no terraço principal, no topo das escadas, antes de entrar no prédio principal.$b$BVou marcar a localização no seu mapa.', 19865),
(64864, 'ptBR', 'A estalagem está no andar principal, à direita de quem entra no prédio.$b$bVou marcar a localização no seu mapa.', 'A estalagem está no andar principal, à direita de quem entra no prédio.$b$bVou marcar a localização no seu mapa.', 19865),
(64865, 'ptBR', 'Jaul Hsu, mestre de estábulo, pode ser encontrado no terraço principal, antes de entrar no prédio principal. Ele está ao lado do mestre de voo.$b$BVou marcar a localização no seu mapa.', 'Jaul Hsu, mestre de estábulo, pode ser encontrado no terraço principal, antes de entrar no prédio principal. Ele está ao lado do mestre de voo.$b$BVou marcar a localização no seu mapa.', 19865),
(64866, 'ptBR', 'Os etéreos se estabeleceram no corredor do andar de cima, à direita de quem entra no prédio principal.$b$bVou marcar a localização no seu mapa.', 'Os etéreos se estabeleceram no corredor do andar de cima, à direita de quem entra no prédio principal.$b$bVou marcar a localização no seu mapa.', 19865),
(64867, 'ptBR', 'Yanyra Quedaluna vende reagentes, e pode ser encontrada no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 'Yanyra Quedaluna vende reagentes, e pode ser encontrada no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 19865),
(64868, 'ptBR', 'Raishen, a Agulha, é bem conhecida pelas belas roupas que faz.$b$bEla trabalha no salão dos artesãos, à esquerda de quando entramos no prédio.$b$bVou marcar a localização no seu mapa.', 'Raishen, a Agulha, é bem conhecida pelas belas roupas que faz.$b$bEla trabalha no salão dos artesãos, à esquerda de quando entramos no prédio.$b$bVou marcar a localização no seu mapa.', 19865),
(64869, 'ptBR', 'Clara Henry oferece suprimentos para encantamento. Você pode encontrá-la no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 'Clara Henry oferece suprimentos para encantamento. Você pode encontrá-la no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 19865),
(64870, 'ptBR', 'Ah, $gum:uma; escriba de pergaminhos! Você está procurando tintas e velino, não? Você pode encontrá-los no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 'Ah, $gum:uma; escriba de pergaminhos! Você está procurando tintas e velino, não? Você pode encontrá-los no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 19865),
(64871, 'ptBR', 'Sim, existe um comerciante de ervas na cidade. Você pode encontrar o Tommy Funileiro no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 'Sim, existe um comerciante de ervas na cidade. Você pode encontrar o Tommy Funileiro no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 19865),
(64872, 'ptBR', 'Você está procurando pelo boticário. Ele faz umas poções e tinturas realmente incríveis. Acabei com a minha coceira rapidinho!$b$bCof cof... O Boticário Verde Limo vende as mercadorias no salão dos artesãos. Vou marcar a localização no seu mapa.', 'Você está procurando pelo boticário. Ele faz umas poções e tinturas realmente incríveis. Acabei com a minha coceira rapidinho!$b$bCof cof... O Boticário Verde Limo vende as mercadorias no salão dos artesãos. Vou marcar a localização no seu mapa.', 19865),
(64873, 'ptBR', 'Preparad$go:a; para preparar uma refeição quente? Você encontrará tudo o que precisa com Jojo. Ela vende os produtos no salão dos artesãos.$b$bVou marcar a localização no seu mapa.', 'Preparad$go:a; para preparar uma refeição quente? Você encontrará tudo o que precisa com Jojo. Ela vende os produtos no salão dos artesãos.$b$bVou marcar a localização no seu mapa.', 19865),
(64874, 'ptBR', 'Os ferreiros trabalham juntos no salão dos artesãos, à esquerda após entrar no prédio principal.$b$bVou marcar a localização no seu mapa.', 'Os ferreiros trabalham juntos no salão dos artesãos, à esquerda após entrar no prédio principal.$b$bVou marcar a localização no seu mapa.', 19865),
(64875, 'ptBR', 'Você pode comprar suprimentos de mineração no salão dos artesãos, à esquerda após entrar no prédio principal.$b$bVou marcar a localização no seu mapa.', 'Você pode comprar suprimentos de mineração no salão dos artesãos, à esquerda após entrar no prédio principal.$b$bVou marcar a localização no seu mapa.', 19865),
(64876, 'ptBR', 'Eu acho que me lembro de um engenheiro no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 'Eu acho que me lembro de um engenheiro no salão dos artesãos, à esquerda ao entrar no prédio.$b$bVou marcar a localização no seu mapa.', 19865),
(64877, 'ptBR', 'Couraria e peles? Você deve estar procurando um curtumeiro. Tem um no salão dos artesãos, se me lembro bem.$b$bVou marcar a localização no seu mapa.', 'Couraria e peles? Você deve estar procurando um curtumeiro. Tem um no salão dos artesãos, se me lembro bem.$b$bVou marcar a localização no seu mapa.', 19865),
(64878, 'ptBR', 'Ah, espero que seus ferimentos não sejam graves! Os curadores podem ser encontrados no salão principal, à esquerda da escadaria central.$b$bVou marcar a localização no seu mapa.', 'Ah, espero que seus ferimentos não sejam graves! Os curadores podem ser encontrados no salão principal, à esquerda da escadaria central.$b$bVou marcar a localização no seu mapa.', 19865),
(64879, 'ptBR', 'Joalheria? É um trabalho incrível, sem dúvida. Você pode comprar suprimentos com Bero, no salão dos artesãos.$b$BVou marcar a localização no seu mapa.', 'Joalheria? É um trabalho incrível, sem dúvida. Você pode comprar suprimentos com Bero, no salão dos artesãos.$b$BVou marcar a localização no seu mapa.', 19865),
(64880, 'ptBR', 'Você está procurando comida e bebida? Se sim, o Chef do Prato Sway, na estalagem, é exatamente o que você busca.$b$bVou marcar a localização no seu mapa.', 'Você está procurando comida e bebida? Se sim, o Chef do Prato Sway, na estalagem, é exatamente o que você busca.$b$bVou marcar a localização no seu mapa.', 19865),
(64881, 'ptBR', 'Procurando cerveja, é? Bem, temos dois mestres cervejeiros que vagam pela cidade vendendo as deliciosas cervejas que preparam.$b$bSe você não quiser procurar por eles, então Hara Pança de Cerveja, no Descanso do Rouxinol, ou Sarya Flor de Chá, na estalagem, poderão te ajudar.', 'Procurando cerveja, é? Bem, temos dois mestres cervejeiros que vagam pela cidade vendendo as deliciosas cervejas que preparam.$b$bSe você não quiser procurar por eles, então Hara Pança de Cerveja, no Descanso do Rouxinol, ou Sarya Flor de Chá, na estalagem, poderão te ajudar.', 19865),
(64882, 'ptBR', 'Você está se coçando por um docinho? Vá falar com Peônia Rosa.$b$bEla normalmente está passeando pelo terraço frontal ou pelo salão principal do templo.', 'Você está se coçando por um docinho? Vá falar com Peônia Rosa.$b$bEla normalmente está passeando pelo terraço frontal ou pelo salão principal do templo.', 19865),
(64883, 'ptBR', 'O padeiro normalmente está vagando pelo templo. Ele está pelo salão principal ou no terraço.', 'O padeiro normalmente está vagando pelo templo. Ele está pelo salão principal ou no terraço.', 19865),
(64884, 'ptBR', 'Você precisa falar com Miguel Bedernik. Ele oferece um amplo estoque de carnes.$b$bVou marcar a localização dele no seu mapa. Boa sorte!', 'Você precisa falar com Miguel Bedernik. Ele oferece um amplo estoque de carnes.$b$bVou marcar a localização dele no seu mapa. Boa sorte!', 19865),
(64885, 'ptBR', 'Está pensando em fazer uma bagunça? Eu devia comprar uns fogos de artifício! O comerciante pode ser encontrado do lado de fora do terraço principal.$b$bVou marcar a localização no seu mapa.', 'Está pensando em fazer uma bagunça? Eu devia comprar uns fogos de artifício! O comerciante pode ser encontrado do lado de fora do terraço principal.$b$bVou marcar a localização no seu mapa.', 19865),
(64886, 'ptBR', 'Grande Tigre, os forasteiros de além da névoa... não podemos confiar neles. Os destroços na Floresta de Jade comprovam isso.', '', 19865),
(64887, 'ptBR', 'Neste exato momento um zepelin se aproxima; sua carga arcana vai devastar a Ilha Theramore e todos que nela estiverem.', '', 19865),
(64888, 'ptBR', '...Eu os vi com os próprios olhos: Legiões mogus, invadindo o Vale em peso. Não fomos treinados para combate em larga escala!', '', 19865),
(64889, 'ptBR', 'Nos dê a chance de consertar as coisas.', '', 19865),
(64890, 'ptBR', 'É isso aí. Se você passar por Luaprata, venha bater um papo comigo. Al diel shala...', '', 19865),
(64892, 'ptBR', '', 'Saudações, viajante. Bem-vind$go:a; à Lanterna Dourada!', 19865),
(64893, 'ptBR', '', 'Descanse seus pés cansados, $r. Comida e bebida de ótima qualidade esperam por você lá dentro.', 19865),
(64894, 'ptBR', '', 'Ah, você está muito magricela, $r. Você precisa comer alguma coisa. Sente-se e lhe servirei algo.', 19865),
(64895, 'ptBR', '', 'Aqui, na Lanterna Dourada, nossas serpentinas nunca secam e os barris nunca param de rolar! Em que posso ajudar?', 19865),
(64896, 'ptBR', '', 'Bem-vind$go:a; à Lanterna Dourada, a melhor estalagem do vale. Se qualquer um quiser discutir isso, vai ter de se entender com os meus punhos.', 19865),
(64897, 'ptBR', '', 'Tenho as camas de pena mais macias que você pode encontrar em mil léguas. Gostaria de experimentar?', 19865),
(64898, 'ptBR', '', 'Você está comendo o suficiente, $r? Lembre-se de cuidar da sua saúde.', 19865),
(64899, 'ptBR', '', 'Minha estalagem oferece todo conforto de um lar e muito mais. Sinta-se à vontade.', 19865),
(64900, 'ptBR', 'Tinturas, poções, tragos e tônicos!', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(64901, 'ptBR', 'Ampolas, compre ampolas aqui!', '', 19865),
(64902, 'ptBR', 'Pão fresquinho e quentinho!', '', 19865),
(64903, 'ptBR', 'Você foi afetado por |cFFFF0404|Hspell:123788|h[Grito de Terror]|h|r !', 'Você foi afetado por |cFFFF0404|Hspell:123788|h[Grito de Terror]|h|r !', 19865),
(64904, 'ptBR', 'Pão fresquinho que acabou de sair do forno! Compre o seu!', '', 19865),
(64905, 'ptBR', '', 'Flores à venda, compre belíssimas flores!', 19865),
(64906, 'ptBR', '%s se refugia em sua crisálida!', '%s se refugia em sua crisálida!', 19865),
(64907, 'ptBR', '%s emerge de sua crisálida!', '%s emerge de sua crisálida!', 19865),
(64908, 'ptBR', '', 'Flores recém-colhidas à venda!', 19865),
(64909, 'ptBR', '', 'Lindas flores para o seu amor! Compre flores!', 19865),
(64910, 'ptBR', '', 'Compre essas lindas flores antes que elas murchem! Flores à venda!', 19865),
(64911, 'ptBR', 'O Sha do Medo |cFFFF0404|Hspell:126121|h[Corrompe]|h|r um campo de dissonância!', 'O Sha do Medo |cFFFF0404|Hspell:126121|h[Corrompe]|h|r um campo de dissonância!', 19865),
(64912, 'ptBR', 'Boa menina, Saari.', '', 19865),
(64913, 'ptBR', 'Que gatinhoa boazinha.', '', 19865),
(64914, 'ptBR', 'Bom, hora de se alongar.', '', 19865),
(64915, 'ptBR', 'Saari! Pega!', '', 19865),
(64916, 'ptBR', 'Hehe, isso é o que eu ganho por mandar um gato pegar alguma coisa!', '', 19865),
(64917, 'ptBR', 'Eu amo a mamãe e o papai.', '', 19865),
(64918, 'ptBR', 'Olha só para ele! Ele está sempre meio ranzinza de manhã.', '', 19865),
(64919, 'ptBR', 'Nossa, olha só aquilo! É imenso!', '', 19865),
(64920, 'ptBR', 'É maior que duas casas juntas!', '', 19865),
(64921, 'ptBR', 'Não chegue muito perto, Maia! Você vai ficar sem cabeça, desse jeito!', '', 19865),
(64922, 'ptBR', '', 'Não é não! Não seja idiota!', 19865),
(64923, 'ptBR', '', 'Eu quero um doce!', 19865),
(64924, 'ptBR', 'Não toque no tigre grande, Maia! Ele vai comer você no jantar!', '', 19865),
(64925, 'ptBR', '', 'Opaaa... Gatinho grande!', 19865),
(64926, 'ptBR', '', 'Ecaaaaaaaaaaaaa!', 19865),
(64927, 'ptBR', 'Aaaauuuuggghhhhh!', '', 19865),
(64928, 'ptBR', 'Não se preocupe, Maia. Eu protejo você.', '', 19865),
(64929, 'ptBR', '', 'Parece assustadoooor.', 19865),
(64930, 'ptBR', '', 'Algum dia, vou voar num desses.', 19865),
(64931, 'ptBR', 'Ei, moça, você pode nos mostrar uns fogos de artifício?', '', 19865),
(64932, 'ptBR', '', 'O que essa coisa moça faz?', 19865),
(64933, 'ptBR', '', 'Ela realmente faz fogos de artifício?', 19865),
(64934, 'ptBR', '', 'Gostaria de ver alguns fogos de artifício, menininha?', 19865),
(64935, 'ptBR', '', 'Uau! Que BARULHO!', 19865),
(64936, 'ptBR', 'Uaaaaaaaaau!! Isso é legal!', '', 19865),
(64937, 'ptBR', '', 'Connor, estou com fome.', 19865),
(64938, 'ptBR', 'Você acabou de comer. Como pode estar com fome de novo?', '', 19865),
(64939, 'ptBR', '', 'Eu não sei... Eu só sou!', 19865),
(64940, 'ptBR', '', 'Olha aquele ali! Ele é meio... esquisito.', 19865),
(64941, 'ptBR', 'Isso não é legal, Maia. Mesmo que ele seja esquisito, você não deve falar isso na frente dele.', '', 19865),
(64942, 'ptBR', '', 'Ops... desculpe.', 19865),
(64943, 'ptBR', 'Vamos jogar.', '', 19865),
(64944, 'ptBR', '', 'Que téédio!', 19865),
(64945, 'ptBR', '', 'Quem é aquela pessoa?', 19865),
(64946, 'ptBR', 'Aquilo é um jinyu.', '', 19865),
(64947, 'ptBR', '', 'Parece um peixão!', 19865),
(64948, 'ptBR', '', 'Como pode um peixe vivo viver fora da água fria?', 19865),
(64949, 'ptBR', 'Isso porque os jinyus são peixes. Bem, tipo um peixe.', '', 19865),
(64951, 'ptBR', 'Não sei. De repente ele é mágico.', '', 19865),
(64953, 'ptBR', '', 'Podemos andar de pipa, Connor?', 19865),
(64954, 'ptBR', 'Acho que sim.', '', 19865),
(64955, 'ptBR', '', 'Essa aberração destruiu... tudo. Todos.', 19865),
(64956, 'ptBR', '', 'Não podemos permitir que a Horda recupere a Íris Focalizadora. Elimine o que restar das forças deles, e eu pegarei o artefato.', 19865),
(64957, 'ptBR', '', 'Tenho que me sintonizar à Íris Focalizadora antes do transporte. Proteja-me!', 19865),
(64958, 'ptBR', '', 'Seu povo não passa de covardes desprezíveis, orc. Vocês não são nada mais que cães raivosos e serão executados.', 19865),
(64959, 'ptBR', '', 'Você cospe na misericórdia? Então não receberá nenhuma. Você quer carnificina? Garrosh receberá mais sangue do que ele jamais desejou.', 19865),
(64960, 'ptBR', 'Ninguém pode protegê-la. Matem a vadia Proudmore e tragam-me a bomba.', '', 19865),
(64961, 'ptBR', 'Ela num é linda? Suspira...', '', 19865),
(64962, 'ptBR', 'Palavras corajosas, maga. Eu cuspirei na sua cara quando você implorar misericórdia.', '', 19865),
(64963, 'ptBR', 'RAAAARRRRR! Vou levar sua cabeça ao Chefe Guerreiro.', '', 19865),
(64964, 'ptBR', 'Ela é tão esperta e engraçada! Tô caidinho por ela.', '', 19865),
(64965, 'ptBR', 'Como eu falo para ela como eu me sinto? Ai, eu não sou bom com palavras!', '', 19865),
(64966, 'ptBR', 'Você acha que ela algum dia poderá sentir algo por alguém como eu? Eu sou tão... pelado!', '', 19865),
(64967, 'ptBR', 'Eu aposto que ela gosta de homens com o peito peludo. O que eu devo fazer?', '', 19865),
(64968, 'ptBR', 'Você acha que eu devia ir para um desses monastérios treinar e me tornar um monge? Sabe, para impressioná-la?', '', 19865),
(64969, 'ptBR', 'Eu não tenho um barrigão de cerveja. Eu preciso de uma. Certo, estou trabalhando nisso!', '', 19865),
(64970, 'ptBR', 'Eu sei que ela gosta de um cara que aguenta beber, então estou buscando uma resistência maior bebendo toda noite.', '', 19865),
(64971, 'ptBR', '', 'Será que todos os homens são tão lentos na hora de chamar uma garota para sair?', 19865),
(64972, 'ptBR', '', 'Eu acho que ele gosta de mim, mas não tenho certeza. O que você acha, $r?', 19865),
(64973, 'ptBR', '', 'Ah não, e se ele achar que eu sou muito peluda? E se ele não gostar de mulher em preto e branco?', 19865),
(64974, 'ptBR', '', 'Estou paquerando o quanto posso, mas acho que ele não está captando a mensagem!', 19865),
(64975, 'ptBR', '', 'Ele continua falando sobre a chave de arco voltaico e capacitores sobrecarregados. Ele realmente sabe como conquistar uma garota. Rawr!', 19865),
(64976, 'ptBR', '', 'Eu com certeza gosto daquele rostinho bonito.', 19865),
(64977, 'ptBR', 'Há sobreviventes da Aliança! Mandem... reforços...', '', 19865),
(64978, 'ptBR', '[%s] confessa: Uma vez eu peguei um arco que um caçador queria.', '[%s] confessa: Uma vez eu peguei um arco que um caçador queria.', 19865),
(64979, 'ptBR', '', 'Vê alguma armadura que goste, $r? Esses conjuntos de armaduras raras podem ser obtidas ao provar seu valor nas masmorras mais desafiadoras de Pandária.$b$bVocê deve buscar essas masmorras e entrar nelas a pé. Aqueles que vencerem os desafios com velocidade suficiente ganharão o respeito dos nossos mestres de armaduras e encontrarão um presente raro esperando por eles na caixa de correio.', 19865),
(64980, 'ptBR', 'Que a luz esteja contigo, $r.', '', 19865),
(64981, 'ptBR', 'O Príncipe de Ventobravo está desprotegido!  Por que não o capturamos para a Horda?', 'O Príncipe de Ventobravo está desprotegido!  Por que não o capturamos para a Horda?', 19865),
(64982, 'ptBR', 'Vê alguma armadura que goste, $r? Esses conjuntos de armaduras raras podem ser obtidas ao provar seu valor nas masmorras mais desafiadoras de Pandária.$b$bVocê deve buscar essas masmorras e entrar nelas a pé. Aqueles que vencerem os desafios com velocidade suficiente ganharão o respeito dos nossos mestres de armaduras e encontrarão um presente raro esperando por eles na caixa de correio.', '', 19865),
(64983, 'ptBR', 'Hah! Falou como um verdadeiro discípulo de Garrosh Grito Infernal.$b$bMas a MINHA Horda não luta contra crianças desarmadas. Nem eu ousaria trazer a guerra para estas câmara sagrada, na presença de um Celestial Majestoso.$b$bAlém disso, este pequenino conquistou a amizade e a confiança do Grande Chefe Baine Casco Sangrento. Por esse motivo, considere-o sob minha proteção.$b$bPor agora.', '', 19865),
(64984, 'ptBR', 'Eu e minha família somos vítimas desse lugar há eras.$b$bDeixe que nosso destino sirva como aviso àqueles que desejam intervir na necromancia.$b$bMe ajude a remover a maldição, $c. Destrua o Umbromestre Gandling.', '', 19865),
(64985, 'ptBR', 'O Vale das Flores Eternas.$b$bQuem poderia imaginar que o chefe guerreiro seria capaz de destruir um lugar tão lindo.$b$bO Lótus Dourado temia que os mogus retomassem esta terra, mas parece que eles subestimaram o tamanho do orgulho de Garrosh.', '', 19865),
(64986, 'ptBR', 'Oh, olá, $n.$b$bNão podia ter chegado em hora melhor.', '', 19865),
(64987, 'ptBR', 'Nosso lar está perdido mas, enquanto estivermos vivos, ainda há um lar a ser construído... em algum lugar.', '', 19865),
(64988, 'ptBR', 'Viveremos para lutar outro dia, $r.', '', 19865),
(64989, 'ptBR', 'Quando chegamos, encontramos um vale resplandescente. A água das fontes não era como nenhuma outra que já tínhamos provado.$B$BMas então surgiu aquele que chamam de Garrosh Grito Infernal, e ele deixou apenas destruição atrás de si. Quando partiu, as águas do Vale já não eram as mesmas.', '', 19865),
(64990, 'ptBR', 'O que aconteceu na Floresta de Jade foi uma terrível tragédia. Estou convicto de que precisams aprender com nossos erros, para assim não repeti-los.$b$bHá muito conhecimento nessa biblioteca. Eu mesmo já aprendi muito sobre o sha.', '', 19865),
(64991, 'ptBR', '[%s] confessa: Eu peguei umas coisas "emprestadas" do banco da minha guilda.', '[%s] confessa: Eu peguei umas coisas "emprestadas" do banco da minha guilda.', 19865),
(64992, 'ptBR', 'Um dia, os jinyus governaram toda Pandária a partir deste local, deste trono do poder.$b$bPrecisamos aprender tudo o que for possível com as histórias, para que para que seja possível recuperar nossa sabedoria ancestral.', '', 19865),
(64993, 'ptBR', 'Desde a minha aterrissagem forçada nestas costas, tenho vagado por todo lado, $r!$b$bEstive em todo lugar, desde o Templo da Serpente de Jade até a costa da Krasarang, passando até mesmo pelo Monte Neverest!$b$bEssa terra é incrível, e estou catalogando todos os meus achados.$b$bMal posso esperar para contar aos meus colegas da Liga dos Exploradores tudo o que vi!', '', 19865),
(64994, 'ptBR', 'Você nunca sabe em quem pode confiar de verdade. A menos que você seja eu; aí é fácil.', '', 19865),
(64995, 'ptBR', 'A imperatriz tem espiões por toda a parte.', '', 19865),
(64996, 'ptBR', 'Os que buscam o poder por meio da força frequentemente o obtém sozinhos.', '', 19865),
(64997, 'ptBR', 'A imperatriz a quem eu servi também era amedrontada e paranoica. No final foi o seu medo que a levou à ruína.', '', 19865),
(64998, 'ptBR', '', 'Sempre tive uma memória boa para números.$b$bQuando os nativos viram o quão rápido eu conseguia somar, subtrair, dividir e multiplicar de cabeça, eles me contrataram!', 19865),
(64999, 'ptBR', 'Você deve manter a mente forte para suportar os sussurros cada vez mais insistentes da imperatriz. Mentes mais fracas sucumbirão a ela sem sequer notarem.', '', 19865),
(65000, 'ptBR', 'Agora que já dei uma olhadela no vale, preciso dizer: alguns lugares aqui parecem um pouco... familiares.$b$bSei que não parece, mas não posso afastar essa sensação. O que você acha que isso significa?', '', 19865),
(65001, 'ptBR', 'Não é demais? Sou fã número um!', '', 19865),
(65002, 'ptBR', '', 'Bem-vind$go:a;, $r! Fique e escute um pouco.', 19865),
(65003, 'ptBR', '', 'Bem-vind$go:a; ao Lounge do Rouxinol, $c. O que podemos tocar para você hoje?', 19865),
(65004, 'ptBR', 'O conhecimento nessa biblioteca é espetacular.', '', 19865),
(65005, 'ptBR', '[%s] confessa: Eu sempre esqueço de engastar gemas no meu equipamento.', '[%s] confessa: Eu sempre esqueço de engastar gemas no meu equipamento.', 19865),
(65006, 'ptBR', '[%s] confessa: Eu passei seis meses caçando o Protodraco Perdido no Tempo.', '[%s] confessa: Eu passei seis meses caçando o Protodraco Perdido no Tempo.', 19865),
(65007, 'ptBR', '[%s] confessa: Eu fui ao Vale Alterac e não ajudei minha equipe em nada.', '[%s] confessa: Eu fui ao Vale Alterac e não ajudei minha equipe em nada.', 19865),
(65008, 'ptBR', '[%s] confessa: Eu morri pra um elevador uma vez. Mais de uma vez.', '[%s] confessa: Eu morri pra um elevador uma vez. Mais de uma vez.', 19865),
(65009, 'ptBR', '[%s] confessa: Eu nunca uso a Fonte de Luz.', '[%s] confessa: Eu nunca uso a Fonte de Luz.', 19865),
(65010, 'ptBR', '[%s] confessa: Eu sempre quis ser um paladino.', '[%s] confessa: Eu sempre quis ser uma paladina.', 19865),
(65011, 'ptBR', '[%s] confessa: Dedões de troll me dão ziquizira.', '[%s] confessa: Dedões de troll me dão ziquizira.', 19865),
(65012, 'ptBR', '[%s] confessa: Eu fiquei parado no fogo.', '[%s] confessa: Eu fiquei parada no fogo.', 19865),
(65013, 'ptBR', '[%s] confessa: Eu disse ao líder do raide que eu estava pronto, mas eu não estava.', '[%s] confessa: Eu disse ao líder do raide que eu estava pronto, mas eu não estava.', 19865),
(65014, 'ptBR', '[%s] confessa: Eu caí de Dalaran.', '[%s] confessa: Eu caí de Dalaran.', 19865),
(65015, 'ptBR', 'Há uma treinadora de batalha, chamada Sara Taramela, que treina as mascotes dela no terraço principal.$b$BVou marcar a localização no seu mapa.', 'Há uma treinadora de batalha, chamada Sara Taramela, que treina as mascotes dela no terraço principal.$b$BVou marcar a localização no seu mapa.', 19865),
(65016, 'ptBR', '[%s] confessa: Eu pedi ouro emprestado a um amigo pra comprar minha primeira montaria.', '[%s] confessa: Eu pedi ouro emprestado a um amigo pra comprar minha primeira montaria.', 19865),
(65017, 'ptBR', 'É, existe um comerciante de suprimentos de pesca lá embaixo, no primeiro andar do Terraço do Verão.$b$bVou marcar a localização no seu mapa.', 'É, existe um comerciante de suprimentos de pesca lá embaixo, no primeiro andar do Terraço do Verão.$b$bVou marcar a localização no seu mapa.', 19865),
(65018, 'ptBR', '[%s] confessa: Eu disse que já tinha estado numa masmorra antes, mas eu não tinha ideia do que estava fazendo. Foi vergonhoso.', '[%s] confessa: Eu disse que já tinha estado numa masmorra antes, mas eu não tinha ideia do que estava fazendo. Foi vergonhoso.', 19865),
(65019, 'ptBR', '[%s] confessa: Eu já soquei um gnomo. Por motivo nenhum. Eu estava tendo um dia ruim.', '[%s] confessa: Eu já soquei um gnomo. Por motivo nenhum. Eu estava tendo um dia ruim.', 19865),
(65020, 'ptBR', '[%s] confessa: Eu superei o lance de um amigo num item de leilão que eu nem queria.', '[%s] confessa: Eu superei o lance de um amigo num item de leilão que eu nem queria.', 19865),
(65021, 'ptBR', '[%s] confessa: Eu me meto em masmorras não para tornar Azeroth um lugar melhor. É só pelo saque mesmo.', '[%s] confessa: Eu me meto em masmorras não para tornar Azeroth um lugar melhor. É só pelo saque mesmo.', 19865),
(65022, 'ptBR', '[%s] confessa: Eu não estava na abertura de Ahn''Qiraj. Eu só li a respeito.', '[%s] confessa: Eu não estava na abertura de Ahn''Qiraj. Eu só li a respeito.', 19865),
(65023, 'ptBR', '[%s] confessa: Eu não faço ideia de quem são os Sin''dorei.', '[%s] confessa: Eu não faço ideia de quem são os Sin''dorei.', 19865),
(65024, 'ptBR', '[%s] confessa: Eu não trato minhas montarias igualmente.', '[%s] confessa: Eu não trato minhas montarias igualmente.', 19865),
(65025, 'ptBR', '[%s] confessa: eu mexo com arqueologia, mas não me interesso muito por história.', '[%s] confessa: eu mexo com arqueologia, mas não me interesso muito por história.', 19865),
(65026, 'ptBR', '[%s] confessa: A risada draeneica me irrita muito..', '[%s] confessa: A risada draeneica me irrita muito..', 19865),
(65027, 'ptBR', '[%s] confessa: Eu já não visito o barbeiro há meses. Goblins Com tesouras. Que medo.', '[%s] confessa: Eu já não visito o barbeiro há meses. Goblins Com tesouras. Que medo.', 19865),
(65028, 'ptBR', '[%s] confessa: Eu achei que pandarens eram tipo pelursos.', '[%s] confessa: Eu achei que pandarens eram tipo pelursos.', 19865),
(65029, 'ptBR', '[%s] confessa: Ah, eu peguei a vela.', '[%s] confessa: Ah, eu peguei a vela.', 19865),
(65030, 'ptBR', '[%s] confessa: Isso é só um revés.', '[%s] confessa: Isso é só um revés.', 19865),
(65031, 'ptBR', '[%s] confessa: Eu taco fogo nas coisas e grito PURIFICADOS PELO FOGO quando não tem ninguém por perto.', '[%s] confessa: Eu taco fogo nas coisas e grito PURIFICADOS PELO FOGO quando não tem ninguém por perto.', 19865),
(65032, 'ptBR', '[%s] confessa: Na verdade eu não me lembro de você lá das montanhas.', '[%s] confessa: Na verdade eu não me lembro de você lá das montanhas.', 19865),
(65033, 'ptBR', '[%s] confessa: Eu às vezes não lembro se Nortúndria fica ao norte ou ao sul daqui.', '[%s] confessa: Eu às vezes não lembro se Nortúndria fica ao norte ou ao sul daqui.', 19865),
(65034, 'ptBR', '[%s] confessa: Eu acho esses nomes com tantos apóstrofo tão confusos.', '[%s] confessa: Eu acho esses nomes com tantos apóstrofo tão confusos.', 19865),
(65035, 'ptBR', '[%s] confessa: Eu esqueci da Nascente do Sol.', '[%s] confessa: Eu esqueci da Nascente do Sol.', 19865),
(65036, 'ptBR', '[%s] confessa: E não é que eu não estava preparado mesmo? Veja você.', '[%s] confessa: E não é que eu não estava preparado mesmo? Veja você.', 19865),
(65037, 'ptBR', '[%s] confessa: Às vezes eu me pergunto se taurens tem gosto de... você sabe.', '[%s] confessa: Às vezes eu me pergunto se taurens tem gosto de... você sabe.', 19865),
(65038, 'ptBR', '[%s] confessa: Eu peço à Luz que me dê forças, mas não sei se ela dá mesmo.', '[%s] confessa: Eu peço à Luz que me dê forças, mas não sei se ela dá mesmo.', 19865),
(65039, 'ptBR', '[%s] confessa: Às vezes eu uso minha montaria para viajar distâncias curtas. CURTAS DE VERDADE.', '[%s] confessa: Às vezes eu uso minha montaria para viajar distâncias curtas. CURTAS DE VERDADE.', 19865),
(65040, 'ptBR', '[%s] confessa: Eu não sei sei Millhouse é um bom sujeito ou não.', '[%s] confessa: Eu não sei sei Millhouse é um bom sujeito ou não.', 19865),
(65041, 'ptBR', '[%s] confessa: Eu sei que ele é um grosso, mas o Garrosh tem um certo charme...', '[%s] confessa: Eu sei que ele é um grosso, mas o Garrosh tem um certo charme...', 19865),
(65042, 'ptBR', '[%s] confessa: Eu vi um mago lançando um feitiço uma vez e meu queixo caiu de verdade quando vi o dano.', '[%s] confessa: Eu vi um mago lançando um feitiço uma vez e meu queixo caiu de verdade quando vi o dano.', 19865),
(65043, 'ptBR', '', 'Fomos levados por visões a esse local. Mas mesmo as visões ficam pálidas em comparação à beleza do Vale.', 19865),
(65044, 'ptBR', '[%s] confessa: Por muito tempo eu achei que o plural de anedota fosse dados.', '[%s] confessa: Por muito tempo eu achei que o plural de anedota fosse dados.', 19865),
(65045, 'ptBR', '[%s] confessa: Às vezes eu peço para um bruxo me evocar mesmo quando eu não estou longe.', '[%s] confessa: Às vezes eu peço para um bruxo me evocar mesmo quando eu não estou longe.', 19865),
(65046, 'ptBR', '[%s] confessa: Às vezes quando estou numa missão, eu quero ficar só, então eu finjo que não estou ouvindo meus amigos.', '[%s] confessa: Às vezes quando estou numa missão, eu quero ficar só, então eu finjo que não estou ouvindo meus amigos.', 19865),
(65047, 'ptBR', 'Foi uma longa jornada até chegar aqui. E nós perdemos muitos no caminho.$b$bMesmo assim... olhe para esse lugar. Fantástico!', 'Foi uma longa jornada até chegar aqui. E nós perdemos muitos no caminho.$b$bMesmo assim... olhe para esse lugar. Fantástico!', 19865),
(65048, 'ptBR', '', 'Gostaria de algo para comer, viajante?', 19865),
(65049, 'ptBR', '', 'Comes e bebes à venda!', 19865),
(65050, 'ptBR', '', 'A fim de um petisco, $r?', 19865),
(65051, 'ptBR', 'Agradeço por abrir os portões para nós, $p. Você nos honra com sua presença.', 'Agradeço por abrir os portões para nós, $p. Você nos honra com sua presença.', 19865),
(65052, 'ptBR', 'A Aliança nos seguiu até aqui. Mesmo nesse lugar sereno, sinto o cheiro de guerra no ar.', 'A Aliança nos seguiu até aqui. Mesmo nesse lugar sereno, sinto o cheiro de guerra no ar.', 19865),
(65053, 'ptBR', 'Os mogus, os mantídeos e a Aliança ameaçam a segurança desse lugar antigo. Precisamos protegê-lo, custe o que custar.', 'Os mogus, os mantídeos e a Aliança ameaçam a segurança desse lugar antigo. Precisamos protegê-lo, custe o que custar.', 19865),
(65054, 'ptBR', '', 'Nós perdemos nosso lar para os yaungóis. Mas esse lugar... esse lugar nos oferece um recomeço.', 19865),
(65055, 'ptBR', 'Achei que tudo estava perdido quando os yaungóis atacaram nosso lar. É clichê, mas os velhos monges estavam certos ao dizer que "quando uma porta se fecha, outra se abre".$b$bOu algo do tipo. Não prestava muita atenção nos ensinamentos deles.', '', 19865),
(65056, 'ptBR', 'Podemos ir ver as serpentes?', '', 19865),
(65057, 'ptBR', 'Hoje não, pequeno. Temos incumbências a resolver.', '', 19865),
(65058, 'ptBR', 'Podemos ver um tauren? Eles parecem com os yaungóis.', '', 19865),
(65059, 'ptBR', 'Podemos ir ver a moça morta-viva? Ela é engraçada.', '', 19865),
(65060, 'ptBR', 'Podemos ir brincar com os goblins? Eu sou mais alto que eles!', '', 19865),
(65061, 'ptBR', 'Quando poderemos ir para casa?', '', 19865),
(65062, 'ptBR', 'Sinto falta dos meus brinquedos. Podemos ir para casa?', '', 19865),
(65063, 'ptBR', 'Podemos voltar para Kun-Lai? O ar tem um cheiro esquisito por aqui.', '', 19865),
(65064, 'ptBR', '', 'Desculpe, mas precisamos ficar aqui por um tempo. A Horda está nos mantendo em segurança.', 19865),
(65065, 'ptBR', '', 'Oi! Você gostaria de desafiar minhas mascotes?', 19865),
(65066, 'ptBR', '', 'Saudações, $r. Eu posso ser pequena, mas tamanho não importa em uma batalha de mascotes!', 19865),
(65067, 'ptBR', '', 'Oi, $c! Você não acha minhas mascotes uma fofura?', 19865),
(65068, 'ptBR', '', 'Olá, meu bem. Como estão as coisas no campo?', 19865),
(65069, 'ptBR', '', 'Posso fazer alguma coisa por você?', 19865),
(65070, 'ptBR', '', 'Uma enxada é a arma de $gum homem honesto:uma mulher honesta;.', 19865),
(65071, 'ptBR', '', 'Ora, olá, $n. Eu sei tudo o que acontece no Coração da Terra, $gmeu caro:minha querida;. Você não chega à minha idade sem ter alguns amigos língua-frouxa.', 19865),
(65072, 'ptBR', 'Aqui vamos nós. Tentem ficar vivos até o fim.', '', 19865),
(65073, 'ptBR', '|TInterface\\Icons\\spell_shadow_corpseexplode.blp:20|t %s comeu muito e começa a |cFFFF0000|Hspell:126126|h[Vomitar]|h|r!', '', 19865),
(65074, 'ptBR', 'Vamos pegar você, Calafrio! Hora da revanche!', '', 19865),
(65075, 'ptBR', '|TInterface\\Icons\\inv_misc_monsterfang_02.blp:20|t %s apanha sua presa em sua |cFFFF0000|Hspell:126187|h[Boca-de-alicate]|h|r! Mate ele!', '', 19865),
(65076, 'ptBR', 'Um homem deve honrar sua família.', '', 19865),
(65077, 'ptBR', 'A Caveira Falante gargalha alegremente ao que a alma do instrutor é destruída.', '', 19865),
(65078, 'ptBR', 'A Caveira Falante parece hesitar em entrar no corredor, mas acompanha você mesmo assim.', '', 19865),
(65079, 'ptBR', 'Você gosta de café?$b$bNão?$b$bAinda bem, porque no meu coador é mais forte!', '', 19865),
(65080, 'ptBR', 'Tá tão seco, mas tão seco, que até crocolisco no seco anda.', '', 19865),
(65081, 'ptBR', 'Todo mundo mente, até semente. Hahahah!', '', 19865),
(65082, 'ptBR', 'O que o tanque disse antes da luta?$b$b"Se estiver em desvantagem, ou mato ou morro. Ou corro pro mato ou corro pro morro."', '', 19865),
(65083, 'ptBR', 'O que aconteceria se o rei Varian fosse corrompido?$b$b...$b$bEu não sei, mas seria muito SHA-to!', '', 19865),
(65084, 'ptBR', '...hic...!$B$B...o que é um... o que é um "gus"...?', '', 19865),
(65085, 'ptBR', 'Eu não aguento olhar.', '', 19865),
(65086, 'ptBR', 'A Caveira Falante segue para a próxima câmara sem dizer uma palavra.', '', 19865),
(65087, 'ptBR', 'Ah, eis o meu mestre assassino favorito! Tinha esperança de encontrar você aqui em Pandária.', '', 19865),
(65088, 'ptBR', 'Excelente, vamos conversar.', '', 19865),
(65089, 'ptBR', 'Tong! Bebidas, por favor.', '', 19865),
(65090, 'ptBR', 'Meu pai, Asa da Morte, tentou destruir Azeroth inteira.', '', 19865),
(65091, 'ptBR', 'Ele estava desencaminhado, é claro, mas numa coisa ele tinha razão. Nosso mundo é... tão frágil.', '', 19865),
(65092, 'ptBR', 'Somos um ponto de luz num universo de trevas. Uma vela na tempestade.', '', 19865),
(65093, 'ptBR', 'Às vezes penso que foi a própria precariedade do nosso mundo que enlouqueceu meu pai.', '', 19865),
(65094, 'ptBR', 'Ah, obrigado, Tong.', '', 19865),
(65095, 'ptBR', 'Bom, vamos direto ao assunto: acredito que estamos rumando a um confronto final. E não, não me refiro ao conflito atual entre Aliança e Horda.', '', 19865),
(65096, 'ptBR', 'Pode acreditar, o que Garrosh Grito Infernal fez em Theramore não é nada comparado aos horrores que neste exato momento se dirigem ao nosso frágil lar.', '', 19865),
(65097, 'ptBR', 'Mas esta guerra me preocupa profundamente. Você compreende minha inquietação?', '', 19865),
(65098, 'ptBR', 'Uma Azeroth DIVIDIDA não poderá de forma alguma resistir às trevas.', '', 19865),
(65099, 'ptBR', 'Esta guerra tem que acabar. E logo. Antes que consuma nossa força!', '', 19865),
(65100, 'ptBR', 'Quero que você saiba que a sua Aliança tem meu apoio total e inquestionável nesta campanha.', '', 19865),
(65101, 'ptBR', 'Pode ter certeza de que minha lealdade está com a Horda.', '', 19865),
(65102, 'ptBR', 'Como encerrar o conflito rápida e decisivamente? A resposta está em heróis e heroínas como você.', '', 19865),
(65103, 'ptBR', 'Vamos garantir que você seja forte o bastante... E então conseguir o equipamento adequado.', '', 19865),
(65104, 'ptBR', 'Tente não morrer! Estamos só no começo de nossa lendária jornada.', '', 19865),
(65105, 'ptBR', 'Ahh! Você retorna triunfante.', '', 19865),
(65106, 'ptBR', 'Fica logo morro acima. Fique alerta, poucos visitantes já voltaram.', '', 19865),
(65107, 'ptBR', 'Você está com aparência pálida! Espero que não tenha se deixado dominar pelo medo?', '', 19865),
(65108, 'ptBR', 'Permita que eu recolha meus pertences, e nos encontraremos lá!', '', 19865),
(65109, 'ptBR', 'Às vezes dou um passeio aqui fora, para pensar. A vista é incrível, não acha?', '', 19865),
(65110, 'ptBR', 'Pandária é de fato uma joia. Tanta beleza. Dá vontade de protegê-la, não dá?', '', 19865),
(65111, 'ptBR', 'Sinto o mesmo sobre Azeroth em si.', '', 19865),
(65112, 'ptBR', 'Você realizou grandes atos, camarada. Garanto que este é só o começo do nosso trabalho conjunto.', '', 19865),
(65113, 'ptBR', 'Eis o PODER dos inimigos que você sobrepujou.', '', 19865),
(65114, 'ptBR', 'E a sabedoria daqueles que você logrou.', '', 19865),
(65115, 'ptBR', 'Aqui! A encarnação do medo que você conquistou. Que ela aterrorize os corações dos seus inimigos!', '', 19865),
(65116, 'ptBR', 'Finalmente, um presente meu. Não se iluda, a Revoada Negra ainda vive!', '', 19865),
(65117, 'ptBR', 'Pronto, está feito. Agora você pode aumentar o poder de qualquer arma tocada pelos shas.', '', 19865),
(65118, 'ptBR', 'Estamos só começando, camarada! Nosso desafio maior ainda está por vir.', '', 19865),
(65119, 'ptBR', 'Mas, quando a guerra tocar estas terras, estaremos prontos para ela!', '', 19865),
(65120, 'ptBR', 'É muito bom ver você novamente, $n! Imagino que as armas que lhe dei em Corvoforte tenham lhe servido bem.$b$bTenho outra "tarefa" para você aqui em Pandária. Novamente, ela exigirá todas a sua habilidade, e eu garanto... valerá a pena!$b$bAntes de começarmos, é importante que você se familiarize com a área. Venha me visitar novamente depois que tiver mais experiência por aqui.', '', 19865),
(65121, 'ptBR', 'Olá novamente. $N, não é? Sim, sim... Acredito que temos alguns assuntos em aberto desde os Reinos do Leste. Como você foi encontrar Pandária?$b$bTenho outra tarefa para você, caso esteja interessad$go:a; no desafio. Garanto que a recompensa valerá a pena.$b$bAntes de começarmos, é importante que você se familiarize com a área. Venha me visitar novamente depois que tiver mais experiência por aqui.', '', 19865),
(65122, 'ptBR', '<O Príncipe Negro olha para você de cima a baixo.>$b$bÉ muito bom conhecer você, $c. Você faz parte da vanguarda, aparentemente... $gUm explorador:Uma exploradora; em uma terra estranha. E como você foi encontrar o misterioso continente de Pandária?$b$bVocê parece ser alguém que resolve as coisas. Preciso que você venha me rever após ter conhecido a área.$b$bEstarei bem aqui.', '', 19865),
(65123, 'ptBR', 'Eu escolhi o nome "Wrathion". Até onde eu sei, sou o último dos dragões negros.$b$bMeu pai era Asa da Morte, o Quebramundo, o Aspecto da Morte, o Destruidor... Mas espero que você não me confunda com ele.$b$bNão tenho amor algum pelo meu pai, uma vez que a corrupção dele destruiu minha raça; ou pela revoada dragônica vermelha, que roubou o ovo de onde nasci e fez experiências para me criar.$b$bVamos dizer que... não sou filiado a ninguém. E estou sempre em busca de heróis que compartilham da minha opinião.', '', 19865),
(65124, 'ptBR', 'Quem é você?', 'Quem é você?', 19865),
(65125, 'ptBR', 'O que você está fazendo em Pandária?', 'O que você está fazendo em Pandária?', 19865),
(65126, 'ptBR', 'Com certeza tenho direito a ALGUNS segredos. Você não concorda, $n?$b$bCheguei logo que as brumas se instauraram. Eu consegui voar até aqui depois que meus colegas de Corvoforte ficaram sabendo batalhas navais nestas costas.$b$bEssa terra ficou oculta por dez mil anos. Eu apenas comecei a explorar seus mistérios.', '', 19865),
(65127, 'ptBR', 'Estou feliz por você ter voltado, $n! Acredito que você esteja, agora, acostumad$go:a; com este estranho continente de Pandária, não?$b$BVocê já me provou seu valor no passado, então podemos ignorar qualquer tipo de teste. Vamos ao que interessa.$b$bVocê está preparad$go:a; para mudar o mundo?', '', 19865),
(65128, 'ptBR', 'Boas vindas, $c! Meus contatos em Pandária informaram que você tem andado bastante ocupad$go:a; por aqui. Admiro mortais com a sua... “iniciativa”.$b$bAzeroth inteira chegou a um ponto de virada na sua história. Se você estiver preparad$go:a; para enfrentar o futuro ao meu lado, garantirei que você seja muito bem recompensad$go:a;.', '', 19865),
(65129, 'ptBR', 'Estamos apenas começando nossa campanha em Pandária, $n.', '', 19865),
(65130, 'ptBR', '', 'Acredito que provavelmente encontramos, enfim, as Fontes da Juventude do meu pai. Precisamos reunir o máximo de informações possível para Tyrande.', 19865),
(65131, 'ptBR', '', 'Minhas sentinelas enfrentaram muitos perigos desde que chegamos a essa nova terra. Estamos prontas para qualquer coisa que o futuro tenha a oferecer.', 19865),
(65132, 'ptBR', '', 'O moral do meu esquadrão melhorou desde que entramos no vale.', 19865),
(65133, 'ptBR', '', 'Esse vale é realmente um paraíso.', 19865),
(65134, 'ptBR', '', 'Ver esse lugar era o sonho do meu pai. Devo realizar os desejos dele nesse lugar.', 19865),
(65135, 'ptBR', 'Um vento ruim sopra dos litorais meridionais. Você está preparad$go:a;?', '', 19865),
(65136, 'ptBR', '', 'Nós descansaremos aqui no vale até reunirmos nossa pesquisa. Então, precisaremos encontrar um novo caminho para casa.', 19865),
(65137, 'ptBR', 'Existe algum tipo de barreira que protege o vale, impedindo que eu use mágica de portal.', '', 19865),
(65138, 'ptBR', '', 'Nosso encontro neste vale é mais que uma mera coincidência.', 19865),
(65139, 'ptBR', '', 'O orgulho de Garrosh destruiu o Vale. O que foi nunca será restaurado.', 19865),
(65140, 'ptBR', '', 'Tyrande nos enviou até aqui como uma vanguarda para a Luz.', 19865),
(65141, 'ptBR', '', 'As árvores aqui são mais bonitas do que as da selva ao sul.', 19865),
(65142, 'ptBR', '', 'Nunca em minha vida vi um lugar como esse.', 19865),
(65143, 'ptBR', '', 'Será que as águas desse vale são as lendárias "Fontes da Juventude"? Talvez a imortalidade esteja ao nosso alcance mais uma vez...', 19865),
(65144, 'ptBR', '', 'Ouvimos relatórios sobre mogus se infiltrando nesse vale. Eles não passarão por nós.', 19865),
(65145, 'ptBR', '', 'Enquanto estudamos as fontes, patrulharemos os limites da cidade e protegeremos essas pessoas.', 19865),
(65146, 'ptBR', '', 'Para ser sincera, eu não acreditei nas visões de Vaeldrin, não logo de início. Mas este lugar irradia uma magia incomum. Serão essas as fabulosas Fontes da Juventude?', 19865),
(65147, 'ptBR', 'Se você tiver tempo, deve visitar o famoso Festival da Cerveja da Lua de Binan. Vou estar lá com algumas das minhas famosas Cervejas Touro Vermelho de Kun-Lai.', '', 19865),
(65148, 'ptBR', 'A lenda fala sobre uma grande batalha que aconteceu neste exato vale, e que transformou os campos dourados em campos vermelhos com o sangue de muitos monges corajosos. Os exércitos de Lei Shen, o Rei Trovão, imperador dos mogus, lutaram bravamente, mas foram eventualmente derrotados.', '', 19865),
(65149, 'ptBR', 'Morra, Gandling! Mate-o!', '', 19865),
(65150, 'ptBR', 'Duzentos navios à minha disposição, e aquele que leva meu FILHO desaparece!', '', 19865),
(65151, 'ptBR', 'Sinto muito, mas não posso voltar agora.', '', 19865),
(65152, 'ptBR', 'Eu decidi procurar o Vale... Vale... Vale...', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(65153, 'ptBR', 'INVADA a costa e PINTE O CONTINENTE DE VERMELHO!', '', 19865),
(65154, 'ptBR', '|TInterface\\Icons\\ability_warlock_improvedsoulleech:20|tVocê foi afligid$go:a; por |cFFFF0000|Hspell:126228|h[Alma Cindida]|h|r! Mate ele!', '', 19865),
(65155, 'ptBR', 'Quatro dias após a queda de Lei Shen, o vale foi envolto por uma nuvem da treva mais profunda. Evocada por Lei Shen em seus momentos finais, a tempestade transcendental cobriu o vale com chuva e golpeou com lanças de raios as colinas.', '', 19865),
(65156, 'ptBR', 'O sangue dos mortos foi lavado pela tempestade e levado ao Lago Pétala Branca, manchando as águas de um vermelho escuro. Em seu suspiro final, a tempestade alcançou o centro do lago, inflamando a própria água. O lago queimou em uma tonalidade carmesim por muitos dias.', '', 19865),
(65157, 'ptBR', 'Quando a labareda se apagou, uma jovem serpente das nuvens foi vista voando perto do meio do lago. As escamas dela faiscavam com a tempestade e o fogo e, por onde ela voasse, grandes nuvens se formavam no céu. Meu povo a chamou de Alani, Filha da Tempestade.', '', 19865),
(65158, 'ptBR', 'Eles dizem que Alani vê apenas o clarão dos maiores raios, e pode apenas ouvir o eco dos maiores trovões. Se você deseja a atenção dela, você precisará controlar a própria essência do céu que a gerou.', '', 19865),
(65159, 'ptBR', 'E ENTÃO o que aconteceu?', 'E ENTÃO o que aconteceu?', 19865),
(65160, 'ptBR', 'Saudações, amig$go:a;! Não costumo ter muitos visitantes, então gostaria de ouvir um conto do Vale das Flores Eternas?', '', 19865),
(65161, 'ptBR', 'Eu aceito.', 'Eu aceito.', 19865),
(65162, 'ptBR', 'Isso faz sentido!', 'Isso faz sentido!', 19865),
(65164, 'ptBR', 'Galerito bobão! Cerva é dos hozens!', '', 19865),
(65165, 'ptBR', 'Pega cerva!', '', 19865),
(65166, 'ptBR', 'Não tem cerva pra você!', '', 19865),
(65167, 'ptBR', 'Eiaaaaarrr!', '', 19865),
(65168, 'ptBR', 'As câmaras antigas dos mogus, intocadas pelo tempo há milhares de anos... quem sabe os segredos que aqui nos esperam?', '', 19865),
(65169, 'ptBR', 'Todos por um! E um por Fedô!', '', 19865),
(65170, 'ptBR', 'Muitos jovens guerreiros pandarens desapareceram nesta... tumba. Preste bastante atenção.', '', 19865),
(65171, 'ptBR', 'Os mogus tinham poder considerável sobre as pedras da terra. A magia delas persiste, mesmo depois de tantos séculos.', '', 19865),
(65172, 'ptBR', 'O enorme quílen parece estar guardando aquela porta. Ande devagar ou ele acordará!', '', 19865),
(65173, 'ptBR', 'Foi por pouco!', '', 19865),
(65174, 'ptBR', 'O mecanismo da porta parece ter sido ativado com a morte dos guardiões. Tenho medo do que podemos encontrar lá dentro.', '', 19865),
(65175, 'ptBR', 'Parece que acordamos algum tipo de espírito.', '', 19865),
(65176, 'ptBR', 'Então as histórias eram verdadeiras...', '', 19865),
(65177, 'ptBR', 'Nós perturbamos o que não deveria ter sido perturbado. Ele não pode escapar desta prisão! Você precisa destruí-lo!', '', 19865),
(65178, 'ptBR', 'Feng, o Amaldiçoado, foi traído por quatro imperadores dos mogus, tendo o corpo destruído cada uma das vezes, e sempre voltava a se erguer.', '', 19865),
(65179, 'ptBR', 'Hozeteiros! Venham!', '', 19865),
(65180, 'ptBR', 'Essa não será a última vez que veremos Feng...', '', 19865),
(65181, 'ptBR', 'Os Zandalari, antigos aliados dos mogus! Eles devem estar procurando a arma lendária nas profundezas das Câmaras!', '', 19865),
(65182, 'ptBR', 'Galeritos!', '', 19865),
(65183, 'ptBR', 'Penetras na festa!', '', 19865),
(65184, 'ptBR', 'Eiaaaaarrr!', '', 19865),
(65185, 'ptBR', 'Não toma cerva!', '', 19865),
(65186, 'ptBR', 'Cata os guéri-guéri!', '', 19865),
(65187, 'ptBR', 'Pelo Capitão Fedô!', '', 19865),
(65188, 'ptBR', 'Sinto muito por não ter lhe dito antes! Estas câmaras abrigam uma arma de poder inimaginável Detenha-os!', '', 19865),
(65189, 'ptBR', 'Eu vou ficar para investigar um pouco mais essa tribuna...', '', 19865),
(65190, 'ptBR', 'Uma passagem secreta se abriu sob a plataforma, vamos por aqui!', '', 19865),
(65191, 'ptBR', 'Olhe a poeira no chão... estes salões escuros já não veem pegadas há muitos séculos.', '', 19865),
(65192, 'ptBR', 'Os mogus outrora escravizaram todas as raças de Pandária, usando-as para seus fins nefastos.', '', 19865),
(65193, 'ptBR', 'Estes jinyus ficaram presos por uma eternidade de servidão.', '', 19865),
(65194, 'ptBR', 'Eu ouço um leve zumbido. Está vindo desta direção!', '', 19865),
(65195, 'ptBR', 'Então está feito. E no entanto... quantas máquinas dessas ainda estão escondidas embaixo da terra? O quanto ainda desconhecemos sobre os segredos sombrios dos mogus?', '', 19865),
(65196, 'ptBR', 'Temo que a guerra contra nossos antigos inimigos ainda esteja longe de acabar.', '', 19865),
(65197, 'ptBR', 'Espantoso! Um legítimo constructo mogu, e funcionando!', '', 19865),
(65198, 'ptBR', 'Não podemos deixar que isso caia em mãos erradas.', '', 19865),
(65199, 'ptBR', 'Um exército infinito de abominações sem alma... Tremo só de pensar na violência que pode surgir de uma máquina assim.', '', 19865),
(65200, 'ptBR', 'Você tem que destruir a máquina. Vá, antes que algum mal caia sobre Pandária.', '', 19865),
(65201, 'ptBR', 'Ligue a máquina, que eu tranco a porta.', '', 19865),
(65202, 'ptBR', 'Que a grande garça guie seus passos.', '', 19865),
(65203, 'ptBR', 'NÃO! Volte aqui, covarde!', '', 19865),
(65204, 'ptBR', 'Há muitos venenos maravilhosos, Arauto do Despertar. Alguns podem ferver você $gvivo:viva;. Alguns devoram a pele. Alguns explodem seu corpo.$B$BTantas variedades maravilhosas.', '', 19865),
(65205, 'ptBR', 'Rápido, destrói aquilo! Precisamos alcançar o Gandling!', '', 19865),
(65206, 'ptBR', 'Já bebeu veneno, Arauto do Despertar? É preciso começar com algo brando, poucas gotas apenas.$B$BVocê provavelmente ficará muito doente. Talvez até perca uma antena ou duas.$B$BMas mantenha essa rotina e você se acostumará muito bem.', '', 19865),
(65207, 'ptBR', 'Vamos!', '', 19865),
(65208, 'ptBR', 'Eu já fui o mais respeitado alquimista real, sem páreo, acima de todos os outros.', '', 19865),
(65209, 'ptBR', 'Bah! Eu me lembro quando Un''sok ainda era um zangão, com medo de preparar sua primeira toxina. Eu o desafio a me enfrentar sozinho. E então veremos qual alquimia é superior.', '', 19865),
(65210, 'ptBR', 'Curve-se ante Shao-Tien!', '', 19865),
(65211, 'ptBR', 'Você é $Gfraco:fraca;!', '', 19865),
(65212, 'ptBR', 'Criança tola.', '', 19865),
(65213, 'ptBR', 'Lá está ele! Mate ele agora, $p!', '', 19865),
(65214, 'ptBR', 'Ah, chegou mais alguém de além das brumas.', '', 19865),
(65215, 'ptBR', 'Há dez mil anos, o último imperador pandaren me procurou em busca de conselho. Ele também estava em conflito. Vamos ver se você está certo, Taran. Vamos ver como alguém de fora lida com os conflitos da alma.', '', 19865),
(65216, 'ptBR', 'Em breve eles dominarão este continente! Temos que estabelecer um limite!', '', 19865),
(65217, 'ptBR', 'Nós vimos sua "ajuda" na Floresta de Jade. Tal "Horda", tal "Aliança"... vocês não têm controle sobre a própria natureza. Só há destruição por onde vocês passam.', '', 19865),
(65218, 'ptBR', 'Ajoelhe-se, verme.', '', 19865),
(65219, 'ptBR', 'Lamentável.', '', 19865),
(65220, 'ptBR', 'Viemos contribuir. Nós podemos ajudar a proteger o Vale.', '', 19865),
(65221, 'ptBR', 'Pare ele! Esqueça-se dela!', '', 19865),
(65222, 'ptBR', '<He olha o corredor atentamente.>', '', 19865),
(65223, 'ptBR', '|TInterface\\Icons\\ability_warlock_baneofhavoc:20|t%s começa a lançar |cFFFF0000|Hspell:126299|h[Libertar Almas]|h|r! Saia daí, rápido!', '', 19865),
(65224, 'ptBR', 'Finalmente.', '', 19865),
(65225, 'ptBR', 'Acabou. A maldição se desfez. Obrigado, $p. Obrigado!', '', 19865),
(65226, 'ptBR', 'Tô com fome!', '', 19865),
(65227, 'ptBR', 'Tenho que comer!', '', 19865),
(65228, 'ptBR', 'Então o Lótus Dourado chegou...', '', 19865),
(65229, 'ptBR', 'Você chegou tarde demais. Os Exércitos de Jade são meus.', '', 19865),
(65230, 'ptBR', 'E com eles, eu esmagarei o Lótus Dourado e reivindicarei o vale em nome do Rei Trovão!', '', 19865),
(65231, 'ptBR', 'Morram, fracotes!', '', 19865),
(65232, 'ptBR', 'O poder infinito dos Exércitos de Jade está sob meu controle!', '', 19865),
(65233, 'ptBR', 'Seu amigo ladino não é tão ágil quanto pensa que é.', '', 19865),
(65234, 'ptBR', 'Minha estátua irá esmagá-lo, e só vai restar um corpo em pedaços.', '', 19865),
(65235, 'ptBR', 'Você deixou seu amigo para morrer...', '', 19865),
(65236, 'ptBR', 'Quão nobre, salvando o amigo da morte certa...', '', 19865),
(65237, 'ptBR', '... e não adiantou nada. Peguem-nos!', '', 19865),
(65238, 'ptBR', 'Sua luta é inútil.', '', 19865),
(65239, 'ptBR', 'Você ignora os segredos poderosos contidos neste vale. Eu os tomarei para mim e depois destruirei toda a sua raça.', '', 19865),
(65240, 'ptBR', 'Levem os prisioneiros para as jaulas. Deixem meus homens brincarem com eles.', '', 19865),
(65241, 'ptBR', 'Minha próxima grande aventura está prestes a começar.$b$bÉ a Luz o que eu vejo?', '', 19865),
(65242, 'ptBR', 'O Elmo de Batalha do Rei Trovão...', '', 19865),
(65243, 'ptBR', 'Parece que meus guardas são inúteis. Terei que dar um jeito em vocês eu mesmo.', '', 19865),
(65244, 'ptBR', 'Não haverá jaulas desta vez, eu irei desmembrar todos vocês!', '', 19865),
(65245, 'ptBR', 'Curvem-se diante do meu poder!', '', 19865),
(65246, 'ptBR', 'Eu extinguirei a vida dos seus corpos!', '', 19865),
(65247, 'ptBR', 'Eu vou rasgar suas almas!', '', 19865),
(65248, 'ptBR', 'Violência. Entende? É só o que há neles.', '', 19865),
(65249, 'ptBR', 'Vocês não são tão fracos quanto eu pensei, mas o elmo ainda é meu...', '', 19865),
(65250, 'ptBR', 'Aaaarrrghh! Mago, da próxima vez que nos encontrarmos, eu separarei a cabeça do seu corpo.', '', 19865),
(65251, 'ptBR', 'Sim... nós somos lutadores. Mas viemos de uma terra violenta. Nós enfrentamos demônios, enfrentamos a morte, enfrentamos até o fim do próprio mundo!', '', 19865),
(65252, 'ptBR', 'Quem me perturba? Mostrem suas feições covardes e ajoelhem-se!', '', 19865),
(65253, 'ptBR', 'PREPARE-SE PARA MORRER, VILÃO!', '', 19865),
(65254, 'ptBR', 'Ahahaha! Que criatura patética!', '', 19865),
(65255, 'ptBR', 'Você não é digno de mim. Você! Venha esmagar essa pulga insignificante!', '', 19865),
(65256, 'ptBR', 'Minha lança irá acabar com você!', '', 19865),
(65257, 'ptBR', 'Acovarde-se perante sua ruína!', '', 19865),
(65258, 'ptBR', 'É verdade. Eles são fortes. E têm muito a nos ensinar.', '', 19865),
(65259, 'ptBR', 'Eu vou mostrar a força de um senhor da guerra!', '', 19865),
(65260, 'ptBR', 'Você não tem para onde ir, fracote!', '', 19865),
(65261, 'ptBR', 'Tolo. Você pretende deter todo o poder do império mogu?', '', 19865),
(65262, 'ptBR', 'Eu não lhe darei uma morte rápida, fracote.', '', 19865),
(65263, 'ptBR', 'Sua fraqueza me enoja!', '', 19865),
(65264, 'ptBR', 'Vou esmagar você!', '', 19865),
(65265, 'ptBR', 'Nós reivindicaremos o que é nosso por direito!', '', 19865),
(65266, 'ptBR', 'Temerário, tremei!', '', 19865),
(65267, 'ptBR', 'Eu me refaço e renovo!', '', 19865),
(65268, 'ptBR', 'O sangue em minhas veias está espesso com toxinas. Jamais temerei veneno algum novamente. Verdadeiramente eu sou minha própria obra-prima!', '', 19865),
(65269, 'ptBR', 'Você não quer provar veneno, Arauto? Nem uma gota?', '', 19865),
(65270, 'ptBR', 'Eu já não sou um mantídeo. Eu sou algo maior.', '', 19865),
(65271, 'ptBR', 'Eu busco treinamento no Caminho da Wok.', 'Eu busco treinamento no Caminho da Wok.', 19865),
(65272, 'ptBR', 'Eu busco treinamento no Caminho da Infusão.', 'Eu busco treinamento no Caminho da Infusão.', 19865),
(65273, 'ptBR', 'Concordamos que é nobre lutar por uma causa justa: defender o lar ou a família. Mas e vingança? E raiva? Sinto que essas emoções são profundas nesta alma.', '', 19865),
(65274, 'ptBR', '', 'Todos os dias eu arquivo alguma coisa nova, e alguma coisa antiga. De vez em quando, é um pergaminho da sabedoria antigo. As vezes, uma pintura do Vale que o Mestre Escriba fez.$b$BDevemos preservar a história para que as futuras gerações aprendam com nossos sucessos... e falhas.', 19865),
(65275, 'ptBR', 'Fique em uma superfície elevada para evitar a Neblina Sombria!', 'Fique em uma superfície elevada para evitar a Neblina Sombria!', 19865),
(65276, 'ptBR', '|TInterface\\Icons\\inv_misc_gem_bloodstone_03:20|t%s se transforma em |cFFFF0000|Hspell:126384|h[Granito Vermelho]|h|r!', '', 19865),
(65277, 'ptBR', '|TInterface\\Icons\\inv_misc_gem_stone_01:20|t%s se transforma em |cFFFF0000|Hspell:126401|h[Granito Verde]|h|r!', '', 19865),
(65278, 'ptBR', '|TInterface\\Icons\\inv_ore_cobalt:20|t%s se transforma em |cFFFF0000|Hspell:126405|h[Granito Azul]|h|r!', '', 19865),
(65279, 'ptBR', 'Eu busco treinamento no Caminho da Grelha.', 'Eu busco treinamento no Caminho da Grelha.', 19865),
(65280, 'ptBR', 'Eu busco treinamento no Caminho da Panela.', 'Eu busco treinamento no Caminho da Panela.', 19865),
(65281, 'ptBR', 'Eu busco treinamento no Caminho da Vaporeira.', 'Eu busco treinamento no Caminho da Vaporeira.', 19865),
(65282, 'ptBR', 'Eu busco treinamento no Caminho do Forno.', 'Eu busco treinamento no Caminho do Forno.', 19865),
(65283, 'ptBR', 'Sim?', 'Sim?', 19865),
(65284, 'ptBR', 'O cheiro é delicioso, não é?', 'O cheiro é delicioso, não é?', 19865),
(65285, 'ptBR', 'Você precisava de alguma coisa?', 'Você precisava de alguma coisa?', 19865),
(65286, 'ptBR', 'Você estaria $Ginteressado:interessada; em aprender a cozinhar?', 'Você estaria $Ginteressado:interessada; em aprender a cozinhar?', 19865),
(65287, 'ptBR', 'Eu busco treinamento em culinária Pandarênica.', 'Eu busco treinamento em culinária Pandarênica.', 19865),
(65288, 'ptBR', 'Eu preciso de ingredientes e equipamento para minha cozinha.', 'Eu preciso de ingredientes e equipamento para minha cozinha.', 19865),
(65289, 'ptBR', 'Quando a manhã se erguer, o martelo cairá.', '', 19865),
(65290, 'ptBR', 'O melhor da vida?\n\nColegas, cerveja e curtição!', '', 19865),
(65291, 'ptBR', 'Cerveja, pra mim, tem que ser igual à mulher: encorpadona.', '', 19865),
(65292, 'ptBR', 'Eu te amo e vou gritar pra todo mundo ouvir. Mas não agora. Fica pra depois.', '', 19865),
(65293, 'ptBR', '', 'Esses meninos dão uma trabalheira.', 19865),
(65294, 'ptBR', '', 'Prometi aos meninos um piquenique aqui em cima, mas é um local perigoso. No outro dia mesmo ouvi dizer que teve uma luta entre estranhos como você.$b$bE alguém da... tartaruga.$b$bEu sempre achei que a tartaruga era uma lenda.', 19865),
(65295, 'ptBR', '', 'Nós normalmente não temos problemas com predadores aqui em cima. De vez em quando, se chove, os sauroks aparecem. Mas só quando tem uma tempestade de raios.', 19865),
(65296, 'ptBR', 'Mããããããe, o Liu está me cutucando!', '', 19865),
(65297, 'ptBR', 'O Liu pegou meu berloque jinyu!', '', 19865),
(65298, 'ptBR', 'O Liu pisou no meu pé!', '', 19865),
(65299, 'ptBR', 'Mãe! O Liu continua se comportanto que nem um hozen!', '', 19865),
(65300, 'ptBR', 'Mãeeee! O Liu me deu um soco!', '', 19865),
(65301, 'ptBR', 'Não fui eu não!', '', 19865),
(65302, 'ptBR', 'Ele que começou!', '', 19865),
(65303, 'ptBR', 'Você que mandou!', '', 19865),
(65304, 'ptBR', 'Não mesmo!', '', 19865),
(65305, 'ptBR', '', 'Parem com isso. Vocês estão se comportando como dois hozens!', 19865),
(65306, 'ptBR', '', 'Se vocês não se comportarem, vou dar meia volta com esse piquenique e vamos para casa. É isso que vocês querem?', 19865),
(65307, 'ptBR', '', 'Ty, para de caguetar o seu irmão. Liu, não dê ao seu irmão motivo para caguetar.', 19865),
(65308, 'ptBR', '', 'Parem com isso, vocês dois. Vocês são mais inteligentes que isso. Vocês podem ser espertos como um jinyu e se comportarem? Ou vão ficar de bobeira como um hozen?', 19865),
(65309, 'ptBR', 'Apresente seu desafio.', '', 19865),
(65310, 'ptBR', 'Isto pode desorientar você momentaneamente, Arauto. A primeira vez que os olhos veem de verdade é sempre difícil.', '', 19865),
(65311, 'ptBR', 'Muito bem... Mestre Cervejeiro Metal.', '', 19865),
(65312, 'ptBR', 'Nós somos todos filhos da tempestade!', '', 19865),
(65313, 'ptBR', '', 'Sempre achei que os trolls eram coisas de lenda antiga.', 19865),
(65314, 'ptBR', '', 'Agradeço, $p. Sua coragem nos salvou nessa batalha.', 19865),
(65315, 'ptBR', '', 'Foi uma luta difícil. A maior parte de nós nunca precisou se preocupar com cavalgantes de sauroks ou hozens famintos de vez em quando.$b$bMas trolls... eles lutam diferente.', 19865),
(65316, 'ptBR', '', 'Os trolls estavam atrás de quê?', 19865),
(65317, 'ptBR', 'Agora você verá. Traidores se escondem em nossas fileiras.', '', 19865),
(65318, 'ptBR', 'Essa foi uma batalha emocionante.', '', 19865),
(65319, 'ptBR', 'Eu queria ter ficado acordado durante as lições de defesa no monastério, quando era um filhote.', '', 19865),
(65320, 'ptBR', 'O que esses trolls queriam aqui? Somos apenas uma vila de pescadores.', '', 19865),
(65321, 'ptBR', 'Trolls. Eram trolls de verdade! Ouvimos apenas histórias sobre eles. Mas vê-los em carne e osso... E são tão ferozes quando as histórias contam.', '', 19865),
(65322, 'ptBR', 'A raiva é parte de nós, sim. Mas nós valorizamos o controle. Os orcs já foram movidos por pura raiva, e viviam em estado sanguinário. Mas eles superaram essa fase.', '', 19865),
(65323, 'ptBR', 'Vocês só querem conquistar uns aos outros!', '', 19865),
(65324, 'ptBR', 'Viver sem raiva não é viver. A raiva é nossa para ser derrotada. Ao vencermos nossa raiva, obtemos grande força.', '', 19865),
(65325, 'ptBR', '|TInterface\\Icons\\ability_warrior_battleshout.blp:20|tO Espírito de Lao-Fe lança |cFFFF0000|Hspell:126471|h[Opressão aos Fracos!]|h|r!', '', 19865),
(65326, 'ptBR', 'Muito bem, Zhi. Não falta paixão aos estrangeiros de além das névoas, mas vamos ver se eles conseguem mesmo controlá-las. Além da raiva está o ódio, a fonte de toda desgraça. O que é isso? Seu ódio tem face!', '', 19865),
(65327, 'ptBR', 'Viu? Viu como esses forasteiros se odeiam? Eles cospem ódio em batalha e carregam ódio para o túmulo!', '', 19865),
(65328, 'ptBR', 'Não, isso não é verdade – nós não somos só desse jeito!', '', 19865),
(65329, 'ptBR', 'Que interessante. Eles trazem muitas coisas boas para as nossas terras, mas também trazem a sombra da guerra.', '', 19865),
(65330, 'ptBR', 'A paz virá. eu juro. E antigos ódios se dissiparão. Você deve acreditar em mim.', '', 19865),
(65331, 'ptBR', '|TInterface\\Icons\\ability_searingarrow.blp:20|tHuo-Shuang lança |cFFFF0000|Hspell:126304|h[Flecha Flamejante]|h|r!', '', 19865),
(65332, 'ptBR', '|TInterface\\Icons\\spell_frost_iceshard.blp:20|tHuo-Shuang lança |cFFFF0000|Hspell:126321|h[Projéteis Congelados]|h|r!', '', 19865),
(65333, 'ptBR', 'Kor''ik! Há quanto tempo você vem trabalhando para a Imperatriz?', '', 19865),
(65334, 'ptBR', 'Vejo que o paragão despertou.', '', 19865),
(65335, 'ptBR', 'O paragão não fala a verdade, Arauto. A mente dele não sobreviveu ao aprisionamento.', '', 19865),
(65336, 'ptBR', 'Ele não pode permitir que ele viva com essa loucura. Os Klaxxi irão querer eliminá-lo.', '', 19865),
(65337, 'ptBR', 'Você e os Klaxxi são tolos! Sua arrogância será seu fim!', '', 19865),
(65338, 'ptBR', 'A única loucura aqui é a sua, Kor''ik! Você realmente achou que passaria desapercebido para sempre?', '', 19865),
(65339, 'ptBR', 'Você não nos enganará. Nós vemos você como você é de verdade!', '', 19865),
(65340, 'ptBR', 'Aquele ali parece com... meu pai!', '', 19865),
(65341, 'ptBR', 'Aquele... aquele ali parece com Garrosh Grito Infernal!', '', 19865),
(65342, 'ptBR', '', 'Saudações, $c. Não farei mal a você.$B$BVenho como membro da Cruzada Escarlate em busca de ajuda, pois eles se tornaram irredimivelmente corruptos e maus.$B$BPreciso da sua ajuda para dar um fim a eles de uma vez por todas.', 19865),
(65343, 'ptBR', 'Ah... Ah não... Eu vou morrer aqui...', '', 19865),
(65344, 'ptBR', 'Não, você não vai! Aqui, toma isso!', 'Não, você não vai! Aqui, toma isso!', 19865),
(65345, 'ptBR', '|TInterface\\Icons\\spell_fire_soulburn.blp:20|t %s está lançando |cFFFF0000|Hspell:126288|h[Decimate]|h|r!', '', 19865),
(65346, 'ptBR', 'A fera está coberta de óleo, acendam o fogo!', '', 19865),
(65347, 'ptBR', 'Arqueiros, ataquem! Façam-no queimar!', '', 19865),
(65348, 'ptBR', 'Acendam o óleo!', '', 19865),
(65349, 'ptBR', 'Pule para se livrar das teias!', 'Pule para se livrar das teias!', 19865),
(65350, 'ptBR', 'Eis alguém que de fato mostrou domínio sobre a raiva. Entre as palavras do filhote e tais atos de heroísmo, acho que compreendo. Os que vêm de além das névoas estão calejados pela guerra. Eles têm cicatrizes, mas aprenderam muito. Confio neles.', '', 19865),
(65351, 'ptBR', 'Você está cometendo um terrível erro!', '', 19865),
(65352, 'ptBR', 'Está decidido! O Vale das Flores Eternas permanecerá aberto! As transgressões dos estrangeiros foram muitas... mas vejo neles a capacidade de consertar o mal que foi feito.', '', 19865),
(65353, 'ptBR', 'Obrigado, Mestre Tigre Branco. Você verá. Eu creio que meu povo – e a Horda – são essencialmente bons.', '', 19865),
(65354, 'ptBR', 'Vou consultar os outros. Encontre-me nos portões.', '', 19865),
(65355, 'ptBR', 'A Imperatriz Shek''zeer irá destruir você!', '', 19865),
(65356, 'ptBR', 'Eu acho sua fé inspiradora. Mas será que você já conheceu nosso chefe guerreiro?', '', 19865),
(65357, 'ptBR', 'A Imperatriz Shek''zeer conhece os seus planos. Sua traição será punida...', '', 19865),
(65358, 'ptBR', '$n, afaste os yaungóis enquanto eu termino a cerveja!', '', 19865),
(65359, 'ptBR', 'Eu gostaria de aprimorar outra arma tocada pelo sha. Você pode ajudar?', 'Eu gostaria de aprimorar outra arma tocada pelo sha. Você pode ajudar?', 19865),
(65360, 'ptBR', 'Você certamente se provou dign$go:a;, mas a matéria-prima não sai de graça.$b$bTenho certeza de que consigo algumas coisas com a Madame Goya, mas não vai ser barato.$b$bPor favor lembre-se de que apenas um Cristal do Medo pode ser equipado por vez.', '', 19865),
(65361, 'ptBR', 'Vale a pena. Eu quero aumentar minha agilidade. <Pagar 10.000 moedas de ouro.>', 'Vale a pena. Eu quero aumentar minha agilidade. <Pagar 10.000 moedas de ouro.>', 19865),
(65362, 'ptBR', '', 'Eu cresci ouvindo lendas sobre o Tigre Branco. Ele é um herói para o povo pandarênico. É uma grande honra estar treinando aqui.', 19865),
(65363, 'ptBR', 'Eu permanecerei aqui para examinar os restos de Kor''ik. Eu $go:a; encontrarei em Klaxxi''vess quando você tiver completado essas tarefas.', '', 19865),
(65364, 'ptBR', '|TInterface\\Icons\\ability_hunter_pet_spider.blp:20|t %s lança |cFFFF0000|Hspell:126652|h[Call Swarmers]|h|r!', '', 19865),
(65365, 'ptBR', 'Eu preciso de outra tocha.', 'Eu preciso de outra tocha.', 19865),
(65366, 'ptBR', 'Lacaios! Me tragam uma cerveja digna de Fedô!', '', 19865),
(65367, 'ptBR', 'Ataquem a costa! Roubem a cerveja!', '', 19865),
(65369, 'ptBR', '', 'Aqui, pegue esses suprimentos. Você precisará deles para as suas missões.', 19865),
(65370, 'ptBR', '|TInterface\\Icons\\inv_misc_idol_02.blp:20|tGara''jal seleciona jogadores aleatoriamente para que se tornem |cFFFF0000|Hspell:122151|h[Bonecos de Vodu]|h|r!', '', 19865),
(65371, 'ptBR', 'Você é um |cFFFF0000|Hspell:122151|h[Boneco de Vodu]|h|r! O dano recebido por você é causado também aos outros Bonecos de Vodu no seu raide!', 'Você é um |cFFFF0000|Hspell:122151|h[Boneco de Vodu]|h|r! O dano recebido por você é causado também aos outros Bonecos de Vodu no seu raide!', 19865),
(65373, 'ptBR', '|TInterface\\Icons\\inv_enchant_voidsphere.blp:20|tGara''jal |cFFFF0000|Hspell:116727|h[Baniu]|h|r você para o Mundo Espiritual! Você e seus aliados precisam derrotar todos os Rasgadores das Almas para retornar ao mundo real.', '', 19865),
(65374, 'ptBR', 'Os sinais cantam uns para os outros, forasteir$go:a;. Mensagens importantes são enviadas.$b$bSeus ouvidos não ouvirão as mensagens. Apenas aqueles em quem os Klaxxi confiam escutam suas palavras.', '', 19865),
(65375, 'ptBR', 'Seria uma honra me sacrificar por algo em que acredito.', '', 19865),
(65376, 'ptBR', '|TInterface\\Icons\\ability_shaman_astralshift.blp:20|tSeu espírito foi curado o suficiente para retornar ao seu corpo no mundo real! Use o botão de ação |cFFFF0000|Hspell:120715|h[Espírito Revitalizado]|h|r para salvar seu espírito!', '', 19865),
(65377, 'ptBR', 'Eu estou ocupado, forasteir$go:a;.', '', 19865),
(65378, 'ptBR', 'Você |cFFFF0000|Hspell:116161|h[Cruzou]|h|r para o Mundo Espiritual! Você ou um aliado precisam curar seu espírito para 90% de Vida em 30 segundos ou você perecerá!', '', 19865),
(65379, 'ptBR', 'Algum dia os klaxxi me promoverão. E eu poderei consumir âmbar.', '', 19865),
(65380, 'ptBR', 'Os Klaxxi não confiam tão facilmente, forasteir$go:a;. Levou muitos anos para que eles passassem a me enxergar.', '', 19865),
(65381, 'ptBR', 'Nós todos temos talentos, forasteir$go:a;. Alguns não são tão fáceis de notar quanto outros.', '', 19865),
(65382, 'ptBR', '|TInterface\\Icons\\ability_druid_challangingroar.blp:20|tGara''jal lança |cFFFF0000|Hspell:117752|h[Frenesi]|h|r!', '', 19865),
(65383, 'ptBR', '', 'Eu diria que estamos na metade do trabalho, não? Os Salões Escarlates já foram, falta o Monastério Escarlate.$B$BNão se assuste se eu desaparecer – preciso chegar lá rápido.', 19865),
(65384, 'ptBR', '', 'Há muitos cadáveres por aí. Muito bom, $p.', 19865),
(65385, 'ptBR', '', 'Você pegou o códice?', 19865),
(65386, 'ptBR', '', 'Ajoelhando-se, a Cruzada Encapuzada examina o corpo do Tecechamas, procurando algo.', 19865),
(65387, 'ptBR', 'Agora, de volta à cerveja!', '', 19865),
(65388, 'ptBR', 'O brilhante é meu!', '', 19865),
(65389, 'ptBR', 'Não é seu!', '', 19865),
(65390, 'ptBR', 'É meu, sssó meu!', '', 19865),
(65391, 'ptBR', 'Meu brilhante...', '', 19865),
(65392, 'ptBR', 'Cavaleiros se aproximam!', '', 19865),
(65393, 'ptBR', '', 'Eu tenho orgulho de defender nossa vila.', 19865),
(65394, 'ptBR', '', 'Pai, eu já não sou aquela criança indefesa que deixava o senhor preocupado.', 19865),
(65395, 'ptBR', '', 'Eu gostaria de continuar meu treinamento para que eu possa sempre defender o nosso lar.', 19865),
(65396, 'ptBR', '', 'Eu manterei a aldeia a salvo para que você possa aposentar suas armas.', 19865),
(65397, 'ptBR', 'Nunca antes um pai se sentiu tão orgulhoso de uma filha, Shomi.', '', 19865),
(65398, 'ptBR', 'Suas palavras me honram, filha. Este é um momento de orgulho para mim.', '', 19865),
(65399, 'ptBR', 'Você sempre será minha menininha e eu sempre me preocuparei com você, mas agora eu sei que você pode tomar conta de si mesma.', '', 19865),
(65400, 'ptBR', 'Ótimas notícias. Nosso estudo das energias e artefatos desse lugar começam a nos recompensar.$b$bNós começamos a entender alguns dos dispositivos mogus que encontramos aqui e, melhor ainda, uma forma de utilizá-los a nosso favor. As próprias paredes dessa estrutura irão sugar e aturdir o poder de qualquer inimigo na área.', '', 19865),
(65401, 'ptBR', 'Talvez seja melhor não se meter em mistérios ainda não totalmente compreendidos. Talvez você devesse desativar os dispositivos de amortecimento. Meus companheiros e eu resolveremos por conta própria. Tenho certeza de que ficaremos bem.', 'Talvez seja melhor não se meter em mistérios ainda não totalmente compreendidos. Talvez você devesse desativar os dispositivos de amortecimento. Meus companheiros e eu resolveremos por conta própria. Tenho certeza de que ficaremos bem.', 19865),
(65402, 'ptBR', 'Sim, por favor desative os dispositivos.', 'Sim, por favor desative os dispositivos.', 19865),
(65403, 'ptBR', 'Tem certeza? Esse é um local perigoso, e nossos pesquisadores iniciais ainda não voltaram da expedição. Se desativarmos o campo de amortecimento, teremos que partir até que as ruínas estejam totalmente seguras, e não poderemos reativar os dispositivos.$b$bEntão, pergunto novamente: tem certeza?', '', 19865),
(65404, 'ptBR', 'Você está atrasado.', '', 19865),
(65405, 'ptBR', 'Os restos do Rei Trovão foram levados pra Ilha da Desforra.', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(65406, 'ptBR', 'Nós realizamos os ritos antigos...', '', 19865),
(65407, 'ptBR', 'Agora, o VERDADEIRO imperador de Pandária vive e respira uma vez mais.', '', 19865),
(65408, 'ptBR', 'Espero que você saiba o que está fazendo.', '', 19865),
(65409, 'ptBR', 'Ai dos usurpadores pandarens! Os mogus vão mandar nessa terra de novo e nós Zandalari vamos ter uma casa nova...', '', 19865),
(65410, 'ptBR', 'Protegê os resto, rapeize!', '', 19865),
(65411, 'ptBR', 'O Rei Trovão vai viver de novo...', '', 19865),
(65412, 'ptBR', 'O Rei Trovão vive! Nossos impérios vão se unir de novo...', '', 19865),
(65413, 'ptBR', 'A gente precisa desta terra! O cataclismo destruiu nosso lar!', '', 19865),
(65414, 'ptBR', 'Isso tá só começando... A gente não vai morrer assim tão fácil...', '', 19865),
(65415, 'ptBR', 'Então você veio até aqui, no coração da poluição. Nós iremos ajudar você. Nossa música ressoará pelas paredes desse lugar perverso, enfraquecendo a determinação daqueles que abandonaram a nossa raça.', '', 19865),
(65416, 'ptBR', 'Somos mais que capazes de lidar com a situação sozinhos. Retire-se. Quando você voltar, encontrará a Imperatriz morta e seus problemas resolvidos.', 'Somos mais que capazes de lidar com a situação sozinhos. Retire-se. Quando você voltar, encontrará a Imperatriz morta e seus problemas resolvidos.', 19865),
(65417, 'ptBR', 'Sim, nós lidaremos com isso do nosso jeito.', 'Sim, nós lidaremos com isso do nosso jeito.', 19865),
(65418, 'ptBR', 'Isso é arrogância ou simples ingenuidade? A sua morte aguarda entre essas paredes. Se nós deixarmos você, você não terá ajuda alguma. Você tem noção do que está dizendo?', '', 19865),
(65419, 'ptBR', 'Que assim seja.', '', 19865),
(65420, 'ptBR', '$n está na |cFFFF0000|Hspell:121970|h[Armadilha]|h|r! Liberte-$go:a; clicando no barril!', '', 19865),
(65421, 'ptBR', 'Sob o Kun-Lai, Trovão a descansar está...', '', 19865),
(65422, 'ptBR', 'Exausta tempestade dorme lá...', '', 19865),
(65423, 'ptBR', 'Mas sangue de reino-irmão mantém...', '', 19865),
(65424, 'ptBR', 'Vivos os que nada têm...', '', 19865),
(65425, 'ptBR', 'Por sangue Zandalari será tomado...', '', 19865),
(65426, 'ptBR', 'Por voz Zandalari será acordado...', '', 19865),
(65427, 'ptBR', 'O campo de batalha não é lugar pra uma mulher!', '', 19865),
(65428, 'ptBR', 'Se eu não tivesse me machucado com essa farpa eu estaria defendendo nossa aldeia também!', '', 19865),
(65429, 'ptBR', 'Shomi não deveria querer lutar. Lutar é para os homens!', '', 19865),
(65430, 'ptBR', 'Shomi é muito criança!', '', 19865),
(65431, 'ptBR', '<Os olhos de Kovok se arregalam e fitam você.>', '', 19865),
(65432, 'ptBR', '<Kovok olha para você com preocupação.>', '', 19865),
(65433, 'ptBR', '<Kovok estala com alegria... é, deve ser alegria.>', '', 19865),
(65434, 'ptBR', 'Em toda a minha vida eu jamais achei que veria os Zandalari.', '', 19865),
(65435, 'ptBR', 'Esta aldeia é pacífica há mais tempo do que eu consigo lembrar. Nossas armas devem estar tão enferrujadas quanto os guerreiros.', '', 19865),
(65436, 'ptBR', 'Sobreviver a este ataque será um milagre.', '', 19865),
(65437, 'ptBR', 'Os Zandalari não vão nem ver o que os atingiu!', '', 19865),
(65438, 'ptBR', 'Finalmente a paz pode ser restaurada!', '', 19865),
(65439, 'ptBR', 'Você é $gum verdadeiro herói:uma verdadeira heroína;!', '', 19865),
(65440, 'ptBR', 'Finalmente posso voltar pro meu tricô! Tenho muitos cachecóis de inverno pra fazer!', '', 19865),
(65441, 'ptBR', 'Você tem nosso respeito e nossa gratidão.', '', 19865),
(65442, 'ptBR', 'Estes últimos acontecimentos me ensinaram muito.', '', 19865),
(65443, 'ptBR', 'Obrigado por me fazer ver quem a minha filha realmente é.', '', 19865),
(65444, 'ptBR', 'Você não só salvou nossa aldeia como também ajudou nossa família.', '', 19865),
(65445, 'ptBR', '', 'Eu cresci tanto, graças a você!', 19865),
(65446, 'ptBR', '', 'Eu espero ansiosa pelo dia em que nossos caminhos se cruzarão novamente!', 19865),
(65447, 'ptBR', '', 'Quem sabe da próxima vez não serei eu a salvar você?', 19865),
(65448, 'ptBR', '', 'Estou pronta para o mundo, mas será que o mundo está pronto pra mim!', 19865),
(65449, 'ptBR', 'Teremos que trabalhar rápido se quisermos encontrar os restos.', '', 19865),
(65450, 'ptBR', 'Cada aldeão é importante. Sem cada grão de areia individual, não teríamos a praia.', '', 19865),
(65451, 'ptBR', 'Em cada desafio que enfrentamos há uma lição a ser aprendida.', '', 19865),
(65452, 'ptBR', 'Esta aldeia agradece a você pela vitória.', '', 19865),
(65453, 'ptBR', 'Seria tolice nos concentrarmos no fato de termos perdido os restos. Esta aldeia será a primeira de muitas a se levantar contra o Rei Trovão. Esta é uma grande vitória!', '', 19865),
(65454, 'ptBR', 'Quando enfrentarmos o Rei Trovão nós estaremos preparados.', '', 19865),
(65455, 'ptBR', '', 'Não devemos ver apenas o lado negativo; há muitos motivos para permanecer otimista.', 19865),
(65456, 'ptBR', '', 'As dificuldades passarão e nós seremos mais fortes por causa delas.', 19865),
(65457, 'ptBR', '', 'Tenho certeza de que você poderá nos ajudar.', 19865),
(65458, 'ptBR', '', 'É por sua causa que a aldeia recuperou a força!', 19865),
(65459, 'ptBR', '', 'Nós não seremos a única aldeia a enfrentar o Rei Trovão!', 19865),
(65460, 'ptBR', '', 'É sempre bom fazer amizade com pescadores. Você nunca vai ter fome!', 19865),
(65461, 'ptBR', 'Isto é terrível! Como é que nós vamos derrotar os Zandalari?', '', 19865),
(65462, 'ptBR', 'Nós somos apenas uma pequena aldeia... O que nós podemos contra as forças do Rei Trovão?', '', 19865),
(65463, 'ptBR', 'Eles estão em maior número! Isso é loucura!', '', 19865),
(65464, 'ptBR', 'Eu sabia que nós iríamos derrotar os invasores!', '', 19865),
(65465, 'ptBR', 'Apesar das coisas que eu falei antes, eu nunca duvidei das suas habilidades!', '', 19865),
(65466, 'ptBR', 'Os Zandalari nunca deviam ter nos subestimado!', '', 19865),
(65467, 'ptBR', '', 'Esta vila normalmente é tão pacífica.', 19865),
(65468, 'ptBR', '', 'A mudança é inevitável, mesmo para aqueles teimosos feito os Doshu.', 19865),
(65469, 'ptBR', '', 'Minha filha tem espírito e resistência! Eu me preocupo menos com ela que com meu marido.', 19865),
(65470, 'ptBR', '', 'Está feito. Você conseguiu, $p!', 19865),
(65471, 'ptBR', '', 'Já basta dessa enganação.', 19865),
(65472, 'ptBR', '', 'Olá, eu sou Lilian. Você não se importa se eu ficar com essas lâminas, certo?', 19865),
(65473, 'ptBR', '', 'A Cruzada Encapuzada observa com desdém o cadáver dilacerado da alta-inquisidora.', 19865),
(65474, 'ptBR', '...ai?', '', 19865),
(65475, 'ptBR', 'Sim... papa. Desculpe, fiquei com a cabeça esquisita por causa daquela coisa.', '', 19865),
(65476, 'ptBR', 'Sai... fora... da cabeça... do meu menino!', '', 19865),
(65477, 'ptBR', 'Bem, é um começo, pelo menos. Você lembra o seu nome?', '', 19865),
(65478, 'ptBR', 'Era controle mental, menino. Existe uma diferença. E não se preocupe. Se caçar fosse fácil, todo mundo seria caçador.', '', 19865),
(65479, 'ptBR', 'Hozens nas Brumas.', 'Hozens nas Brumas.', 19865),
(65480, 'ptBR', 'Contos de Peixe.', 'Contos de Peixe.', 19865),
(65481, 'ptBR', 'O Sombrio Coração dos Mogus', 'O Sombrio Coração dos Mogus', 19865),
(65482, 'ptBR', '', 'É bom ver você de novo, $n. Eu estava preocupada, achando que você não viria.$B$BVamos logo acabar com isso de uma vez? A Cruzada Escarlate já deixou claro que não vai se exterminar sozinha.', 19865),
(65483, 'ptBR', 'Coração do Enxame Mantídeo', 'Coração do Enxame Mantídeo', 19865),
(65484, 'ptBR', 'Pelo que Vale a Pena Lutar', 'Pelo que Vale a Pena Lutar', 19865),
(65485, 'ptBR', 'A Canção dos Yaungóis', 'A Canção dos Yaungóis', 19865),
(65486, 'ptBR', 'Os Sete Fardos de Shaohao', 'Os Sete Fardos de Shaohao', 19865),
(65487, 'ptBR', 'A Balada de Liu Lang.', 'A Balada de Liu Lang.', 19865),
(65488, 'ptBR', 'Nunca adivinharíamos quanto conhecimento estava escondido por trás desses muros. E ainda há muito mais a ser adicionado.$b$bConforme você explora a terra, fique de olho nos objetos de interesse que possam nos ajudar a aprender mais sobre nosso passado. Junte-os para montar uma história, e talvez eu consiga compartilhar uma ou duas histórias com você.', '', 19865),
(65489, 'ptBR', 'É bom ver outro explorador! Tem gente que descobre terra nova e já sai procurando as fortalezas e os templos.$b$bEu não.$b$bPara conhecer um povo de verdade, é preciso se sujar os pés um pouco. Venha, caminhe comigo! Vamos ver o que esses pandarens do interior valorizam na vida.$b$bEste é o Caminho do Andarilho.', '', 19865),
(65490, 'ptBR', 'Minha sobrinha Li Li está tão impaciente para explorar Pandária. Mas não se aprende sobre uma nova terra correndo de um lugar pro outro. É importante conversar com todos que você encontra, experimentar um lugar até ele se tornar parte da sua alma.$b$bEste é o Caminho do andarilho!', '', 19865),
(65491, 'ptBR', 'Li Li não entende por que seu sempre paro para provar as cervejas locais. Mas em minha experiência, aprende-se muito sobre um povo conhecendo suas bebidas!$b$bVocê já provou as bebidas pandarênicas do interior? Muito secas, muito escuras. Um gole e você percebe que são pra se saborear lentamente. São a bebida de um povo que não tem pressa, que aproveita o tempo com os amigos.$b$bO que VOCÊ bebe, $c? E o que isso me diria a seu respeito?', '', 19865),
(65492, 'ptBR', 'Esses fazendeiros pandarens são muito interessantes! Uma comunidade muito próxima. Todo mundo conhece todo mundo.$b$bÉ bem diferente das cidades grandes em Kalimdor ou nos Reinos do Leste.', '', 19865),
(65493, 'ptBR', 'Por que você está sempre com tanta pressa, $n? Você corre loucamente de um estranho necessitado ao outro, para ganhar novas experiências.$b$bMas a vida não é um só um copo a ser enchido! Fique um pouco e aproveite os lugares que descobrir!', '', 19865),
(65494, 'ptBR', 'Minha família saiu de Pandária para explorar o mundo nas costas da Ilha Errante. Isso foi há muitas gerações.$b$bMas eu soube que há outros Malte do Trovão aqui em Pandária! Minha família há muito perdida. Como eles são? Eles fazem cerveja feito eu? Eles são aventureiros, como você e eu?', '', 19865),
(65495, 'ptBR', 'Se passar tempo suficiente aqui no vale, quem sabe você não fará amigos entre os nativos? Talvez até um dia se aquietar num terreninho com uma fazenda só sua.$b$bPense só! VOCÊ, $gum:uma; $c $gcansado:cansada; de batalhas, indo cuidar de uma fazenda!$b$b<Chen fecha os olhos e dá uma grande gargalhada.>', '', 19865),
(65496, 'ptBR', 'Aceite o Caminho do Andarilho! Não é bem um plano de ação, é mais uma postura.$b$bToda pessoa que você encontra é uma história. todo lugar para onde você vai é uma aventura. Toda bebida que você prova é a melhor da sua vida.$b$bNão é uma vida tão má assim, não é?', '', 19865),
(65497, 'ptBR', '<Chen lhe cumprimenta com um aceno mas parece estranhamento deprimido.>', '', 19865),
(65498, 'ptBR', 'A viagem ao Mundo Espiritual deixou você com |cFFFF0000|Hspell:117723|h[Alma Frágil]|h|r temporariamente! Se você tentar viajar para o Mundo Espiritual antes de a Alma Frágil expirar, você morrerá instantaneamente!', '', 19865),
(65499, 'ptBR', 'As águas sagradas estão conspurcadas, mas ainda há esperança. Nossos antigos rituais purificam e resistem, mesmo com essa grande corrupção. E, conforme as águas se recuperam, a força daqueles que as mancham diminui.', '', 19865),
(65500, 'ptBR', 'Este ser pode se alimentar de Medo, mas não temos nenhum para oferecer. Pare com esse ritual, pois não precisamos de ajuda para purificar esse lugar.', 'Este ser pode se alimentar de Medo, mas não temos nenhum para oferecer. Pare com esse ritual, pois não precisamos de ajuda para purificar esse lugar.', 19865),
(65501, 'ptBR', 'Quando o ritual terminar, não poderemos continuá-lo, e a corrupção continuará com força total. Nossa coragem é admirável, mas caso falhe, estaremos todos condenados. Você entende o que lhe peço? Compreende as consequências?', '', 19865),
(65502, 'ptBR', 'Esse é um momento histórico, $n. O que você acha que existe por trás dos portões?', '', 19865),
(65503, 'ptBR', 'Quando eu perguntar "Quem é o mestre?", vocês respondem: "Shonuf"!', '', 19865),
(65504, 'ptBR', 'Eu tenho o brilho!', '', 19865),
(65505, 'ptBR', 'Venha, encare a morte.', '', 19865),
(65506, 'ptBR', 'Sua armadura será o meu troféu!', '', 19865),
(65507, 'ptBR', '|TInterface\\Icons\\inv_misc_bomb_05.blp:20|tSabotador Kip''tilak lança |cFFFF0000|Hspell:107268|h[Sabotage]|h|r em |cFFFF0000$n|r!', '', 19865),
(65508, 'ptBR', 'Você está diante da sua morte.', '', 19865),
(65509, 'ptBR', 'Você foi |cFFFF0000|Hspell:107268|h[Sabotaged]|h|r!', 'Você foi |cFFFF0000|Hspell:107268|h[Sabotaged]|h|r!', 19865),
(65510, 'ptBR', 'O Sabotador Kip''tilak dispara uma série de explosões!', '', 19865),
(65511, 'ptBR', 'É bom ver você aqui, criança.', '', 19865),
(65512, 'ptBR', 'Eu, sim. A forma de derrotar o Medo é olhar diretamente nos olhos, sem piscar, de maneira resoluta.', 'Eu, sim. A forma de derrotar o Medo é olhar diretamente nos olhos, sem piscar, de maneira resoluta.', 19865),
(65513, 'ptBR', '|TInterface\\Icons\\ability_parry.blp:20|tO Mestre Monte de Neve ativa a |cFFFF0000|Hspell:106454|h[Postura de Aparo]|h|r!', '', 19865),
(65514, 'ptBR', 'Que os espíritos estejam com você, valente.', '', 19865),
(65515, 'ptBR', '|TInterface\\Icons\\spell_nature_earthbind.blp:20|tO Mestre Monte de Neve usa o |cFFFF0000|Hspell:106434|h[Chute do Tornado]|h|r!', '', 19865),
(65516, 'ptBR', '|TInterface\\Icons\\ability_hunter_sickem.blp:20|tMestre Monte de Neve se prepara |cFFFF0000$n|r para |cFFFF0000|Hspell:118961|h[Perseguição]|h|r!', '', 19865),
(65517, 'ptBR', 'Vamos descobrir!', 'Vamos descobrir!', 19865),
(65518, 'ptBR', '', 'Sim, essas servirão mais que bem. Sinto como se elas tivessem sido feitas para mim.', 19865),
(65519, 'ptBR', 'Mestre Monte de Neve está |cFFFF0000|Hspell:118961|h[Perseguindo]|h|r você! Se ele pegá-lo, usará a técnica |cFFFF0000|Hspell:106352|h[Batida de Tornado]|h|r em você! Corra do Mestre Monte de Neve até que a Perseguição acabe!', 'Mestre Monte de Neve está |cFFFF0000|Hspell:118961|h[Perseguindo]|h|r você! Se ele pegá-lo, usará a técnica |cFFFF0000|Hspell:106352|h[Batida de Tornado]|h|r em você! Corra do Mestre Monte de Neve até que a Perseguição acabe!', 19865),
(65520, 'ptBR', '|TInterface\\Icons\\inv_weapon_hand_30.blp:20|tO Mestre Monte de Neve usa a técnica |cFFFF0000|Hspell:106853|h[Punhos da Fúria]|h|r!', '', 19865),
(65522, 'ptBR', '', 'Neve-que-voa escolhe |cFFFF0000$n|r para perseguir com o |cFFFF0000|Hspell:106706|h[Aço Giratório]|h|r dela!', 19865),
(65523, 'ptBR', '', 'Neve-que-voa está perseguindo você com a técnica |cFFFF0000|Hspell:|h[Aço Giratório]|h|r dela! Corra dela até que ela escolha outra pessoa!', 19865),
(65524, 'ptBR', '', '|TInterface\\Icons\\inv_sword_24.blp:20|tNeve-que-voa usa a técnica |cFFFF0000|Hspell:106706|h[Aço Giratório]|h|r!', 19865),
(65525, 'ptBR', 'Um Novato Shado-Pan escolheu você para um |cFFFF0000|Hspell:106774|h[Combate Justo]|h|r! Ele atacará você até ser derrotado!', 'Um Novato Shado-Pan escolheu você para um |cFFFF0000|Hspell:106774|h[Combate Justo]|h|r! Ele atacará você até ser derrotado!', 19865),
(65526, 'ptBR', '|TInterface\\Icons\\ability_warrior_battleshout.blp:20|tO Mestre Armeiro Harlan chama dois aliados para se juntarem à batalha!', '', 19865),
(65527, 'ptBR', '|TInterface\\Icons\\inv_weapon_halberd_05.blp:20|tO Mestre Armeiro Harlan lança |cFFFF0000|Hspell:111216|h[Espadas da luz]|h|r!', '', 19865),
(65528, 'ptBR', 'Você morreu pela habilidade |cFFFF0000|Hspell:|h[Espadas da Luz]|h|r do Mestre Armeiro Harlan. Ele escolhe uma entre duas direções quando usa a habilidade, então tente reagir de acordo com a direção escolhida por ele para conseguir se esquivar!', 'Você morreu pela habilidade |cFFFF0000|Hspell:|h[Espadas da Luz]|h|r do Mestre Armeiro Harlan. Ele escolhe uma entre duas direções quando usa a habilidade, então tente reagir de acordo com a direção escolhida por ele para conseguir se esquivar!', 19865),
(65529, 'ptBR', '|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|tO Vizir Imperial Zor''lok alvejou você com sua habilidade |cFFFF0000|Hspell:122761|h[Exalar]|h|r! Use suas habilidades de sobrevivência ou chame um aliado com bastante vida para ficar entre você e o Vizir Imperial Zor''lok!', '|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|tO Vizir Imperial Zor''lok alvejou você com sua habilidade |cFFFF0000|Hspell:122761|h[Exalar]|h|r! Use suas habilidades de sobrevivência ou chame um aliado com bastante vida para ficar entre você e o Vizir Imperial Zor''lok!', 19865),
(65530, 'ptBR', 'Você morreu para o feitiço |cFFFF0000|Hspell:122713|h[Força e Verve]|h|r do Vizir Imperial Zor''lok. Tente entrar em uma das zonas de  |cFFFF0000|Hspell:122706|h[Cancelamento de Ruídos]|h|r para minimizar o dano desse feitiço e use suas habilidades curativas ou as de um aliado para se manter $gvivo:viva;.', 'Você morreu para o feitiço |cFFFF0000|Hspell:122713|h[Força e Verve]|h|r do Vizir Imperial Zor''lok. Tente entrar em uma das zonas de  |cFFFF0000|Hspell:122706|h[Cancelamento de Ruídos]|h|r para minimizar o dano desse feitiço e use suas habilidades curativas ou as de um aliado para se manter $gvivo:viva;.', 19865),
(65531, 'ptBR', 'Você sucumbiu ao feitiço |cFFFF0000|Hspell:123791|h[Canção da Imperatriz]|h|r do Vizir Imperial Zor''lok. Você ou um dos seus aliados deve ir até a plataforma onde está o Vizir Imperial Zor''lok e enfrentá-lo em combate próximo.', 'Você sucumbiu ao feitiço |cFFFF0000|Hspell:123791|h[Canção da Imperatriz]|h|r do Vizir Imperial Zor''lok. Você ou um dos seus aliados deve ir até a plataforma onde está o Vizir Imperial Zor''lok e enfrentá-lo em combate próximo.', 19865),
(65532, 'ptBR', 'O Vizir Imperial Zor''lok fez você ser |cFFFF0000|Hspell:122740|h[Convertid$go:a;]|h|r para lutar pelo Império Mantídeo! Seus ex-aliados precisam reduzir sua vida em 50% para libertar você do domínio da imperatriz!', 'O Vizir Imperial Zor''lok fez você ser |cFFFF0000|Hspell:122740|h[Convertid$go:a;]|h|r para lutar pelo Império Mantídeo! Seus ex-aliados precisam reduzir sua vida em 50% para libertar você do domínio da imperatriz!', 19865),
(65533, 'ptBR', 'Você pereceu para a habilidade |cFFFF0000|Hspell:122336|h[Anéis Sônicos]|h|r do Vizir Imperial Zor''lok. Quando o Vizir Imperial Zor''lok começar a lançar |cFFFF0000|Hspell:122496|h[Attenuation]|h|r afaste-se dele e se esquive dos Anéis Sônicos que ele emite.', 'Você pereceu para a habilidade |cFFFF0000|Hspell:122336|h[Anéis Sônicos]|h|r do Vizir Imperial Zor''lok. Quando o Vizir Imperial Zor''lok começar a lançar |cFFFF0000|Hspell:122496|h[Atenuação]|h|r afaste-se dele e se esquive dos Anéis Sônicos que ele emite.', 19865),
(65534, 'ptBR', '|TInterface\\Icons\\spell_shaman_earthquake.blp:20|tKuai, o Brutamontes, usa a habilidade |cFFFF0000|Hspell:119922|h[Onda de Choque]|h|r!', '', 19865),
(65536, 'ptBR', '|TInterface\\Icons\\ability_druid_supriseattack.blp:20|tMu''Shiba lança |cFFFF0000|Hspell:119946|h[Assolar]|h|r em |cFFFF0000$n|r!', '', 19865),
(65537, 'ptBR', '|TInterface\\Icons\\inv_elemental_primal_air.blp:20|tMing, o Astuto, evoca um |cFFFF0000|Hspell:119981|h[Dervixe Giratório]|h|r!', '', 19865),
(65538, 'ptBR', '|TInterface\\Icons\\spell_druid_ursolsvortex.blp:20|tMing, o Astuto, cria um |cFFFF0000|Hspell:120099|h[Campo Magnético]|h|r!', '', 19865),
(65539, 'ptBR', '|TInterface\\Icons\\ability_warrior_savageblow.blp:20|tHaiyan, o Inexorável, ataca |cFFFF0000$n|r com um |cFFFF0000|Hspell:123655|h[Golpe Traumático]|h|r!', '', 19865),
(65540, 'ptBR', 'Aqui estamos todos. Esse é um momento histórico, $n. Minha esposa ao morrer, vislumbrou uma cidade de luz por trás desses portões. O que você acha que vamos encontrar?', '', 19865),
(65541, 'ptBR', 'Haiyan, o Inexorável, atinge você com um |cFFFF0000|Hspell:123655|h[Golpe Traumático]|h|r! As habilidades de cura utilizadas em você serão menos eficientes enquanto o efeito do golpe persistir!', '', 19865),
(65542, 'ptBR', 'Só tem um jeito de saber...', 'Só tem um jeito de saber...', 19865),
(65543, 'ptBR', '|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|tHaiyan, o Inexorável, prepara |cFFFF0000$n|r com um |cFFFF0000|Hspell:120195|h[Meteoro]|h|r!', '', 19865),
(65544, 'ptBR', 'Você morreu para o |cFFFF0000|Hspell:120195|h[Meteoro]|h|r de Haiyan, o Inexorável! Quando Haiyan, o Inexorável, utilizar essa habilidade, o grupo precisa se juntar, para que todos dividam o dano.', '', 19865),
(65545, 'ptBR', '|TInterface\\Icons\\spell_fire_fireball.blp:20|tHaiyan, o Inexorável, começa a lançar |cFFFF0000|Hspell:120167|h[Conflagrar]|h|r!', '', 19865),
(65546, 'ptBR', 'Vou proteger o vale com a minha vida!', 'Vou proteger o vale com a minha vida!', 19865),
(65547, 'ptBR', 'Precisamos manter o equilíbrio!', 'Precisamos manter o equilíbrio!', 19865),
(65548, 'ptBR', 'Pela honra!', 'Pela honra!', 19865),
(65549, 'ptBR', 'O lótus dourado precisa proteger o vale!', 'O lótus dourado precisa proteger o vale!', 19865),
(65550, 'ptBR', 'Os campos do verão vão permanecer seguros enquanto eu viver!', 'Os campos do verão vão permanecer seguros enquanto eu viver!', 19865),
(65551, 'ptBR', 'Nós lutamos juntos, irmãos!', 'Nós lutamos juntos, irmãos!', 19865),
(65552, 'ptBR', 'Tire esses brutos do vale!', 'Tire esses brutos do vale!', 19865),
(65553, 'ptBR', 'Fiquem alerta!', 'Fiquem alerta!', 19865),
(65554, 'ptBR', 'Defender o vale com a minha vida é uma honra!', 'Defender o vale com a minha vida é uma honra!', 19865),
(65555, 'ptBR', 'A batalha é nossa!', 'A batalha é nossa!', 19865),
(65556, 'ptBR', 'Nós somos vitoriosos!', 'Nós somos vitoriosos!', 19865),
(65557, 'ptBR', 'Ah-hah! Mais uma chance de testar meu poder.', '', 19865),
(65558, 'ptBR', 'Eles estão recuando!', 'Eles estão recuando!', 19865),
(65559, 'ptBR', 'Em guarda!', '', 19865),
(65560, 'ptBR', 'Derrotado... por essa laia...', '', 19865),
(65561, 'ptBR', 'Hah-HAH!', '', 19865),
(65562, 'ptBR', 'Tsc! Você precisa treinar mais.', '', 19865),
(65563, 'ptBR', 'Que eles encontrem paz.', 'Que eles encontrem paz.', 19865),
(65564, 'ptBR', 'Xeun nos ensinou a ter coragem.', 'Xeun nos ensinou a ter coragem.', 19865),
(65565, 'ptBR', 'O vale está seguro, agora.', 'O vale está seguro, agora.', 19865),
(65567, 'ptBR', '', 'As lâminas se transformam conforme ela as puxa do corpo de Cristalba.', 19865),
(65568, 'ptBR', '', 'Você acredita na cara de pau desse gromulinho? Esse mercadorzinho barato vai me falir com esses preços daqui a pouco.', 19865),
(65569, 'ptBR', 'FUMMM!', '', 19865),
(65570, 'ptBR', 'He gesticula para as estátuas que se aproximam, pedindo ajuda.', '', 19865),
(65571, 'ptBR', 'Não baixem a guarda!', 'Não baixem a guarda!', 19865),
(65572, 'ptBR', 'Um bandido hozen está roubando a cerveja! Detenha-o!', 'Um bandido hozen está roubando a cerveja! Detenha-o!', 19865),
(65573, 'ptBR', 'Olá, $n! A Andarilha das Lendas está começando a aula descendo essa escada, caso queira ouvir.', '', 19865),
(65574, 'ptBR', 'Criaturas lamentáveis.', '', 19865),
(65575, 'ptBR', 'Vou ensinar a vocês o significado da força.', '', 19865),
(65576, 'ptBR', 'Lei Shen retorna, fracote.', '', 19865),
(65577, 'ptBR', 'O vale pertence aos Shao-Tien!', '', 19865),
(65578, 'ptBR', 'Nós iremos reinar em Pandária mais uma vez!', '', 19865),
(65579, 'ptBR', 'Não há como escapar do nosso poder!', '', 19865),
(65580, 'ptBR', 'Criança tola.', '', 19865),
(65581, 'ptBR', 'Desista.', '', 19865),
(65582, 'ptBR', 'Ele vai cortar e picotar de maneiras que não são agradáveis! Curvem-se respeitosamente para Maki Lâmina d''Água, samurai saurok!', '', 19865),
(65583, 'ptBR', '', 'Essa é a Canção de Liu Lang, o primeiro pandaren explorador.', 19865),
(65584, 'ptBR', '', 'A canção foi escrita em uma língua antiga, a língua dos imperadores e eruditos. Quase ninguém mais a fala.', 19865),
(65585, 'ptBR', '', 'É sobre as aventuras dele.', 19865),
(65586, 'ptBR', '', 'O bravo Liu Lang saiu para explorar o mundo nas costas de uma tartaruga marinha.', 19865),
(65587, 'ptBR', '', 'Alguém se lembra do nome da tartaruga? Yin?', 19865),
(65588, 'ptBR', '', 'Isso mesmo, a tartaruga se chamava Shen-zin Su. Inicialmente, ela era grande suficiente para que apenas Liu Lang se sentasse.', 19865),
(65589, 'ptBR', '', 'Ela cresceu, e cresceu, e cresceu, e ficou tão grande que as pessoas hoje a chamam de "Ilha Errante".', 19865),
(65590, 'ptBR', '', 'Alguma pergunta, Hao?', 19865),
(65591, 'ptBR', '', 'Sim, Hao, nosso lar é nas costas da Shen-zin Su.', 19865),
(65592, 'ptBR', '', 'Liu Lang descobriu muitas coisas ao explorar o mundo. Ah, sim, Hao?', 19865),
(65593, 'ptBR', '', 'É uma ótima pergunta. Ninguém falou com Shen-zin Su por muitas gerações. Ele falava apenas com Liu Lang.', 19865),
(65594, 'ptBR', '', 'Mas tenho certeza de que Shen-zin Su sabe que estamos aqui. E ele se preocupa conosco!', 19865),
(65595, 'ptBR', '', 'Principalmente com Hao! Liu Lang uma vez disse: "Nobre é aquele que sempre faz perguntas".', 19865),
(65596, 'ptBR', '', '"Nós devemos ser como as crianças, pois o mundo é nosso ancião e tem muitas coisas a nos ensinar".', 19865),
(65597, 'ptBR', '', 'Alunos! Alunos! Prestem atenção.', 19865),
(65598, 'ptBR', '', 'Alguém sabe com que frequência Liu Lang voltava a Pandária?', 19865),
(65599, 'ptBR', '', 'Haha, não, Yin. Liu Lang comeria em qualquer lugar que ele explorasse.', 19865),
(65600, 'ptBR', '', 'Ele voltava ao continente de Pandária a cada cinco anos.', 19865),
(65601, 'ptBR', '', 'Você está certo, Yin. Ele está de fato escondido, atrás de uma manta de névoa.', 19865),
(65602, 'ptBR', '', 'Alguém se lembra como Liu Lang sempre conseguia encontrar o continente? Nan?', 19865),
(65603, 'ptBR', '', 'Isso mesmo! Liu Lang sempre teve uma forma de voltar para casa. A cada cinco anos, ele voltava e pegava mais exploradores.', 19865),
(65604, 'ptBR', '', 'Sim, Hao! Apenas os pandarens mais BRAVOS se uniam a Liu Lang na tartaruga para explorar o mundo.', 19865),
(65605, 'ptBR', '', 'Shen-zin Su já não volta à terra firme há bom tempo. Mas isso não impediu que alguns pandarens explorassem.', 19865),
(65606, 'ptBR', '', 'Sim, como Chen e Li Li! Eles estão fora, explorando o mundo. Talvez algum dia vocês também façam o mesmo.', 19865),
(65607, 'ptBR', '', 'Que bom que você perguntou, Yin. Liu Lang explorou o mundo por toda a vida dele, e criou muitas crianças aqui na Ilha Errante.', 19865),
(65608, 'ptBR', '', 'Eventualmente, ele envelheceu, e visitou Pandária uma última vez.', 19865),
(65609, 'ptBR', '', 'Mas ninguém quis explorar o mundo com ele. E, então, ele partiu.', 19865),
(65610, 'ptBR', '', 'Shen-zin Su nunca mais voltou a Pandária.', 19865),
(65611, 'ptBR', '', 'Cansado, Liu Lang disse adeus à Shen-zin Su, seu mais velho amigo.', 19865),
(65612, 'ptBR', '', 'E, assim, Liu Lang foi para o Bosque dos Cajados, levando consigo uma sombrinha de bambu que ele sempre carregou nas aventuras dele.', 19865),
(65613, 'ptBR', '', 'Ele abriu a sombrinha, a fincou no chão e sentou-se sob a sombra fresca.', 19865),
(65614, 'ptBR', '', 'Fechou os olhos e se tornou um só com a terra. E então, vocês sabem o que aconteceu?', 19865),
(65615, 'ptBR', '', 'A sombrinha... desabrochou! Ela criou raízes, flores, e se tornou uma árvore!', 19865),
(65616, 'ptBR', '', 'Bem, é verdade. Se vocês algum dia forem ao Bosque dos Cajados, poderão vê-la.', 19865),
(65617, 'ptBR', '', 'Está junto de cajados de anciãos que vieram antes de nós, e que se transformaram em grandes árvores.', 19865),
(65618, 'ptBR', '', 'Não é uma história triste! Liu Lang mesmo disse, "Nunca lamente uma vida bem vivida".', 19865),
(65619, 'ptBR', '', 'E eu acho que ele viveu uma vida muito, muito boa. Nós devemos tudo a Liu Lang, o primeiro explorador pandaren.', 19865),
(65620, 'ptBR', '', 'Nós contamos a história dele para que ele seja sempre lembrado.', 19865),
(65621, 'ptBR', '', 'Obrigada, Ruolin! Foi lindo.', 19865),
(65622, 'ptBR', '', 'Poderia cantar novamente, para os alunos que acabaram de chegar?', 19865),
(65623, 'ptBR', 'Um fim honorável para o nobre Maki... Tenho certeza de que seu clã ficaria orgulhoso se ele não tivesse sido o último deles!', '', 19865),
(65624, 'ptBR', 'Os shado-pans sempre foram amigos dos grômulos. Por que eles não deixam entrar para fazer comércio?', '', 19865),
(65625, 'ptBR', 'Viajamos por um longo percurso. Agora, os shado-pans dizem que não querem nossas mercadorias. Isso é muito estranho.', '', 19865),
(65626, 'ptBR', 'Nós viajamos por entre hozens irritados, yetis furiosos e iaques imundos para chegarmos aqui. Agora, os shado-pans agem como se fossemos estranhos.$b$bÉ muita falta de sorte, certamente.', '', 19865),
(65627, 'ptBR', 'Meu nariz está gelado. É um péssimo sinal.', '', 19865),
(65628, 'ptBR', 'Perdi meu iaque na estrada. Isso não é nada bom.', '', 19865),
(65629, 'ptBR', 'Se esse shado-pan não nos deixarem entrar logo, vou fazer ele cheirar o MEU sorte-sim.', '', 19865),
(65630, 'ptBR', 'Isso é muito estranho. Os Shado-Pan são nossos melhores clientes. Nós vendemos suprimentos para eles, e eles nos mantém a salvo.$b$bPor que eles estão nos rejeitando? Não entendo.', '', 19865),
(65631, 'ptBR', 'Por que não consigo entender nenhuma palavra?', '', 19865),
(65632, 'ptBR', 'Voando através das brumas com a morte em seus punhos, aí vem o sinistro e sereno assassino: Satay Byu!', '', 19865),
(65633, 'ptBR', 'Ooo, aquela era uma carpa assassina que acabou ela mesma boiando de cabeça pra baixo.', '', 19865),
(65634, 'ptBR', '', 'Sobre o que é essa música?', 19865),
(65635, 'ptBR', '', 'Shen-zin Su!', 19865),
(65636, 'ptBR', 'Todos saúdem os NOVOS CAMPEÕES da Arena da Aniquilação!', '', 19865),
(65637, 'ptBR', 'A gente vive nas costas de um tartarugão?', '', 19865),
(65638, 'ptBR', '', 'Caraca, Hao. Você não prestou atenção?', 19865),
(65639, 'ptBR', 'Eu achava esquisito que as montanhas tivessem barbatanas!', '', 19865),
(65640, 'ptBR', 'A tartaruga sabe que a gente vive aqui?', '', 19865),
(65641, 'ptBR', '', 'Até mesmo Hao?', 19865),
(65642, 'ptBR', 'Ei!', '', 19865),
(65643, 'ptBR', 'É, vocês deviam ser mais que nem eu.', '', 19865),
(65644, 'ptBR', '', 'Eca! Eu prefiro pular dessa ponte.', 19865),
(65645, 'ptBR', '', '...Sempre que ele ficava com fome?', 19865),
(65646, 'ptBR', '', 'Mas Pandária não está escondida em algum lugar? Ninguém consegue encontrar!', 19865),
(65647, 'ptBR', '', 'Porque as tartarugas marinhas sempre voltam à praia onde nasceram!', 19865),
(65648, 'ptBR', 'Isso significa que os nossos pais e avós foram todos exploradores também?', '', 19865),
(65649, 'ptBR', '', 'Mas nós não exploramos mais, né?', 19865),
(65650, 'ptBR', '', 'Como Chen e Li Li Malte do Trovão!', 19865),
(65651, 'ptBR', 'Eu quero explorar o mundo!', '', 19865),
(65652, 'ptBR', '', 'Não quer não, ele tá cheio de trolls.', 19865),
(65653, 'ptBR', 'Ah. Bem, esquece, então.', '', 19865),
(65654, 'ptBR', '', 'Andarilha das Lendas! O que aconteceu com Liu Lang?', 19865),
(65655, 'ptBR', 'O quê?', '', 19865),
(65656, 'ptBR', '', 'O quê? O quê?', 19865),
(65657, 'ptBR', 'É im-pos-sível!', '', 19865),
(65658, 'ptBR', '', 'Que história triste!', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(65659, 'ptBR', 'He mexe no cadeado da sua jaula.', '', 19865),
(65660, 'ptBR', 'He gesticula para o vale oriental, e então desaparece nas sombras.', '', 19865),
(65661, 'ptBR', 'He luta para se libertar.', '', 19865),
(65662, 'ptBR', 'He desmorona no chão, exausto.', '', 19865),
(65663, 'ptBR', 'He aponta o corredor adiante.', '', 19865),
(65664, 'ptBR', 'He faz um gesto para que você espere.', '', 19865),
(65665, 'ptBR', 'He continua cuidadosamente.', '', 19865),
(65666, 'ptBR', 'Você pode usar as bombas e canhões próximos para estourar os hozens!', 'Você pode usar as bombas e canhões próximos para estourar os hozens!', 19865),
(65667, 'ptBR', 'Eu pensei que esse fosse um torneio de "força". Mas eu só vejo fraqueza.', '', 19865),
(65668, 'ptBR', 'Eu sou a arma dos reis! O que faz você pensar que tem alguma chance?', '', 19865),
(65669, 'ptBR', 'Você fracassará.', '', 19865),
(65670, 'ptBR', 'Er... o que foi aquilo?', '', 19865),
(65671, 'ptBR', 'Eita! Cuidado aí! Esses ladrilhos têm tendências violentas...', '', 19865),
(65672, 'ptBR', 'Ladrilho de nuvem, bom. Outros ladrilhos, ruins. Tinha um ladrilho no início da escadaria que meu deu a dica. Meus olhos afiados salvaram meus traços delicados mais uma vez!', '', 19865),
(65673, 'ptBR', 'Eita ferro! Parece que temos companhia... Cuide desses vira-latas e eu cuido da cerveja.', '', 19865),
(65674, 'ptBR', 'Ufa! Essa foi por pouco. Certo, o negócio é o seguinte...', '', 19865),
(65675, 'ptBR', 'Os mogus, eles não parecem muito bons nesse jogo, se os cadáveres deles indicam alguma coisa.', '', 19865),
(65676, 'ptBR', 'Entendo, entendo.', '', 19865),
(65677, 'ptBR', 'Hummm, e então?', '', 19865),
(65678, 'ptBR', 'Eu acho que iria gostar muito mais de jogar pedras naquele corredor ali. A vista seria bem mais bonita!', '', 19865),
(65679, 'ptBR', 'Agora onde está aquele moguzão malvado que veio passeando por aqui há uns minutinhos?', '', 19865),
(65680, 'ptBR', 'Ele...é tão...', '', 19865),
(65681, 'ptBR', '...feio!', '', 19865),
(65682, 'ptBR', 'O que você está fazendo aqui, afinal? Veio até aqui só para ficar na minha maravilhosa companhia?', '', 19865),
(65683, 'ptBR', 'Zhi me enviou.', 'Zhi me enviou.', 19865),
(65684, 'ptBR', 'GALEROSOS!', '', 19865),
(65685, 'ptBR', 'Tolos, vocês morrerão comigo!', '', 19865),
(65686, 'ptBR', 'Eu fracassei, mas você não viverá para contar essa vitória!', '', 19865),
(65687, 'ptBR', 'A artilharia vai calcinar no chão, restando nada!', '', 19865),
(65688, 'ptBR', 'Reforços, venham aqui e matem esses fracotes!', '', 19865),
(65689, 'ptBR', 'Haha, tolos que não voam!', '', 19865),
(65690, 'ptBR', 'Ah, não...', 'Ah, não...', 19865),
(65691, 'ptBR', 'O que vamos fazer?!', 'O que vamos fazer?!', 19865),
(65692, 'ptBR', 'Os yaungóis estragam tudo!', 'Os yaungóis estragam tudo!', 19865),
(65693, 'ptBR', 'De novo?!', 'De novo?!', 19865),
(65694, 'ptBR', 'Não dá pra ter uma só noite de paz?', 'Não dá pra ter uma só noite de paz?', 19865),
(65695, 'ptBR', 'Fiquem quietos agora, deixem Hsieh falar.', '', 19865),
(65696, 'ptBR', 'Você nos salvou, $p!', 'Você nos salvou, $p!', 19865),
(65697, 'ptBR', 'O que faríamos sem você, $p?', 'O que faríamos sem você, $p?', 19865),
(65698, 'ptBR', 'O festival foi salvo!', 'O festival foi salvo!', 19865),
(65699, 'ptBR', 'Você é fenomenal, $p!', 'Você é fenomenal, $p!', 19865),
(65700, 'ptBR', 'Case comigo, $p!', 'Case comigo, $p!', 19865),
(65701, 'ptBR', 'Com $p por perto, os yaungóis nem tiveram chance!', 'Com $p por perto, os yaungóis nem tiveram chance!', 19865),
(65702, 'ptBR', 'Você chutou o traseiro dos yaungóis, $p!', 'Você chutou o traseiro dos yaungóis, $p!', 19865),
(65703, 'ptBR', 'Vamos renomear a aldeia para $Plópolis!', 'Vamos renomear a aldeia para $Plópolis!', 19865),
(65704, 'ptBR', 'Bom trabalho, $p, você salvou a aldeia. Estamos em dívida eterna com você.', '', 19865),
(65705, 'ptBR', '', 'Ei, $n! Eu estou preparando algo especial para o festival. Venha aqui mais tarde e eu lhe darei um pouco.', 19865),
(65706, 'ptBR', '', 'Está pronto! Eu pus em cima da mesa.', 19865),
(65707, 'ptBR', '', 'Que barulho é esse lá fora?', 19865),
(65708, 'ptBR', '', 'Não ficou bom não, $n. Acho que você não vai querer provar.', 19865),
(65709, 'ptBR', 'Preciso de um minuto para me recuperar.', 'Preciso de um minuto para me recuperar.', 19865),
(65710, 'ptBR', 'Preciso recuperar minha força.', 'Preciso recuperar minha força.', 19865),
(65711, 'ptBR', 'Me proteja!', 'Me proteja!', 19865),
(65712, 'ptBR', 'Não desse jeito...', 'Não desse jeito...', 19865),
(65713, 'ptBR', 'Sua mente é fraca.', '', 19865),
(65714, 'ptBR', 'Uma criatura tão fraca.', '', 19865),
(65715, 'ptBR', 'Outr$go:a; fracote.', '', 19865),
(65716, 'ptBR', 'Você me servirá muito bem.', '', 19865),
(65717, 'ptBR', 'Você veio para a sua sepultura.', '', 19865),
(65718, 'ptBR', 'Você dará uma excelente mascote.', '', 19865),
(65719, 'ptBR', 'Rápido, todos às armas!', '', 19865),
(65720, 'ptBR', 'O templo não cairá!', '', 19865),
(65721, 'ptBR', 'Não vamos deixar que isso aconteça.', '', 19865),
(65722, 'ptBR', 'Devemos muito a você.', '', 19865),
(65723, 'ptBR', 'Hoje, os shado-pans dão as boas-vindas a você.', '', 19865),
(65724, 'ptBR', 'Sua perseverança nos fortalece. Sua coragem nos conduz. Sua honra nos inspira.', '', 19865),
(65725, 'ptBR', 'Deste dia em diante, você será um de nós.', '', 19865),
(65726, 'ptBR', 'Siga em frente, agora como membro dos Shado-Pans!', '', 19865),
(65727, 'ptBR', 'Já era hora!', '', 19865),
(65728, 'ptBR', 'Vamos sair para um drinque!', '', 19865),
(65729, 'ptBR', 'Nós sabíamos que você conseguiria!', '', 19865),
(65730, 'ptBR', 'Esses caras não têm bom gosto.', '', 19865),
(65731, 'ptBR', 'Tenho uma mistura especial para você!', '', 19865),
(65732, 'ptBR', 'Humpf... Que previsível.', '', 19865),
(65733, 'ptBR', 'Já lutei com vermingues mais espertos que você.', '', 19865),
(65734, 'ptBR', 'Você lutaria melhor se relaxasse um pouco.', '', 19865),
(65735, 'ptBR', 'Belos golpes. Quero estudá-los mais.', '', 19865),
(65736, 'ptBR', 'Se lutar desse jeito funciona para você, então tudo bem...', '', 19865),
(65737, 'ptBR', 'Hã? Ah, olá, inimigos.', '', 19865),
(65738, 'ptBR', 'Durante a luta, eu tive uma ideia para uma cerveja nova.', '', 19865),
(65739, 'ptBR', 'Estamos muito acima desses caras.', '', 19865),
(65740, 'ptBR', 'Se beber, não dirija, lute.', '', 19865),
(65741, 'ptBR', 'Que luta criativa, né?', '', 19865),
(65742, 'ptBR', 'O quê? Não!', '', 19865),
(65743, 'ptBR', 'Temos que detê-los!', '', 19865),
(65744, 'ptBR', 'Você não vai passar pela gente de jeito nenhum!', '', 19865),
(65745, 'ptBR', 'Cruzar com os shado-pans foi uma má ideia.', '', 19865),
(65746, 'ptBR', 'Bom trabalho. Acho que você aprendeu alguma coisa comigo.', '', 19865),
(65747, 'ptBR', '%s se enfurece por ser separado do seu Chamâmbar!', '', 19865),
(65748, 'ptBR', 'Os mogus estão atacando o templo!', '', 19865),
(65749, 'ptBR', 'Os mogus estão atacando o Templo Niuzao. Precisamos de ajuda.', '', 19865),
(65750, 'ptBR', 'Rápido, todos às armas!', '', 19865),
(65751, 'ptBR', 'Acredite em sua própria força.', '', 19865),
(65752, 'ptBR', 'Rechace-os!', '', 19865),
(65753, 'ptBR', 'Não desista!', '', 19865),
(65754, 'ptBR', 'Enquanto eu estiver de pé, este templo não cairá.', '', 19865),
(65755, 'ptBR', 'Atacar!', '', 19865),
(65756, 'ptBR', 'Rechace-os!', '', 19865),
(65757, 'ptBR', 'Acredite em sua própria força!', '', 19865),
(65758, 'ptBR', 'Seu poder é meu!', '', 19865),
(65759, 'ptBR', 'Rendam-se à minha força!', '', 19865),
(65760, 'ptBR', 'Eu mostrarei a vocês o que é FORÇA!', '', 19865),
(65761, 'ptBR', 'Eu vou despedaçar vocês!', '', 19865),
(65762, 'ptBR', 'Vocês não vencerão jamais!', '', 19865),
(65763, 'ptBR', 'Eu mostrarei a vocês o cerne do medo!', '', 19865),
(65764, 'ptBR', 'Eu sinto a fraqueza em vocês.', '', 19865),
(65765, 'ptBR', 'Espalhem-se como folhas ao vento!', '', 19865),
(65766, 'ptBR', 'Vocês não são nada.', '', 19865),
(65767, 'ptBR', 'Não. NÃO!', '', 19865),
(65768, 'ptBR', 'Eu sou invencível!', '', 19865),
(65769, 'ptBR', 'Esse não era o meu destino!', '', 19865),
(65770, 'ptBR', 'Meu poder se esvai!', '', 19865),
(65771, 'ptBR', 'Mestre, guie-me!', '', 19865),
(65772, 'ptBR', 'A tormenta arruinará vocês!', '', 19865),
(65773, 'ptBR', 'Ninguém escapa da tormenta.', '', 19865),
(65774, 'ptBR', 'Ataque!', '', 19865),
(65775, 'ptBR', 'Mestre, eu o decepcionei...', '', 19865),
(65776, 'ptBR', 'Os mantídeos cercam vocês de todos os lados.', '', 19865),
(65777, 'ptBR', 'Seu templo está em ruínas.', '', 19865),
(65778, 'ptBR', 'Seus defensores estão mortos.', '', 19865),
(65779, 'ptBR', 'Você está esquecido. É isso que você teme, não é?', '', 19865),
(65780, 'ptBR', 'Tão afastado, aqui no lado escuro da muralha.', '', 19865),
(65781, 'ptBR', 'Você está sozinho contra o poderio do enxame, um foco de luz solitário num mar de trevas.', '', 19865),
(65782, 'ptBR', 'Os seus irmãos e irmãs celestiais ajudam você? Não, não ajudam.', '', 19865),
(65783, 'ptBR', 'Se você morrer, quem iria notar?', '', 19865),
(65784, 'ptBR', 'Dê seu manto celestial para meu mascote e permita que um novo celestial tome o seu lugar!', '', 19865),
(65785, 'ptBR', 'Então não tenho escolha a não ser matar você.', '', 19865),
(65786, 'ptBR', 'Shan''ze! Hei Feng! Matem-no!', '', 19865),
(65787, 'ptBR', 'Rá! Fácil demais!', 'Rá! Fácil demais!', 19865),
(65788, 'ptBR', 'Rá! Que divertido!', 'Rá! Que divertido!', 19865),
(65789, 'ptBR', 'É hora de esmagar os inimigos.', 'É hora de esmagar os inimigos.', 19865),
(65790, 'ptBR', 'Boa luta, camarada!', 'Boa luta, camarada!', 19865),
(65791, 'ptBR', 'Vamos ver do que você é capaz!', 'Vamos ver do que você é capaz!', 19865),
(65792, 'ptBR', 'Rraaaagh!', 'Rraaaagh!', 19865),
(65793, 'ptBR', 'Tão fácil. Que decepção!', 'Tão fácil. Que decepção!', 19865),
(65794, 'ptBR', 'O cheiro da vitória!', 'O cheiro da vitória!', 19865),
(65795, 'ptBR', 'Será que você vai ser um desafio?', 'Será que você vai ser um desafio?', 19865),
(65796, 'ptBR', 'Que perda de tempo.', 'Que perda de tempo.', 19865),
(65797, 'ptBR', 'Vamos nessa!', 'Vamos nessa!', 19865),
(65798, 'ptBR', 'Honra na vitória!', 'Honra na vitória!', 19865),
(65799, 'ptBR', '', 'O quê? Não!', 19865),
(65800, 'ptBR', '', 'Isso NÃO vai acontecer.', 19865),
(65801, 'ptBR', '', 'Destruam-nos!', 19865),
(65802, 'ptBR', '', 'Eles estão caindo! Não pare!', 19865),
(65803, 'ptBR', '', 'Bom trabalho! Grande combate.', 19865),
(65804, 'ptBR', '', 'Adoro essa sensação após uma boa luta.', 19865),
(65805, 'ptBR', '', 'Vamos comemorar!', 19865),
(65806, 'ptBR', 'Mantenha-os afastados! Eles não vão vasculhar nossos segredos!', '', 19865),
(65807, 'ptBR', 'Esta luta nos é favorável.', '', 19865),
(65808, 'ptBR', 'Tome cuidado e não baixe a guarda.', '', 19865),
(65809, 'ptBR', 'Então, viveremos para lutar outro dia.', '', 19865),
(65810, 'ptBR', 'Nós não fraquejaremos.', '', 19865),
(65811, 'ptBR', 'Nós lutamos bem, mas é melhor não abusar da sorte.', '', 19865),
(65812, 'ptBR', 'Golpeie o inimigo. Eu serei seu escudo.', '', 19865),
(65813, 'ptBR', 'Nós lutamos para que outros vivam em paz.', '', 19865),
(65814, 'ptBR', 'Você luta bem. Cuidado com a confiança em demasia.', '', 19865),
(65815, 'ptBR', 'Pelos caídos!', '', 19865),
(65816, 'ptBR', 'Sua raça não irá mais derramar sangue inocente!', '', 19865),
(65817, 'ptBR', 'A batalha foi ganha.', '', 19865),
(65818, 'ptBR', 'Eu vou ficar mais tranquilo sabendo que esse aqui morreu.', '', 19865),
(65819, 'ptBR', 'Não!', '', 19865),
(65820, 'ptBR', 'Isto não pode ficar assim.', '', 19865),
(65821, 'ptBR', 'Pelos Shado-Pans!', '', 19865),
(65822, 'ptBR', 'Continuem! A vitória está ao nosso alcance.', '', 19865),
(65823, 'ptBR', 'Boa luta. Estou feliz que você tenha sobrevivido à batalha.', '', 19865),
(65824, 'ptBR', 'Fico honrado de lutar ao seu lado.', '', 19865),
(65825, 'ptBR', 'Eu parto para contemplar os que não puderam compartilhar essa vitória conosco.', '', 19865),
(65826, 'ptBR', 'Preciso de treinamento.', 'Preciso de treinamento.', 19865),
(65827, 'ptBR', 'Um novo continente repleto de segredos esquecidos! Compartilhe o que você aprender com os Andarilhos das Lendas e comigo, e eu lhe informarei sobre meus outros projetos.', 'Um novo continente repleto de segredos esquecidos! Compartilhe o que você aprender com os Andarilhos das Lendas e comigo, e eu lhe informarei sobre meus outros projetos.', 19865),
(65828, 'ptBR', 'Fale-me sobre seus outros projetos.', 'Fale-me sobre seus outros projetos.', 19865),
(65829, 'ptBR', 'Atenção, recrutas! Graças $gao:à; $p, nós iremos retomar o monte Kun-Lai dos Yaungóis e torná-lo seguro novamente. Pela Horda!', '', 19865),
(65830, 'ptBR', 'Você trabalhou bem aqui, amigo. Nós logo teremos uma base de operações forte aqui. Agora vá ver se mais alguém precisa da sua ajuda.', '', 19865),
(65831, 'ptBR', 'Pela Horda!', 'Pela Horda!', 19865),
(65832, 'ptBR', 'Recrutas, eu quero que vocês lembrem que $p salvou vocês, e que a Aliança irá salvar Kun-Lai!', '', 19865),
(65833, 'ptBR', 'Você fez um excelente trabalho. Agora poderemos manter nossa base de operações aqui sem grandes problemas.', '', 19865),
(65834, 'ptBR', 'Pela Aliança!', 'Pela Aliança!', 19865),
(65835, 'ptBR', '', 'Odeio todos vocês!', 19865),
(65836, 'ptBR', '', 'Por quê? Por que tinha que ser ele?', 19865),
(65837, 'ptBR', '', 'Terei minha justiça!', 19865),
(65838, 'ptBR', '', 'Morte por morte!', 19865),
(65839, 'ptBR', '', 'Não se esqueça de falar com Fei Li antes de partir. Você achará as habilidades dela bastante úteis contra os inimigos.', 19865),
(65840, 'ptBR', 'Você está muito mais forte do que eu esperava.', 'Você está muito mais forte do que eu esperava.', 19865),
(65841, 'ptBR', 'Se você precisar de cura na batalha, fale comigo.', 'Se você precisar de cura na batalha, fale comigo.', 19865),
(65842, 'ptBR', 'Seria uma honra lutar junto a você.', 'Seria uma honra lutar junto a você.', 19865),
(65843, 'ptBR', 'Confie no poder da Imperatriz. Ela nos levará à glória!', '', 19865),
(65844, 'ptBR', 'Juntos, o enxame se erguerá mais alto que qualquer império desta terra!', '', 19865),
(65845, 'ptBR', 'A vontade da Imperatriz é a nossa vontade. A grandeza d''Ela é a nossa grandeza. A vitória d''Ela é uma vitória do enxame!', '', 19865),
(65846, 'ptBR', 'Você ousa desafiar a voz da Imperatriz? O que a voz fala, o enxame escuta!', '', 19865),
(65847, 'ptBR', 'Blasfêmia! Você não faz parte do enxame!', '', 19865),
(65848, 'ptBR', 'Você é apenas um contra a fúria divina da Imperatriz! Você também fracassará!', '', 19865),
(65849, 'ptBR', 'O enxame é a lâmina que cortará nossos inimigos!', '', 19865),
(65850, 'ptBR', 'Um só corte bastará.', '', 19865),
(65851, 'ptBR', 'Nossos inimigos cairão sob nossas lâminas!', '', 19865),
(65852, 'ptBR', 'Você quer testar o fio da minha lâmina?', '', 19865),
(65853, 'ptBR', 'Eu sinto o cheiro de desobediência Klaxxi! Pare de correr e encare o Senhor das Lâminas!', '', 19865),
(65854, 'ptBR', 'Ahahahahah... era para doer?', '', 19865),
(65855, 'ptBR', 'O vento frio sopra. A hora do Enxame começou!', '', 19865),
(65856, 'ptBR', 'Eles acham que uma muralha irá nos deter? Eles acreditam que pedra pode deter os que cavalgam o vento?', '', 19865),
(65857, 'ptBR', 'O enxame escurecerá o céu com nossas tropas! Nós traremos a noite eterna para estas terras!', '', 19865),
(65858, 'ptBR', 'Infiltrador! Vocês não conseguirão deter o enxame!', '', 19865),
(65859, 'ptBR', 'Voando pra longe, pequeno cavaleiro? Um campeão de verdade me enfrentaria no coração do medo!', '', 19865),
(65860, 'ptBR', 'Uma tentativa lamentável.', '', 19865),
(65861, 'ptBR', 'Sim, meus monstrinhos! Vão! Atirem-se contra nossos inimigos!', '', 19865),
(65862, 'ptBR', 'O próximo estágio de meu experimento se inicia!', '', 19865),
(65863, 'ptBR', 'Ahh, se eu te pego! Você daria uma ótima cobaia!', '', 19865),
(65864, 'ptBR', 'Auuugghhh! Isso doeu!', '', 19865),
(65865, 'ptBR', 'Estão...com medo?', '', 19865),
(65866, 'ptBR', 'A ilha está infestada com os servos da Imperatriz.', '', 19865),
(65867, 'ptBR', 'Não vai ser uma luta fácil.', '', 19865),
(65868, 'ptBR', 'A Imperatriz deve ser levada à justiça.', '', 19865),
(65869, 'ptBR', 'Não tenha medo.', '', 19865),
(65870, 'ptBR', 'O medo é uma ilusão.', '', 19865),
(65871, 'ptBR', 'Avante, combatente!', '', 19865),
(65872, 'ptBR', 'Atacar!', '', 19865),
(65873, 'ptBR', 'Pelo enxame!', '', 19865),
(65874, 'ptBR', 'A justiça prevalecerá.', '', 19865),
(65875, 'ptBR', 'Ela deve responder por seus crimes.', '', 19865),
(65876, 'ptBR', 'Você fez bem, andarilh$go:a; da muralha.', '', 19865),
(65877, 'ptBR', 'Você é mais valente do que parece, estranh$go:a;', '', 19865),
(65878, 'ptBR', 'Não deixe o medo consumir você!', '', 19865),
(65879, 'ptBR', 'Não podemos permitir que eles destruam essa árvore.', '', 19865),
(65880, 'ptBR', 'Não podemos permitir que eles destruam essa árvore. É a última de seu tipo.', '', 19865),
(65881, 'ptBR', 'A guerra não acabou, mas eles sofreram um golpe amargo.', '', 19865),
(65882, 'ptBR', 'Não se meta com um Klaxxi.', '', 19865),
(65883, 'ptBR', 'Ahhh, olha quem resolveu aparecer.', '', 19865),
(65884, 'ptBR', 'Vejo que os paragões finalmente chegaram para salvar o dia.', '', 19865),
(65885, 'ptBR', 'Vocês são relíquias ancestrais de outrora!', '', 19865),
(65886, 'ptBR', 'O que você pode fazer contra o poderio do enxame?', '', 19865),
(65887, 'ptBR', 'Tão poucos. Tão fracos.', '', 19865),
(65888, 'ptBR', 'O enxame consumira você!', '', 19865),
(65889, 'ptBR', 'Tenha medo de mim!', '', 19865),
(65890, 'ptBR', 'Aterrorizante, não é mesmo?', '', 19865),
(65891, 'ptBR', 'Você está... com medo?', '', 19865),
(65892, 'ptBR', 'Eis o poder do enxame!', '', 19865),
(65893, 'ptBR', 'Junte-se a nós!', '', 19865),
(65894, 'ptBR', 'Estou... sozinho.', '', 19865),
(65895, 'ptBR', 'Não. NÃO!', '', 19865),
(65896, 'ptBR', 'Não foi... suficiente...', '', 19865),
(65897, 'ptBR', 'Imperatriz... eu... falhei com a Senhora...', '', 19865),
(65898, 'ptBR', 'Serei vingado!', '', 19865),
(65901, 'ptBR', 'Seja lá quem foi que disse preferir acender uma vela a amaldiçoar a escuridão...$b$bBem, provavelmente ainda não acendeu tantas velas quanto eu.', '', 19865),
(65902, 'ptBR', 'Pode me dar um rabanete vermelho?', 'Pode me dar um rabanete vermelho?', 19865),
(65903, 'ptBR', 'Você tem algum Melão-do-lago Doce sobrando?', 'Você tem algum Melão-do-lago Doce sobrando?', 19865),
(65904, 'ptBR', 'Poderia me dar um pêssego aveludado para Ella?', 'Poderia me dar um pêssego aveludado para Ella?', 19865),
(65905, 'ptBR', 'Você tem alguma Cereja-negra?', 'Você tem alguma Cereja-negra?', 19865),
(65906, 'ptBR', '', 'Ahhhh droga, eu ia comer! Bem, se Ella precisa deles, eu não vou comer mais. Aqui, leva isso!', 19865),
(65907, 'ptBR', 'Um rabanete para a querida Ella? Bem, é claro que posso arrumar um. Aqui está.', '', 19865),
(65908, 'ptBR', 'A pequena Ella tá tentando fazer cerveja? Estou curioso! Desejo sorte a ela. Fazer cerveja não é algo que um novato pode fazer assim, de supetão. De qualquer forma, eu posso arrumar um Melão-do-lago para ela.', '', 19865),
(65909, 'ptBR', '', 'Eu ia cobrar uma grana boa por esse pêssego, mas a Ella é uma ótima cliente no meu mercado, então ele será por conta da casa. Só dessa vez, tá ouvindo?', 19865),
(65910, 'ptBR', '', 'Dizem: "Vire seu rosto para o sol, e as sombras ficarão atrás de você".$b$bEspero que você encontre dias de sol pela frente, $n!', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(65911, 'ptBR', 'Uau! Issssso tá uma dilíííííshia! Onde conshigo maish?', '', 19865),
(65912, 'ptBR', 'Hmmm, isso tá ótimo! ÓTIMO! É a melhor coisa que experimentei em um bom tempo. Quem fez?', '', 19865),
(65913, 'ptBR', 'Humm, isso está muito gostoso, $n. Não me importaria em tomar outra rodada... ou duas... hic!', '', 19865),
(65914, 'ptBR', '', 'Hummm, não provo uma cerveja com essa complexidade e clareza desde... bem... desde a época de ouro da Cervejaria Malte do Trovão! Quem quer que a tenha feito tem um verdadeiro talento.', 19865),
(65915, 'ptBR', 'Sua perícia em culinária só é tão avançada quanto seu Caminho mais desenvolvido.', 'Sua perícia em culinária só é tão avançada quanto seu Caminho mais desenvolvido.', 19865),
(65916, 'ptBR', 'Hummmm. Mmmmmmm..... Isso está... simplesmente... incrível. Sua amiga Ella é muito talentosa! Diga a ela para falar com meu Tio Gao na Cervejaria. Acho que ela encontrou um novo lar conosco, os Malte do Trovão.', '', 19865),
(65917, 'ptBR', '<Mishi olha para você com preocupação.>', '', 19865),
(65918, 'ptBR', '<Mishi fica intrigada com suas ações.>', '', 19865),
(65919, 'ptBR', '<Mishi se pergunta o que você está fazendo.>', '', 19865),
(65920, 'ptBR', '<Mishi vira o rosto com curiosidade na sua direção.>', '', 19865),
(65921, 'ptBR', '<Mishi observa você.>', '', 19865),
(65922, 'ptBR', '<Mishi está muito feliz com você!>', '', 19865),
(65923, 'ptBR', '<Mishi salta para cima e para baixo com empolgação.>', '', 19865),
(65924, 'ptBR', '<Mishi sorri para você.>', '', 19865),
(65925, 'ptBR', '<Mishi salta para cima e para baixo com alegria.>', '', 19865),
(65926, 'ptBR', '<Mishi está feliz!>', '', 19865),
(65927, 'ptBR', 'Mande um Soco Apimentado para derrubar os hozens do carrinho!', 'Mande um Soco Apimentado para derrubar os hozens do carrinho!', 19865),
(65928, 'ptBR', 'Mande um Soco Apimentado nos hozens que pulam no carrinho!', 'Mande um Soco Apimentado nos hozens que pulam no carrinho!', 19865),
(65929, 'ptBR', 'Ufa! Daqui pra frente as coisas devem ficar mais fáceis!', 'Ufa! Daqui pra frente as coisas devem ficar mais fáceis!', 19865),
(65930, 'ptBR', 'Isso é o mais perto que qualquer estrangeiro já chegou do Engenho de Nalak''sha!', '', 19865),
(65931, 'ptBR', 'Parece que conseguimos! Estamos salvos!', 'Parece que conseguimos! Estamos salvos!', 19865),
(65932, 'ptBR', 'Eles se foram! ufa! parece que o caminho está limpo.', 'Eles se foram! ufa! parece que o caminho está limpo.', 19865),
(65933, 'ptBR', 'Nós conseguimos! O caminho deve estar livre agora.', 'Nós conseguimos! O caminho deve estar livre agora.', 19865),
(65934, 'ptBR', 'Grande sorte-sim! O que é AQUILO?', 'Grande sorte-sim! O que é AQUILO?', 19865),
(65935, 'ptBR', 'Oh, dia mais azarado de todos! O que é AQUILO?', 'Oh, dia mais azarado de todos! O que é AQUILO?', 19865),
(65936, 'ptBR', 'Nós temos que - oh, dia mais azarado de todos! O que é AQUILO?', 'Nós temos que - oh, dia mais azarado de todos! O que é AQUILO?', 19865),
(65937, 'ptBR', 'Auuughhh! Tem yeti na pista!', 'Auuughhh! Tem yeti na pista!', 19865),
(65938, 'ptBR', 'Auuughhh! Tem yeti na pista! Vai, iaque, rápido, rápido!', 'Auuughhh! Tem yeti na pista! Vai, iaque, rápido, rápido!', 19865),
(65939, 'ptBR', 'Auuughhh! Tem yeti na pista! Parece que ainda não estamos salvos!', 'Auuughhh! Tem yeti na pista! Parece que ainda não estamos salvos!', 19865),
(65940, 'ptBR', 'Os segredos morrerão com você.', '', 19865),
(65941, 'ptBR', 'Estamos a caminho do Festival do Andarilho. Você devia se unir a nós!', 'Estamos a caminho do Festival do Andarilho. Você devia se unir a nós!', 19865),
(65942, 'ptBR', 'O Festival do Andarilho é essa noite. Você vem?', 'O Festival do Andarilho é essa noite. Você vem?', 19865),
(65943, 'ptBR', 'O que é o Festival do Andarilho?', 'O que é o Festival do Andarilho?', 19865),
(65944, 'ptBR', 'Diz a lenda que, um belo dia, Liu Lang saiu para explorar os mares além de Pandária nas costas de uma tartaruga gigante. A cada cinco anos, Liu Lang voltava, sempre buscando novos exploradores para acompanhá-lo nas viagens. Até hoje, sempre que vemos um pandaren sonhando acordado ou contemplando o céu, perguntamos se ele está "esperando a tartaruga”.$b$bA maioria dos pandarens não é muito aventureira – eles gostam de ficar perto do lar e da lareira. Mas alguns de nós ainda são sonhadores... Hoje nós nos reunimos na Praia da Tartaruga, na costa ao sul, para contemplar o mar e celebrar o espírito aventureiro de Liu Lang.$b$bÉ o chamado Festival do Andarilho.', 'Diz a lenda que, um belo dia, Liu Lang saiu para explorar os mares além de Pandária nas costas de uma tartaruga gigante. A cada cinco anos, Liu Lang voltava, sempre buscando novos exploradores para acompanhá-lo nas viagens. Até hoje, sempre que vemos um pandaren sonhando acordado ou contemplando o céu, perguntamos se ele está "esperando a tartaruga”.$b$bA maioria dos pandarens não é muito aventureira – eles gostam de ficar perto do lar e da lareira. Mas alguns de nós ainda são sonhadores... Hoje nós nos reunimos na Praia da Tartaruga, na costa ao sul, para contemplar o mar e celebrar o espírito aventureiro de Liu Lang.$b$bÉ o chamado Festival do Andarilho.', 19865),
(65945, 'ptBR', 'Este é o Festival do Andarilho, $n! Onde os pandarens com espírito aventureiro se reúnem para celebrar o primeiro explorador a se aventurar além das brumas.$b$bÉ um momento de contemplação e canções. Agradeço por se juntar a nós!', 'Este é o Festival do Andarilho, $n! Onde os pandarens com espírito aventureiro se reúnem para celebrar o primeiro explorador a se aventurar além das brumas.$b$bÉ um momento de contemplação e canções. Agradeço por se juntar a nós!', 19865),
(65946, 'ptBR', 'O que está acontecendo aqui?', 'O que está acontecendo aqui?', 19865),
(65947, 'ptBR', '', 'Saudações, $n!$b$bEsse é o "Festival do Andarilho", onde nós celebramos os feitos do primeiro pandaren explorador, e nos reunimos na praia para contemplar o mar.$b$bHouve um tempo em que as brumas que pairavam sobre Pandária eram tão espessas que você algumas vezes não conseguia ver nem mesmo aquela pedra imensa bem ali na costa. Agora olhe só, que noite linda! Estou feliz por você estar aqui para ver.', 19865),
(65948, 'ptBR', '', 'Andarilho das Lendas Cho! Estou tão feliz por você estar se juntando a nós essa semana.', 19865),
(65949, 'ptBR', '', 'Você pode cantar a Canção de Liu Lang para nós?', 19865),
(65950, 'ptBR', '', 'Sua voz é muito bonita. Algumas vezes eu pude jurar que ouvi uma orquestra inteira!', 19865),
(65951, 'ptBR', '', 'Obrigada, Andarilho das Lendas!', 19865),
(65952, 'ptBR', '$n! Estou deliciado em ver que você está celebrando o Festival do Andarilho conosco!$b$bDizem que os pandarens não são do tipo aventureiro. Mas olha só esses rostos – ah, você vê? Os olhos brilhantes dos sonhadores!$b$bEu devia saber que, algum dia, em breve, haveriam muitos pandarens aventureiros para se comentar, fazendo a diferença por todo o mundo. Você não acha?', '', 19865),
(65953, 'ptBR', 'Aqui está uma surpresa de verdade para você. O que você acha que eles estão celebrando? E qual você acha que deveria ser a bebida adequada para brindar a ocasião?', '', 19865),
(65954, 'ptBR', '', 'Uau, incrível! Olhe todas essa luzes!$b$bO que você acha que está acontecendo? Quem é o cara na tartaruga?$b$bPeraaaaaaíííí – é o Liu Lang$b$bAquela tartaruga deve ser o Shen-zin Su. ELE MESMO! Aquela estátua é de uma mini Ilha Errante!$b$bEstamos em casa, Tio Chen!$b$bBem, mais ou menos.', 19865),
(65955, 'ptBR', 'Desvie ou destrua os Totens da Tempestade de Gash''nul.', '', 19865),
(65956, 'ptBR', '%s foi desmontado do cavalga-vento.', '', 19865),
(65957, 'ptBR', 'Ba-Bam ainda tá de pé Bumbando Cerveja!', '', 19865),
(65958, 'ptBR', 'Dança feito macaco!', '', 19865),
(65959, 'ptBR', 'Eiaaarr! Eu tenho cerveja.', '', 19865),
(65960, 'ptBR', 'Fedentinho tá cozinhando e fazendo cerveja!', '', 19865),
(65961, 'ptBR', 'Baga Baga vai esquentar a festa!', '', 19865),
(65962, 'ptBR', 'Eu gostaria de treinar jogar bola com um bebê serpente.', 'Eu gostaria de treinar jogar bola com um bebê serpente.', 19865),
(65963, 'ptBR', '', 'Parece que você já está brincando com a sua serpente, $n. Mas você só pode fazer isso com uma serpente por vez.$b$bTermine a sessão de treinamento atual antes de praticar com outra serpente.', 19865),
(65964, 'ptBR', 'Terminei de treinar. Pegue sua serpentinha de volta.', 'Terminei de treinar. Pegue sua serpentinha de volta.', 19865),
(65965, 'ptBR', 'Esse lugar é muito limpinho. Não sei se gosto daqui. Parece que falta um cheiro de "alguém viveu aqui".', '', 19865),
(65966, 'ptBR', 'Vasculhe a ilha e encontre cerveja para o caldeirão de Bô! Mas deixe alguém perto para defender Bô!', 'Vasculhe a ilha e encontre cerveja para o caldeirão de Bô! Mas deixe alguém perto para defender Bô!', 19865),
(65967, 'ptBR', 'Lance a Bola Saltitante à sua serpente e veja quanto tempo você consegue mantê-la no ar! Quando terminar de brincar, fale comigo e pegarei sua serpente. Boa sorte!', 'Lance a Bola Saltitante à sua serpente e veja quanto tempo você consegue mantê-la no ar! Quando terminar de brincar, fale comigo e pegarei sua serpente. Boa sorte!', 19865),
(65968, 'ptBR', 'Bem, como fui? Bem, espero...', 'Bem, como fui? Bem, espero...', 19865),
(65969, 'ptBR', 'Consertando', 'Consertando', 19865),
(65970, 'ptBR', '', 'Filhos de Pandária. A névoa desvaneceu. Para o bem ou mal, nossa terra está aberta para todos.', 19865),
(65971, 'ptBR', '', 'Vamos nos unir e reconstruir este lugar sagrado. O primeiro passo para curarmos nosso mundo maculado pela guerra.', 19865),
(65972, 'ptBR', 'Eu tenho fé em nossos amigos do outro lado da névoa.', '', 19865),
(65973, 'ptBR', 'Ah... A força deles é uma inspiração... e muito necessária. Temos que acreditar que seus corações sejam puros.', '', 19865),
(65974, 'ptBR', 'Só... mais... um!', '', 19865),
(65975, 'ptBR', 'Aliança... perto...', '', 19865),
(65976, 'ptBR', 'Que minha força seja a sua força. Avance e destrua seus inimigos!', '', 19865),
(65977, 'ptBR', 'Meus feromônios serão úteis ao cuidar de vários inimigos ao mesmo tempo.', '', 19865),
(65978, 'ptBR', 'Vá em frente e ative essa coisa.', 'Vá em frente e ative essa coisa.', 19865),
(65979, 'ptBR', '', 'Não, não, não tente se levantar. Sua guerra não está aqui, você precisa descansar', 19865),
(65980, 'ptBR', '|TInterface\\Icons\\ability_warlock_soulsiphon:20|t%s começa a lançar |cFFFF0000|Hspell:126299|h[Liberar Almas]|h|r! Pule pra água!', '', 19865),
(65981, 'ptBR', 'A arquitetura aqui é estranha, diferindo de muitas formas dos designs tradicionais dos mogus. Essa sala parece ser algum tipo de dispositivo, mas não vejo nada sobre o propósito dela nas minhas anotações. \n$bSó vamos descobrir o que é isso ativando o objeto e observando.\n$bO que poderia acontecer de tão ruim?', '', 19865),
(65982, 'ptBR', 'Estamos voando na névoa há horas, General. A tripulação está... ficando inquieta.', '', 19865),
(65983, 'ptBR', 'Volte ao posto, soldado! Vamos encontrar essa terra ou morrer tentando.', '', 19865),
(65984, 'ptBR', 'Nave da Aliança! A bombordo!', '', 19865),
(65985, 'ptBR', 'Atacar!', '', 19865),
(65986, 'ptBR', 'Nave inimiga a estibordo! Preparar para atirar! Fogo!', '', 19865),
(65987, 'ptBR', '|TInterface\\Icons\\ability_warrior_charge.blp:20|t%s põe os olhos em |cFFFF0000$n|r e começa a lançar |cFFFF0000|Hspell:127245|h[Golpe Fatal]|h|r! Saia daí!', '', 19865),
(65988, 'ptBR', 'Horda... aqui...', '', 19865),
(65989, 'ptBR', 'Hahahaha! Atingiu em cheio! Vai afundar!', '', 19865),
(65990, 'ptBR', 'Terra à vista!', '', 19865),
(65991, 'ptBR', 'Este recinto pulsa de energia, mas é diferente de tudo que já vi.', '', 19865),
(65992, 'ptBR', 'Fascinante, nunca ouvi histórias de nada parecido. Os mogus sabem esconder bem seus segredos.', '', 19865),
(65993, 'ptBR', 'Isso parece um terminal que controla o dispositivo. Vamos ver...', '', 19865),
(65994, 'ptBR', 'Mais estranhos estão aparecendo em nossas praias todos os dias.$b$bEsse grupo ainda estava tentando acertar uns aos outros até ontem à noite. Espero que não seja um sinal do que está por vir.', 'Mais estranhos estão aparecendo em nossas praias todos os dias.$b$bEsse grupo ainda estava tentando acertar uns aos outros até ontem à noite. Espero que não seja um sinal do que está por vir.', 19865),
(65995, 'ptBR', 'Uhh, tem alguma coisa errada, General... Nós estamos perdendo altitude, e rápido!', '', 19865),
(65996, 'ptBR', 'Sensores ativos. Todos os núcleos operando em eficiência máxima.', '', 19865),
(65997, 'ptBR', 'Ativando', 'Ativando', 19865),
(65998, 'ptBR', 'Erro de pareamento de identificação da matriz. Entidades desconhecidas detectadas.', '', 19865),
(65999, 'ptBR', '%s lança |cFFFF0000|Hspell:116529|h[Reduzir Potência]|h|r!', '', 19865),
(66000, 'ptBR', 'Magnífico! Ele fala! Isso é muito mais do que esperávamos dos mogus.', '', 19865),
(66001, 'ptBR', 'Ai, ai... Isso pode se complicar. Vou ficar observando... de uma distância segura.', '', 19865),
(66002, 'ptBR', 'Você precisa de algo?', '', 19865),
(66003, 'ptBR', 'Caçaremos nossos inimigos.', '', 19865),
(66004, 'ptBR', '', 'Serei a lâmina na garganta de nossos inimigos.', 19865),
(66005, 'ptBR', 'A máquina foi destruída, e assim o poder dos mogus se enfraquece.', '', 19865),
(66006, 'ptBR', '', 'Ninguém resistirá aos Shado-Pan', 19865),
(66007, 'ptBR', 'Esses discos me parecem familiares, mas não sei de onde vêm.', '', 19865),
(66008, 'ptBR', 'Eles me chamam, os discos... Preciso...', '', 19865),
(66009, 'ptBR', 'Eu... vejo tudo claramente agora.', '', 19865),
(66010, 'ptBR', 'Os titãs...? Parece que os mogus recuperaram tecnologias titânicas ancestrais para expandir seu império!', '', 19865),
(66011, 'ptBR', 'Temos que ir, ainda não acabamos.', '', 19865),
(66012, 'ptBR', 'Tenwu da Fumaça Vermelha cumprimenta você.', '', 19865),
(66013, 'ptBR', 'Os inimigos dos Shado-Pan cairão diante de Tenwu da Fumaça Vermelha!', '', 19865),
(66014, 'ptBR', 'Mantenha os arqueiros fora da muralha. Raigonn tem que chegar ao portão.', '', 19865),
(66015, 'ptBR', 'Aqui... experimente isso.', '', 19865),
(66016, 'ptBR', 'Ah, sim. Hrm. Me... desculpe se isso não agradou...', '', 19865),
(66017, 'ptBR', 'Ela deve ser uma pilha de ossos e gosma! Mas com o estômago forte, com certeza...', '', 19865),
(66018, 'ptBR', 'Existem duas grandes disciplinas entre o nosso povo. Os Tushuis são pacientes, pensativos e ponderados. Os Huojin são ferozes, ativos e ativos. Ambas disciplinas nos servem da sua própria maneira, e não poderiam existir de maneira eficiente sem a outra.', '', 19865),
(66019, 'ptBR', 'Busco, mais que tudo, ajudar os jovens pandarens a explorar o potencial deles nessas terras. A verdadeira maestria vem com o tempo e a prática, mas há valor mesmo ao encontrar os primeiros passos de um caminho adequado.', '', 19865),
(66020, 'ptBR', 'Meu... pai...', '', 19865),
(66021, 'ptBR', '', 'Ah, claro.', 19865),
(66022, 'ptBR', '', 'Encontre força na paciência.', 19865),
(66023, 'ptBR', '', 'Uau! Uh, é... interessante!', 19865),
(66024, 'ptBR', 'Quem comanda este enxame? Apareça! Responda aos Klaxxi.', '', 19865),
(66025, 'ptBR', 'Fale seu nome, marionete, para que nossos anais fiquem completos.', '', 19865),
(66026, 'ptBR', 'Sua "Imperatriz" caiu. Os Klaxxi já pronunciaram seu julgamento. Afaste-se ou será varrido daqui.', '', 19865),
(66027, 'ptBR', 'Blasfêmia!', '', 19865),
(66028, 'ptBR', '', 'Apenas a mente equilibrada está realmente preparada para enfrentar qualquer provação.', 19865),
(66029, 'ptBR', '', 'Somente uma mente em paz pode preparar totalmente um corpo para a batalha.', 19865),
(66030, 'ptBR', '', 'Você está fascinado pelas maravilhas da metalurgia? A arte da fundição? A beleza da mistura de metais e ligas?', 19865),
(66031, 'ptBR', '<cof><cof> Eu... retornei.', '', 19865),
(66032, 'ptBR', 'Mantenham os cintos de segurança afivelados... brincadeira, a gente nem tem cinto de segurança.', 'Mantenham os cintos de segurança afivelados... brincadeira, a gente nem tem cinto de segurança.', 19865),
(66033, 'ptBR', 'Nós já chegamos, yeti?', 'Nós já chegamos, yeti?', 19865),
(66034, 'ptBR', 'Arauto, seus feitos conquistaram a confiança dos Klaxxi.', '', 19865),
(66035, 'ptBR', 'Espero que esse iaque saiba o caminho até o topo da montanha, porque eu não sei!', 'Espero que esse iaque saiba o caminho até o topo da montanha, porque eu não sei!', 19865),
(66036, 'ptBR', 'Esta é sua primeira viagem ao Neverest? A minha também!', 'Esta é sua primeira viagem ao Neverest? A minha também!', 19865),
(66037, 'ptBR', '', 'Entendo que a mente dos Tushui não é o único caminho para a sabedoria, mas ainda existem escolhas que não devem ser aceitas. Riscos que são muitos perigosos para serem levados em consideração. Decisões que não posso perdoar...$b$bChegou a hora de eu deixar Shen-zin Su. Tenho muito respeito por Delora Coração de Leão pela sua confiança e valor, e suas histórias da Aliança falam bem do povo dela. Ainda não sei se encontrarei um lar ali, mas para onde meu caminho levar, vou encontrar uma forma de ajudar o mundo além dessa ilha.$b$bApesar de tudo, gostei do pouco tempo que estivemos juntos, $n. Espero que você possa se unir a mim, mas compreendo que sua decisão não é fácil.', 19865),
(66038, 'ptBR', 'Você merece uma recompensa. Venha comigo.', '', 19865),
(66039, 'ptBR', 'Imagino quanta neve resta no Neverest... Entendeu? Hein, sacou?', 'Imagino quanta neve resta no Neverest... Entendeu? Hein, sacou?', 19865),
(66040, 'ptBR', 'Nós mantídeos somos uma raça ancestral. Os pandarens com quem você se associa não passam de crianças. Eles têm um papel a cumprir.', '', 19865),
(66041, 'ptBR', 'A cada ciclo, nossos filhos enxameiam suas muralhas. Os pandarens matam os fracos. Os fortes retornam.', '', 19865),
(66042, 'ptBR', 'A cada geração, ficamos mais fortes.', '', 19865),
(66043, 'ptBR', 'Hmm, é, talvez eu devesse ter mandado o carrinho pra revisão mesmo.', 'Hmm, é, talvez eu devesse ter mandado o carrinho pra revisão mesmo.', 19865),
(66044, 'ptBR', 'Antes da sua história começar, nosso império era vasto. Nós compartilhávamos este mundo com nossos reinos irmãos, Ahn''Qiraj e Azjol-Nerub.', '', 19865),
(66045, 'ptBR', 'Nossos deuses eram muitos, e poderosos. Nós mantídeos adorávamos as sete cabeças de Y''shaarj.', '', 19865),
(66046, 'ptBR', 'O Antigo era grandioso e terrível era Sua fúria. Ele consumia a esperança e gerava desespero. Ele inalava coragem e exalava medo.', '', 19865),
(66047, 'ptBR', 'Quando os usurpadores chegaram – os seus "Titãs" – Y''shaarj foi destruído.', '', 19865),
(66048, 'ptBR', 'Seu último e terrível sopro de vida assombrou esta terra desde então, mas as sombras que ele deixou para trás são meros sussurros de sua antiga glória.', '', 19865),
(66049, 'ptBR', 'Eu digo a você agora, pois você mereceu este aviso.', '', 19865),
(66050, 'ptBR', 'Seus deuses não são nossos deuses, forasteir$go:a;.', '', 19865),
(66051, 'ptBR', 'Se os Antigos um dia retornarem, nós mantídeos mais uma vez estaremos ao lado Deles.', '', 19865),
(66052, 'ptBR', 'Os mais sábios entre vocês farão o mesmo.', '', 19865),
(66053, 'ptBR', 'Isto é tudo o que tenho a dizer. Venha, aceite sua recompensa. E lembre-se do que você aprendeu hoje.', '', 19865),
(66054, 'ptBR', 'A quantidade de tempo que ela passa praticando parece excessiva... Mas, os resultados, não posso ignorar. O físico dela é belíssimo.', '', 19865),
(66055, 'ptBR', '', 'Minha família lapida jade e gemas há quase dez gerações. Você pode se surpreender com o que posso lhe ensinar.', 19865),
(66056, 'ptBR', '', 'Eu admito, aquilo me pareceu muito divertido!', 19865),
(66057, 'ptBR', '', 'E acho que você fez uma nova amizade.', 19865),
(66058, 'ptBR', '', 'Aquele foi brabo...', 19865),
(66059, 'ptBR', 'Martelo e tenazes. Martelo e tenazes. O dia inteiro é martelo e tenazes.', '', 19865),
(66060, 'ptBR', 'Tem alguns curandeiros debaixo dos destroços! Liberte-os!', '', 19865),
(66061, 'ptBR', 'Encontre os curandeiros e liberte-os! Precisamos deles aqui na ferida!', '', 19865),
(66062, 'ptBR', 'Fique por perto e mantenha os curandeiros a salvo! Nossas vidas dependem disso.', '', 19865),
(66063, 'ptBR', 'Se perdermos os curandeiros, Shen-zin Su morrerá, e todos nós com ele. Mantenham-nos a salvo!', '', 19865),
(66064, 'ptBR', 'Venha! A Horda nos aguarda!', '', 19865),
(66065, 'ptBR', 'Vamos descobrir do que esse “chefe guerreiro” é feito.', '', 19865),
(66066, 'ptBR', 'Juntos, podemos usar o poderio da Horda para fazer um mundo melhor!', '', 19865),
(66067, 'ptBR', '|TInterface\\Icons\\warrior_talent_icon_lambstotheslaughter.blp:20|tVocê está |cFFFF0000|Hspell:127275|h[Marcad$go:a; para Execução]|h|r!', '', 19865),
(66068, 'ptBR', '', '<Aysa parece estar totalmente absorta nos exercícios dela.>', 19865),
(66069, 'ptBR', 'Ah! Um sorte-sim veio aprender? Tenho muitas habilidades a ensinar.', '', 19865),
(66070, 'ptBR', '|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s começa a lançar |cFFFF0000|Hspell:124967|h[Extrair Poder]|h|r!', '', 19865),
(66071, 'ptBR', '|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s começa a lançar |cFFFF0000|Hspell:119360|h[Extrair Poder]|h|r!', '', 19865),
(66072, 'ptBR', '', 'Ah! Um fã de poções? Os cervejeiros trabalham suas misturas, mas muitas vezes perdem suas melhores notas para uma poção ou medicamento.', 19865),
(66073, 'ptBR', 'Você quer Wikky?', 'Você quer Wikky?', 19865),
(66074, 'ptBR', 'Cê tá cas laricas?', 'Cê tá cas laricas?', 19865),
(66075, 'ptBR', 'Por que você chama Wikky?', 'Por que você chama Wikky?', 19865),
(66076, 'ptBR', 'O que cê quer?', 'O que cê quer?', 19865),
(66077, 'ptBR', 'Wikky ouve assobio!', 'Wikky ouve assobio!', 19865),
(66078, 'ptBR', 'Por que você acorda Wikky?', 'Por que você acorda Wikky?', 19865),
(66079, 'ptBR', 'Wikky tá aqui!', 'Wikky tá aqui!', 19865),
(66080, 'ptBR', 'Mas que caca que cê qué?', 'Mas que caca que cê qué?', 19865),
(66081, 'ptBR', 'Wikky é prestativo!', 'Wikky é prestativo!', 19865),
(66082, 'ptBR', 'O que você quer com Wikky?', 'O que você quer com Wikky?', 19865),
(66083, 'ptBR', 'Busque comida pra mim, Wikky!', 'Busque comida pra mim, Wikky!', 19865),
(66084, 'ptBR', 'Wikky volta logo!', 'Wikky volta logo!', 19865),
(66085, 'ptBR', 'Você Fedô!', 'Você Fedô!', 19865),
(66086, 'ptBR', 'Wikky encontra presentes!', 'Wikky encontra presentes!', 19865),
(66087, 'ptBR', '', 'Só porque você colocou mágica em um artefato não significa que ela tem que ficar nele.', 19865),
(66088, 'ptBR', 'Wikky voltou!', 'Wikky voltou!', 19865),
(66089, 'ptBR', 'É, é melhor você correr!', '', 19865),
(66090, 'ptBR', 'Wikky traz presentes!', 'Wikky traz presentes!', 19865),
(66091, 'ptBR', 'Wikky faz o que você pede!', 'Wikky faz o que você pede!', 19865),
(66092, 'ptBR', 'Eu vou esganar vocês, seus moleques cretinos!', '', 19865),
(66093, 'ptBR', 'Wikky é prestativo! Viu??', 'Wikky é prestativo! Viu??', 19865),
(66094, 'ptBR', 'Vou transformar você em comida de florzinha!', 'Vou transformar você em comida de florzinha!', 19865),
(66095, 'ptBR', 'Casco Negro vai transformar você em pó!', 'Casco Negro vai transformar você em pó!', 19865),
(66096, 'ptBR', 'Sintam a força dos Yaungóis!', 'Sintam a força dos Yaungóis!', 19865),
(66097, 'ptBR', 'Estou vendo tudo vermelho!', 'Estou vendo tudo vermelho!', 19865),
(66098, 'ptBR', 'Você acordou o touro, agora aguenta a tourada!', 'Você acordou o touro, agora aguenta a tourada!', 19865),
(66099, 'ptBR', 'DAK VAI PARTIR VOCÊ AO MEIO!', 'DAK VAI PARTIR VOCÊ AO MEIO!', 19865),
(66100, 'ptBR', 'Meu tempo com os Shado-Pans me ensinou muitos segredos. Talvez você tenha conquistado o direito de aprender alguns também.', '', 19865),
(66101, 'ptBR', 'Você! O que você está fazendo aqui?', 'Você! O que você está fazendo aqui?', 19865),
(66102, 'ptBR', 'A noite é escura e selvagem.', 'A noite é escura e selvagem.', 19865),
(66103, 'ptBR', 'Eu arrancarei a carne dos seus ossos!', 'Eu arrancarei a carne dos seus ossos!', 19865),
(66104, 'ptBR', 'Eu banirei você para a terra do vento e dos fantasmas!', 'Eu banirei você para a terra do vento e dos fantasmas!', 19865),
(66105, 'ptBR', 'Sinta o punho das trevas!', 'Sinta o punho das trevas!', 19865),
(66106, 'ptBR', 'Seu fim está próximo.', 'Seu fim está próximo.', 19865),
(66107, 'ptBR', 'As trevas chegam.', 'As trevas chegam.', 19865),
(66108, 'ptBR', 'Suas almas serão MINHAS!', 'Suas almas serão MINHAS!', 19865),
(66109, 'ptBR', 'Quebre-os.', 'Quebre-os.', 19865),
(66110, 'ptBR', 'Você sentirá dor.', 'Você sentirá dor.', 19865),
(66111, 'ptBR', 'Eu vou esmagar seu crânio com minhas mãos nuas.', 'Eu vou esmagar seu crânio com minhas mãos nuas.', 19865),
(66112, 'ptBR', 'Morte! Ruína! Destruição!', 'Morte! Ruína! Destruição!', 19865),
(66113, 'ptBR', 'A tortura de mil mortes gritantes $go:a; aguarda...', 'A tortura de mil mortes gritantes $go:a; aguarda...', 19865),
(66114, 'ptBR', 'Mais crânios para a pilha...', 'Mais crânios para a pilha...', 19865),
(66115, 'ptBR', 'Venha, bucha de canhão, encarar seu fim.', 'Venha, bucha de canhão, encarar seu fim.', 19865),
(66116, 'ptBR', 'Não! Eu preciso voltar até Ela!', 'Não! Eu preciso voltar até Ela!', 19865),
(66117, 'ptBR', 'Você está longe de casa, não é mesmo?', 'Você está longe de casa, não é mesmo?', 19865),
(66118, 'ptBR', 'Ela me protegerá!', 'Ela me protegerá!', 19865),
(66119, 'ptBR', 'Eu posso sentir o seu medo...', 'Eu posso sentir o seu medo...', 19865),
(66120, 'ptBR', 'Meus irmãos são incontáveis.', 'Meus irmãos são incontáveis.', 19865),
(66121, 'ptBR', 'Os filhotes irão jantar seu cadáver!', 'Os filhotes irão jantar seu cadáver!', 19865),
(66122, 'ptBR', 'Os Mantídeos irão recobrir esta terra e devorar todos os que se opuserem a nós!', 'Os Mantídeos irão recobrir esta terra e devorar todos os que se opuserem a nós!', 19865),
(66123, 'ptBR', 'A fonte se agita...', 'A fonte se agita...', 19865),
(66124, 'ptBR', 'As águas estão inquietas...', 'As águas estão inquietas...', 19865),
(66125, 'ptBR', 'Você interrompe minha meditação? Você irá pagar...', 'Você interrompe minha meditação? Você irá pagar...', 19865),
(66126, 'ptBR', 'Eu vejo o seu fim...', 'Eu vejo o seu fim...', 19865),
(66127, 'ptBR', 'As águas falam do seu fim...', 'As águas falam do seu fim...', 19865),
(66128, 'ptBR', 'Se tu quiser aprender alguma coisinha sobre fundição, eu sou o anão que tu procura!', '', 19865),
(66129, 'ptBR', 'As ondas tremem com sua aproximação...', 'As ondas tremem com sua aproximação...', 19865),
(66130, 'ptBR', 'As profundezas trovejantes chamam você...', 'As profundezas trovejantes chamam você...', 19865),
(66131, 'ptBR', 'Você morre!', 'Você morre!', 19865),
(66132, 'ptBR', 'Fura fura fura fura fura fura!', 'Fura fura fura fura fura fura!', 19865),
(66133, 'ptBR', 'Nós pegamos o que queremos!', 'Nós pegamos o que queremos!', 19865),
(66134, 'ptBR', 'Eu vou usar sua pele de chapéu!', 'Eu vou usar sua pele de chapéu!', 19865),
(66135, 'ptBR', 'Você não deveria ter vindo aqui!', 'Você não deveria ter vindo aqui!', 19865),
(66136, 'ptBR', 'Não! Meu ouro!!', 'Não! Meu ouro!!', 19865),
(66137, 'ptBR', 'Quem está aí?', 'Quem está aí?', 19865),
(66138, 'ptBR', 'Você trouxe conflito às nossas terras! Eu levarei conflito a você agora!', 'Você trouxe conflito às nossas terras! Eu levarei conflito a você agora!', 19865),
(66139, 'ptBR', 'Estas trevas em meu coração são culpa sua!', 'Estas trevas em meu coração são culpa sua!', 19865),
(66140, 'ptBR', 'Minha visão está nublada, o que você fez conosco?', 'Minha visão está nublada, o que você fez conosco?', 19865),
(66141, 'ptBR', 'A decadência desta terra chegará ao fim quando você morrer!', 'A decadência desta terra chegará ao fim quando você morrer!', 19865),
(66142, 'ptBR', 'Eu preciso ceder à raiva! É a única maneira!', 'Eu preciso ceder à raiva! É a única maneira!', 19865),
(66143, 'ptBR', 'Meu treinamento não serviu de nada, e foi culpa sua!', 'Meu treinamento não serviu de nada, e foi culpa sua!', 19865),
(66144, 'ptBR', 'As trevas em minha alma gritam por liberdade!', 'As trevas em minha alma gritam por liberdade!', 19865),
(66145, 'ptBR', 'Vô te fedê cocê!', 'Vô te fedê cocê!', 19865),
(66146, 'ptBR', 'Bem no fededor!', 'Bem no fededor!', 19865),
(66147, 'ptBR', 'Dá pra cá essa larica!!', 'Dá pra cá essa larica!!', 19865),
(66148, 'ptBR', 'Vô te pancá no kokoruto!', 'Vô te pancá no kokoruto!', 19865),
(66149, 'ptBR', 'Cê tem kaka no koko!', 'Cê tem kaka no koko!', 19865),
(66150, 'ptBR', 'Ha ha, cê nem pega Ik-Ik!', 'Ha ha, cê nem pega Ik-Ik!', 19865),
(66151, 'ptBR', 'Vô te fazer em pedacitos!', 'Vô te fazer em pedacitos!', 19865),
(66152, 'ptBR', 'Por favor, animal gostoso, vem com o Martar, vem.', 'Por favor, animal gostoso, vem com o Martar, vem.', 19865),
(66153, 'ptBR', 'Ei ei ei ei ei!', 'Ei ei ei ei ei!', 19865),
(66154, 'ptBR', 'Martar quer um amiguinho peludo!!', 'Martar quer um amiguinho peludo!!', 19865),
(66155, 'ptBR', 'Não! O tesouro de Martar é do Martar!', 'Não! O tesouro de Martar é do Martar!', 19865),
(66156, 'ptBR', '', 'Essa estranha nova terra tem muito a oferecer em forma de ervas e medicamentos, se você souber o que procurar.', 19865),
(66157, 'ptBR', 'A Alma de Lilian se desvanece para o reino espiritual. Ela não pode mais ser machucada!', 'A Alma de Lilian se desvanece para o reino espiritual. Ela não pode mais ser machucada!', 19865),
(66158, 'ptBR', 'A Força do Imperador aparece nas alcovas!', 'A Força do Imperador aparece nas alcovas!', 19865),
(66159, 'ptBR', 'Não deixem ninguém passar!', '', 19865),
(66160, 'ptBR', 'A Coragem do Imperador aparece nas alcovas!', 'A Coragem do Imperador aparece nas alcovas!', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(66161, 'ptBR', 'Não cedam. Sem misericórdia!', '', 19865),
(66162, 'ptBR', 'Resistam comigo e destruam o inimigo!', '', 19865),
(66163, 'ptBR', 'São muitos cachorros. Não vamos conseguir detê-los!', '', 19865),
(66164, 'ptBR', 'Eu decepcionei... nossa irmandade sagrada...', '', 19865),
(66165, 'ptBR', 'Você veio procurar o velho Tapin, né? Ouviu falar do meu apelido? Tinha uma época que eles me chamavam de "barbeiro" por causa da minha habilidade em esfolamento.', '', 19865),
(66166, 'ptBR', 'Tome essa pedra. Ela ajudará.', '', 19865),
(66167, 'ptBR', 'Pronto em 3...', 'Pronto em 3...', 19865),
(66168, 'ptBR', '2...', '2...', 19865),
(66169, 'ptBR', '1...', '1...', 19865),
(66170, 'ptBR', 'Rolar!', 'Rolar!', 19865),
(66171, 'ptBR', 'Você saiu do percurso de rolamento!', 'Você saiu do percurso de rolamento!', 19865),
(66172, 'ptBR', 'Percurso concluído!', 'Percurso concluído!', 19865),
(66173, 'ptBR', 'Parabéns!', 'Parabéns!', 19865),
(66174, 'ptBR', 'Você chegou em primeiro lugar!', 'Você chegou em primeiro lugar!', 19865),
(66175, 'ptBR', 'Você chegou em segundo lugar!', 'Você chegou em segundo lugar!', 19865),
(66176, 'ptBR', 'Você chegou em terceiro lugar!', 'Você chegou em terceiro lugar!', 19865),
(66177, 'ptBR', 'Zach Chow resmunga.', '', 19865),
(66178, 'ptBR', '<O mantídeo sai do esconderijo.>$b$bAfaste-se, $r.$b$bA Imperatriz não está em sã consciência. Nós Klaxxi estamos nos reunindo para atacá-la, mas ainda não estamos preparados. E nem você.$b$bA hora de atacar está próxima, mas ainda não é agora.', '', 19865),
(66179, 'ptBR', 'Graças aos seus atos, os hozens temem seu povo. Conceda-me um instante...', '', 19865),
(66180, 'ptBR', 'Ah, aqui está. Quatorze mil anos atrás, estas terras eram governadas por uma terrível raça de guerreiros conhecidos como "mogus".', '', 19865),
(66181, 'ptBR', 'Os mogus governavam pelo medo. E o medo os manteve... até que os primeiros monges pandarens nos ensinaram coragem.', '', 19865),
(66182, 'ptBR', 'Então, os mogus foram derrubados.', '', 19865),
(66183, 'ptBR', 'Veja bem, os que governam pelo medo só permanecem no poder enquanto os governados temem.', '', 19865),
(66184, 'ptBR', 'Os hozens são muitas coisas, mas não são covardes – não por muito tempo. Se você não quiser enfrentar os hozens, inspire-os!', '', 19865),
(66185, 'ptBR', 'Vou ajudar você, mas antes eu gostaria de aprender um pouco mais sobre o seu povo. Você me acompanharia por algum tempo?', '', 19865),
(66186, 'ptBR', 'Conceda-me sua ajuda, Iyyokuk. [Aprimoramento Klaxxi]', 'Conceda-me sua ajuda, Iyyokuk. [Aprimoramento Klaxxi]', 19865),
(66187, 'ptBR', 'Conceda-me sua ajuda, Guardião do Enxame. [Aprimoramento Klaxxi]', 'Conceda-me sua ajuda, Guardião do Enxame. [Aprimoramento Klaxxi]', 19865),
(66188, 'ptBR', 'Conceda-me sua ajuda, Gafanhoto. [Aprimoramento Klaxxi]', 'Conceda-me sua ajuda, Gafanhoto. [Aprimoramento Klaxxi]', 19865),
(66189, 'ptBR', 'Conceda-me sua ajuda, Manipulador. [Aprimoramento Klaxxi]', 'Conceda-me sua ajuda, Manipulador. [Aprimoramento Klaxxi]', 19865),
(66190, 'ptBR', 'Ao matar um inimigo, você poderá usar minha habilidade Vira-Aço. Quando seus inimigos tentarem atacar você, você é quem os atacará.', '', 19865),
(66191, 'ptBR', 'Eu sirvo sua majestade, o último de sua raça.$b$bSe você tiver algum problema comigo, vá reclamar com o príncipe.', 'Só estou mantendo os olhos abertos, $c. Não tem mal nenhum nisso.$b$bSe você tiver notícias para mim, eu as passarei adiante. Se não, é melhor você seguir caminho.', 19865),
(66192, 'ptBR', 'Mantenha a mente aberta e alerta. Veja oportunidades. Explore-as!', '', 19865),
(66193, 'ptBR', 'Eu recobri suas armas com meu preparado especial, Arauto. Você infectará os cadáveres com um soro mutagênico que irá... bom... veja por si $gmesmo:mesma;.', '', 19865),
(66194, 'ptBR', 'Este feromônio de rastreio irá revelar alvos de grande valor.', '', 19865),
(66195, 'ptBR', 'Acabem com eles!', '', 19865),
(66196, 'ptBR', 'A chave da vitória é o controle, Arauto. Use minhas habilidades para dominar a mente do inimigo e transforme-o em um aliado.', '', 19865),
(66197, 'ptBR', 'Eu encontro, você compra.', '', 19865),
(66198, 'ptBR', 'Chegue mais perto para evitar a |cFFFF0000|Hspell:127404|h[Lança Dourada]|h|r!', '', 19865),
(66199, 'ptBR', '|TInterface\\Icons\\ability_hunter_pet_devilsaur.blp:20|tSenhor dos Escravos Hithiss aumenta o poder dos aliados dele com um |cFFFF0000|Hspell:127414|h[Chamado Primevo]|h|r!', '', 19865),
(66200, 'ptBR', 'Onde... onde é que está? Inútil... não presta pra nada, vá pro inferno!', '', 19865),
(66201, 'ptBR', 'Era... uma... armadilha...', '', 19865),
(66202, 'ptBR', 'Fácil demais!', '', 19865),
(66203, 'ptBR', 'Você estava ao menos tentando?!', '', 19865),
(66204, 'ptBR', 'Hahah, vocês morrem tão fácil!', '', 19865),
(66205, 'ptBR', 'Hah! Os que fracassaram mereceram morrer; você só abateu os fracos!', '', 19865),
(66206, 'ptBR', 'Eu mesmo terei que acabar com isso. E farei direito!', '', 19865),
(66207, 'ptBR', '|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|tGeneral Zhun libera uma |cFFFF0000|Hspell:127334|h[Onda de Dor]|h|r em seus inimigos!', '', 19865),
(66208, 'ptBR', 'Não se mexa! Não vai doer nada.', '', 19865),
(66209, 'ptBR', 'Ah! Carne fresca para os cães!', '', 19865),
(66210, 'ptBR', 'Perfure a carne!', '', 19865),
(66211, 'ptBR', 'Lâminas... Retalhem todos!', '', 19865),
(66212, 'ptBR', 'Sangue! Corra à minha volta!', '', 19865),
(66213, 'ptBR', 'Não fiquem aí parados. Atacar!', '', 19865),
(66214, 'ptBR', 'Animais estúpidos! Vou sacrificar vocês depois de matar esses fracotes.', '', 19865),
(66215, 'ptBR', 'Carne para os cães!', '', 19865),
(66218, 'ptBR', 'Soltem os cães!', '', 19865),
(66219, 'ptBR', 'Soltei os cachorros!', '', 19865),
(66220, 'ptBR', 'Não!', '', 19865),
(66221, 'ptBR', 'Meu cachorro!', '', 19865),
(66222, 'ptBR', 'Como ousa?', '', 19865),
(66223, 'ptBR', 'Hah, reforços!', '', 19865),
(66224, 'ptBR', 'Vamos esmagar vocês como baratas!', '', 19865),
(66225, 'ptBR', 'Estamos com sua seiva. Venham pegar!', '', 19865),
(66226, 'ptBR', 'Mesmo juntos... nós fracassamos...', '', 19865),
(66227, 'ptBR', 'Fracote!', '', 19865),
(66228, 'ptBR', 'O raio não tem misericórdia!', '', 19865),
(66229, 'ptBR', 'Ninguém desafiará os Shado-Pans!', '', 19865),
(66230, 'ptBR', 'Arqueiros, atacar!', '', 19865),
(66231, 'ptBR', 'Continuem atirando! Ninguém pode escapar!', '', 19865),
(66232, 'ptBR', 'Menos um, não cedam!', '', 19865),
(66233, 'ptBR', 'Obrigado por salvar o festival, $n!', '', 19865),
(66234, 'ptBR', '', 'Bom trabalho, $n. Não teríamos conseguido sem você.', 19865),
(66235, 'ptBR', '', 'Os yaungóis estão vindo de todas as direções, $n! Rápido, defenda a aldeia antes que eles a queimem!', 19865),
(66236, 'ptBR', 'Os Shado-Pans não precisam de ajuda externa! Expulse os intrometidos!', '', 19865),
(66237, 'ptBR', '|TInterface\\Icons\\ability_warstomp.blp:20|t %s começa a lançar |cFFFF0000|Hspell:127480|h[Pancada Esmagadora ]|h|r! Afaste-se!', '', 19865),
(66238, 'ptBR', '%s pega uma arma caída.', '', 19865),
(66239, 'ptBR', 'Venha! Não podemos permitir que machuquem o Andarilho das Lendas!', '', 19865),
(66240, 'ptBR', 'Os shado-pans tem muitos segredos. O mais importante deles é como criar armas e armadura de qualidade insuperável.', '', 19865),
(66241, 'ptBR', 'Eita... ferro. Essa cerveja ficou um pouco mais forte do que eu previa...', '', 19865),
(66242, 'ptBR', 'Eita... ferro. Essa cerveja ficou um pouco mais forte do que eu previa... Eu...', '', 19865),
(66243, 'ptBR', 'Só preciso descansar a vista um pouco...', '', 19865),
(66244, 'ptBR', 'Eu sirvo apenas ao Klaxxi''va.', '', 19865),
(66248, 'ptBR', 'Você tem nosso muito obrigado! Eu acompanharei o Andarilho das Lendas em segurança até o Vale.', '', 19865),
(66249, 'ptBR', 'Um baú devolvido! Meus humildes agradecimentos...', '', 19865),
(66250, 'ptBR', 'Um precioso barril de Cerveja Rocha Verde! Oba!', '', 19865),
(66251, 'ptBR', 'Isso vai ensinar os malditos a não se meterem com o produto mais premiado do nosso dojo!', '', 19865),
(66252, 'ptBR', 'Ah, de volta ao seu lugar. Obrigado!', '', 19865),
(66253, 'ptBR', 'Um aventureiro pode até salvar a aldeia, mas só um HERÓI de verdade devolve a cerva!', '', 19865),
(66254, 'ptBR', 'Nossa preciosa cervejinha! Você tem os nossos mais sinceros agradecimentos.', '', 19865),
(66255, 'ptBR', 'Se você puder se aventurar na floresta em volta, recupere quaisquer barris roubados que encontrar. Eu farei uma mistura concentrada que dará a você poderes maravilhosos...', '', 19865),
(66256, 'ptBR', 'Excelente! Esses patéticos iniciados estavam me entediando!', '', 19865),
(66257, 'ptBR', 'Caminhante das Águas', 'Caminhante das Águas', 19865),
(66258, 'ptBR', 'Quílen', 'Quílen', 19865),
(66259, 'ptBR', 'Basilisco', 'Basilisco', 19865),
(66260, 'ptBR', 'Garça', 'Garça', 19865),
(66261, 'ptBR', 'Bode', 'Bode', 19865),
(66262, 'ptBR', 'Porco-espinho', 'Porco-espinho', 19865),
(66263, 'ptBR', 'Um chapéu bonitão! Acredito que era isso que você estava procurando, não?', '', 19865),
(66264, 'ptBR', 'Tchauzinho por enquanto, colega!', '', 19865),
(66266, 'ptBR', '1...', '', 19865),
(66267, 'ptBR', '3...', '', 19865),
(66268, 'ptBR', 'Defensores do vale, vocês têm 30 minutos para voltar ao Pagode Dourado!', 'Defensores do vale, vocês têm 30 minutos para voltar ao Pagode Dourado!', 19865),
(66269, 'ptBR', 'Forças mogu apareceram no portão principal! Todos os defensores devem retornar ao Pagode Dourado em 15 minutos!', 'Forças mogu apareceram no portão principal! Todos os defensores devem retornar ao Pagode Dourado em 15 minutos!', 19865),
(66271, 'ptBR', 'Defensores, vocês têm cinco minutos antes de serem chamados novamente ao Pagode Dourado!', 'Defensores, vocês têm cinco minutos antes de serem chamados novamente ao Pagode Dourado!', 19865),
(66272, 'ptBR', 'Ótimo, você voltou.', 'Ótimo, você voltou.', 19865),
(66273, 'ptBR', 'Os batedores relatam uma ofensiva mogu em 30 minutos! Liberem o vale a oeste!', 'Os batedores relatam uma ofensiva mogu em 30 minutos! Liberem o vale a oeste!', 19865),
(66274, 'ptBR', 'Defensores, vocês têm quinze minutos para sair do vale ocidental! Grupos de mogus estão deixando os acampamentos!', 'Defensores, vocês têm quinze minutos para sair do vale ocidental! Grupos de mogus estão deixando os acampamentos!', 19865),
(66275, 'ptBR', 'Mogus vão invadir o vale em cinco minutos! Defensores, essa é a última chance de escapar!', 'Mogus vão invadir o vale em cinco minutos! Defensores, essa é a última chance de escapar!', 19865),
(66276, 'ptBR', 'Tô contigo e não abro, $n!', 'Tô contigo e não abro, $n!', 19865),
(66277, 'ptBR', '|TInterface\\Icons\\spell_nature_agitatingtotem.blp:20|tGara''jal evoca um Totem de Espírito. Use-o para |cFFFF0000|Hspell:116161|h[Cruzar]|h|r para o Mundo Espiritual!', '', 19865),
(66278, 'ptBR', '|TInterface\\Icons\\spell_nature_agitatingtotem.blp:20|tGara''jal evoca um Totem de Espírito. Use-o para |cFFFF0000|Hspell:116260|h[Cruzar]|h|r para o Mundo Espiritual!', '', 19865),
(66279, 'ptBR', '$n prepara um Banquete da Infusão!', '$n prepara um Banquete da Infusão!', 19865),
(66280, 'ptBR', '$n prepara um Banquete da Grelha!', '$n prepara um Banquete da Grelha!', 19865),
(66281, 'ptBR', '$n prepara um Banquete do Forno!', '$n prepara um Banquete do Forno!', 19865),
(66282, 'ptBR', '$n prepara um Banquete da Panela!', '$n prepara um Banquete da Panela!', 19865),
(66283, 'ptBR', '$n prepara um Banquete da Vaporeira!', '$n prepara um Banquete da Vaporeira!', 19865),
(66284, 'ptBR', '$n prepara um Banquete da Wok!', '$n prepara um Banquete da Wok!', 19865),
(66285, 'ptBR', '$n prepara um Grande Banquete da Infusão!', '$n prepara um Grande Banquete da Infusão!', 19865),
(66286, 'ptBR', '$n prepara um Grande Banquete da Grelha!', '$n prepara um Grande Banquete da Grelha!', 19865),
(66287, 'ptBR', '$n prepara um Grande Banquete do Forno!', '$n prepara um Grande Banquete do Forno!', 19865),
(66288, 'ptBR', '$n prepara um Grande Banquete da Panela!', '$n prepara um Grande Banquete da Panela!', 19865),
(66289, 'ptBR', '$n prepara um Grande Banquete da Wok!', '$n prepara um Grande Banquete da Wok!', 19865),
(66290, 'ptBR', '$n prepara um Grande Banquete da Vaporeira!', '$n prepara um Grande Banquete da Vaporeira!', 19865),
(66291, 'ptBR', '$n prepara um Banquete Pandarênico!', '$n prepara um Banquete Pandarênico!', 19865),
(66292, 'ptBR', '$n prepara um Grande Banquete Pandarênico!', '$n prepara um Grande Banquete Pandarênico!', 19865),
(66293, 'ptBR', 'Ouvi falar do seu "heroísmo", Gafanhoto. Dizem que seus ataques aos campos de trabalho e fazendas dos mogus atrasaram a finalização da muralha em décadas.', '', 19865),
(66294, 'ptBR', 'Não posso argumentar contra os seus resultados, mas como pode $Gum:uma; orgulhos$go:a; guerreir$go:a; do enxame fazer seu nome perseguindo aldeões e fazendeiros?', '', 19865),
(66295, 'ptBR', 'Fácil: não é preciso pular muito longe entre as mortes.', '', 19865),
(66296, 'ptBR', 'Sanguinári$go:a;, seus poderes de regeneração me fascinam. Será que você permitiria que eu fizesse alguns testes?', '', 19865),
(66297, 'ptBR', 'Que tipo de testes?', '', 19865),
(66298, 'ptBR', 'Só uma pequena indução de trauma celular, talvez algumas amostras de tecido, uma sessão de sondagem genética microssônica profunda... Nada muito invasivo!', '', 19865),
(66299, 'ptBR', 'Isso por último foi o quê mesmo?', '', 19865),
(66300, 'ptBR', 'Amostras de tecido?', '', 19865),
(66301, 'ptBR', 'Não, depois.', '', 19865),
(66302, 'ptBR', 'Nada muito invasivo?', '', 19865),
(66303, 'ptBR', 'Assunto encerrado.', '', 19865),
(66304, 'ptBR', 'Que tal é agir por conta própria novamente, Guardião do Enxame? Sua imperatriz também foi vítima da paranoia, não foi?', '', 19865),
(66305, 'ptBR', 'A grã-imperatriz Zek''hara mascarou suas reais intenções por trás de pretensas preocupações maternais. Ela disse que sua conduta sufocante era necessária para nos proteger.', '', 19865),
(66306, 'ptBR', 'Mas na verdade ela estava obcecada com controle. Ela queria permanecer no poder para sempre e estava disposta a sacrificar nosso ciclo eterno para conseguir isso. Não tivemos escolha a não ser eliminá-la.', '', 19865),
(66307, 'ptBR', 'É claro.', '', 19865),
(66308, 'ptBR', 'E tendo visto o que a grã-imperatriz Shek''zeer está fazendo com nossa terra... não é preciso me convencer.', '', 19865),
(66309, 'ptBR', 'Eu já servi a Shek''zeer durante algum tempo, como se sabe. Antes de eu ser preservado. A loucura dela não é algo racional, feito ambição.', '', 19865),
(66310, 'ptBR', 'Quando ela tentou coibir o enxame foi para prevenir, nas palavras dela, "uma perda de vidas insensata".', '', 19865),
(66311, 'ptBR', 'Ela não confia em ninguém. A paranoia lhe corrói os pensamentos. Ela é movida por medo incessante.', '', 19865),
(66312, 'ptBR', 'Como eu me sinto? Eu não me arrependo de nada, se é isso que você quer saber. É uma honra servir aos Klaxxi.', '', 19865),
(66313, 'ptBR', 'É uma honra servir ao seu lado, Escolado. Eu estudei o seu trabalho com afinco.', '', 19865),
(66314, 'ptBR', 'Graças às anotações detalhadas que você fez ao desenvolver a câmara de preservação, eu pude criar uma versão modificada para preservar o Kovok aqui também.', '', 19865),
(66315, 'ptBR', 'Sim, ele certamente parece... saudável.', '', 19865),
(66316, 'ptBR', 'Eu nunca imaginei que meu trabalho iria tão longe. É uma prova do grande poder dos kypari. Nossa civilização jamais teria se recuperado se não fosse por eles. Lembre-se disso.', '', 19865),
(66317, 'ptBR', 'Que fera impressionante você tem aqui, Manipulador. Muito intrigante.', '', 19865),
(66318, 'ptBR', 'Não.', '', 19865),
(66319, 'ptBR', 'Todos esses anos em estase, e depois esse crescimento rápido e súbito.', '', 19865),
(66320, 'ptBR', 'Nem pergunte.', '', 19865),
(66321, 'ptBR', 'Eu só estou dizendo... aposto que os genes dele têm bastante história pra contar...', '', 19865),
(66322, 'ptBR', 'E eu só estou dizendo, Dissecador, que você não parece ter resistência alguma contra manipulação sônica.', '', 19865),
(66323, 'ptBR', 'Que tal se de repente você ficasse muito "interessada" pelo seu próprio tórax? Aposto que suas mãos habilidosas conseguiriam fazer uma vivissecção em poucos segundos, com o incentivo certo.', '', 19865),
(66324, 'ptBR', 'Entendi seu argumento.', '', 19865),
(66325, 'ptBR', 'Grrr... eu preciso matar alguma coisa. Toda essa espera está me dando nos nervos.', '', 19865),
(66326, 'ptBR', 'Silêncio.', '', 19865),
(66327, 'ptBR', 'Monges, rolar tanto assim não deixa vocês tontos?', '', 19865),
(66328, 'ptBR', 'Os hozens nem sempre são os melhores cervejeiros, mas os de Ungá Ingô de alguma forma roubam os melhores ingredientes.', '', 19865),
(66329, 'ptBR', '', 'Bem-vind$go:a; ao Monastério de Tian.', 19865),
(66330, 'ptBR', 'Ai! Ai! Ai!', '', 19865),
(66331, 'ptBR', '', 'Que bom ver você, $n! Meus estudantes e eu viemos experimentar a famosa cerveja do Mestre Buf e para celebrar o Festival!', 19865),
(66332, 'ptBR', '', 'Como tecelões da névoa, devemos proteger os que precisam.', 19865),
(66333, 'ptBR', '', 'O Tecelão da Névoa Nian é um professor severo, mas tem um bom coração.', 19865),
(66334, 'ptBR', '', 'Irmãs, a aldeia precisa da nossa ajuda. Sigam para a frente de batalha e curem os feridos!', 19865),
(66335, 'ptBR', '', 'Sim senhora!', 19865),
(66336, 'ptBR', 'Eles pretendem executar o Andarilho das Lendas Fu! Por favor, você tem que me ajudar a impedi-los...', '', 19865),
(66337, 'ptBR', 'Se o Andarilho das Lendas for morto, muitos de nós terão morrido por nada...\n\nVocê me ajudará a impedir a execução?', '', 19865),
(66338, 'ptBR', 'Vamos salvá-lo.', 'Vamos salvá-lo.', 19865),
(66339, 'ptBR', 'Xuen nos ensinou o significado da força.', '', 19865),
(66340, 'ptBR', 'É bom ver todo mundo de astral tão alto.', '', 19865),
(66341, 'ptBR', 'O festival me lembra do quão belo Kun-Lai é.', '', 19865),
(66342, 'ptBR', 'Saudações, $n. Está $Gpronto:pronta; gostando do festival?', '', 19865),
(66343, 'ptBR', 'Precisamos defender os aldeões! Eu cuidarei dos portões frontais, o resto de vocês se espalhe e não deixem nenhum yaungol passar!', '', 19865),
(66345, 'ptBR', 'Esses filhotes de serpente são adequados para batalhas de mascotes?', 'Esses filhotes de serpente são adequados para batalhas de mascotes?', 19865),
(66346, 'ptBR', '', 'Vejo que temos uma mascote de batalha no nosso campo de treinamento. Serpentes das Nuvens são capazes de fazer de tudo, incluindo lutar com outras mascotes! A chave para encontrar filhotes é construir uma amizade com uma adulta. Uma vez que você esteja exaltad$go:a; com a ordem, você as encontrará espalhadas pelo arboreto.', 19865),
(66347, 'ptBR', 'Dois construtos titânicos aparecem nas grandes alcovas!', 'Dois construtos titânicos aparecem nas grandes alcovas!', 19865),
(66348, 'ptBR', 'Pela glória do General Zhun!', '', 19865),
(66349, 'ptBR', 'Em nome do Rei Trovão!', '', 19865),
(66350, 'ptBR', 'Vou arrancar sua cabeça!', '', 19865),
(66351, 'ptBR', 'Nada se compara à minha espada!', '', 19865),
(66352, 'ptBR', 'Você OUSA se erguer perante um discípulo do Mestre de Pergaminhos Fon?!', '', 19865),
(66353, 'ptBR', 'Sua agonia não terá FIM!', '', 19865),
(66354, 'ptBR', 'Vou esmagar seu crânio!', '', 19865),
(66355, 'ptBR', 'Quebrarei cada osso do seu corpo!', '', 19865),
(66356, 'ptBR', 'Obrigado pela ajuda, $gamigo:amiga;. é melhor eu me apresentar à Arqueira Li.', '', 19865),
(66357, 'ptBR', 'Hrghhh!!', '', 19865),
(66358, 'ptBR', 'Você acha que estou louco, não acham? Sim... sim, talvez eu esteja um pouco.$b$bSabe, mesmo depois de oitocentos e setenta e sete anos de imobilidade, o desejo de respirar não vai embora.$b$bTalvez algo tenha dado errado com meu aprisionamento. Talvez tenha sido meu intelecto incrivelmente aguçado. Qualquer que tenha sido o caso, eu fiquei completamente consciente da passagem do tempo durante meus anos no âmbar.$b$bApós setenta e oito anos, eu parei de tentar escapar. Eu mantive minha mente aguçada criando e resolvendo quebra-cabeças. O âmbar cuidou bem do resto do meu corpo.$b$bMas, minha sanidade? Não, eu não posso afirmar que ela tenha sobrevivido intacta.', '', 19865),
(66359, 'ptBR', 'Invasores! As jaulas dos prisioneiros estão sendo atacadas. Enviem reforços!', '', 19865),
(66360, 'ptBR', 'Os Klaxxi disseram que precisavam de alguém pra continuar punindo os tolos no futuro.$B$BEu disse a eles: "Eu sou o mantídeo que vocês querem."', '', 19865),
(66361, 'ptBR', 'Há intrusos no templo!', '', 19865),
(66362, 'ptBR', 'Há intrusos no templo! Socorro!', '', 19865),
(66363, 'ptBR', 'As muralhas do templo foram violadas!', '', 19865),
(66364, 'ptBR', 'Alguém se infiltrou no templo! Alarme! Alarme!', '', 19865),
(66365, 'ptBR', 'MESTRES! Há invasores no templo!', '', 19865),
(66366, 'ptBR', 'Perigo, mestres! INVASORES!', '', 19865),
(66367, 'ptBR', 'O templo foi invadido, mestres! SOCORRO!', '', 19865),
(66368, 'ptBR', 'Socorro, ó grandes mestres! SOCORRO!', '', 19865),
(66369, 'ptBR', 'Uma pequena taxa pelos suprimentos é necessária.', 'Uma pequena taxa pelos suprimentos é necessária.', 19865),
(66370, 'ptBR', 'Está gravado no escudo: Sentinela Ku-Yao. Ele pertence ao pai do jovem.', 'Está gravado no escudo: Sentinela Ku-Yao. Ele pertence ao pai do jovem.', 19865),
(66371, 'ptBR', 'O saco de dormir de Ku-Yao está vazio. Ele não está aqui.', 'O saco de dormir de Ku-Yao está vazio. Ele não está aqui.', 19865),
(66372, 'ptBR', 'Este é Ha-Cha, o iaque da Sentinela Ku-Yao.', 'Este é Ha-Cha, o iaque da Sentinela Ku-Yao.', 19865),
(66373, 'ptBR', 'Você está procurando por Ku-Yao? Não o vejo há dias. Você não acha que ele está com problemas, acha?', 'Você está procurando por Ku-Yao? Não o vejo há dias. Você não acha que ele está com problemas, acha?', 19865),
(66374, 'ptBR', 'Agradeço a ajuda, $gsenhor:senhora;. Agora, vou continuar a busca pelo meu pai.', '', 19865),
(66375, 'ptBR', 'Espero encontrá-lo.', '', 19865),
(66376, 'ptBR', 'Você... Shado-Pan. Você veio aqui me ajudar?', '', 19865),
(66377, 'ptBR', 'Meu filho... ele está aqui? Vivo!?', '', 19865),
(66378, 'ptBR', 'Sim. Seu filho, Ku-Mo, está procurando por você.', 'Sim. Seu filho, Ku-Mo, está procurando por você.', 19865),
(66379, 'ptBR', 'Ele está na Guarnição Shado-Pan no momento. Aqui está uma pipa. Vá encontrá-lo!', 'Ele está na Guarnição Shado-Pan no momento. Aqui está uma pipa. Vá encontrá-lo!', 19865),
(66380, 'ptBR', 'Volte à Trilha da Juta!', '', 19865),
(66381, 'ptBR', 'São necessários três jogadores para purificar a Fonte de Vida!', 'São necessários três jogadores para purificar a Fonte de Vida!', 19865),
(66382, 'ptBR', 'Pai!', '', 19865),
(66383, 'ptBR', 'Eu trouxe a sua besta, pai!', '', 19865),
(66384, 'ptBR', 'Agora você pode atirar nos mantídeos!', '', 19865),
(66385, 'ptBR', 'Este pedaço de âmbar pode ser bem o que os Klaxxi estão procurando.', '', 19865),
(66386, 'ptBR', 'Acho que vou parar de lutar por um tempo, Ku-Mo.', '', 19865),
(66387, 'ptBR', 'Sério?', '', 19865),
(66388, 'ptBR', 'Vamos. Está na hora de irmos para casa.', '', 19865),
(66389, 'ptBR', 'Você devia ficar com essa besta, Ku-Mo.', '', 19865),
(66390, 'ptBR', 'Uau...', '', 19865),
(66391, 'ptBR', 'Mesmo em meu sono, eu ouvi o terror dela.', '', 19865),
(66392, 'ptBR', 'O medo domina seu coração e sua mente. A Imperatriz já não pode governar o império.', '', 19865),
(66393, 'ptBR', 'A hora do despertar deve estar próxima, mas eles não vieram me buscar. O que os Klaxxi estão esperando?', '', 19865),
(66394, 'ptBR', 'Uma presença se aproxima! Alguém lá fora pode me ouvir! Mas... não é um Klaxxi.', '', 19865),
(66395, 'ptBR', 'Sim! Quebre isso! Liberte-me do meu sonho de âmbar!', '', 19865),
(66397, 'ptBR', 'Abandonar Diabrete Vil', 'Abandonar Diabrete Vil', 19865),
(66398, 'ptBR', 'Abandonar Senhor do Caos', 'Abandonar Senhor do Caos', 19865),
(66399, 'ptBR', 'Abandonar Shivarra', 'Abandonar Shivarra', 19865),
(66400, 'ptBR', 'Abandonar Observador', 'Abandonar Observador', 19865),
(66401, 'ptBR', 'Abandonar Guardião Colérico', 'Abandonar Guardião Colérico', 19865),
(66402, 'ptBR', 'Fale comigo quando estiver pronto para tentar novamente.', 'Fale comigo quando estiver pronta para tentar novamente.', 19865),
(66403, 'ptBR', 'Extinto!', '', 19865),
(66404, 'ptBR', 'Isso deixa você zangado?', '', 19865),
(66405, 'ptBR', 'Sinta sua raiva!', '', 19865),
(66406, 'ptBR', 'Que sua raiva consuma você!', '', 19865),
(66407, 'ptBR', 'Alimente-me com sua IRA!', '', 19865),
(66408, 'ptBR', 'Minha fúria foi LIBERADA!', '', 19865),
(66409, 'ptBR', 'Vou te deixar perto da torre. Não se acostume.', '', 19865),
(66410, 'ptBR', 'A torre é logo ali. Vou te dar cobertura pelo alto. Seja rápid$go:a;.', '', 19865),
(66411, 'ptBR', 'Você ouve um rangido vindo da alavanca do elevador!', 'Você ouve um rangido vindo da alavanca do elevador!', 19865),
(66412, 'ptBR', 'Tá na hora de uma cirurgiazinha cardíaca!', '', 19865),
(66413, 'ptBR', 'Doem... meu corpo... para a ciência...', '', 19865),
(66414, 'ptBR', 'Mais uma cirurgia bem sucedida!', '', 19865),
(66415, 'ptBR', 'I think it''s time to go for a Randall P. walk.', '', 19865),
(66416, 'ptBR', 'Hmm... no path. Guess I''ll have to Randall P. swim.', '', 19865),
(66417, 'ptBR', 'Agradeço pela companhia, $c.', '', 19865),
(66418, 'ptBR', '|TInterface\\Icons\\item_earthenmight.blp:20|t %s começa a lançar |cFFFF0000|Hspell:128107|h[Raise Earth]|h|r!  Watch out!', '', 19865),
(66419, 'ptBR', 'Acho que está na hora do Randall P. pular.', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(66420, 'ptBR', 'Sim, Klaxxi''va. O quanto eu esperei para ouvir as ordens do Conselho!', '', 19865),
(66421, 'ptBR', 'Entendo. Muita coisa aconteceu depois que comecei meu longo sono.', '', 19865),
(66422, 'ptBR', 'Você não atrapalhará a afinação!', '', 19865),
(66423, 'ptBR', 'Qual é a fonte do SEU poder? Pense com cuidado antes de responder. Muitos aventureiros apontam para suas armas, ou equipamento, ou para livros de poder arcano.', '', 19865),
(66424, 'ptBR', 'Há muito tempo, quando meu povo era escravo do império mogu, nós fomos proibidos de portar qualquer arma. Nós não éramos lutadores. E ninguém acreditava que poderíamos combater os mogus sem magia ou aço.', '', 19865),
(66425, 'ptBR', 'Até que Kang, o Punho da Primeira Aurora, abriu nossos olhos.', '', 19865),
(66426, 'ptBR', 'Um dia, nosso amado monge emitiu um desafio aos seus companheiros escravos. "Me batam!", ele pediu aos seus irmãos.', '', 19865),
(66427, 'ptBR', 'Surpresos, os acossados escravos pandarens tentaram atingir Kang. Um por um eles falharam, pois ele bloqueava seus golpes como um dançarino, e se esquivava dos ataques como um caniço ao vento.', '', 19865),
(66428, 'ptBR', '"Nossas costas são calosas por causa das chicotadas dos mogus", ele disse. "Nossos braços são fortes de tanto construir fortalezas. Nossas mentes são aguçadas pela necessidade de conviver com o inimigo. Vocês acham que os mogus são mais fortes? Eu digo que nós somos a força deles!"', '', 19865),
(66429, 'ptBR', 'Os fazendeiros, peões de obra, pastores e ferreiros... todos se curvaram diante de Kang. "Nos ensine", eles disseram. "Nos ensine a lutar".', '', 19865),
(66430, 'ptBR', 'E quando eles se levantaram... se levantaram como guerreiros.', '', 19865),
(66431, 'ptBR', 'Sua voz. Suas mãos. ESSAS são as ferramentas dos verdadeiros heróis. Use-as bem... e você poderá mudar o mundo.', '', 19865),
(66432, 'ptBR', 'Pule para evitar que a resina endureça!', 'Pule para evitar que a resina endureça!', 19865),
(66433, 'ptBR', 'Larvas patéticas e sem asas. Vocês invadem o MEU domínio, e eu ouvirei seus gritos de morte enquanto vocês caem deste terraço!', '', 19865),
(66434, 'ptBR', 'Set''thik, em formação! Mostrem a eles quem controla os ventos de Pandária!', '', 19865),
(66435, 'ptBR', 'Fôlego da imperatriz, traga o poderoso Garalon para nós!', '', 19865),
(66436, 'ptBR', 'Garalon, transforme os ossos deles em pó!', '', 19865),
(66437, 'ptBR', 'Impossível! Sri''thik, Zar''thik, Kor''thik, para o topo do terraço! Precisamos defender a Imperatriz!', '', 19865),
(66438, 'ptBR', 'Acredito que você esteja aqui por causa das tartaliscas-dragão, jovem? Desculpe. Não posso ajudar até que você se prove $gum aliado:uma aliada; leal ao meu povo.', 'Acredito que você esteja aqui por causa das tartaliscas-dragão, jovem? Desculpe. Não posso ajudar até que você se prove $gum aliado:uma aliada; leal ao meu povo.', 19865),
(66439, 'ptBR', 'Acredito que você esteja aqui por causa das tartaliscas-dragão, jovem?', 'Acredito que você esteja aqui por causa das tartaliscas-dragão, jovem?', 19865),
(66440, 'ptBR', 'Quais tartaliscas-dragão estão à venda?', 'Quais tartaliscas-dragão estão à venda?', 19865),
(66441, 'ptBR', 'Vitória da Horda!', '', 19865),
(66442, 'ptBR', 'Vitória da Aliança!', '', 19865),
(66443, 'ptBR', 'Espero que eles consigam chegar até aqui. Então minha força e habilidades serão evidentes para todos!', '', 19865),
(66444, 'ptBR', 'Ah-hah! Vocês todos logo desejarão não ter vindo para cá...', '', 19865),
(66445, 'ptBR', 'Mas... eu estava... quem é que vai...?!', '', 19865),
(66446, 'ptBR', 'Seus ossos entalhados irão decorar as armas dos nossos guerreiros!', '', 19865),
(66447, 'ptBR', 'Você achou que tinha alguma chance?', '', 19865),
(66448, 'ptBR', 'Permita-me mostrar o poder da alquimia do âmbar...', '', 19865),
(66449, 'ptBR', 'Boas-vindas, estrangeiros. O Mestre Monte de Neve está esperando por vocês na escola. Lembrem-se de mostrar o respeito adequado ao Mestre.', 'Boas-vindas, estrangeiros. O Mestre Monte de Neve está esperando por vocês na escola. Lembrem-se de mostrar o respeito adequado ao Mestre.', 19865),
(66451, 'ptBR', 'Parece que a Imperatriz Shek''zeer deixou nosso império cair no caos. Temos que cuidar disso. Mas primeiro, preciso recobrar minhas forças.', '', 19865),
(66452, 'ptBR', 'Eu não disse que minhas asas eram rápidas? Você se move muito lentamente, Arauto do Despertar.', '', 19865),
(66453, 'ptBR', 'As forças da Cruzada Escarlate na região estão prontas para ajudar seu Comandante se ele for atacado.', '', 19865),
(66454, 'ptBR', '2...', '', 19865),
(66455, 'ptBR', 'Certamente é um ótimo dia.', '', 19865),
(66456, 'ptBR', 'Você gosta de caminhar? Eu gosto.', '', 19865),
(66457, 'ptBR', 'Perdi a conta de há quanto tempo estou caminhando.', '', 19865),
(66458, 'ptBR', 'Oh! Como você chegou aqui?', '', 19865),
(66459, 'ptBR', 'Nada deixa seu sangue fluir melhor do que uma longa e calma caminhada.', '', 19865),
(66460, 'ptBR', 'Antes de você perguntar: não, ainda não chegamos.', '', 19865),
(66461, 'ptBR', 'Espero que você esteja gostando tanto quanto eu.', '', 19865),
(66462, 'ptBR', 'Uma caminhada sempre é mais rápida quando temos $gum:uma; $c $r  amistos$go:a; ao lado.', '', 19865),
(66463, 'ptBR', 'Eu acho que fiquei aqui por tempo suficiente. Gostaria de caminhar comigo?', '', 19865),
(66464, 'ptBR', 'Caminhar? É claro!', 'Caminhar? É claro!', 19865),
(66465, 'ptBR', '$gBem-vindo:Bem-vinda; à minha loja, viajante!', '', 19865),
(66466, 'ptBR', 'Ah! Então você procura itens maravilhosos? Bem, você veio ao lugar certo!', '', 19865),
(66467, 'ptBR', 'Pode olhar à vontade, mas não pode tocar à vontade!', '', 19865),
(66468, 'ptBR', 'Você gostaria de um mapa mágico? Ah, esqueça, já acabaram todos.', '', 19865),
(66469, 'ptBR', 'Que os ventos guiem sua jornada!', '', 19865),
(66471, 'ptBR', 'Boa sorte para você, $gamigo:amiga;!', '', 19865),
(66472, 'ptBR', 'Purifique-se pelo fogo!', '', 19865),
(66473, 'ptBR', 'Essa arma aí... Você roubou da sua irmã?', '', 19865),
(66474, 'ptBR', 'Essa arma aí... Você roubou da sua irmã?', '', 19865),
(66475, 'ptBR', 'O que faz você pensar que eu venderia pra você, forasteiro?', '', 19865),
(66476, 'ptBR', 'Espere. Os Klaxxi falam comigo. Sim, Conselho, eu ouvi as intenções da imperatriz. O reinado dela tem de acabar.', '', 19865),
(66477, 'ptBR', 'Já ouvi o suficiente, Conselho. Eu verei meu antigo lar com meus próprios olhos. Eu testemunharei a ruína causada por Shek''zeer.', '', 19865),
(66478, 'ptBR', 'Imediatamente, Klaxxi''va.', '', 19865),
(66479, 'ptBR', 'Antes de eu ser aprisionado em âmbar eu fiz algo bastante arriscado.$B$BPercebi que o âmbar poderia fazer um milagre que eu não poderia fazer nem em mil anos de cuidadosos experimentos.$B$BAntes de eu me tornar um Paragão, eu me injetei com uma dúzia de venenos letais. As propriedades curativas do âmbar me protegeram, como previ, e o tempo se encarregou do resto.$B$BE agora, eu posso lidar com qualquer veneno sem medo.', '', 19865),
(66480, 'ptBR', 'Este ser macio aqui me servirá bem. Venha, Arauto.', '', 19865),
(66481, 'ptBR', 'É uma boa pergunta. Somos um grupo estranho... poucos pandarens escolhem viver deste lado da muralha.$b$bEnfim, estamos fazendo cerveja. Mas não é qualquer cerveja... estamos usando a seiva das grandes árvores kypari como ingrediente.', '', 19865),
(66482, 'ptBR', '...nojento, eu sei. Mas não é.$b$bO âmbar que essas árvores produzem tem fantásticas propriedades curativas. Os mantídeos adoram isso. Eles a consomem, usam nas armas e na arquitetura... Já ouvi lendas que eles embalsamam os heróis da raça nesse negócio.', '', 19865),
(66483, 'ptBR', 'Exatamente. As tradições dos mestres da seiva se estendem por incontáveis gerações no passado. Eu sou apenas um elo numa corrente formada por pandarens sedentos de seiva.$b$bNo entanto, às vezes, eu temo que eu possa ser o elo final.', '', 19865),
(66484, 'ptBR', 'As árvores estão morrendo. Kypari Vor já morreu... uma vítima do sha. E já não produzirá mais âmbar. Mal se parece com um árvore.$b$bAs poucas árvores produtoras de âmbar que sobraram estão sendo exploradas até o último galho pelos mantídeos, ou correm o risco de sucumbir ao sha. De qualquer maneira... se não houver seiva, não haverá mestres da seiva. E então eu terei que voltar para meu antigo trabalho.', '', 19865),
(66485, 'ptBR', 'Fritador de bolinhos.$b$b<Vu suspira.>', '', 19865),
(66486, 'ptBR', 'O que você está fazendo aqui?', 'O que você está fazendo aqui?', 19865),
(66487, 'ptBR', 'Cerveja feita com seiva? Isso parece...', 'Cerveja feita com seiva? Isso parece...', 19865),
(66488, 'ptBR', 'E vocês fazem cerveja com isso.', 'E vocês fazem cerveja com isso.', 19865),
(66489, 'ptBR', 'E por quê?', 'E por quê?', 19865),
(66490, 'ptBR', 'Qual era o seu antigo trabalho?', 'Qual era o seu antigo trabalho?', 19865),
(66491, 'ptBR', '%s está |cFFFF0000|Hspell:128419|h[Ganhando Velocidade]|h|r!', '', 19865),
(66492, 'ptBR', 'Não cedam. Sem misericórdia!', '', 19865),
(66493, 'ptBR', 'Resistam comigo e destruam o inimigo!', '', 19865),
(66496, 'ptBR', 'Bah! Os que fracassaram mereceram morrer; você só abateu os fracos!', '', 19865),
(66497, 'ptBR', '%s acorda do seu sono com o som do combate!', '', 19865),
(66498, 'ptBR', 'Nham nham nham nham...', '', 19865),
(66499, 'ptBR', 'Tão... DOCE!', '', 19865),
(66500, 'ptBR', 'Tantas SEMENTES!', '', 19865),
(66501, 'ptBR', 'Tão... PICANTE!', '', 19865),
(66502, 'ptBR', 'Por favor, insira vegetais...', '', 19865),
(66503, 'ptBR', 'Insira uma pilha de ginseng.', 'Insira uma pilha de ginseng.', 19865),
(66504, 'ptBR', 'Insira uma pilha de cenouras mordelícia.', 'Insira uma pilha de cenouras mordelícia.', 19865),
(66505, 'ptBR', 'Insira uma pilha de repolho verde.', 'Insira uma pilha de repolho verde.', 19865),
(66506, 'ptBR', 'Insira uma pilha de abóbora jade.', 'Insira uma pilha de abóbora jade.', 19865),
(66507, 'ptBR', 'Insira uma pilha de abóboras mogu.', 'Insira uma pilha de abóboras mogu.', 19865),
(66508, 'ptBR', 'Insira uma pilha de nabo rosa.', 'Insira uma pilha de nabo rosa.', 19865),
(66509, 'ptBR', 'Insira uma pilha de alho-poró de florada vermelha.', 'Insira uma pilha de alho-poró de florada vermelha.', 19865),
(66510, 'ptBR', 'Insira uma pilha de cebolinhas.', 'Insira uma pilha de cebolinhas.', 19865),
(66511, 'ptBR', 'Insira uma pilha de melão listrado.', 'Insira uma pilha de melão listrado.', 19865),
(66512, 'ptBR', 'Insira uma pilha de nabo branco.', 'Insira uma pilha de nabo branco.', 19865),
(66513, 'ptBR', 'Insira uma pilha de uvas-de-bruxa.', 'Insira uma pilha de uvas-de-bruxa.', 19865),
(66514, 'ptBR', 'O Vegetron 4000 está recarregando, tente outra vez mais tarde.', '', 19865),
(66515, 'ptBR', 'Lutar me deixa... com FOME!', '', 19865),
(66516, 'ptBR', 'Intrusos na Fonte da Vida! Não os deixem escapar!', '', 19865),
(66517, 'ptBR', 'Ggrgll!', '', 19865),
(66518, 'ptBR', 'Espere, o quê...?', '', 19865),
(66519, 'ptBR', 'Mmmphhh', '', 19865),
(66520, 'ptBR', 'Socorro!', '', 19865),
(66521, 'ptBR', 'Os mantídeos estão passando por sobre a muralha!', '', 19865),
(66522, 'ptBR', '%s vê a oportunidade de jogar a Colmeia Bombástica Tóxica no redemoinho!', '', 19865),
(66523, 'ptBR', 'Lançamento Poderoso se aproximando! Não seja jogado da montanha!', '', 19865),
(66524, 'ptBR', 'Me dê o cristal ressoante, seu come-casca raquítico!', '', 19865),
(66525, 'ptBR', 'Eu devia saber que você não viria sozinho, Kor''ik.', '', 19865),
(66526, 'ptBR', '|TInterface\\Icons\\ability_druid_ravage.blp:20|t Garalon não consegue atingir pelo menos dois jogadores e ganha |cFFFF0000|Hspell:122754|h[Fúria]|h|r!', '|TInterface\\Icons\\ability_druid_ravage.blp:20|t Garalon não consegue atingir pelo menos dois jogadores e ganha |cFFFF0000|Hspell:122754|h[Fúria]|h|r!', 19865),
(66527, 'ptBR', 'É adequado que eu seja o destruidor do bichinho dos Klaxxi!', '', 19865),
(66528, 'ptBR', 'Venha, $gforasteiro:forasteira;! Me enfrente se tiver coragem!', '', 19865),
(66529, 'ptBR', 'Dispare os canhões para matar os bombardeiros!', '', 19865),
(66530, 'ptBR', 'Você foi tol$go:a; em me interromper, forasteir$go:a;.', '', 19865),
(66531, 'ptBR', 'Ele já foi? Já acabou?', '', 19865),
(66532, 'ptBR', 'O colosso está ferido! Não pare de atacar!', '', 19865),
(66533, 'ptBR', 'Está quase derrotado! Continue batendo!', '', 19865),
(66534, 'ptBR', 'Isso não acabou...', '', 19865),
(66535, 'ptBR', 'Do que precisa um servo dos Klaxxi?', '', 19865),
(66536, 'ptBR', 'Leve-me para o Ermo da Salmoura.', 'Leve-me para o Ermo da Salmoura.', 19865),
(66537, 'ptBR', 'Deseja me pagar um tributo? Então faça-o com sangue!', '', 19865),
(66538, 'ptBR', 'Preciso viajar pra algum lugar.', 'Preciso viajar pra algum lugar.', 19865),
(66539, 'ptBR', 'Leve-me para o Lago das Estrelas.', 'Leve-me para o Lago das Estrelas.', 19865),
(66540, 'ptBR', '[Clique com o botão direito] na arma de aprendiz no seu inventário para equipar-se com ela.\nA tecla padrão para abrir suas bolsas é [B]', '[Clique com o botão direito] na arma de aprendiz no seu inventário para equipar-se com ela.\nA tecla padrão para abrir suas bolsas é [B]', 19865),
(66541, 'ptBR', 'Nosso trabalho aqui acabou por agora. Vamos dar as notícias de nossa vitória para o Conselho Klaxxi. Eles esperam o nosso retorno.', '', 19865),
(66542, 'ptBR', '"Você me impressiona, jovem alun$go:a;. Você possui grande força dentro de si."', '', 19865),
(66543, 'ptBR', 'O que está acontecendo? Por que estamos nos reunindo tão cedo?', '', 19865),
(66544, 'ptBR', 'Não, não... esse enxame está vindo cedo demais. Preciso falar com o Adjunto!', '', 19865),
(66545, 'ptBR', 'Por que estou... aqui...?', '', 19865),
(66546, 'ptBR', 'Onde estamos? Estávamos... enxameando?!', '', 19865),
(66547, 'ptBR', 'Os pandarens estavam preparados. Esse ataque foi insensato.', '', 19865),
(66548, 'ptBR', 'Isso está errado. Ainda não é o momento certo para o enxame atacar.', '', 19865),
(66549, 'ptBR', 'Essa muralha não pode segurar o poder dos mantídeos!', '', 19865),
(66550, 'ptBR', 'Eu cumpro a vontade dela! Nós derrubaremos essa muralha e devoraremos as terras além!', '', 19865),
(66551, 'ptBR', 'Você não teria outro pacote de incensos, teria?', 'Você não teria outro pacote de incensos, teria?', 19865),
(66552, 'ptBR', 'Manterei o navio aqui o máximo que puder.$B$BTenha cuidado!', '', 19865),
(66553, 'ptBR', 'Defenderemos o navio e a tripulação enquanto pudermos.$B$BNão se preocupe conosco!', 'Defenderemos o navio e a tripulação enquanto pudermos.$B$BNão se preocupe conosco!', 19865),
(66554, 'ptBR', 'O que aconteceu aqui?!$B$BA torre da Grã-senhora Proudmore... se foi!', 'O que aconteceu aqui?!$B$BA torre da Grã-senhora Proudmore... se foi!', 19865),
(66555, 'ptBR', 'Que desastre!$B$BO que poderia ter causado isso?!', 'Que desastre!$B$BO que poderia ter causado isso?!', 19865),
(66556, 'ptBR', 'Me pergunto se alguém sobreviveu...', 'Me pergunto se alguém sobreviveu...', 19865),
(66557, 'ptBR', 'A Horda fez isso?!$B$BQue a Luz nos proteja...', 'A Horda fez isso?!$B$BQue a Luz nos proteja...', 19865),
(66558, 'ptBR', 'Pela Luz... Theramore! O que aconteceu aqui?!', '', 19865),
(66559, 'ptBR', 'Abel, vá lá pra baixo e se esconda. Todo o resto, atenção e estejam prontos para um ataque.', '', 19865),
(66560, 'ptBR', 'Se alguém tiver coragem de ir investigar, manteremos o navio aqui o máximo que for possível.', '', 19865),
(66561, 'ptBR', 'S-sim senhor!', '', 19865),
(66562, 'ptBR', '', 'Capitão! Mantenha sua tripulação segura a bordo. Defenderemos o navio se ele for atacado.', 19865),
(66563, 'ptBR', 'Um navio! E da ALIANÇA!', '', 19865),
(66564, 'ptBR', 'Não me importa! VOU MATAR TUDO QUE ESTIVER A BORDO! Andem, seus brutos!', '', 19865),
(66565, 'ptBR', '', 'Apenas um transporte, Grud. Não um navio de guerra.', 19865),
(66566, 'ptBR', 'Sempre imaginei o que estaria por trás desses portões.', 'Sempre imaginei o que estaria por trás desses portões.', 19865),
(66567, 'ptBR', 'Olha só este lugar! É incrível!', 'Olha só este lugar! É incrível!', 19865),
(66568, 'ptBR', 'Eu ouvi que um herói de uma terra distante convenceu Xuen, o deus tigre, a abrir o vale. Talvez eu os veja, um dia.', 'Eu ouvi que um herói de uma terra distante convenceu Xuen, o deus tigre, a abrir o vale. Talvez eu os veja, um dia.', 19865),
(66569, 'ptBR', 'Os Shado-Pans nos disseram que aqui seria um paraíso seguro para todos os refugiados de Kun-Lai. Talvez aqui encontraremos a paz, finalmente.', 'Os Shado-Pans nos disseram que aqui seria um paraíso seguro para todos os refugiados de Kun-Lai. Talvez aqui encontraremos a paz, finalmente.', 19865),
(66570, 'ptBR', 'Ouvi todo tipo de histórias sobre o que existe do outro lado do portão. Nunca imaginei que seria algo assim.', 'Ouvi todo tipo de histórias sobre o que existe do outro lado do portão. Nunca imaginei que seria algo assim.', 19865),
(66571, 'ptBR', 'Talvez possamos encontrar um novo lar aqui, no vale.', 'Talvez possamos encontrar um novo lar aqui, no vale.', 19865),
(66572, 'ptBR', '', 'Lá vêm eles, Halters! Prepare-se!', 19865),
(66573, 'ptBR', 'Este era realmente o lar dos antigos imperadores de Pandária? É lindo.', 'Este era realmente o lar dos antigos imperadores de Pandária? É lindo.', 19865),
(66574, 'ptBR', 'Ter testemunhado a abertura dos portões... é uma história que vou passar para os filhos dos meus filhos.', 'Ter testemunhado a abertura dos portões... é uma história que vou passar para os filhos dos meus filhos.', 19865),
(66575, 'ptBR', 'POR THERAMORE!', '', 19865),
(66576, 'ptBR', 'Há um clarão de luz vindo de alguma parte das costas da criatura.', '', 19865),
(66577, 'ptBR', 'Pegue o objeto.', 'Pegue o objeto.', 19865),
(66578, 'ptBR', 'Há muito dano a ser consertado.', '', 19865),
(66579, 'ptBR', 'Kor''ik foi apenas o primeiro a nos trair. Ninguém é confiável.', '', 19865),
(66580, 'ptBR', 'A guerra chegou, Arauto.', '', 19865),
(66581, 'ptBR', 'A concha da criatura reluz.', '', 19865),
(66582, 'ptBR', 'O que Jaluu pode fazer por você?', '', 19865),
(66583, 'ptBR', 'Sempre procure conquistar o impossível.', '', 19865),
(66584, 'ptBR', 'Que você busque honra e coragem todos os dias, $r.', '', 19865),
(66585, 'ptBR', 'Apenas para os aliados mais confiáveis nós revelaremos os segredos mais secretos da Lótus Dourada.', '', 19865),
(66586, 'ptBR', 'Você parece... que é de ferro...', '', 19865),
(66587, 'ptBR', 'Boas vindas ao Vale. Fique em paz.', '', 19865),
(66588, 'ptBR', 'ME AJUDA!', '', 19865),
(66589, 'ptBR', '', 'Boa sorte para você, $r. Aqui, você encontrará representantes de todas as facções de Pandária. Quando você tiver um pouco mais de experiência, volte e fale conosco. Incríveis aventuras e recompensas esperam por você.', 19865),
(66590, 'ptBR', '', 'Que a estrela da sorte brilhe sobre você, $c. Aqui, você encontrará representantes de todas as facções de Pandária. Fale com eles para descobrir se você é $go:a; grande aventurei$gro:ra; que eles procuram.', 19865),
(66591, 'ptBR', 'Que lugar é este?', 'Que lugar é este?', 19865),
(66592, 'ptBR', 'SOEM O ALARME! A Aliança está se aproximando do porto!', '', 19865),
(66593, 'ptBR', 'Mexam-se, cães!', 'Mexam-se, cães!', 19865),
(66594, 'ptBR', 'Andem logo, peões!', 'Andem logo, peões!', 19865),
(66595, 'ptBR', 'Mais rápido, cães, ou vocês vão ser DEMITIDOS!', 'Mais rápido, cães, ou vocês vão ser DEMITIDOS!', 19865),
(66596, 'ptBR', 'Andem! ANDEM, seus vermes lerdos!', 'Andem! ANDEM, seus vermes lerdos!', 19865),
(66597, 'ptBR', '', 'Boas-vindas, viajante. Que este seja o seu lar, se assim você desejar. Subindo as escadas, você encontrará cofres de banco e os portais de cidade. Comerciantes de todo tipo se estabeleceram no prédio. Por favor, explore à vontade.', 19865),
(66598, 'ptBR', 'O que posso encontrar aqui na cidade?', 'O que posso encontrar aqui na cidade?', 19865),
(66599, 'ptBR', 'Precisa de um pouco de sorte ao seu lado, $r? Todo mundo precisa de um pouco de sorte para melhorar um pouco as coisas!$b$bNão se preocupe, posso ajudar a ajustar as probabilidades ao seu favor!', '', 19865),
(66600, 'ptBR', 'Boas-vindas, $r. Aqui, você encontrará representantes de todas as facções de Pandária. Quando você tiver um pouco mais de experiência, volte e fale conosco. Incríveis aventuras e recompensas esperam por você.', '', 19865),
(66601, 'ptBR', 'Boas-vindas, $r. Aqui, você encontrará representantes de todas as facções de Pandária. Fale com eles para descobrir se você é $go:a; grande aventurei$gro:ra; que eles procuram.', '', 19865),
(66602, 'ptBR', 'Oh, ho! Oh ho ho.$B$BYo ho ho, inclusive.$B$BEu acabo de voltar da terra de Pandária, com suas montanhas íngremes, colinas ondeantes e o rum mais forte que já provei.  Eu encalhei o navio na Floresta de Jade e minha carga tornou o lugar inabitável, mas enquanto isso eu posso levar você ligeirinho até o Vale dos Quatro Ventos.$B$BVocê confia em mim, $c?', '', 19865),
(66603, 'ptBR', 'Iaaarrrr! Cê num vai querer se meter comigo, $gfilhote:mocinha;.$B$BCirculando!', '', 19865),
(66604, 'ptBR', 'Bom trabalho. Continuem assim.', '', 19865),
(66605, 'ptBR', 'Muito bem. Não falta muito!', '', 19865),
(66606, 'ptBR', 'Terminem aqui primeiro e teremos rum para todo mundo!', '', 19865),
(66607, 'ptBR', 'Quanta energia. Excelente!', '', 19865),
(66608, 'ptBR', 'Você veio daquele navio? Péssima ideia. Theramore é terra da HORDA agora!', '', 19865),
(66609, 'ptBR', 'Iarr, o Almirante me mandou pra cá pra vender parte do butim que saqueamos na Floresta de Jade. Ele achou que poderia te ajudar em sua jornada.$B$BSe cê quiser também posso te levar de volta pro continente.', '', 19865),
(66613, 'ptBR', 'Vale dos Quatro Ventos', 'Vale dos Quatro Ventos', 19865),
(66614, 'ptBR', 'O que você tem para vender?', 'O que você tem para vender?', 19865),
(66615, 'ptBR', 'Seu fim está próximo!', '', 19865),
(66616, 'ptBR', 'Quando estiver morrendo, animal, lembre que eu lhe dei uma escolha.', '', 19865),
(66617, 'ptBR', 'Comerciantes de todas as plagas vieram até esta cidade. O que você busca?', 'Comerciantes de todas as plagas vieram até esta cidade. O que você busca?', 19865),
(66618, 'ptBR', 'Não encontra o que precisa na cidade?$b$bO que você está procurando? Talvez eu possa ajudar você.', 'Não encontra o que precisa na cidade?$b$bO que você está procurando? Talvez eu possa ajudar você.', 19865),
(66619, 'ptBR', 'Oh, procurando seu instrutor de classe? Infelizmente, nenhum deles chegou até o Vale das Flores Eternas.$b$bVocê precisa retornar à sua terra natal para encontrá-los.', 'Oh, procurando seu instrutor de classe? Infelizmente, nenhum deles chegou até o Vale das Flores Eternas.$b$bVocê precisa retornar à sua terra natal para encontrá-los.', 19865),
(66620, 'ptBR', 'Procurando por um treinador de profissões?$b$bOs mestres zen treinadores podem ser encontrados por toda Pandária. Diga-me quem você procura.$b$bSe você não puder encontrar a pessoa aqui em Pandária, você pode buscar mestres de profissões na sua cidade natal. Eles também poderão treinar você na sua arte.', 'Procurando por um treinador de profissões?$b$bOs mestres zen treinadores podem ser encontrados por toda Pandária. Diga-me quem você procura.$b$bSe você não puder encontrar a pessoa aqui em Pandária, você pode buscar mestres de profissões na sua cidade natal. Eles também poderão treinar você na sua arte.', 19865),
(66621, 'ptBR', 'Você busca o Mestre da Seda Tsai nos Campos de Seda, que ficam no Vale dos Quatro Ventos. Vou marcar a localização dele no seu mapa.', 'Você busca o Mestre da Seda Tsai nos Campos de Seda, que ficam no Vale dos Quatro Ventos. Vou marcar a localização dele no seu mapa.', 19865),
(66622, 'ptBR', 'Você pode aprender a pescar melhor visitando Nat Pagle no Cais dos Pescadores, na Selva de Krasarang. Deixe-me marcar a localização para você.', 'Você pode aprender a pescar melhor visitando Nat Pagle no Cais dos Pescadores, na Selva de Krasarang. Deixe-me marcar a localização para você.', 19865),
(66623, 'ptBR', 'Existem mestres mineradores na Pedreira Rocha Verde, na Floresta de Jade. Eles provavelmente podem ajudar você a minerar melhor. Vou marcar a localização no mapa.', 'Existem mestres mineradores na Pedreira Rocha Verde, na Floresta de Jade. Eles provavelmente podem ajudar você a minerar melhor. Vou marcar a localização no mapa.', 19865),
(66624, 'ptBR', 'Você pode encontrar um treinador de couraria no Bazar dos Grômulos, no Monte Kun-Lai. Vou marcar a localização no seu mapa.', 'Você pode encontrar um treinador de couraria no Bazar dos Grômulos, no Monte Kun-Lai. Vou marcar a localização no seu mapa.', 19865),
(66625, 'ptBR', 'Ouvi dizer que existem mestres alquimistas dentre os Klaxxi, bem além da muralha, no Ermo do Medo. Vou marcar a localização no seu mapa.', 'Ouvi dizer que existem mestres alquimistas dentre os Klaxxi, bem além da muralha, no Ermo do Medo. Vou marcar a localização no seu mapa.', 19865),
(66626, 'ptBR', 'Tem um treinador de esfolamento no Safári do Rosarães, no Vale dos Quatro Ventos.$b$bVou marcar a localização dele no seu mapa.', 'Tem um treinador de esfolamento no Safári do Rosarães, no Vale dos Quatro Ventos.$b$bVou marcar a localização dele no seu mapa.', 19865),
(66627, 'ptBR', 'Para questões de encantamento, você deve falar com Lai Pata de Feitiço na Flor da Manhã, na Floresta de Jade.$b$bVou marcar a localização no seu mapa.', 'Para questões de encantamento, você deve falar com Lai Pata de Feitiço na Flor da Manhã, na Floresta de Jade.$b$bVou marcar a localização no seu mapa.', 19865),
(66628, 'ptBR', 'Você encontrará essa pessoa no Safári do Rosarães, no Vale dos Quatro Ventos.$b$bVou marcar a localização deles no seu mapa.', 'Você encontrará essa pessoa no Safári do Rosarães, no Vale dos Quatro Ventos.$b$bVou marcar a localização deles no seu mapa.', 19865),
(66629, 'ptBR', 'Você deve estar procurando o Mestre Zen Lao! Ele está trabalhando na Guarnição do Sol Poente, no Vale das Flores Eternas.$b$bVou marcar a localização dele no seu mapa.', 'Você deve estar procurando o Mestre Zen Lao! Ele está trabalhando na Guarnição do Sol Poente, no Vale das Flores Eternas.$b$bVou marcar a localização dele no seu mapa.', 19865),
(66630, 'ptBR', 'Existe um mestre em arqueologia no Trono do Conhecimento, acima do Palácio Mogu''shan, aqui no Vale das Flores Eternas.$b$bVou marcar a localização dele no seu mapa.', 'Existe um mestre em arqueologia no Trono do Conhecimento, acima do Palácio Mogu''shan, aqui no Vale das Flores Eternas.$b$bVou marcar a localização dele no seu mapa.', 19865),
(66631, 'ptBR', 'Ah sim, você está procurando a Curandeira Nan. Você poderá encontrá-la dentro do Santuário das Sete Estrelas.$b$bVou marcar a localização dela no mapa.', 'Ah sim, você está procurando a Curandeira Nan. Você poderá encontrá-la dentro do Santuário das Sete Estrelas.$b$bVou marcar a localização dela no mapa.', 19865),
(66632, 'ptBR', 'Interessad$go:a; em desenvolver suas técnicas de culinária?$b$bVocê precisa falar com a família Pata de Ferro! Eles podem ser encontrados no Mercado de Meia Colina, no Vale dos Quatro Ventos.$b$bVou marcar a localização deles no seu mapa.', 'Interessad$go:a; em desenvolver suas técnicas de culinária?$b$bVocê precisa falar com a família Pata de Ferro! Eles podem ser encontrados no Mercado de Meia Colina, no Vale dos Quatro Ventos.$b$bVou marcar a localização deles no seu mapa.', 19865),
(66633, 'ptBR', 'Se você busca mais conhecimento sobre as artes do herborismo, sugiro que fale com o treinador na Floresta de Jade.$b$bVou marcar a localização no seu mapa.', 'Se você busca mais conhecimento sobre as artes do herborismo, sugiro que fale com o treinador na Floresta de Jade.$b$bVou marcar a localização no seu mapa.', 19865),
(66634, 'ptBR', 'Sim, eu sei de um mestre de escrivania no Trono do Conhecimento, no Vale das Flores Eternas.$b$bVou marcar a localização dele no seu mapa.', 'Sim, eu sei de um mestre de escrivania no Trono do Conhecimento, no Vale das Flores Eternas.$b$bVou marcar a localização dele no seu mapa.', 19865),
(66635, 'ptBR', 'Você procura Mai, a Moldadora de Jade. Você a encontrará na Vila Rocha Verde, na Floresta de Jade.$b$bVou marcar a localização dela no seu mapa.', 'Você procura Mai, a Moldadora de Jade. Você a encontrará na Vila Rocha Verde, na Floresta de Jade.$b$bVou marcar a localização dela no seu mapa.', 19865),
(66636, 'ptBR', '', 'Podemos levar algumas das suas mascotes, senhorita Taramela? Por favor!', 19865),
(66637, 'ptBR', '', 'Não não, pequeninos. Vocês não são grandes o suficiente!', 19865),
(66638, 'ptBR', 'Ahhh, cara...', '', 19865),
(66639, 'ptBR', 'Leng Cavalgante das Nuvens pode ensinar você a voar em Pandária. Ele monta em uma serpente das nuvens no terraço principal. Vou marcar a localização dele no seu mapa.', 'Leng Cavalgante das Nuvens pode ensinar você a voar em Pandária. Ele monta em uma serpente das nuvens no terraço principal. Vou marcar a localização dele no seu mapa.', 19865),
(66640, 'ptBR', '$p ATRAIU', '', 19865),
(66641, 'ptBR', '', 'Humpf. Eu provavelmente sou mais alto que ela.', 19865),
(66642, 'ptBR', 'Não há mestres de batalha aqui no vale.$b$bVocê deve voltar para a sua cidade natal para entrar na fila de campos de batalha ou arenas de guerra.', 'Não há mestres de batalha aqui no vale.$b$bVocê deve voltar para a sua cidade natal para entrar na fila de campos de batalha ou arenas de guerra.', 19865),
(66643, 'ptBR', 'Os serviços de Transmogrificação e Cofre Etéreo podem ser encontrados na sua cidade natal.', 'Os serviços de Transmogrificação e Cofre Etéreo podem ser encontrados na sua cidade natal.', 19865),
(66644, 'ptBR', 'Treinamento de Voo', 'Treinamento de Voo', 19865),
(66645, 'ptBR', 'Treinamento de Batalha de Mascotes', 'Treinamento de Batalha de Mascotes', 19865),
(66646, 'ptBR', 'Outro', 'Outro', 19865),
(66647, 'ptBR', 'O Templo da Serpente de Jade, uma masmorra de nível 85-87 na Floresta de Jade, está disponível para testes. Espere até seu grupo estar completo para então se teleportar para esta masmorra. Pedras de Encontro ainda não estão disponíveis para esta masmorra.\n\nPara deixar o Templo da Serpente de Jade, simplesmente atravesse a saída normal de dentro da masmorra e você será $gteleportado:teleportada; para fora. Se você morrer e libertar seu espírito, você se teleportará a partir desse PNJ.', '', 19865),
(66648, 'ptBR', 'Estou no meu grupo e $gpronto:pronta; para me teleportar para o Templo da Serpente de Jade!', 'Estou no meu grupo e $gpronto:pronta; para me teleportar para o Templo da Serpente de Jade!', 19865),
(66649, 'ptBR', 'Leve-me de volta ao Templo da Serpente de Jade!', 'Leve-me de volta ao Templo da Serpente de Jade!', 19865),
(66650, 'ptBR', '', 'Sara Taramela ordena que O Violinista execute um salto!', 19865),
(66651, 'ptBR', 'Transmogrificação e Cofre Etéreo', 'Transmogrificação e Cofre Etéreo', 19865),
(66652, 'ptBR', 'Sacerdote Testa Branca reclama de dor.', '', 19865),
(66653, 'ptBR', 'Mercadorias de Alquimia', 'Mercadorias de Alquimia', 19865),
(66654, 'ptBR', 'Suprimentos de Ferraria', 'Suprimentos de Ferraria', 19865),
(66655, 'ptBR', 'Pão', 'Pão', 19865),
(66656, 'ptBR', 'Cervejas', 'Cervejas', 19865),
(66657, 'ptBR', 'Suprimentos de Culinária', 'Suprimentos de Culinária', 19865),
(66658, 'ptBR', 'Suprimentos de Encantamento', 'Suprimentos de Encantamento', 19865),
(66659, 'ptBR', 'Suprimentos de Engenharia', 'Suprimentos de Engenharia', 19865),
(66660, 'ptBR', '', 'Calma, calma, Sacerdote. Você não está em condições de ajudar ninguém no momento. Seus dois braços estão quebrados! Vou pegar um remédio para você.', 19865),
(66661, 'ptBR', 'Fogos de Artifício', 'Fogos de Artifício', 19865),
(66662, 'ptBR', 'Suprimentos de Primeiros Socorros', 'Suprimentos de Primeiros Socorros', 19865),
(66663, 'ptBR', 'Suprimentos de Pesca', 'Suprimentos de Pesca', 19865),
(66664, 'ptBR', 'Comida e Bebida', 'Comida e Bebida', 19865),
(66665, 'ptBR', 'Plantas', 'Plantas', 19865),
(66666, 'ptBR', '', 'Precisamos de uma caneca gelada aqui! Urgente!', 19865),
(66667, 'ptBR', 'Suprimentos de Escrivania', 'Suprimentos de Escrivania', 19865),
(66668, 'ptBR', 'Suprimentos de Joalheria', 'Suprimentos de Joalheria', 19865),
(66669, 'ptBR', 'Suprimentos de Esfolamento e Couraria', 'Suprimentos de Esfolamento e Couraria', 19865),
(66670, 'ptBR', 'Carne', 'Carne', 19865),
(66671, 'ptBR', 'Suprimentos de Mineração', 'Suprimentos de Mineração', 19865),
(66672, 'ptBR', 'Doces Gostosos', 'Doces Gostosos', 19865),
(66673, 'ptBR', 'Suprimentos de Alfaiataria', 'Suprimentos de Alfaiataria', 19865),
(66674, 'ptBR', 'Procurando mercadorias diversas? Bonni terá o que você precisa. Ela vende as mercadorias na Lanterna Dourada. Vou marcar a localização no seu mapa.', 'Procurando mercadorias diversas? Bonni terá o que você precisa. Ela vende as mercadorias na Lanterna Dourada. Vou marcar a localização no seu mapa.', 19865),
(66675, 'ptBR', 'Vi um negociante arrumando suas mercadorias na Lanterna Dourada. Vou marcar a localização dele no seu mapa.', 'Vi um negociante arrumando suas mercadorias na Lanterna Dourada. Vou marcar a localização dele no seu mapa.', 19865),
(66676, 'ptBR', 'Eu acho que você poderia dizer...', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(66677, 'ptBR', 'Eu acho que você poderia dizer que ela está com bolo no forno!', '', 19865),
(66678, 'ptBR', 'Por que sua esposa ainda está usando o forno? Minha carne precisa ser cozida!', '', 19865),
(66679, 'ptBR', 'Miguel Bedernik rosna.', '', 19865),
(66680, 'ptBR', '', 'Parem com isso, vocês dois!', 19865),
(66681, 'ptBR', 'Muito boa luta, $gpupilo:pupila;. Você provou que aceitou o meu caminho... o Caminho da Garça.', '', 19865),
(66682, 'ptBR', 'A esperança pode florescer em qualquer parte... até no canto escuro de uma floresta esquecida.', '', 19865),
(66683, 'ptBR', 'Só é necessário que $gum herói:uma heroína; feito voc~e plante a semente.', '', 19865),
(66684, 'ptBR', 'Pare esse pesadelo!', '', 19865),
(66685, 'ptBR', 'Eu não serei controlado!', '', 19865),
(66686, 'ptBR', 'Ah, qual intendente você procura? Talvez eu possa ajudar a encontrá-los.', 'Ah, qual intendente você procura? Talvez eu possa ajudar a encontrá-los.', 19865),
(66687, 'ptBR', 'Procurando pelo Intendente dos Pescadores? Seria o Nat Pagle. Você pode encontrá-lo no Cais dos Pescadores, na Selva de Krasarang.$b$bVou marcar a localização no seu mapa.', 'Procurando pelo Intendente dos Pescadores? Seria o Nat Pagle. Você pode encontrá-lo no Cais dos Pescadores, na Selva de Krasarang.$b$bVou marcar a localização no seu mapa.', 19865),
(66688, 'ptBR', 'Você precisa falar com Teng Malte Fulminante! Ele pode ser encontrado na Cervejaria Malte do Trovão, no Vale dos Quatro Ventos.$b$bVou marcar a localização dele no seu mapa.', 'Você precisa falar com Teng Malte Fulminante! Ele pode ser encontrado na Cervejaria Malte do Trovão, no Vale dos Quatro Ventos.$b$bVou marcar a localização dele no seu mapa.', 19865),
(66689, 'ptBR', 'Se você estiver procurando a intendente dos Lavradores, o nome é Gina Garra de Barro. Ela estará à frente do mercado de Meia Colina.$b$bDeixa eu marcar a localização dela no seu mapa.', 'Se você estiver procurando a intendente dos Lavradores, o nome é Gina Garra de Barro. Ela estará à frente do mercado de Meia Colina.$b$bDeixa eu marcar a localização dela no seu mapa.', 19865),
(66690, 'ptBR', 'San Escama Vermelha é o intendente da Ordem da Serpente das Nuvens.$b$bVocê pode encontrá-lo no Arboreto, na Floresta de Jade.$b$bVou marcar a localização dele no seu mapa.', 'San Escama Vermelha é o intendente da Ordem da Serpente das Nuvens.$b$bVocê pode encontrá-lo no Arboreto, na Floresta de Jade.$b$bVou marcar a localização dele no seu mapa.', 19865),
(66691, 'ptBR', 'Hummm, temo saber muito pouco sobre os Klaxxi, mas ouvi cochichos sobre a cidade deles, Klaxxi''vess. bem a oeste, no Ermo do Medo. De repente você encontra o Intendente dos Klaxxi lá.$b$bVou marcar a localização no seu mapa.', 'Hummm, temo saber muito pouco sobre os Klaxxi, mas ouvi cochichos sobre a cidade deles, Klaxxi''vess. bem a oeste, no Ermo do Medo. De repente você encontra o Intendente dos Klaxxi lá.$b$bVou marcar a localização no seu mapa.', 19865),
(66692, 'ptBR', 'O intendente Shado-Pan pode ser encontrado na Guarnição Shado-Pan, nas Estepes de Taolong.$b$bVou marcar a localização dele no seu mapa.', 'O intendente Shado-Pan pode ser encontrado na Guarnição Shado-Pan, nas Estepes de Taolong.$b$bVou marcar a localização dele no seu mapa.', 19865),
(66693, 'ptBR', 'Ah, você quer falar com Jaluu, o Generoso! Ele está bem aqui do lado.', 'Ah, você quer falar com Jaluu, o Generoso! Ele está bem aqui do lado.', 19865),
(66694, 'ptBR', 'O intendente dos Celestiais Majestosos pode ser encontrado aqui no vale. O Sábio Coração Branco está com os outros representantes das facções, na parte de baixo do Terraço do Verão.$b$bVou marcar a localização dele no seu mapa.', 'A intendente dos Celestiais Majestosos pode ser encontrada aqui no vale. A Sábia Botão de Lótus está com os representantes das outras facções, na parte de baixo do Terraço Dourado.$b$bVou marcar a localização dela no seu mapa.', 19865),
(66695, 'ptBR', 'A intendente dos Celestiais Majestosos pode ser encontrada aqui no vale. A Sábia Botão de Lótus está com os representantes das outras facções, na parte de baixo do Terraço do Verão.$b$bVou marcar a localização dela no seu mapa.', 'A intendente dos Celestiais Majestosos pode ser encontrada aqui no vale. A Sábia Botão de Lótus está com os representantes das outras facções, na parte de baixo do Terraço do Verão.$b$bVou marcar a localização dela no seu mapa.', 19865),
(66696, 'ptBR', 'Você procura Tan Shin Tiao. Ela pode ser encontrada no Trono do Conhecimento, acima do Palácio Mogu''shan, aqui no Vale das Flores Eternas.$b$bVou marcar a localização dela no seu mapa.', 'Você procura Tan Shin Tiao. Ela pode ser encontrada no Trono do Conhecimento, acima do Palácio Mogu''shan, aqui no Vale das Flores Eternas.$b$bVou marcar a localização dela no seu mapa.', 19865),
(66697, 'ptBR', 'A intendente de bravura, Comandante Coração de Boi, pode ser encontrada no Templo Niuzao, nas Estepes de Taolong.$b$bVou marcar a localização dela no seu mapa.', 'A intendente de bravura, Comandante Coração de Boi, pode ser encontrada no Templo Niuzao, nas Estepes de Taolong.$b$bVou marcar a localização dela no seu mapa.', 19865),
(66698, 'ptBR', 'Você pode trocar suas marcas da justiça com o Comandante Lo Ping, que pode ser encontrado no Templo Niuzao, nas Estepes de Taolong.$b$bVou marcar a localização dele no seu mapa.', 'Você pode trocar suas marcas da justiça com o Comandante Lo Ping, que pode ser encontrado no Templo Niuzao, nas Estepes de Taolong.$b$bVou marcar a localização dele no seu mapa.', 19865),
(66699, 'ptBR', 'O Intendente de Honra pode ser encontrado no Espinhaço da Serpente, a grande muralha a oeste.$B$BVou marcar a localização deles no seu mapa.', 'O Intendente de Honra pode ser encontrado no Espinhaço da Serpente, a grande muralha a oeste.$B$BVou marcar a localização deles no seu mapa.', 19865),
(66700, 'ptBR', 'Intendentes', 'Intendentes', 19865),
