(73035, 'ptBR', '|TInterface\\Icons\\spell_shadow_destructivesoul.blp:20|t%s lança |cFFFF0000|Hspell:140543|h[Potencializar Machado]|h|r! Fuja!', '', 19865),
(73036, 'ptBR', '|TInterface\\Icons\\warrior_talent_icon_bloodandthunder.blp:20|t%s começa a lançar |cFFFF0000|Hspell:140531|h[Renúncia]|h|r! Quebre as |cFFFF0000Correntes|r para se libertar!', '', 19865),
(73037, 'ptBR', 'Definir', 'Definir', 19865),
(73038, 'ptBR', 'Fazer da Fazenda Sol Cantante seu lar.', 'Fazer da Fazenda Sol Cantante seu lar.', 19865),
(73039, 'ptBR', '<Um pesado tomo com a capa surrada e sujeira embrenhada na encadernação. Parece que Yoon estava seguindo a tradição e fazendo um histórico dos acontecimentos da Fazenda Sol Cantante em seu diário. o livro está aberto na última entrada: uma nota para você!>$B$B"Obrigado por restaurar a terra da minha família à sua glória anterior. Agora estou cuidando de coisas mais importantes. Agora é a sua vez de preencher estas páginas.', '', 19865),
(73040, 'ptBR', 'O Entocador da Caverna começa a chamar Espreitadores Xistosos para auxiliá-lo!', '', 19865),
(73041, 'ptBR', 'O Entocador da Caverna avisa aos Espreitadores Xistosos próximos da sua presença usando |cFFF00000|Hspell:140600|h[Chamado Sônico]|h|r!', '', 19865),
(73044, 'ptBR', '%s começa a lançar um Hino de Silêncio! Esconda-se em uma barreira!', '%s começa a lançar um Hino de Silêncio! Esconda-se em uma barreira!', 19865),
(73045, 'ptBR', 'Pare de lançar feitiços! %s está gerando um |cFFFF0000|Hspell:139869|h[Choque Disruptor]|h|r.', '', 19865),
(73046, 'ptBR', 'Pare de lançar feitiços! %s está gerando um |cFFFF0000|Hspell:139867|h[Choque Disruptor]|h|r.', '', 19865),
