(85763, 'ptBR', 'Você vai me mostrar Ashran?', 'Você vai me mostrar Ashran?', 19865),
(85764, 'ptBR', 'Sua Serraria está sendo atacada!', 'Sua Serraria está sendo atacada!', 19865),
(85765, 'ptBR', 'Sua Arena de Treinamento está sendo atacada!', 'Sua Arena de Treinamento está sendo atacada!', 19865),
(85766, 'ptBR', 'De novo não! Outro ferrão quebrado.', 'De novo não! Outro ferrão quebrado.', 19865),
(85767, 'ptBR', 'Sua Torre dos Magos está sendo atacada!', 'Sua Torre dos Magos está sendo atacada!', 19865),
(85768, 'ptBR', 'Seu Depósito de Ferro-velho está sendo atacado!', 'Seu Depósito de Ferro-velho está sendo atacado!', 19865),
