INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(89496, 'ptBR', 'Hora de bater!', '', 19865),
(89497, 'ptBR', 'Ninguém bate Blook!', '', 19865),
(89498, 'ptBR', '', 'Nós vamos perseverar.', 19865),
(89499, 'ptBR', 'Mas... Blook bate, não batido.', '', 19865),
(89500, 'ptBR', 'Cê batido por Blook.', '', 19865),
(89501, 'ptBR', 'Blookado!', '', 19865),
(89502, 'ptBR', 'Batidus!', '', 19865),
(89503, 'ptBR', 'Salve, batedor de Blook.', '', 19865),
(89504, 'ptBR', 'Oi, chefe da batida.', '', 19865),
(89505, 'ptBR', 'Eu sou Bashiok!', '', 19865),
(89506, 'ptBR', 'Eu... sou... Bashiok.', '', 19865),
(89507, 'ptBR', 'Tu vacilou quando decidiu vir pra Lança de Guerra.', '', 19865),
(89508, 'ptBR', 'Acha que pode me matar com isso? Há!', '', 19865),
(89509, 'ptBR', 'Mais um cretino levou a pior.', '', 19865),
(89510, 'ptBR', 'Sim! Venha com tudo para a morte!', '', 19865),
(89511, 'ptBR', 'Vou abrir um riso largo na sua cara.', '', 19865),
(89512, 'ptBR', 'Tu morre melhor do que luta.', '', 19865),
(89513, 'ptBR', 'Vou desenhar um sorriso no seu cadáver.', '', 19865),
(89514, 'ptBR', 'Você chama isso de estilo de luta? Há há há!', '', 19865),
(89515, 'ptBR', 'Seus aliados não têm senso de humor... nem limite de dor.', '', 19865),
(89516, 'ptBR', 'Burrice tua me desafiar!', '', 19865),
(89517, 'ptBR', 'Eu rio da minha própria derrota!', '', 19865),
(89518, 'ptBR', 'Passa o rodo em geral!', '', 19865),
(89519, 'ptBR', 'Sou tudo que há de mais ORC!', '', 19865),
(89520, 'ptBR', 'Fique aí. Vou queimar seu cadáver depois.', '', 19865),
(89521, 'ptBR', 'Ah, você tombou.', '', 19865),
(89522, 'ptBR', 'Pare de me olhar!', '', 19865),
(89523, 'ptBR', 'Nunca mais lute assim.', '', 19865),
(89524, 'ptBR', 'Que seja você quem ri por último, comandante.', '', 19865),
(89525, 'ptBR', 'Parece que seus soldados estão com medo do meu campeonato de cabeçadas.', '', 19865),
(89526, 'ptBR', 'Como me encontrou?', '', 19865),
(89527, 'ptBR', 'Dagg é o maior ladrão que já andou sobre a terra!', '', 19865),
(89528, 'ptBR', 'Cê não me ver!', '', 19865),
(89529, 'ptBR', 'Como... cê... vê... Dagg... ?', '', 19865),
(89530, 'ptBR', 'Dagg coloca "necessidade".', '', 19865),
(89531, 'ptBR', 'Dagg ver saque primeiro!', '', 19865),
(89532, 'ptBR', 'Você acha mais tesouro?', '', 19865),
(89533, 'ptBR', 'Sempre procura Dagg.', '', 19865),
(89534, 'ptBR', 'Como cê vê através do disfarço de Dagg?', '', 19865),
(89535, 'ptBR', 'Dagg disfarço!', '', 19865),
(89536, 'ptBR', 'Cê melhor chefe que Dagg teve. Dagg é unânime nisso.', '', 19865),
(89537, 'ptBR', 'Cê morreu. Dagg é unânime nisso.', '', 19865),
(89538, 'ptBR', 'Isso deu a Dagg uma ideia pr''um disfarço novo.', '', 19865),
(89539, 'ptBR', 'Presa fresca.', '', 19865),
(89540, 'ptBR', 'Mais comida para o meu ajudante.', '', 19865),
(89541, 'ptBR', 'Ah! Uma coisa para testar minhas novas armadilhas.', '', 19865),
(89542, 'ptBR', 'Foi... uma péssima... ideia...', '', 19865),
(89543, 'ptBR', 'Patético.', '', 19865),
(89544, 'ptBR', 'Escolheu o lado errado, idiota.', '', 19865),
(89545, 'ptBR', 'Ainda está no topo da cadeia alimentar, comandante?', '', 19865),
(89546, 'ptBR', 'Pelo Kirin Tor!', '', 19865),
(89547, 'ptBR', 'O que acha que irá conseguir?', '', 19865),
(89548, 'ptBR', 'Nossa, acha mesmo que irá vencer?', '', 19865),
(89549, 'ptBR', 'Fascinante. Quanta barbárie.', '', 19865),
(89550, 'ptBR', 'Você sabe que eu não estou aqui de verdade, não é?', '', 19865),
(89551, 'ptBR', 'Estou perdendo o controle da minha imagem...', '', 19865),
(89552, 'ptBR', 'Bom, foi um resultado interessante.', '', 19865),
(89553, 'ptBR', 'Se tivesse praticado, você poderia até ter sido uma ameaça mais séria.', '', 19865),
(89554, 'ptBR', 'Bom ver você, comandante.', '', 19865),
(89555, 'ptBR', 'Saudações, comandante.', '', 19865),
(89556, 'ptBR', '', 'Vou queimar um sorriso nesta sua cara.', 19865),
(89557, 'ptBR', '', 'Hahahaha!', 19865),
(89558, 'ptBR', '', 'Seu crânio será meu.', 19865),
(89559, 'ptBR', '', 'Eu vou fazer você rir.', 19865),
(89560, 'ptBR', '', 'Vou... morrer... de rir!', 19865),
(89561, 'ptBR', '', 'Queime meu corpo... fique com... meu crânio.', 19865),
(89562, 'ptBR', '', 'Não morra ainda. Ainda não acabei.', 19865),
(89563, 'ptBR', '', 'Diga "oi" pro "adeusinho"!', 19865),
(89564, 'ptBR', '', 'Quando você morrer, posso ficar com o seu crânio?', 19865),
(89565, 'ptBR', '', 'Que o fogo leve seus inimigos!', 19865),
(89566, 'ptBR', '', 'Pelo Lobo do Gelo!', 19865),
(89567, 'ptBR', '', 'Espíritos, guiem-me!', 19865),
(89568, 'ptBR', '', 'Você tentou dar um passo maior do que a perna, $t.', 19865),
(89569, 'ptBR', '', 'Estamos prontos!', 19865),
(89570, 'ptBR', '', 'Pela honra!', 19865),
(89571, 'ptBR', '', 'Tolo desonrado.', 19865),
(89572, 'ptBR', '', 'Vitória ao Lobo do Gelo.', 19865),
(89573, 'ptBR', '', 'Asha... estou chegando...', 19865),
(89574, 'ptBR', '', 'Salve.', 19865),
(89575, 'ptBR', 'Isso é que é um ambiente cheio de alvos!', '', 19865),
(89576, 'ptBR', 'Vim buscar você, $n!', '', 19865),
(89577, 'ptBR', 'Pro... chão...', '', 19865),
(89578, 'ptBR', 'Machado perfeito!', '', 19865),
(89579, 'ptBR', 'Solicito ataque aéreo.', '', 19865),
(89580, 'ptBR', 'Você pode ser meu copiloto quando quiser.', '', 19865),
(89581, 'ptBR', 'Vejamos se você aguenta o recado.', '', 19865),
(89582, 'ptBR', 'Será que você dobra no meio? Vejamos.', '', 19865),
(89583, 'ptBR', 'Um desafiante?', '', 19865),
(89584, 'ptBR', 'Boa... luta...', '', 19865),
(89585, 'ptBR', 'Chute na cabeça.', '', 19865),
(89586, 'ptBR', 'Você deve ser mais veloz que o murro.', '', 19865),
(89587, 'ptBR', 'Você não tinha a menor chance.', '', 19865),
(89588, 'ptBR', 'Estes seus soldados estão moles demais.', '', 19865),
(89589, 'ptBR', 'Aguardarei ansiosamente pelo próximo desafio, Comandante.', '', 19865),
(89590, 'ptBR', 'Lug''dol está por perto.', '', 19865),
(89591, 'ptBR', '', 'Tiro e queda.', 19865),
(89592, 'ptBR', '', 'Não tem escapatória.', 19865),
(89593, 'ptBR', '', 'Tenho o veneno ideal para você.', 19865),
(89594, 'ptBR', '', 'Que desperdício de flechas.', 19865),
(89595, 'ptBR', '', 'Treino de pontaria.', 19865),
(89596, 'ptBR', '', 'Queime... meu corpo...', 19865),
(89597, 'ptBR', '', 'Cubra os meus rastros.', 19865),
(89598, 'ptBR', 'Tu já morreu. Só não percebeu ainda.', '', 19865),
(89599, 'ptBR', 'Tu vai morrer. Nada pessoal.', '', 19865),
(89600, 'ptBR', 'Pelo Chefe Guerreiro!', '', 19865),
(89601, 'ptBR', 'Pela Horda!', '', 19865),
(89602, 'ptBR', 'Tu não vai nem ver de onde veio.', '', 19865),
(89603, 'ptBR', 'Teu sangue vai jorrar logo, logo.', '', 19865),
(89604, 'ptBR', 'Tu vai ter que... se esforçar mais... se quiser me... matar.', '', 19865),
(89605, 'ptBR', 'Tu já morreu!', '', 19865),
(89606, 'ptBR', 'Menos um.', '', 19865),
(89607, 'ptBR', 'Ding!', '', 19865),
(89608, 'ptBR', 'Taz''dingo!', '', 19865),
(89609, 'ptBR', 'Fique de olho nas sombras, chefia.', '', 19865),
(89610, 'ptBR', 'É nóis, chefia.', '', 19865),
(89611, 'ptBR', 'Vol''jin manda seus cumprimentos.', '', 19865),
(89612, 'ptBR', 'Posso guardar seu manto? Não? Pois não, comandante, fique à vontade para continuar sujando de lama o chão que passei a manhã inteira encerando.', '', 19865),
(89613, 'ptBR', 'Você se aliaria ao inimigo, Tormmok? Você está traindo seu rei!', '', 19865),
(89614, 'ptBR', 'É, vamos... incinerar e esmagalhar eles todos!', '', 19865),
(89615, 'ptBR', 'Parem de... se bater!', '', 19865),
(89616, 'ptBR', 'Bombeia a forja pra superacelerar!', '', 19865),
(89617, 'ptBR', 'Eu voltarei!', '', 19865),
(89618, 'ptBR', 'Espera só até eu dar um jeito neles.', '', 19865),
(89619, 'ptBR', 'Opa! Eu ainda não tinha acabado...', '', 19865),
(89620, 'ptBR', 'Não... assim não....', '', 19865),
(89621, 'ptBR', 'Eu vou DETONAR vocês!', '', 19865),
(89622, 'ptBR', 'Ahh, eu tava esperando algo para pulverizar e incinerar!', '', 19865),
(89623, 'ptBR', 'Fracote indefeso!', '', 19865),
(89624, 'ptBR', 'Só pode haver... dois! Ha ha ha!', '', 19865),
(89625, 'ptBR', 'Hah, você acha isso foi bom? Espera só então!', '', 19865),
(89626, 'ptBR', 'Se o bicho sangra, a gente pode matar!', '', 19865),
(89627, 'ptBR', 'Me escuta agora... e acredita depois...', '', 19865),
(89628, 'ptBR', 'Vou estraçalhar todos os seus ossos.', '', 19865),
(89629, 'ptBR', 'Ah, mas nem pensar.', '', 19865),
(89630, 'ptBR', 'Vou arrebentar esse traste!', '', 19865),
(89631, 'ptBR', 'Vem cá! Vou te mostrar só uma coisa!', '', 19865),
(89632, 'ptBR', 'Tu vai levar uma bica no meio das pernas.', '', 19865),
(89633, 'ptBR', 'Tu tá querendo, não tá?', '', 19865),
(89634, 'ptBR', 'Ah é, ninguém mandou.', '', 19865),
(89635, 'ptBR', 'Vou fazer igualzinho com a tua mãe!', '', 19865),
(89636, 'ptBR', 'E ai de tu, se levantar!', '', 19865),
(89637, 'ptBR', 'Har! Apagou.', '', 19865),
(89638, 'ptBR', '%s arrota.', '', 19865),
(89639, 'ptBR', 'Ah-hyup!', '', 19865),
(89640, 'ptBR', 'Fala que eu atiro!', '', 19865),
(89641, 'ptBR', 'Já tá na hora do rango?', '', 19865),
(89642, 'ptBR', 'Não me deixam chegar nem perto da reserva de pólvora. Pra que reservar pólvora? Aí que eu te pergunto...', '', 19865),
(89643, 'ptBR', 'Sua cura é uma BOSTA!', '', 19865),
(89644, 'ptBR', 'Eu não tenho rei. Eu escolhi o meu lado.', '', 19865),
(89645, 'ptBR', 'Roubei o chapéu.', '', 19865),
(89646, 'ptBR', '%s guincha.', '', 19865),
(89647, 'ptBR', 'EU. SOU. BASHIOK!', '', 19865),
(89648, 'ptBR', 'Eu sou Bashiok.', '', 19865),
(89649, 'ptBR', 'Eu SOU Bashiok.', '', 19865),
(89650, 'ptBR', 'Ahahahaha!', '', 19865),
(89651, 'ptBR', 'Insetos, vocês não passam de insetos para mim!', '', 19865),
(89652, 'ptBR', 'Mais, tragam mais para morrer pelo fio da minha arma!', '', 19865),
(89653, 'ptBR', 'É uma estupidez se opor a mim, fracote!', '', 19865),
(89654, 'ptBR', 'Fácil demais!', '', 19865),
(89655, 'ptBR', 'Já podes desistir, Socrethar. Foste sobrepujado.', '', 19865),
(89656, 'ptBR', 'O império... se erguerá novamente!', '', 19865),
(89657, 'ptBR', 'Tua vontade não é nada aqui.', '', 19865),
(89658, 'ptBR', 'Vitória ou morte!', '', 19865),
(89659, 'ptBR', 'Corra enquanto pode.', '', 19865),
(89660, 'ptBR', 'Ninguém é páreo para mim!', '', 19865),
(89661, 'ptBR', 'Você devia ter corrido.', '', 19865),
(89662, 'ptBR', 'Vou lhe apresentar o martelo!', '', 19865),
(89663, 'ptBR', 'Forjarei uma arma em sua honra, comandante.', '', 19865),
(89664, 'ptBR', 'Vi que chegou um carregamento de minério. Farei bom uso dele.', '', 19865),
(89665, 'ptBR', 'O que quer de mim?', '', 19865),
(89666, 'ptBR', 'Obrigado mais uma vez por ter me libertado.', '', 19865),
(89667, 'ptBR', 'Comandante, jamais poderei pagar esta dívida.', '', 19865),
(89668, 'ptBR', 'Ainda não me acostumei a poder ver o céu o dia todo.', '', 19865),
(89669, 'ptBR', 'Pelo menos... morrerei... livre.', '', 19865),
(89670, 'ptBR', 'Poderia pegar minha espada, comandante? Não consigo entrar no círculo rúnico que Dar''gud colocou em torno dela.', '', 19865),
(89671, 'ptBR', 'Esses orcs estão vivos ou... mortos-vivos?', 'Esses orcs estão vivos ou... mortos-vivos?', 19865),
(89672, 'ptBR', 'Sou eternamente grata.', '', 19865),
(89673, 'ptBR', 'Sobrevivi mais um dia. Você tem meu agradecimento!', '', 19865),
(89674, 'ptBR', 'As fúrias nunca se esquecerão disso. Agradeço muito.', '', 19865),
(89675, 'ptBR', 'Você acabou de ganhar um poderoso aliado, camarada.', '', 19865),
(89676, 'ptBR', 'Salvando', 'Salvando', 19865),
(89677, 'ptBR', 'POSIÇÃO DE SENTIDO!', '', 19865),
(89678, 'ptBR', 'VOLTEM AO TRABALHO!', '', 19865),
(89679, 'ptBR', 'ESTOU CERCADO DE NANICOS PREGUIÇOSOS!', '', 19865),
(89680, 'ptBR', '', 'Está vendo aquela luz adiante? Deve ser isso!', 19865),
(89681, 'ptBR', '', 'Aquela luz adiante deve ser a localização do cristal. Gorjavernus deve estar lá.', 19865),
(89682, 'ptBR', 'O cheiro de sangue atrai mordiscantes gorens!', '', 19865),
(89683, 'ptBR', 'Você pagará imensamente por sua interferência, mortal.', '', 19865),
(89684, 'ptBR', '', 'Bom trabalho! Vamos levar a Luz do Êxodo para um local seguro.', 19865),
(89685, 'ptBR', '', 'Você ouve um assovio bem baixo vindo do sul.', 19865),
(89686, 'ptBR', '', 'E não volte nunca mais, escória demoníaca. Comandante, vamos tirar a Luz do Êxodo daqui.', 19865),
(89687, 'ptBR', '|TInterface\\Icons\\Ability_Druid_EmpoweredTouch:20|t Yalnu começa a canalizar |cFFFF0404|Hspell:169613|h[Gênese]|h|r.', '', 19865),
(89688, 'ptBR', 'Que saco, esses peões nas docas devem estar ensebando.', 'Que saco, esses peões nas docas devem estar ensebando.', 19865),
(89689, 'ptBR', 'O que houve? Nosso maquinário parou.', 'O que houve? Nosso maquinário parou.', 19865),
(89690, 'ptBR', 'Manda um dos nanicos lá nas docas para verificar.', 'Manda um dos nanicos lá nas docas para verificar.', 19865),
(89691, 'ptBR', 'Manda um dos nanicos lá na fornalha para verificar.', 'Manda um dos nanicos lá na fornalha para verificar.', 19865),
(89692, 'ptBR', 'O que aconteceu com as prensas? Elas esfriaram!', 'O que aconteceu com as prensas? Elas esfriaram!', 19865),
(89693, 'ptBR', 'Cadê o Encarregado Feldspar? Alguém precisa colocar isso pra funcionar de novo!', 'Cadê o Encarregado Feldspar? Alguém precisa colocar isso pra funcionar de novo!', 19865),
(89694, 'ptBR', 'Tirem eles de perto de mim.', '', 19865),
(89695, 'ptBR', 'Não vou ser o primeiro a morrer de novo.', '', 19865),
(89696, 'ptBR', 'Fique longe!', '', 19865),
(89697, 'ptBR', 'Pare. Pare... é tudo que peço.', '', 19865),
(89698, 'ptBR', 'O saque é meu.', '', 19865),
(89699, 'ptBR', 'Ufa.', '', 19865),
(89700, 'ptBR', 'Peguei um. Pessoal, eu peguei um!', '', 19865),
(89701, 'ptBR', '"Senhor da Guerra" Schweitzer. Gostei...', '', 19865),
(89702, 'ptBR', 'Uma passo a menos para o posto de Grão-marechal.', '', 19865),
(89703, 'ptBR', 'Esta guarnição tá precisando de um trampolim.', '', 19865),
(89704, 'ptBR', 'Quando você vai mandar fazer o campinho da pelada?', '', 19865),
(89705, 'ptBR', 'Por que não construirmos uma cervejaria?', '', 19865),
(89706, 'ptBR', 'Comandante, os homens querem um tobogã. No caso, "homens" quer dizer "eu".', '', 19865),
(89707, 'ptBR', 'Quando você vai mandar fazer a arena de rock pesado?', '', 19865),
(89708, 'ptBR', 'Que tal um parque, que nem o de Ventobravo? Quer dizer, não "que nem" o de Ventobravo.', '', 19865),
(89709, 'ptBR', 'Comandante, venho lhe pedir desculpas pelo concurso de tabardo molhado de ontem à noite.', '', 19865),
(89710, 'ptBR', '... de novo...?', '', 19865),
(89711, 'ptBR', 'Chupa meu mana, trouxa!', 'Chupa meu mana, trouxa!', 19865),
(89712, 'ptBR', 'Deixa comigo.', 'Deixa comigo.', 19865),
(89713, 'ptBR', 'Toma essa!', 'Toma essa!', 19865),
(89714, 'ptBR', 'Arrebenta esse troço!', 'Arrebenta esse troço!', 19865),
(89715, 'ptBR', 'Fracote.', 'Fracote.', 19865),
(89716, 'ptBR', 'HA HA! Por Gnomeregan!', 'HA HA! Por Gnomeregan!', 19865),
(89717, 'ptBR', 'Patético.', 'Patético.', 19865),
(89718, 'ptBR', 'Que dó.', 'Que dó.', 19865),
(89719, 'ptBR', 'Morreu!', 'Morreu!', 19865),
(89720, 'ptBR', 'Que tal uma reforma nas instalações mágicas?', 'Que tal uma reforma nas instalações mágicas?', 19865),
(89721, 'ptBR', 'Comandante, como faço para entrar nas missões mais... lucrativas?', 'Comandante, como faço para entrar nas missões mais... lucrativas?', 19865),
(89722, 'ptBR', 'Meus itens estão encantados e equipados com joias, comandante!', 'Meus itens estão encantados e equipados com joias, comandante!', 19865),
(89723, 'ptBR', 'Quando tiver um tempo, comandante, eu gostaria de sugerir algumas formas de aprimorar seu equipamento.', 'Quando tiver um tempo, comandante, eu gostaria de sugerir algumas formas de aprimorar seu equipamento.', 19865),
(89724, 'ptBR', 'Estou... sem... manaaaaa...', 'Estou... sem... manaaaaa...', 19865),
(89725, 'ptBR', '', 'É meu.', 19865),
(89726, 'ptBR', '', 'Me dê cobertura!', 19865),
(89727, 'ptBR', '', 'Quando quiser...', 19865),
(89728, 'ptBR', '', 'Au! Bem no pescoço!', 19865),
(89729, 'ptBR', '', 'Aah! No pescoço.', 19865),
(89730, 'ptBR', '', 'Aah! No pescoço.', 19865),
(89731, 'ptBR', '', 'Ai! Atravessou a cabeça.', 19865),
(89732, 'ptBR', '', 'Deitou.', 19865),
(89733, 'ptBR', '', 'Sou sua maior fã, comandante.', 19865),
(89734, 'ptBR', '', 'Estou tão feliz de estar aqui. Meu último grupo... acho que estão mortos.', 19865),
(89735, 'ptBR', '', 'Lua Negra é tão lindo!', 19865),
(89736, 'ptBR', '', 'Esta guarnição é beeem melhor que a do Almirante Taylor.', 19865),
(89737, 'ptBR', '', '... socorro!', 19865),
(89738, 'ptBR', 'Leve-me até o Posto Avançado Lança de Guerra!', 'Leve-me até o Posto Avançado Lança de Guerra!', 19865),
(89739, 'ptBR', 'Rápido, $n, o grão-marechal quer vê-$Glo:la; imediatamente em Escudo Tonante!', 'Rápido, $n, o grão-marechal quer vê-$Glo:la; imediatamente em Escudo Tonante!', 19865),
(89740, 'ptBR', '', 'Pão fresco! Olha o pão fresco!', 19865),
(89741, 'ptBR', '', 'Integral e quentinho!', 19865),
(89742, 'ptBR', '', 'Roliiinhos, boliiinhos, pããão! Fornada quentiiinha!', 19865),
(89743, 'ptBR', '', 'Venham, venham! Peguem o pão quentinho!', 19865),
(89744, 'ptBR', 'Ouvi falar que Harrison Jones ainda não está nem próximo de encontrar aquele artefato.', '', 19865),
(89745, 'ptBR', '', 'Quanto tempo ele pretende demorar? Não podemos ficar aqui nesse buraco para sempre com a Horda no nosso pescoço.', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(89746, 'ptBR', 'Espero que não demore muito mais. Não vejo minha família em Ventobravo há meses.', '', 19865),
(89747, 'ptBR', '', 'A Horda está ficando mais ousada a cada dia. Eles atacaram outros dos nossos postos avançados hoje de manhã.', 19865),
(89748, 'ptBR', 'Será que esses vira-latas esqueceram que nós temos um tratado?', '', 19865),
(89749, 'ptBR', '', 'Parece. Acho que eles temem que, se encontrarmos o artefato, acabemos por usá-lo contra eles.', 19865),
(89750, 'ptBR', 'Se continuarem atacando os nossos soldados desse jeito, eles podem muito bem nos levar a isso.', '', 19865),
(89751, 'ptBR', 'Flanquear e destruir!', '', 19865),
(89752, 'ptBR', 'Aniquile-os.', '', 19865),
(89753, 'ptBR', 'Por Orgrimmar, pela Horda, pela glória de nossos pais!', '', 19865),
(89754, 'ptBR', 'Vou dar um fim nisso.', '', 19865),
(89755, 'ptBR', 'Deixe os ossos para distrair os lobos.', '', 19865),
(89756, 'ptBR', '%s cospe no cadáver.', '', 19865),
(89757, 'ptBR', 'Sempre é doce, o gosto da vitória.', '', 19865),
(89758, 'ptBR', 'Pode ficar com o corpo, mas os dentes são meus.', '', 19865),
(89759, 'ptBR', 'Nada mais bonito do que sangue sobre a neve.', '', 19865),
(89760, 'ptBR', 'Glória ao poder da Horda, comandante!', '', 19865),
(89761, 'ptBR', 'Ninguém ousa questionar sua força.', '', 19865),
(89762, 'ptBR', 'Fogofrio está dominada pela Horda. Se precisarmos construir outra guarnição, eu me voluntario a compor a vanguarda.', '', 19865),
(89763, 'ptBR', 'Glória ao novo Chefe Guerreiro! Ainda que não seja orc.', '', 19865),
(89764, 'ptBR', 'Envie-me para o fronte. Minha força está às suas ordens.', '', 19865),
(89765, 'ptBR', 'Nós veremos nossos inimigos prostrados aos nossos pés! Ouviremos o lamento de... quem se dignar a se lamentar por estes animais. Mal posso esperar para ouvir seu lamento! Haha! Lamentadores são divertidos.', '', 19865),
(89766, 'ptBR', 'Minha vida... pertence... À HORDA!', '', 19865),
(89767, 'ptBR', '', 'Iau! Peguem-nos!', 19865),
(89768, 'ptBR', '', 'Ai! Ai! Estou lutando!', 19865),
(89769, 'ptBR', '', 'Eles estão na base! Estão quebrando todas as minhas coisas!', 19865),
(89770, 'ptBR', '', 'Estou conjurando feitiços!', 19865),
(89771, 'ptBR', '', 'É, foi desse jeitinho.', 19865),
(89772, 'ptBR', '', 'E eu não estava nem prestando atenção.', 19865),
(89773, 'ptBR', '', 'Oba!', 19865),
(89774, 'ptBR', '', 'Mortão.', 19865),
(89775, 'ptBR', '', 'Oi!', 19865),
(89776, 'ptBR', '', 'Aaai, gostei do seu equipamento.', 19865),
(89777, 'ptBR', '', 'Nossa, adorei sua casa.', 19865),
(89778, 'ptBR', '', 'Peço desculpas pelos demônios terem incendiado suas coisas. Eles botam fogo em tudo.', 19865),
(89779, 'ptBR', '', 'Mas... mas... não!', 19865),
(89780, 'ptBR', 'Eu os reduzirei a pó.', '', 19865),
(89781, 'ptBR', 'He... hehe... hehe HA!', '', 19865),
(89782, 'ptBR', 'Ah, como é doce e gloriosa a morte!', '', 19865),
(89783, 'ptBR', 'Olha só o que acabou de chegar: material novo!', '', 19865),
(89784, 'ptBR', 'Separe uma parte pra mim!', '', 19865),
(89785, 'ptBR', 'Deixe os membros, eu vou usar depois.', '', 19865),
(89786, 'ptBR', 'Rosto: derretido.', '', 19865),
(89787, 'ptBR', 'Se tiver sobrado miolo, guarde um pouco pra mim.', '', 19865),
(89788, 'ptBR', 'Dá para construir uma criatura maravilhosa com este material.', '', 19865),
(89789, 'ptBR', 'Estes órgãos vão dar uma grana.', '', 19865),
(89790, 'ptBR', 'Meu trabalho está progredindo a largos passos, em Draenor. Aqui, não preciso burlar nenhuma "lei".', '', 19865),
(89791, 'ptBR', 'Eu estava pensando, será que eu não poderia conduzir uns "experimentos" com alguns guardas...?', '', 19865),
(89792, 'ptBR', 'Quer um pouco de fluido embalsamador, comandante?', '', 19865),
(89793, 'ptBR', 'Vou lhe fazer uma proposta: em vez de cinco guardas normais, que tal costurar todos num guardão gigante e estabanado? Pense com calma!', '', 19865),
(89794, 'ptBR', 'Adoro o friozinho da Serra Fogofrio, conserva os cadáveres.', '', 19865),
(89795, 'ptBR', 'Que tal essa força, comandante? E esses braços musculosos aí, hein? Se quiser um bracinho extra, já sabe, é só falar.', '', 19865),
(89796, 'ptBR', 'Quase todos os seguidores tem rins redundantes. Você se importaria se eu pegasse alguns "emprestados"? A banheira já está preparada.', '', 19865),
(89797, 'ptBR', 'Eu vou assombrar você!', '', 19865),
(89798, 'ptBR', 'É meu!', '', 19865),
(89799, 'ptBR', '*Cof* Estamos lutando contra alguma coisa?', '', 19865),
(89800, 'ptBR', '*Cof cof* Hã? A gente tá lutando?', '', 19865),
(89801, 'ptBR', 'Aí, tira a mão que é meu!', '', 19865),
(89802, 'ptBR', 'Pode crer.', '', 19865),
(89803, 'ptBR', 'Pira na onda da morte, mermão.', '', 19865),
(89804, 'ptBR', '$n (Aliança) saqueou o |c00FFFF00|Hspell:168506|h[Artefato Antigo]|h|r!', '', 19865),
(89805, 'ptBR', 'Ahaaam!', '', 19865),
(89806, 'ptBR', 'Vou comer você na janta.', '', 19865),
(89807, 'ptBR', '$n (Horda) saqueou o |c00FFFF00|Hspell:168506|h[Artefato Antigo]|h|r!', '', 19865),
(89808, 'ptBR', 'Cuidado, o comandante!', '', 19865),
(89809, 'ptBR', 'Eu juro que não fui eu.', '', 19865),
(89810, 'ptBR', 'Comandante! Tu não viu nada de estranho, não, né? Eu tô de boassa, geral, aliás, de boa na lagoa.', '', 19865),
(89811, 'ptBR', 'Aí, comandante, tá no rango?', '', 19865),
(89812, 'ptBR', 'Pssst! Cala boca, o comandante tá vindo. Pst! Opa, ei.', '', 19865),
(89813, 'ptBR', '%s tem um ataque de tosse.', '', 19865),
(89814, 'ptBR', 'Pela Ali... ahem! Horda, pela Horda!', '', 19865),
(89815, 'ptBR', 'Por alguém!', '', 19865),
(89816, 'ptBR', 'O que esses caras estão fazendo aqui?', '', 19865),
(89817, 'ptBR', 'Não me mate! Eu sou um sacerdote!', '', 19865),
(89818, 'ptBR', 'Ontem à noite foi a maior loucura, hein? Quando foi que começou a nevar em Lua Negra?', '', 19865),
(89819, 'ptBR', 'Comandante eu, é... chega mais... psst... acho que tem espiões da Horda aqui na base.', '', 19865),
(89820, 'ptBR', 'Qual é a desse monte de crânio e espeto. Parece coisa de... o Rei tá sabendo disso?', '', 19865),
(89821, 'ptBR', 'Comandante, não sei quem foi que você contratou, mas, pra mim, isto aqui tá parecendo base da Horda.', '', 19865),
(89822, 'ptBR', 'Boas-vindas, gladiadores! Vocês foram escolhidos pelo Imperador Mar''gok em pessoa para participar dos jogos gladiatórios! Tamanha honra reserva-se apenas aos mais sanguinários e ferozes lutadores de Draenor. Que vocês alcancem a honra e a vitória, no dia de hoje!', '', 19865),
(89823, 'ptBR', 'Encontrei uma patrulha da Horda tentando contornar um dos nossos postos avançados hoje.', '', 19865),
(89824, 'ptBR', '', 'É, é? Eles viram você?', 19865),
(89825, 'ptBR', 'É, um deles me viu. Faca no olho e tudo resolvido.', '', 19865),
(89826, 'ptBR', 'Leve-me até o Castelo Escudo Tonante.', 'Leve-me até o Castelo Escudo Tonante.', 19865),
(89827, 'ptBR', 'Subam na plataforma. Ela os levará à arena, onde a glória os espera!', '', 19865),
(89828, 'ptBR', '', 'Deixa eu adivinhar: sutileza não é o seu forte.', 19865),
(89829, 'ptBR', 'Consegui uma bela faca nova quando estava fazendo o reconhecimento hoje.', '', 19865),
(89830, 'ptBR', '', 'Sério? Onde?', 19865),
(89831, 'ptBR', 'Na barriga de um goren.', '', 19865),
(89832, 'ptBR', 'Quando o elevador começar a subir, esta sala será inundada de gás venenoso, matando todos que ficarem para trás. Sugiro que subam na plataforma.', '', 19865),
(89833, 'ptBR', 'Isto mesmo, espremam-se aí em cima. Vocês não vão querer ficar aqui embaixo. Não mesmo, não depois que soltarmos o gás venenoso para eliminar os covardes.', '', 19865),
(89834, 'ptBR', 'Subam na plataforma! O elevador iniciará a ascensão gloriosa rumo à arena logo, logo!', '', 19865),
(89835, 'ptBR', 'Boa sorte, aventureiros! Que o mais forte conquiste a glória do Coliseu!', '', 19865),
(89836, 'ptBR', '', 'Você achou uma faca no estômago de um goren? O que fez você pensar em abrir o bicho?', 19865),
(89837, 'ptBR', 'Onde mais você acha eles guardam o saque?', '', 19865),
(89838, 'ptBR', 'Eu... vejo...', '', 19865),
(89839, 'ptBR', 'Não sei por que o Harrison Jones nos pediu para vir até aqui e ajudar na escavação. Não consigo procurar um artefato que seja sem que um ogro tente me partir ao meio!', '', 19865),
(89840, 'ptBR', 'Se você acha que os ogros são ruins, devia ver os espíritos ôgricos perto do altar. Está bem ruim, lá.', '', 19865),
(89841, 'ptBR', 'Espíritos ôgricos? Luz, essa ilha tem mesmo uns jeitos criativos de matar.', '', 19865),
(89842, 'ptBR', 'Ouvi dizer que estão descobrindo uns negócios interessantes nas minas. Mas o Harrison está mantendo a coisa na moita.', '', 19865),
(89843, 'ptBR', 'O que você acha que é?', '', 19865),
(89844, 'ptBR', 'Eu falei com um dos operários, e ele disse que o lugar é assombrado. Eles dizem que há gente desaparecendo, e também está havendo acidentes.', '', 19865),
(89845, 'ptBR', 'Coisas estranhas. Paredes sólidas de uma caverna desabando de repente em um escavador. Maquinário defeituoso mastigando o operador. E eles dizem que isso acontece com mais frequência quanto mais fundo se vai.', '', 19865),
(89846, 'ptBR', 'Não gosto nada disso. Acho que vou ficar só aqui na estalagem.', '', 19865),
(89847, 'ptBR', 'É. Nesse ponto eu não vou discutir.', '', 19865),
(89848, 'ptBR', 'Acidentes? Que tipo de acidentes?', '', 19865),
(89849, 'ptBR', 'Como você chegou aqui?', '', 19865),
(89850, 'ptBR', 'Está quieto aqui, você não acha? Quase... quieto demais.', '', 19865),
(89851, 'ptBR', 'Envenenamento', 'Envenenamento', 19865),
(89852, 'ptBR', 'Depressa, $n, Volrath disse para você voltar para a Lança de Guerra imediatamente!', 'Depressa, $n, Volrath disse para você voltar para a Lança de Guerra imediatamente!', 19865),
(89853, 'ptBR', 'Kronus nasceu! Bom trabalho, $n.', '', 19865),
(89854, 'ptBR', 'Olhe ao redor. Não está vendo que já vencemos?', '', 19865),
(89855, 'ptBR', 'Os fragmentos de artefatos contêm poder mágico suficiente para restaurar essa Fúria da Terra à força total.$B$BQuantos você nos trouxe?', '', 19865),
(89856, 'ptBR', 'Notícias do front, senhor!', '', 19865),
(89857, 'ptBR', 'A Aliança não pode ficar com Ashran, $c. O poder de qualquer artefato ôgrico aqui vai ser da gente.', '', 19865),
(89858, 'ptBR', '', 'Soldados da Aliança, peguem rápido os suprimentos deles e tomem um grifo de volta para a Bastilha Escudo Tonante!', 19865),
(89859, 'ptBR', '', 'Soldados da Aliança, precisamos partir agora! Há reforços da Horda a caminho!', 19865),
(89860, 'ptBR', '', 'Retirada, rápido, reforços da Aliança estão chegando em breve!', 19865),
(89861, 'ptBR', '', 'Saqueiem os suprimentos deles e peguem uma mantícora de volta para o Posto Avançado Lança de Guerra!', 19865),
(89862, 'ptBR', 'Podem afrouxar o cinto, gurias! Hoje a janta vai ser um banquete!', '', 19865),
(89863, 'ptBR', '', 'Eu atiro para matar.', 19865),
(89864, 'ptBR', '', 'O que você tá olhando?', 19865),
(89865, 'ptBR', 'Por tudo que é mais profano, o que é aquela coisa?', '', 19865),
(89866, 'ptBR', '', 'Ninguém passa a perna em mim.', 19865),
(89867, 'ptBR', '', 'Que a Dama Sombria nos proteja... é pior do que eu pensava.', 19865),
(89868, 'ptBR', 'Parece que os ogros do Aclive do Brutamontes estão usando grandes feras para arremessar pedras gigantes em nossos soldados!', '', 19865),
(89869, 'ptBR', 'Então os ogros gostam de jogar pedra, é?', '', 19865),
(89870, 'ptBR', 'Vou mandar o Rebimboca aprontar um dos tanques dele e fazer uma visitinha. Vamos ver como as pedras deles se saem contra o aço.', '', 19865),
(89871, 'ptBR', 'Obrigado pelo relatório, soldado. Pode voltar a campo.', '', 19865),
(89872, 'ptBR', 'Sim, senhor!', '', 19865),
(89873, 'ptBR', 'Algo que lembra seiva escorre da boca de Acantus.', '', 19865),
(89874, 'ptBR', 'Senhor, nossos batedores relatam que as forças da Horda estão trabalhando para fortalecer uma antiga fúria da terra!', '', 19865),
(89875, 'ptBR', 'Você disse fúria da terra? Isso é um problema.', '', 19865),
(89876, 'ptBR', 'Vou precisar me reunir com nossos aliados druidas. O anciente que eles estão despertando pode ser nossa única forma de derrotar tal força.', '', 19865),
(89877, 'ptBR', '$n serviu um Festim Selvagem.', '$n serviu um Festim Selvagem.', 19865),
(89878, 'ptBR', 'Estão chegando relatórios sobre uma fera gigantesca que habita a mina dos ogros.', '', 19865),
(89879, 'ptBR', 'Nenhum dos nossos batedores conseguiu dar uma boa olhada nela, mas a coisa é tão grande que mal cabe na caverna!', '', 19865),
(89880, 'ptBR', 'Precisaremos alertar nossos homens que estiverem lutando nas proximidades da caverna. Bom trabalho, soldado.', '', 19865),
(89881, 'ptBR', 'Comandante, eu sugiro abrir a cancha. Aqui não é lugar pra querer se abancar.', '', 19865),
(89882, 'ptBR', '', 'Repugnante. Comandante, eu dou cobertura enquanto você pega o que sobrou daquela... coisa.', 19865),
(89883, 'ptBR', 'Harrison Jones relata que, embora tenha recebido diversos fragmentos, não está progredindo na descoberta da localização do artefato que procuramos.', '', 19865),
(89884, 'ptBR', 'Ele solicita mais homens para ajudar na busca.', '', 19865),
(89885, 'ptBR', 'Ele pede como se tivéssemos um suprimento infinito de aventureiros à disposição. Ele vai ter quem quer que se voluntarie para ajudar. Os nossos soldados já estão espalhados demais graças à ameaça da Horda.', '', 19865),
(89886, 'ptBR', 'As sombras renovaram minhas forças.', '', 19865),
(89887, 'ptBR', 'Leorajh se tornou ainda mais forte!', '', 19865),
(89888, 'ptBR', 'Sim... eu me aproximo das sombras mais e mais.', '', 19865),
(89889, 'ptBR', 'Leorajh, mais poderoso do que nunca!', '', 19865),
(89890, 'ptBR', 'É aquela que procuramos. O bastão dela é a chave.', '', 19865),
(89891, 'ptBR', 'Sim... excelente. RaAWK!', '', 19865),
(89892, 'ptBR', 'As contas de oração de Leorajh!', '', 19865),
(89893, 'ptBR', 'Comandante, conseguimos!', '', 19865),
(89894, 'ptBR', '', 'Obrigada, doçura. Agora, de volta à batalha!', 19865),
(89895, 'ptBR', '', 'Eu estava quase morrendo. Obrigada!', 19865),
(89896, 'ptBR', 'Muito bem, Twix... vamos dar uma olhada no famoso predador Aogexon!', '', 19865),
(89897, 'ptBR', 'Não somos os únicos com prisioneiros, $c.$B$BDo outro lado, na base inimiga, embaixo do prédio principal, fica a prisão da Aliança.$B$BSó precisamos encontrar aquelas Chaves da Prisão de Escudo Tonante para resgatá-los.', '', 19865),
(89898, 'ptBR', '', 'Você que manda, chefe! Iniciando holoprojeção D-092!', 19865),
(89899, 'ptBR', 'Dizem que as presas de Aogexon são capazes de cortar aço maciço! Magnífico!', '', 19865),
(89900, 'ptBR', 'Nós temos que conseguir as presas de Aogexon, Twixnee. Eles virarão ótimos fósseis um dia!', '', 19865),
(89901, 'ptBR', 'Vamos nos aproximar do espécime!', '', 19865),
(89902, 'ptBR', '', 'O próximo no banco de dados é Bergruu. Iniciando holoprojeção D-093...', 19865),
(89903, 'ptBR', 'Ahh, sim! Bergruu, o poderoso Couro de Ferro das planícies do norte! Dizem que o chifre de Bergruu é o maior chifre de fenoceronte já visto...', '', 19865),
(89904, 'ptBR', '', 'Será que alguém chegou perto o suficiente para medir o troço?', 19865),
(89905, 'ptBR', 'Ainda não! No entanto, muitos colecionadores pagariam uma fortuna por ele.', '', 19865),
(89906, 'ptBR', 'Vamos em frente. Agora é Dekorhan, o elekk de Nagrand, misterioso e ancestral!', '', 19865),
(89907, 'ptBR', '', 'Iniciando holoprojeção D-095...', 19865),
(89908, 'ptBR', 'O elekk é uma das espécies vivas mais antigas de Draenor. Muitas gerações de orcs registraram avistamentos de Dekorhan...', '', 19865),
(89909, 'ptBR', 'Pergunta rápida, Twix! Como você descobre a idade de um elekk?', '', 19865),
(89910, 'ptBR', '', 'Humm... pelo tamanho das presas?', 19865),
(89911, 'ptBR', 'Exatamente! Você aprendeu isso comigo?', '', 19865),
(89912, 'ptBR', '', 'Que tamanho é documento? Hãã... sim, claro! Pode apostar!', 19865),
(89913, 'ptBR', 'Agora, então, vamos analisar um talbuque mortífero e esquivo conhecido como Durocasco...', '', 19865),
(89914, 'ptBR', '', 'Holoprojeção D-096 iniciada, chefe!', 19865),
(89915, 'ptBR', 'Durocasco é o talbuque mais perigoso desta região de Nagrand. Um espécime de rara qualidade...', '', 19865),
(89916, 'ptBR', 'É nosso dever como arqueólogos preservar esta fera magnífica enquanto ela está no auge de sua vida!', '', 19865),
(89917, 'ptBR', '', 'Só de ouvir você falando, já fico orgulhosa de ser arqueóloga, senhor!', 19865),
(89918, 'ptBR', 'Como deve ser, Twixnee... como deve ser.', '', 19865),
(89919, 'ptBR', 'Agora, vamos ao próximo espécime!', '', 19865),
(89920, 'ptBR', '', 'Iniciando holoprojeção D-097... Gagrog, o Brutal!', 19865),
(89921, 'ptBR', 'Que criatura magnífica e brutal! Poucos gronns são temidos como Gagrog, o Brutal!', '', 19865),
(89922, 'ptBR', '', 'Escondam as mulheres e crianças! Escondam todo mundo!', 19865),
(89923, 'ptBR', 'Em algum lugar por aí, em uma coleção particular, há um espaço vazio esperando pelo crânio de Gagrog.', '', 19865),
(89924, 'ptBR', 'Chefe, você está enchendo meus olhos de lágrimas!', '', 19865),
(89925, 'ptBR', 'Aqui é a nossa cidade, verme.', 'Aqui é a nossa cidade, verme.', 19865),
(89926, 'ptBR', 'É isso aí, cai fora!', 'É isso aí, cai fora!', 19865),
(89927, 'ptBR', 'Contempla o poder da Legião!', '', 19865),
(89928, 'ptBR', 'Eu te destruirei!', '', 19865),
(89929, 'ptBR', 'Agora, vamos dar uma olhada em Mu''gra! Holoprojeção D-098, Twix...', '', 19865),
(89930, 'ptBR', '', 'D-098 saindo agora mesmo!', 19865),
(89931, 'ptBR', 'Mu''gra... meu arqui-inimigo!', '', 19865),
(89932, 'ptBR', '', 'Arqui-inimigo? Você tem história com esse hipopótamo?', 19865),
(89933, 'ptBR', 'Digamos que extrair um dente de hipopótamo para fins de preservação é muito mais perigoso quando o bicho está vivo...', '', 19865),
(89934, 'ptBR', '', 'Nossa, que tipo de coisa nós, arqueólogos, temos que enfrentar hoje em dia! Vixe!', 19865),
(89935, 'ptBR', 'Vamos para o próximo espécime!', '', 19865),
(89936, 'ptBR', '', 'Você que manda, Sr. G! Iniciando holoprojeção D-099...', 19865),
(89937, 'ptBR', 'Ahh, sim! Nós temos aqui Thek''talon, uma roca-dos-ventos de tamanho e ferocidade incríveis.', '', 19865),
(89938, 'ptBR', '', 'Ela tem garras grandes?', 19865),
(89939, 'ptBR', 'Certamente, Twix... e afiadas! Pena que não temos tempo de deixar Thek''talon morrer de morte morrida e se fossilizar aos poucos com o passar das eras...', '', 19865),
(89940, 'ptBR', '... pois é nosso dever dar uma mãozinha à natureza e acelerar o processo!', '', 19865),
(89941, 'ptBR', '', 'Fossilização natural? E alguém lá tem tempo pra isso!?', 19865),
(89942, 'ptBR', 'Twixnee, por favor, inicie a holoprojeção de Xelganak!', '', 19865),
(89943, 'ptBR', '', 'Agorinha, chefe! Iniciando holoprojeção D-100...', 19865),
(89944, 'ptBR', 'Xelganak é de fato uma criatura muito peculiar! O fluido bioluminescente na bolsa de Xelganak é altamente corrosivo e pode ser expelido em alta velocidade.', '', 19865),
(89945, 'ptBR', '', 'Então Xelganak pode derreter a cara de alguém?', 19865),
(89946, 'ptBR', 'O que você acha que aconteceu com Mr. Katracabum? Ele não nasceu daquele jeito!', '', 19865),
(89947, 'ptBR', '', '<Rachelle acena educadamente para você com a cabeça.>$B$BSaudações.', 19865),
(89948, 'ptBR', '', 'Sim?', 19865),
(89949, 'ptBR', '', 'Olá.', 19865),
(89950, 'ptBR', '', 'Bom dia.', 19865),
(89951, 'ptBR', '', 'Precisa de alguma coisa?', 19865),
(89952, 'ptBR', '', '<Rachelle olha para as ferramentas.>$B$BTemos muito trabalho a fazer.', 19865),
(89953, 'ptBR', '', '<Rachelle dá de ombros.>$B$BNão sou muito de falar.', 19865),
(89954, 'ptBR', '', 'Pois não, posso ajudar?', 19865),
(89955, 'ptBR', 'Meu sistema de Lançamento Foguete patenteado é impecável. Agora só falta esses peixes deixarem de manha e começarem a morder!', '', 19865),
(89956, 'ptBR', 'Nina, não estamos pegando peixe! Precisamos de mais foguetes!', '', 19865),
(89957, 'ptBR', 'Quem diz que é preciso técnica para fazer um lançamento longo nunca tentou usar foguetes!', '', 19865),
(89958, 'ptBR', 'Cansou de lançar a isca feito um fracote esmilinguido? Experimente o meu sistema patenteado de Lançamento Foguete!', '', 19865),
(89959, 'ptBR', 'Tem gente que acha estranho, mas eu acho o som ritmado do maquinário goblin bem relaxante. \n\nJá o cheiro, eu dispenso.', '', 19865),
(89960, 'ptBR', 'Queima em Fogo Vil!', '', 19865),
(89961, 'ptBR', 'Todos os gladiadores sucumbiram. Não há campeão, hoje.', 'Todos os gladiadores sucumbiram. Não há campeão, hoje.', 19865),
(89962, 'ptBR', 'Tenho alguns feitiços que podem consertar o seu equipamento... por um preço.', '', 19865),
(89963, 'ptBR', 'Preciso de reagentes.', 'Preciso de reagentes.', 19865),
(89964, 'ptBR', 'Cara, esses soldados da Aliança são uns afrescalhados mesmo!', '', 19865),
(89965, 'ptBR', 'Tá falando do cara que não parava de gritar, só porque você decepou o pé dele?', '', 19865),
(89966, 'ptBR', 'É! Ah, fala sério, era só um pezinho! A coisa mais besta de costurar de volta.', '', 19865),
(89967, 'ptBR', 'Hã, acho que não é bem assim...', '', 19865),
(89968, 'ptBR', 'Então, qual é a desses artefatos que todo mundo fica falando?', '', 19865),
(89969, 'ptBR', 'Só sei que a Aliança quer eles e os elfos acham que eles são poderosos. Eles não podem pôr as mãos numa coisa dessas.', '', 19865),
(89970, 'ptBR', 'Quer dizer que são poderosos? De repente eu devia arrumar um pra mim.', '', 19865),
(89971, 'ptBR', '', 'Por que orc cisma de praticar com machado afiado?', 19865),
(89972, 'ptBR', '', 'Da próxima vez, não puxe a flecha você mesmo. Encontre outra arma para furar seu oponente.', 19865),
(89973, 'ptBR', '', 'Deixe-me ver o machucado...', 19865),
(89974, 'ptBR', '', 'Não se mexa, vou dar os pontos.', 19865),
(89975, 'ptBR', 'As respostas estão lá fora, escondendo-se em lugares sombrios.$B$BPrecisamos ser ousados o suficiente para buscá-las.', '', 19865),
(89976, 'ptBR', 'Quero verificar minha correspondência.', 'Quero verificar minha correspondência.', 19865),
(89977, 'ptBR', 'Quero consertar meus equipamentos.', 'Quero consertar meus equipamentos.', 19865),
(89978, 'ptBR', 'Eu aposto no grandalhão!', 'Eu aposto no grandalhão!', 19865),
(89979, 'ptBR', 'Ai! Isso deve ter doído!', 'Ai! Isso deve ter doído!', 19865),
(89980, 'ptBR', 'Morde ele! Morde ele!', 'Morde ele! Morde ele!', 19865),
(89981, 'ptBR', 'Hei! Aquele ali não luta justo!', 'Hei! Aquele ali não luta justo!', 19865),
(89982, 'ptBR', 'Vamos lá, brutamontes!', 'Vamos lá, brutamontes!', 19865),
(89983, 'ptBR', 'Estou perto de reproduzir a interface Apexis.', '', 19865),
(89984, 'ptBR', '', 'Intrusos! Alguém informe Keli''dan!', 19865),
(89985, 'ptBR', 'Será um prazer devorar sua alma...', '', 19865),
(89986, 'ptBR', '<Raastok cacareja de alegria.>$B$BVocê viu o tamanho daquela explosão?! Maravilhoso!', '', 19865),
(89987, 'ptBR', 'Bando de estraga-prazeres! Vou botar fogo nessas suas armaduras ridículas!', '', 19865),
(89988, 'ptBR', 'Quero verificar as missões para seguidor.', 'Quero verificar as missões para seguidor.', 19865),
(89989, 'ptBR', '%s foge!', '', 19865),
(89990, 'ptBR', 'Você está pisando em solo sagrado. Sobre o solo da arena derramaram sangue os maiores gladiadores de Draenor. A maioria deles tiveram que dar a vida em troca de tamanha honra. Hoje, vocês farão o mesmo.', '', 19865),
(89991, 'ptBR', 'Vocês lutarão. Vocês matarão. Vocês saudarão! 100 VIDAS. Vida ou morte.', '', 19865),
(89992, 'ptBR', 'Ao último gladiador de pé, honra, glória e riquezas!', '', 19865),
(89993, 'ptBR', '$n foi abaixo! Só sobrou bosta e sangue de $r no chão! ', '', 19865),
(89994, 'ptBR', 'O que foi isso?! Alguma coisa explodiu no chão. Acho que foi $n!', '', 19865),
(89995, 'ptBR', '$n foi pro chão! Me lembrou aquele dia em que um elekk esmagou as bolas dum orcão. Foi uma semana incrível aqui no circo!', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(89996, 'ptBR', '$n morreu! Parece que só sobraram $9662W gladiadores na luta!', '', 19865),
(89997, 'ptBR', 'Ui! Aquele $r levou feio!', '', 19865),
(89998, 'ptBR', 'Acho que o faxineiro vai ficar demorar dias pra varrer os pedaços de $n!', '', 19865),
(89999, 'ptBR', 'Que $r mais bebê! Morreu fácil!', '', 19865),
(90000, 'ptBR', 'HA! Aí, Jhorn, lembra quando eu caguei um cocô parecendo um $r? Tá a cara $gdo:da; $n agora!', '', 19865),
(90001, 'ptBR', '', 'Ah, isso vai ser interessante. Você não se importaria se eu fizesse umas anotações, né?', 19865),
(90002, 'ptBR', '', 'É fácil perceber por que objetos como estes foram muito valiosos para suas culturas! Hum, foi mal pelas suas mascotes.', 19865),
(90003, 'ptBR', '', 'Resultados muito interessantes. Obrigado por me ajudar a testá-los!', 19865),
(90004, 'ptBR', '', 'Bem, o que você espera de algo que ficou enterrado por um milênio?', 19865),
(90005, 'ptBR', '', 'Em sua cultura nativa, aquela mascote teria sido reverenciada como uma martir.', 19865),
(90006, 'ptBR', '', 'Hum, eu meio que esperava que isso poderia acontecer.', 19865),
(90007, 'ptBR', '', 'Felizmente, Gyreixo consegue consertar qualquer coisa. Até ele mesmo.', 19865),
(90008, 'ptBR', '', 'Certo, será que isso foi o dispositivo funcionando normalmente, como esperado, ou ele simplesmente explodiu?', 19865),
(90009, 'ptBR', '', 'Tudo em nome da ciência.', 19865),
(90010, 'ptBR', 'Você alimentará minhas raízes.', '', 19865),
(90011, 'ptBR', '', 'Tenho bandagens no meu kit de campo, se você precisar...', 19865),
(90012, 'ptBR', '', 'Temos que respeitar a engenhosidade de um dispositivo tão antigo.', 19865),
(90013, 'ptBR', 'As plantas se regozijarão no seu cadáver.', '', 19865),
(90014, 'ptBR', '', 'Vou incluir um agradecimento especial à sua mascote quando eu publicar esta pesquisa.', 19865),
(90015, 'ptBR', '', 'Ah, você deve estar falando do meu pai, Belloc. O que ele e o Relicário fazem mal pode ser chamado de "arqueologia". Na verdade são saqueadores de tumbas.$B$BA verdadeira arqueologia é a busca por fatos, não por tesouro. Quero aprender sobre o passado, estudar de onde viemos, e recuperar conhecimento perdido.', 19865),
(90016, 'ptBR', 'Eu posso cair... mas, um dia, você será dominado pelas plantas...', '', 19865),
(90017, 'ptBR', 'Gumélion? Acho que já ouvi esse nome antes...', 'Gumélion? Acho que já ouvi esse nome antes...', 19865),
(90018, 'ptBR', '', 'Você não parece ser muito $gbom:boa; em batalhas de mascotes. Talvez devesse voltar quando tiver melhorado.', 19865),
(90019, 'ptBR', '', 'Lá vamos nós!', 19865),
(90020, 'ptBR', '', 'Ah, minhas mascotes foram tão bem. Elas vão ganhar uns abraços extras por isso.', 19865),
(90021, 'ptBR', '', 'Ah, acho que está tudo bem. Mas o Rabisco vai precisar de um olho novo.', 19865),
(90022, 'ptBR', '', 'Não se preocupe, eu dou um beijinho no dodói que passa.', 19865),
(90023, 'ptBR', '', 'Uma sopinha vai deixar você melhor!', 19865),
(90024, 'ptBR', '', 'Ah, não!', 19865),
(90025, 'ptBR', '', 'Ela não morreu, só está olhando pra dentro.', 19865),
(90026, 'ptBR', '', 'Vou colocar uma bandagem de arco-íris no machucadinho.', 19865),
(90027, 'ptBR', '', 'Ah, não!', 19865),
(90028, 'ptBR', '', 'Seu bichinho tá nanando também?', 19865),
(90029, 'ptBR', '', 'Você pode curar o seu bichinho, né?', 19865),
(90030, 'ptBR', 'Inicie o ritual de evocação. Quero evocar meus aliados para cá.', 'Inicie o ritual de evocação. Quero evocar meus aliados para cá.', 19865),
(90031, 'ptBR', '', 'Como eu pensei, $r, você é muito $gfraco:fraca;.', 19865),
(90032, 'ptBR', '', 'Você tem sorte que meus lobos ainda são filhotes, senão você teria sido a refeição.', 19865),
(90033, 'ptBR', '', 'Nossa derrota expôs nossas fraquezas. Esta perda melhorará o treinamento deles.', 19865),
(90034, 'ptBR', '', 'Esse era muito burro.', 19865),
(90035, 'ptBR', '', 'Esse tinha coragem de sobra.', 19865),
(90036, 'ptBR', '', 'Esse não cometerá o mesmo erro de novo.', 19865),
(90037, 'ptBR', '', 'Esse era muito lento.', 19865),
(90038, 'ptBR', '', 'Esse vai precisar de cura.', 19865),
(90039, 'ptBR', '', 'Um bom abate.', 19865),
(90040, 'ptBR', '', 'Uma morte limpa.', 19865),
(90041, 'ptBR', '', 'Sequer foi um desafio.', 19865),
(90042, 'ptBR', '', 'Por que suas mascotes são tão fracas?', 19865),
(90043, 'ptBR', '', 'Um abate fácil. Meus lobos não aprenderão nada.', 19865),
(90044, 'ptBR', 'Gladiadores, matem!', '', 19865),
(90045, 'ptBR', 'Sigo sendo o maior senhor da guerra de toda Nagrand!', '', 19865),
(90046, 'ptBR', 'O quê? Como é possível? Você roubou!', '', 19865),
(90047, 'ptBR', 'O que é uma morte quando se tem um exército de três?', '', 19865),
(90048, 'ptBR', 'Meus gladiadores lutarão até a morte!', '', 19865),
(90049, 'ptBR', 'Você deixa Tarr furioso!', '', 19865),
(90050, 'ptBR', 'Mandei você matar, não morrer!', '', 19865),
(90051, 'ptBR', 'Haha, $r não tem mais bichinho.', '', 19865),
(90052, 'ptBR', 'Golpe do gladiador!', '', 19865),
(90053, 'ptBR', 'Não está se divertindo?', '', 19865),
(90054, 'ptBR', 'Tarr vai abalar você!', '', 19865),
(90055, 'ptBR', 'É por isto que Tarr é o maior senhor da guerra de toda Nagrand!', '', 19865),
(90056, 'ptBR', '', 'Ei, $Gmoço:moça;, quer ver os meus mascotes?', 19865),
(90057, 'ptBR', '', 'Então volta depois.', 19865),
(90058, 'ptBR', '', 'Eu posso ser pequena, mas se você machucar os meus mascotes, eu vou machucar você.', 19865),
(90059, 'ptBR', '', 'Obrigada, moç$Go:a;! Eu aposto 100 de cobre nessa luta.', 19865),
(90060, 'ptBR', '', 'Isso é que nem a vez em que a minha cidade foi tomada por demônios.', 19865),
(90061, 'ptBR', '', 'Está tudo bem. Eles estão acostumados a morrer.', 19865),
(90062, 'ptBR', '', 'Não é a primeira vez que alguém caça esse aqui até os confins da terra.', 19865),
(90063, 'ptBR', '', 'Calma aí! Eu paguei uns bons cobres por esse aqui.', 19865),
(90064, 'ptBR', '', 'Eu vendo uma Pedra de Jardel para você se você prometer não fazer isso de novo.', 19865),
(90065, 'ptBR', '', 'A minha má sorte é de família.', 19865),
(90066, 'ptBR', '', 'Me desculpe, moç$Go:a;.', 19865),
(90067, 'ptBR', '', 'Não jogue esse fora. Ainda dá para consertar.', 19865),
(90068, 'ptBR', '', 'É isso aí! As minhas mascotes são das ruas de Caldeum.', 19865),
(90069, 'ptBR', '', 'É. Foi um pouco de má sorte, moç$Go:a;.', 19865),
(90070, 'ptBR', '$R, eu me devoto ao treinamento dos guardiões de Anzu. Tu ajudarias a minha causa?', '', 19865),
(90071, 'ptBR', 'Pois bem, volta depois de treinad$go:a;.', '', 19865),
(90072, 'ptBR', 'Nossa esperança jaz no que estes bichos se tornarão. Eles são sagrados para nós.', '', 19865),
(90073, 'ptBR', 'Glória a Anzu!', '', 19865),
(90074, 'ptBR', 'Somos arakkoas. Não nos deixamos derrubar por uma simples derrota.', '', 19865),
(90075, 'ptBR', 'É um mau presságio.', '', 19865),
(90076, 'ptBR', 'Anzu, protege teus filhos!', '', 19865),
(90077, 'ptBR', 'Não! Os guardiões não podem cair!', '', 19865),
(90078, 'ptBR', 'Ruína infinda! Ruíiiiiina infiiiiiiinda!', '', 19865),
(90079, 'ptBR', 'A maldição de Sethe recaiu sobre nós.', '', 19865),
(90080, 'ptBR', 'É um bom presságio.', '', 19865),
(90081, 'ptBR', 'A força dos arakkoas está conosco.', '', 19865),
(90082, 'ptBR', 'O deus corvo nos deu sua bênção neste dia.', '', 19865),
(90083, 'ptBR', 'Os guardiões ainda estão de pé.', '', 19865),
(90084, 'ptBR', 'Anzu protege seus filhos.', '', 19865),
(90085, 'ptBR', '', 'Olá, $n. Gostaria de dançar com minhas mariposas?', 19865),
(90086, 'ptBR', '', 'Entendo. Volte quando já tiver se preparado.', 19865),
(90087, 'ptBR', '', 'Preste atenção, $n. A força muitas vezes vem de onde menos se espera.', 19865),
(90088, 'ptBR', '', 'Espero que tenha aprendido uma lição hoje.', 19865),
(90089, 'ptBR', '', 'Espero que tenha aprendido uma lição hoje.', 19865),
(90090, 'ptBR', '', 'Sinto muito pela perda, mas estou feliz pela vitória.', 19865),
(90091, 'ptBR', '', 'Nada tema, um simples feitiço de cura consertará tudo.', 19865),
(90092, 'ptBR', '', 'A vida é cheia de surpresas.', 19865),
(90093, 'ptBR', '', 'A Luz ainda não a levou. Ela só está repousando.', 19865),
(90094, 'ptBR', '', 'A mariposa voa em direção às chamas, pelo que parece.', 19865),
(90095, 'ptBR', '', 'A vida é cheia de surpresas.', 19865),
(90096, 'ptBR', '', 'É loucura subestimar a força da natureza.', 19865),
(90097, 'ptBR', '', 'A mariposa é delicada, mas sabe se defender.', 19865),
(90098, 'ptBR', '', 'Não se desespere, você e sua mascote podem aprender com isto.', 19865),
(90099, 'ptBR', '', 'Uma bela lição aprendida tarde demais.', 19865),
(90100, 'ptBR', 'Inicie o ritual da luz guia. Quero evocar meus aliados para cá.', 'Inicie o ritual da luz guia. Quero evocar meus aliados para cá.', 19865),
(90101, 'ptBR', 'Desculpe, ainda preciso treinar um dos meus ajudantes até o nível 25.', 'Desculpe, ainda preciso treinar um dos meus ajudantes até o nível 25.', 19865),
(90102, 'ptBR', 'Eu admiro os seus princípios. Continue.', 'Eu admiro os seus princípios. Continue.', 19865),
(90103, 'ptBR', 'Abra um portal para a minha guarnição.', 'Abra um portal para a minha guarnição.', 19865),
(90104, 'ptBR', 'A |cFFE86B17|Hspell:175519|h[Essência da Chama]|h|r cai das suas mãos!', 'A |cFFE86B17|Hspell:175519|h[Essência da Chama]|h|r cai das suas mãos!', 19865),
(90105, 'ptBR', 'As trevas... fluem em mim. Em cada veia do meu corpo.', '', 19865),
(90106, 'ptBR', 'Venham, estranhos! Entrem no reino das Terras Sombrias! Eu os entregarei à morte.', '', 19865),
(90107, 'ptBR', 'Os Lua Negra NÃO PODEM ser derrotados. Nós caminhamos no reino da própria morte.', '', 19865),
(90108, 'ptBR', 'Eu sou o arauto do fim!', '', 19865),
(90109, 'ptBR', 'Ossos e sombras! Exército dos mortos, erga-se!', '', 19865),
(90110, 'ptBR', 'Abismo adentro!', '', 19865),
(90111, 'ptBR', 'Sinta o abraço gelado da morte.', '', 19865),
(90112, 'ptBR', 'Meu poder... ecoará... por toda... a eternidade.', '', 19865),
(90113, 'ptBR', 'Sua alma vai me servir!', '', 19865),
(90114, 'ptBR', 'Dobre-se à minha vontade!', '', 19865),
(90115, 'ptBR', '', 'Ergam-se, rios dos condenados. ERGAM-SE! ERGAM-SE em nome das trevas, ERGAM-SE em nome de Ner''zhul! A Lua Negra chama...', 19865),
(90116, 'ptBR', '', 'Ancestrais dos Lua Negra, brilhem na escuridão! Me deem suas forças!', 19865),
(90117, 'ptBR', '', 'Por Ner''zhul...', 19865),
(90118, 'ptBR', '', 'Hmm, sim. O sacrifício PERFEITO.', 19865),
(90119, 'ptBR', '', 'Suas almas serão MINHAS.', 19865),
(90120, 'ptBR', '', 'Espíritos inquietos, OUÇAM meu comando!', 19865),
(90121, 'ptBR', '', 'Outro espírito para o exército!', 19865),
(90122, 'ptBR', '', 'Aceitem as trevas eternas...', 19865),
(90123, 'ptBR', '', 'Os mortos... se erguerão novamente...', 19865),
(90124, 'ptBR', 'Vamos lá!', 'Vamos lá!', 19865),
(90125, 'ptBR', 'Reacenda a |cFFE86B17|Hspell:175519|h[Essência da Chama]|h|r em uma Chama Acendedora!', 'Reacenda a |cFFE86B17|Hspell:175519|h[Essência da Chama]|h|r em uma Chama Acendedora!', 19865),
(90126, 'ptBR', 'Agradeço, $n. Que as Fúrias do Fogofrio aqueçam seu coração!', '', 19865),
(90127, 'ptBR', 'Obrigado pela ajuda, $n. Não estou totalmente bem, mas não importa. Vamos em frente!', 'Obrigada pela ajuda, $n. Não estou totalmente bem, mas não importa. Vamos em frente!', 19865),
(90128, 'ptBR', '$n, não esquecerei da sua ajuda. Essas feridas não me impedirão de lutar bem!', '$n, não esquecerei da sua ajuda. Essas feridas não me impedirão de lutar bem!', 19865),
(90129, 'ptBR', 'Assim é melhor. Sofri um revés no combate, mas você me deu a chance de me redimir.', 'Assim é melhor. Sofri um revés no combate, mas você me deu a chance de me redimir.', 19865),
(90130, 'ptBR', 'Por Sha''tar, agradeço a ajuda. Sofri ferimentos, mas agora posso continuar a lutar!', 'Por Sha''tar, agradeço a ajuda. Sofri ferimentos, mas agora posso continuar a lutar!', 19865),
(90131, 'ptBR', '$n, eu me lembrarei do seu nome. Estas feridas não são maiores que minha fúria. Vamos à luta!', '$n, eu me lembrarei do seu nome. Estas feridas não são maiores que minha fúria. Vamos à luta!', 19865),
(90132, 'ptBR', 'Obrigado pela ajuda, $n. Lutemos juntos, por Shattrath!', 'Obrigado pela ajuda, $n. Lutemos juntos, por Shattrath!', 19865),
(90133, 'ptBR', 'Agradeço muito, $r, mas não desejo lutar ao seu lado.', 'Agradeço muito, $r, mas não desejo lutar ao seu lado.', 19865),
(90134, 'ptBR', 'Nossos caminhos não se cruzam, $r. Agradeço a ajuda, mas tenho que ir.', 'Nossos caminhos não se cruzam, $r. Agradeço a ajuda, mas tenho que ir.', 19865),
(90135, 'ptBR', 'Minhas feridas são profundas demais, camarada. Devo ir, mas espero que nos encontremos de novo.', 'Minhas feridas são profundas demais, camarada. Devo ir, mas espero que nos encontremos de novo.', 19865),
(90136, 'ptBR', 'Preciso beber mais.', '', 19865),
(90137, 'ptBR', 'Uma fruta esmagada é ainda mais doce.', '', 19865),
(90138, 'ptBR', 'Tenho muitos ferimentos, $n, e preciso ir me curar. Agradeço pelo tempo que passamos juntos.', 'Tenho muitos ferimentos, $n, e preciso ir me curar. Agradeço pelo tempo que passamos juntos.', 19865),
(90139, 'ptBR', 'Você já recebeu a bênção no Altar do Peregrino. Uma enorme sensação de paz e serenidade recai sobre você.', 'Você já recebeu a bênção no Altar do Peregrino. Uma enorme sensação de paz e serenidade recai sobre você.', 19865),
(90140, 'ptBR', 'Bênção de K''ure', 'Bênção de K''ure', 19865),
(90141, 'ptBR', 'Muito bom o seu grogue, comandante.', '', 19865),
(90142, 'ptBR', '', 'Vá embora.', 19865),
(90143, 'ptBR', 'Vá com a Luz, comandante.', '', 19865),
(90144, 'ptBR', 'Há tanta morte nestas terras...', '', 19865),
(90145, 'ptBR', 'Vá com a bênção de Aviana.', '', 19865),
(90146, 'ptBR', 'As plantas e fungos de Draenor podem ser usados para confeccionar toda sorte de pestilência. \n\nAcho que nossa próxima peste será a melhor de todas!', '', 19865),
(90147, 'ptBR', 'Você já passou algum tempo — mas digo passar mesmo, de verdade — dentro de uma gosma ácida do pântano? Eu não recomendo.', '', 19865),
(90148, 'ptBR', 'Alô, escudeiro.', '', 19865),
(90149, 'ptBR', 'Eu encontrarei um meio de salvar Bolvar, nem que isto tome o resto dos meus dias.', '', 19865),
(90150, 'ptBR', '', 'Deixe-me a sós.', 19865),
(90151, 'ptBR', 'Zen''Kiki curte a forma de gatinho pra dar uma bodada esperta.', '', 19865),
(90152, 'ptBR', 'Sofri ferimentos, $n. Preciso descansar. Al diel shala!', 'Sofri ferimentos, $n. Preciso descansar. Al diel shala!', 19865),
(90153, 'ptBR', 'Com as minhas receitas, você poderá transformar os reagentes draenorianos em misturas com o poder de criar e destruir, conforme a sua vontade.\n\nIsto é, contanto que você possua a perícia necessária para manuseá-los.', '', 19865),
(90154, 'ptBR', 'Ah, olá, comandante! Gostaria de ouvir uma longa história sobre uma ponte?', '', 19865),
(90155, 'ptBR', 'Preciso descansar, $n. Shorel''aran!', 'Preciso descansar, $n. Shorel''aran!', 19865),
(90156, 'ptBR', '', 'As instruções são simples: ou você se abaixa, ou perde a cabeça. Se perder a cabeça, fica mais fácil de se abaixar depois.', 19865),
(90157, 'ptBR', 'Eu, Gamon, salvarei a todos nós!', '', 19865),
(90158, 'ptBR', 'Será que neste mundo não tem nenhum artefato destruidor de mundos? Não podemos deixar que caiam nas mãos do inimigo de jeito nenhum!', '', 19865),
(90159, 'ptBR', 'Luta não, senta perto do fogo. Fogo quentinho, lá fora friaca. Senta aí.', '', 19865),
(90160, 'ptBR', 'Adoro barcos!', '', 19865),
(90161, 'ptBR', 'Se quiser me inspecionar, fique da distância máxima.', '', 19865),
(90162, 'ptBR', '', 'Boa sorte, comandante.', 19865),
(90163, 'ptBR', 'Não conheço nada além da guerra. Aqui, pelo menos, sou alguém.', '', 19865),
(90164, 'ptBR', 'Juntar cinquenta! Aham! Tava contando pra eles sobre a melhor tarefa que já passei pra um aspirante a aventureiro. Ah, bons tempos aqueles...', '', 19865),
(90165, 'ptBR', 'Em Draenor, há muitas feras cujo couro é tão resistente quanto o de um kodo. \n\nCom algum treino, posso lhe mostrar como transformar o couro em armaduras fortíssimas.', '', 19865),
(90166, 'ptBR', 'Estou tentando me comunicar interdimensionalmente com o Mordisco, SE VOCÊ NÃO SE IMPORTAR.', '', 19865),
(90167, 'ptBR', '', 'Oi! Este forte é da hora.', 19865),
(90168, 'ptBR', 'A estátua de pedra emite uma aura tranquila. Uma placa diz:$B$BAqueles que forem abençoados pela luz de A''dal ganharão firmeza e armadura para enfrentar os mais desafiadores dos inimigos.$B$BA bênção de D''ore concede cura em momentos difíceis.$B$BK''ara guia as armas do abençoado, dando-lhes a possibilidade de desferir mais golpes em tempos de guerra.$B$BK''ure recompensa os fiéis com movimentos céleres como o vento.', 'A estátua de pedra emite uma aura tranquila. Uma placa diz:$B$BAqueles que forem abençoados pela luz de A''dal ganharão firmeza e armadura para enfrentar os mais desafiadores dos inimigos.$B$BA bênção de D''ore concede cura em momentos difíceis.$B$BK''ara guia as armas do abençoado, dando-lhes a possibilidade de desferir mais golpes em tempos de guerra.$B$BK''ure recompensa os fiéis com movimentos céleres como o vento.', 19865),
(90169, 'ptBR', 'Bênção de D''ore', 'Bênção de D''ore', 19865),
(90170, 'ptBR', 'Bênção de K''ara', 'Bênção de K''ara', 19865),
(90171, 'ptBR', 'Bênção de A''dal', 'Bênção de A''dal', 19865),
(90172, 'ptBR', 'Você tem cara de quem precisa de uma guaribada no guarda-roupa. \n\nPara sua sorte, eu posso ser a pessoa certa para lhe ensinar a fazer alguns dos trajes mais requintados de Draenor.\n\nGostaria de dar uma olhada nos meus moldes?', '', 19865),
(90173, 'ptBR', 'Os gemeiros draeneicos guardam com muito cuidado os segredos de como controlar o poder latente das gemas de Draenor.\n\nEu, porém, consegui acessar esses segredos, e posso compartilhá-los com joalheiros talentosos.\n\nPor um preço, é claro.', '', 19865),
(90174, 'ptBR', 'Então tu quer aperfeiçoar tuas coisas com o poder do vodu. \n\nO Ged''kah sabe o que fazer.', '', 19865),
(90175, 'ptBR', '', 'Algumas palavras são fortes quanto um feitiço vodu. \n\nQuem sabe essas palavras conhece o verdadeiro poder!', 19865),
(90176, 'ptBR', 'Esses caras da Horda de Ferro acham que sabem fazer máquinas.\n\nEspere só até eles verem do que um goblin é capaz, uma vez que pusermos as mãos na tecnologia deles!', '', 19865),
(90177, 'ptBR', 'Agora que a Aliança está se tornando uma ameaça novamente em Ashran, a demanda por armas e armaduras de qualidade está maior do que nunca!\n\nVocê sente o cheiro de lucro?', '', 19865),
(90178, 'ptBR', 'Zikk, meu parcêro. Cê me quebra um galho e vai ali pegar um pergaminho dos encantadores?', '', 19865),
(90179, 'ptBR', 'Mas que raptor mais bonzinho!', '', 19865),
(90180, 'ptBR', 'Onde que eu vou enfiar esse cálamo agora?', '', 19865),
(90181, 'ptBR', 'O trabalho do escriba num acaba nunca, cara.', '', 19865),
(90182, 'ptBR', '', 'Fique à vontade para guardar seus bichos junto com os raptores. Vamos alimentar eles direitinho. \n\nOs seus bichos, claro. Tu tinha entendido o quê?', 19865),
(90183, 'ptBR', '', 'Shhhhh... Estou tentando pegar alguma coisa!', 19865),
(90184, 'ptBR', 'Você quer saber por que estamos aqui? Somos aventureiros experientes e buscamos despertar uma fera marinha lendária.', '', 19865),
(90185, 'ptBR', 'Essa criatura tem que existir! Vou procurá-la até o meu último dia de vida!', '', 19865),
(90186, 'ptBR', '', 'Os reagentes de Draenor são tão maravilhosos quanto misteriosos.\n\nPor um preço, posso lhe ensinar como utilizar seu pontecial.', 19865),
(90187, 'ptBR', 'Meu poder não tem fim!', '', 19865),
(90188, 'ptBR', 'Pelas penas da Mãe Corvo, você não vai encontrar negócio melhor!', '', 19865),
(90189, 'ptBR', 'Mostre-me suas mercadorias.', 'Mostre-me suas mercadorias.', 19865),
(90190, 'ptBR', 'Graaauuuurrrrr! Graaauuuuuurrrrrrrr!!!!!', '', 19865),
(90191, 'ptBR', 'Já viste alguma criatura marinha gigantesca nestas águas?', '', 19865),
(90192, 'ptBR', 'Tome. Você parece com fome.', '', 19865),
(90193, 'ptBR', 'Coma isso. Vai fazer você ficar forte.', '', 19865),
(90194, 'ptBR', '01010011 01100101 00100000 01110001 01110101 01101001 01110011 01100101 01110010 00100000 01110110 01100101 01101110 01100011 01100101 01110010 00100000 01101111 00100000 01101010 01101111 01100111 01101111 ', '', 19865),
(90195, 'ptBR', '01110110 01101111 01100011 11101010 00100000 01110000 01110010 01100101 01100011 01101001 01110011 01100001 00100000 01101101 01101001 01110010 01100001 01110010 00100000 01100010 01100101 01101101 ', '', 19865),
(90196, 'ptBR', '', 'Estou dizendo que vai funcionar, pode acreditar em mim!', 19865),
(90197, 'ptBR', 'Eu nem consigo ver com este troço... como esse plano vai funcionar se a gente não consegue ver pra onde está indo?', '', 19865),
(90198, 'ptBR', '', 'Basta seguir o som do dinheiro que você vai ganhar quando vender todos esses ossos!', 19865),
(90199, 'ptBR', '', 'O disfarce está funcionando! Esses gronns burros nem desconfiam que estamos aqui!', 19865),
(90200, 'ptBR', 'Então a gente só precisa esperar eles dormirem e depois fugir com os ossos?', '', 19865),
(90201, 'ptBR', '', 'Exato... Ei, você está sentindo alguma coisa subindo pela sua cabeça?', 19865),
(90202, 'ptBR', 'Só uma sensação de arrependimento por ter deixado você me convencer entrar nessa...', '', 19865),
(90203, 'ptBR', '', 'Então, o que tem a dizer sobre as máquinas que você e seus capangas estão construindo para a Horda de Ferro?', 19865),
(90204, 'ptBR', 'Não tenho nada para lhe dizer!', '', 19865),
(90205, 'ptBR', '', 'Pois bem, se você quer dificultar as coisas...', 19865),
(90206, 'ptBR', '', 'Vai soltar o verbo agora ou isto não foi o bastante para persuadi-lo?', 19865),
(90207, 'ptBR', 'Não vou falar nada! Não sou alcaguete!', '', 19865),
(90208, 'ptBR', '', 'Convençam-no a falar.', 19865),
(90209, 'ptBR', 'Chega, por favor! Eu falo! Mande esses caras pararem!', '', 19865),
(90210, 'ptBR', '', 'Deixem-nos a sós, rapazes. Temos muito a conversar.', 19865),
(90211, 'ptBR', 'Caveira Oca', 'Caveira Oca', 19865),
(90213, 'ptBR', 'Em meio ao caos e à carnificina do Coliseu, um de vocês emergirá vitorioso. $n! Louvem o seu nome! Glória a $n no dia de hoje!', '', 19865),
(90214, 'ptBR', 'Venham honrar o campeão! Venham vislumbrar as riquezas presenteadas ao mais forte membro de seu povo!', '', 19865),
(90216, 'ptBR', '', 'Forjada em fogo, meu poder não tem limites, meus aliados nada temem!', 19865),
(90217, 'ptBR', 'A batalha começou! O último gladiador de pé será vitorioso!', '', 19865),
(90218, 'ptBR', '', 'Meu corpo tombou, mas meu espírito se ergue. Estarei sempre com vocês.', 19865),
(90219, 'ptBR', 'Impostores de meia-tigela como Harrison Jones podem desprezar meus métodos, mas fossilização leva milhares de anos!$B$BA melhor forma de preservar uma criatura rara e fascinante é fazer isso com as próprias mãos!$B$BPor que esperar milhares de anos para a natureza fazer uma coisa quando você mesmo pode fazer um trabalho melhor?', '', 19865),
(90220, 'ptBR', 'Você ajuda a Sociedade de Preservação de Bondebico, e nós ajudamos você! Não esqueça que dar é melhor que receber, mas sem ouro não tem tesouro!', '', 19865),
(90221, 'ptBR', '<Mr. Katracabum agita os braços desesperadamente quando você se aproxima.>$B$BOa! Ei! Quem está aí?$B$BAh, desculpe... eu não ando enxergando muito bem depois daquela... situação com Xelganak.', '', 19865),
(90226, 'ptBR', 'Os magos invocarão um portal a oeste de Ashran, que pode ser usado para levar você de volta à Bastilha Escudo Tonante.', '', 19865),
(90227, 'ptBR', 'GRRRRAAAAaaaaahhhh!!!', '', 19865),
(90228, 'ptBR', '$n é invencível! Fique de olhe $gnele:nela; Karrath.', '', 19865),
(90229, 'ptBR', 'Se eu roubei esses rylaks da Horda de Ferro?$B$BDepende de quem quer saber!', '', 19865),
(90230, 'ptBR', '', 'Você parece fazer o tipo aventureiro!$B$BSe você encontrar alguma relíquia ou artefato por aí, traga para cá e faremos negócio!', 19865),
(90233, 'ptBR', 'A trompa sinalizadora soou. Por que os outros não chegaram?', '', 19865),
(90234, 'ptBR', 'Provavelmente estão bebendo até cair.', '', 19865),
(90235, 'ptBR', 'Há alguma coisa errada. Tenho a sensação de que estão nos observando.', '', 19865),
(90237, 'ptBR', '', 'Não sei de nada, eu só trabalho no holoprojetor! Se você quer trabalho, tem que falar com o Sr. G!', 19865),
(90239, 'ptBR', 'Nada ainda sobre os movimentos das tropas ao norte.', '', 19865),
(90240, 'ptBR', 'Nossos soldados avistaram artilharia subindo pela costa.', '', 19865),
(90241, 'ptBR', 'Nossos guerreiros pegaram o posto avançado de surpresa e queimaram tudo.', '', 19865),
(90242, 'ptBR', 'Ainda não tivemos nenhuma notícia dos nossos batedores.', '', 19865),
(90243, 'ptBR', 'Nossos navios chegarão nas Docas de Ferro em breve.', '', 19865),
(90244, 'ptBR', 'Há relatos de grandes baixas ao sul.', '', 19865),
(90245, 'ptBR', 'Nossos batedores avistaram uma caravana pronta para ser saqueada.', '', 19865),
(90246, 'ptBR', 'Ainda não tivemos notícia dos outros clãs.', '', 19865),
(90248, 'ptBR', 'Nossas tropas queimaram a aldeia e não deixaram sobreviventes.', '', 19865),
(90249, 'ptBR', 'Há forças inimigas se movendo a oeste, através de Nagrand.', '', 19865),
(90250, 'ptBR', 'Algum peixe mordeu? Descobri que paciência (e uma cerva) ajudam muito a pegar peixe grande!', '', 19865),
(90251, 'ptBR', 'Você trouxe uma caixa térmica? Eu NUNCA saio pra pescar sem uma caixa térmica!', '', 19865),
(90252, 'ptBR', 'Algum peixe mordeu? Descobri que paciência (e uma cerva) ajudam muito a pegar peixe grande!', '', 19865),
(90253, 'ptBR', '*HIC!* Aquilo era um golfinho!? *HIC!* Eu adoro golfinhos!', '', 19865),
(90254, 'ptBR', 'Sério? Pra dizer a verdade, acho que eu jogaria esse de volta na água.', '', 19865),
(90257, 'ptBR', 'Vermes Carniceiros mortos: $1i (+$2i VP)', 'Vermes Carniceiros mortos: $1i (+$2i VP)', 19865),
(90258, 'ptBR', 'Infiltradores mortos: $1i (+$2i VP)', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(90260, 'ptBR', 'Pilhadores detidos: $1i (+$2i VP)', '', 19865),
(90261, 'ptBR', '*BOCEJO* Parece que você está precisando de uma ajudinha externa!', '', 19865),
(90262, 'ptBR', 'A plateia está ficando cansada! Talvez um foguinho anime as coisas!', '', 19865),
(90263, 'ptBR', 'Este ritmo é lento demais para mim! Vejamos se isto ajuda...', '', 19865),
(90264, 'ptBR', 'Minha paciência se esgotou! VOCÊ VAI LUTAR!', '', 19865),
(90265, 'ptBR', 'Fui!', '', 19865),
(90266, 'ptBR', 'Volto mais tarde. Guarde uma cerveja pra mim!', '', 19865),
(90267, 'ptBR', 'Boa sorte com os peixes gigantes!', '', 19865),
(90268, 'ptBR', '''Dia, $n! Deu sorte?', '', 19865),
(90269, 'ptBR', 'Te encontrei, $n!', '', 19865),
(90270, 'ptBR', 'Saudações, $n!', '', 19865),
(90271, 'ptBR', 'Fúria Branca cava os destroços com tristeza.', '', 19865),
(90272, 'ptBR', 'Saímos vitoriosos, mas custou caro.', '', 19865),
(90273, 'ptBR', 'O que aconteceu aqui?', 'O que aconteceu aqui?', 19865),
(90274, 'ptBR', 'Blargh! Ninguém derrama minha cerveja... MORRA!', '', 19865),
(90275, 'ptBR', 'MINHA FORÇA... EU NÃO SEREI... PARTI... DO...', '', 19865),
(90276, 'ptBR', 'AUGHHHHH!', '', 19865),
(90277, 'ptBR', 'TUDO QUE VIVE... VIRA PÓ.', '', 19865),
(90278, 'ptBR', 'QUEBRAR.', '', 19865),
(90279, 'ptBR', 'A TERRA CONSOME VOCÊ.', '', 19865),
(90280, 'ptBR', 'EU... SOU... ETERNO!', '', 19865),
(90281, 'ptBR', 'DESPEDAÇAR.', '', 19865),
(90282, 'ptBR', 'ERGAM-SE, MONTANHAS!', '', 19865),
(90283, 'ptBR', 'É... DEMAIS!', '', 19865),
(90284, 'ptBR', 'O QUE... É... ISSO...', '', 19865),
(90285, 'ptBR', 'ATÉ A MONTANHA... CAI...', '', 19865),
(90286, 'ptBR', 'VOLTE AO PÓ.', '', 19865),
(90287, 'ptBR', 'CARNE. INÚTIL.', '', 19865),
(90288, 'ptBR', 'O sacrifício dele ecoará pelas nossas gerações... para sempre.', '', 19865),
(90289, 'ptBR', 'Kral''ach... As trevas falam... UMA VOZ!', '', 19865),
(90290, 'ptBR', 'MESTRE! ESTOU INDO EM SEU AUXÍLIO!', '', 19865),
(90291, 'ptBR', 'Yjj''rmr… Xzzolos…', '', 19865),
(90292, 'ptBR', 'Noite! Meu sangue... estrelas...', '', 19865),
(90293, 'ptBR', 'Sim, Tectus. Curve-se... à vontade... de nosso mestre...', '', 19865),
(90294, 'ptBR', 'Não! Você não compreende... é preciso permanecer...', '', 19865),
(90295, 'ptBR', 'Quem ousa intrometer-se em assuntos da Legião!?', '', 19865),
(90296, 'ptBR', 'Este mundo... TODOS os mundos... hão de queimar!', '', 19865),
(90297, 'ptBR', 'O mestre exige sua alma.', '', 19865),
(90298, 'ptBR', 'Queime.', '', 19865),
(90299, 'ptBR', 'Apareçam, servos!', '', 19865),
(90300, 'ptBR', 'Queimem no fogo do mestre!', '', 19865),
(90301, 'ptBR', 'Morra, inseto!', '', 19865),
(90302, 'ptBR', 'Melhor assim! Não nos desaponte de novo!', '', 19865),
(90303, 'ptBR', 'Não sou um anfitrião sofisticadíssimo? Não estão se divertindo?', '', 19865),
(90304, 'ptBR', 'Percam o interesse da plateia de novo e vocês pagarão caro!', '', 19865),
(90305, 'ptBR', '|TInterface\\Icons\\spell_druid_massentanglement.blp:20|t Você está $gemaranhado:emaranhanda; em |cFFFF0404|Hspell:176001|h[Gavinhas Selvagens]|h|r!', '|TInterface\\Icons\\spell_druid_massentanglement.blp:20|t Você está $gemaranhado:emaranhanda; em |cFFFF0404|Hspell:176001|h[Gavinhas Selvagens]|h|r!', 19865),
(90306, 'ptBR', 'Tanto músculo e não consegue quebrar pedra!? Ogron inútil!', '', 19865),
(90307, 'ptBR', 'Até talbuque morto é mais útil que esses ogron estúpido!', '', 19865),
(90308, 'ptBR', '|TInterface\\Icons\\Ability_Druid_EmpoweredTouch:20|t Tarlna começa a canalizar |cFFFF0404|Hspell:175979|h[Gênese]|h|r.', '|TInterface\\Icons\\Ability_Druid_EmpoweredTouch:20|t Tarlna começa a canalizar |cFFFF0404|Hspell:175979|h[Gênese]|h|r.', 19865),
(90309, 'ptBR', 'Ei, sabe o que é mais burro que um ogron?', '', 19865),
(90310, 'ptBR', 'Dois ogron! Har har har!', '', 19865),
(90312, 'ptBR', 'Trabalha, seu ogron preguiçoso!', '', 19865),
(90313, 'ptBR', 'É melhor cê começar a quebrar pedra, ou eu quebro você!', '', 19865),
(90314, 'ptBR', 'Para de vagabundagem e quebra pedra, ogron burro!', '', 19865),
(90315, 'ptBR', 'Vá para a Estrada da Glória!', '', 19865),
(90316, 'ptBR', 'Thaelin chegará em breve.', 'Thaelin chegará em breve.', 19865),
(90317, 'ptBR', 'Test - male.', 'Test - female', 19865),
(90318, 'ptBR', 'Coloca esses ogron pra trabalhar de novo!', '', 19865),
(90319, 'ptBR', 'Controla os ogron, agora!', '', 19865),
(90320, 'ptBR', 'Faz esses ogron trabalhar ou afunda a cabeça deles!', '', 19865),
(90321, 'ptBR', 'Gosta de carne? A gente tem trocentas carnes frescas aqui! Quer quanto?', '', 19865),
(90322, 'ptBR', '', 'Comandante, pode me dar um momento?', 19865),
(90324, 'ptBR', '', 'Entendo sua preocupação quanto a esse artefato, Myshal, mas precisamos nos abster de interferir nos esforços de nossos aliados para obtê-lo.', 19865),
(90325, 'ptBR', 'Mas sacerdotisa, se o artefato for poderoso como dizem, a destruição que pode ser causada pelo usuário será devastadora!', '', 19865),
(90326, 'ptBR', '', 'É por isso que precisamos garantir que sejam nossos aliados a obtê-lo. Uma vez que eles o tenham, ofereceremos nossa orientação para que ele não seja usado da forma errada.', 19865),
(90327, 'ptBR', 'E se eles não derem ouvidos? E se a sede de poder de nossos aliados levá-los pelo caminho da destruição?', '', 19865),
(90328, 'ptBR', 'Eu adoro goblins, mas eles são um público difícil.', '', 19865),
(90329, 'ptBR', '', 'Esperemos que esse dia não chegue, Myshal.', 19865),
(90330, 'ptBR', '', 'Você parece perturbado, Myshal. O que o aflinge?', 19865),
(90331, 'ptBR', 'São as forças da Horda, sacerdotisa. Elas lutam com grande selvageria para obter o artefato antes de nós.', '', 19865),
(90332, 'ptBR', 'Você acha que eles querem usá-lo contra a Aliança?', '', 19865),
(90333, 'ptBR', '', 'Talvez eles lutem com tanta ferocidade por temor de que o usemos contra eles.', 19865),
(90334, 'ptBR', '', 'Saudações amigas.', 19865),
(90335, 'ptBR', '', 'Seu pedido já foi feito.', 19865),
(90336, 'ptBR', '', 'Obrigada, comandante. Vejo você em sua guarnição.', 19865),
(90337, 'ptBR', 'Você só recebe uma pequena centelha de loucura... e, se perdê-la, você não é nada.', '', 19865),
(90338, 'ptBR', 'Não importa o que as pessoas lhe digam. Palavras e ideias podem mudar o mundo.', '', 19865),
(90339, 'ptBR', 'Se há uma coisa que eu aprendi em Draenor é nunca puxar briga com um ogro. Eles não têm nada a perder.', '', 19865),
(90340, 'ptBR', '', 'Se esse artefato que Harrison está procurando for tão poderoso quanto ele parece pensar que é, espero que permaneça sem ser descoberto.\n\nA despeito de intenções, o uso de grandes poderes frequentemente tem consequências drásticas.', 19865),
(90341, 'ptBR', 'Mas ei, a Aliança nem é tão ruim. se você quer uma aventura linguística, vá beber com um anão.', '', 19865),
(90342, 'ptBR', 'Engenharia goblínica... é, claro. Vocês goblins têm mãos e um cérebro, e sangue suficiente para operar apenas uma parte de cada vez!', '', 19865),
(90343, 'ptBR', 'E esses draeneis? Ou, como dizem por aí, a outra raça azul. Dá para confiar em um exército que faz martelos de guerra com gemas cor-de-rosa?', '', 19865),
(90344, 'ptBR', 'Você sabe a diferença entre uma briga de bar e um casamento órquico? Nem eu.', '', 19865),
(90345, 'ptBR', 'Vocês estão bem mesmo por aqui. Vocês têm direito a armas e carga animal, a armar os animais de carga, a carregar os animais armados... Vocês podem fazer o que quiserem!', '', 19865),
(90346, 'ptBR', '', 'Comandante, pode dar um momento do teu tempo?', 19865),
(90347, 'ptBR', 'Alguém já esteve em Luaprata? Eu só me apresento em Luaprata uma noite de cada vez. É um lugar horrível e espalhafatoso.', '', 19865),
(90348, 'ptBR', 'Você imita personagens?', 'Você imita personagens?', 19865),
(90349, 'ptBR', '', 'Obrigada, comandante. Te vejo na tua guarnição.', 19865),
(90350, 'ptBR', 'Mostre a Barreira do Inferno antes da invasão.', 'Mostre a Barreira do Inferno antes da invasão.', 19865),
(90351, 'ptBR', 'Olá a todos! Aqui é o João Ligeiro!', '', 19865),
(90352, 'ptBR', 'Olha só ESSA aqui!', '', 19865),
(90353, 'ptBR', 'PODERES CÓSMICOS FENOMENAIS!!!', '', 19865),
(90354, 'ptBR', 'Dentro de uma lampadazinha.', '', 19865),
(90355, 'ptBR', '', 'A guerra não apenas visita estas terras, ela mora aqui. A violência viceja no passado, presente e futuro...', 19865),
(90356, 'ptBR', 'Eu só tinha uma chance.', '', 19865),
(90357, 'ptBR', 'Meu poder é macro!', '', 19865),
(90358, 'ptBR', '<Kharg não parece estar interessado.>', '', 19865),
(90359, 'ptBR', 'Em que Kharg pode ajudar você, gladiad$Gor:a;?', '', 19865),
(90360, 'ptBR', 'Eu quero lutar no Coliseu!', 'Eu quero lutar no Coliseu!', 19865),
(90361, 'ptBR', 'O preço para lutar no Coliseu é 100 Ossos Quebrados. Quer prosseguir?', '', 19865),
(90362, 'ptBR', 'Que que foi? Mim precisa exercitar mais!', '', 19865),
(90363, 'ptBR', 'Jamais deixe um kaliri no quarto. Eles ouvem TUDO.', '', 19865),
(90364, 'ptBR', 'Trilhatralha, precisamos consertar esse tanque. Nossa tropa precisa de ajuda no front!', '', 19865),
(90365, 'ptBR', 'Precisamos desse robô removedor de rochas trabalhando dobrado, Velochispa. Você espera que o Harrison Jones vasculhe aquela mina com uma picareta?', '', 19865),
(90366, 'ptBR', 'Quanto tempo leva uma manutenção normal, Enegroia? Nós precisávamos desse tanque em campo horas atrás!', '', 19865),
(90367, 'ptBR', 'Onde está a Porcatorta? Ela está trabalhando nesse tanque aranha há eras!', '', 19865),
(90368, 'ptBR', 'Todo esse trabalho de coordenação é cansativo. Uma cervejinha gelada com certeza caía bem...', '', 19865),
(90369, 'ptBR', 'Minhas desculpas, gladiad$Gor:a;, mas você já venceu no Coliseu esta semana. Volte na próxima semana.', '', 19865),
(90370, 'ptBR', 'Grange gomandange, você... hic! Eu drabalho gom uz orquish dejjde o gomezzo! ... Hic!', '', 19865),
(90371, 'ptBR', 'Acabou, Jacob. Venha sem resistência e nós colocamos você no primeiro grifo para a cadeia por traição.', 'Acabou, Jacob. Venha sem resistência e nós colocamos você no primeiro grifo para a cadeia por traição.', 19865),
(90372, 'ptBR', 'Tu campe$Gão:ã;! Então tu só pode lutar de novo no Coliseu daqui a seis...centos anos. Ou será que é uma semana? Mim não sabe!', '', 19865),
(90373, 'ptBR', 'Espera, você vai gostar disso.', '', 19865),
(90374, 'ptBR', 'Que som é esse? Parece um estouro de kodos...', '', 19865),
(90375, 'ptBR', 'Você nunca vai me pegar vivo... hic!', '', 19865),
(90376, 'ptBR', 'Um odor fétido paira no ar. Demônios...', '', 19865),
(90377, 'ptBR', 'Estamos com sorte! Vamos poder mostrar mais uma vez aos demônios que a verdadeira Horda não se dobra por nada!', '', 19865),
(90378, 'ptBR', 'É aqui que eles vão atacar primeiro...', '', 19865),
(90379, 'ptBR', 'Finalmente, uma luta...', '', 19865),
(90380, 'ptBR', 'Fique de olhos abertos. Eles vão surgir a qualquer momento.', '', 19865),
(90381, 'ptBR', 'Sinto a presença deles...', '', 19865),
(90382, 'ptBR', 'O clã Lua Negra é uma vergonha para todos os orcs. Cada membro que matarmos será uma lição para os outros.', '', 19865),
(90383, 'ptBR', 'Olá, bonec$Go:a;!', 'Olá, bonec$Go:a;!', 19865),
(90384, 'ptBR', 'Oh! Dois segundos como mulher e já estou sentindo os calores.', 'Oh! Dois segundos como mulher e já estou sentindo os calores.', 19865),
(90385, 'ptBR', '', 'O frio incomoda você mesmo, hein.', 19865),
(90386, 'ptBR', 'Há muitos aventureiros chegando em Ashran ultimamente. Alguns buscam o ganho pessoal, enquanto outros vêm ajudar a Aliança a enfrentar a Horda.\n\nQue tipo de aventura tu vieste procurar, camarada?', '', 19865),
(90387, 'ptBR', '', 'A certa distância você parece uma miudeza.', 19865),
(90388, 'ptBR', 'Comandante, reuniremos as tropas assim que você der o sinal.', '', 19865),
(90389, 'ptBR', 'Meu poder só é superado por minha estatura!', '', 19865),
(90390, 'ptBR', 'Espero que o último seja maior que os outros.', '', 19865),
(90391, 'ptBR', '', 'Recebam a cura!', 19865),
(90392, 'ptBR', '', 'Que a luz feche suas feridas!', 19865),
(90393, 'ptBR', '', 'O dia da sua morte ainda não chegou!', 19865),
(90394, 'ptBR', 'O líder deles chegou. Pela Horda!', '', 19865),
(90395, 'ptBR', 'Derrotado? Não! Charles, onde você estava?', '', 19865),
(90396, 'ptBR', 'Nada pode me deter!', '', 19865),
(90397, 'ptBR', 'Vivo ou morto, Minha estatura supera em muito a sua!', '', 19865),
(90398, 'ptBR', 'Vamos mandar esses ogros de volta para o Malho Imponente!', '', 19865),
(90399, 'ptBR', 'Vamos acabar com o sofrimento desses pobres diabos!', '', 19865),
(90400, 'ptBR', 'Os gorens fugiram, mas não acho que fugiram da gente...', '', 19865),
(90401, 'ptBR', 'O poder do sol e da lua flui por mim com um estrondo ensurdecedor.', '', 19865),
(90402, 'ptBR', 'Vou passar semanas pra tirar esses espinhos da minha armadura...', '', 19865),
(90403, 'ptBR', 'Por Alune, eu voltarei, mais forte do que nunca!', '', 19865),
(90404, 'ptBR', 'Nunca pensei que iria cansar de esmagar crânios.', '', 19865),
(90405, 'ptBR', 'Isto vai cuidar dos ogros inferiores.', '', 19865),
(90406, 'ptBR', 'Eles estão frenéticos demais para perceber que foram derrotados!', '', 19865),
(90407, 'ptBR', 'BUM!', '', 19865),
(90408, 'ptBR', 'CA-BUM!', '', 19865),
(90409, 'ptBR', 'BA-DA-BUM!', '', 19865),
(90410, 'ptBR', 'Saúdem $n! Campe$Gão:ã; do Coliseu! $GRei:Rainha; dos gladiadores!', '', 19865),
(90411, 'ptBR', 'Se tem um gronn vindo, os gorens não devem estar longe. Leve os peões a um lugar seguro!', '', 19865),
(90412, 'ptBR', 'Às armas! Aos seus postos! Olhem para baixo. Eles virão debaixo...', '', 19865),
(90413, 'ptBR', 'É aqui que eles vão atacar primeiro...', '', 19865),
(90414, 'ptBR', 'Eles estão vindo...', '', 19865),
(90415, 'ptBR', 'Cuidado com flores e gavinhas. Qualquer planta pode ser um inimigo...', '', 19865),
(90416, 'ptBR', 'Eles estão vindo...', '', 19865),
(90417, 'ptBR', 'Vou te deixar em brasa, coisa fofa!', 'Vou te deixar em brasa, coisa fofa!', 19865),
(90418, 'ptBR', 'Lembre-se: quando morrerem, não deixe que caiam sobre você.', '', 19865),
(90419, 'ptBR', '', 'Grange gomandange, você... hic! Eu drabalho gom a Alianzzza dejjde o gomezzo! ... Hic!', 19865),
(90420, 'ptBR', 'Acabou, Rorka. Venha sem resistência e nós colocamos você na primeira mantícora para a cadeia por traição.', 'Acabou, Rorka. Venha sem resistência e nós colocamos você na primeira mantícora para a cadeia por traição.', 19865),
(90421, 'ptBR', '', 'Você nunca vai me pegar viva... hic!', 19865),
(90422, 'ptBR', 'Não é possível que seja só isso.', '', 19865),
(90423, 'ptBR', 'Espalhem-se! Protejam as estruturas!', '', 19865),
(90424, 'ptBR', 'A primeira leva foi só para dar uma amaciada...', '', 19865),
(90425, 'ptBR', 'Espalhem-se! Eles atacarão de todas as direções!', '', 19865),
(90426, 'ptBR', 'Curvem-se perante a força da Horda de Ferro!', '', 19865),
(90427, 'ptBR', 'Vou arrancar sua cabeça a machadadas!', '', 19865),
(90428, 'ptBR', 'Acho que vou ter que cuidar de você eu mesmo.', '', 19865),
(90429, 'ptBR', 'Aonde você pensa que vai?', '', 19865),
(90430, 'ptBR', 'Espalhem-se! Protejam as estruturas!', '', 19865),
(90431, 'ptBR', 'Foi só um teste.', '', 19865),
(90432, 'ptBR', 'Espalhem-se! Protejam as estruturas!', '', 19865),
(90433, 'ptBR', 'Não sobrou nenhum no portão principal...', '', 19865),
(90434, 'ptBR', 'Espalhem-se! Protejam as estruturas!', '', 19865),
(90435, 'ptBR', 'Não vamos tombar assim tão fácil!', '', 19865),
(90436, 'ptBR', 'Espalhem-se! Não deixem eles ganharem terreno!', '', 19865),
(90437, 'ptBR', 'Os gorens fugiram, mas não acho que fugiram da gente...', '', 19865),
(90438, 'ptBR', '', 'Começa a batalha!', 19865),
(90439, 'ptBR', 'A... Horda é... dureza.', '', 19865),
(90440, 'ptBR', '', 'Está ficando quente aqui em cima...', 19865),
(90441, 'ptBR', '', 'Achou que eu fosse moleza que nem a Balinda? Ha!', 19865),
(90442, 'ptBR', '', 'Nem esquenta.', 19865),
(90443, 'ptBR', '', 'Use uma roupa mais quente da próxima vez.', 19865),
(90444, 'ptBR', '', 'Estou queimando!', 19865),
(90445, 'ptBR', 'É agora, soldados. Fiquem em guarda e nós venceremos.', '', 19865),
(90446, 'ptBR', 'O comandante inimigo chegou! Vai ser como nos velhos tempos!', '', 19865),
(90447, 'ptBR', '', 'Estilhaçada!', 19865),
(90448, 'ptBR', 'Ahhh, agora dá pra sentir meus dedos do pé. Valeu, $Gbróder:irmãzinha;. Não vou esquecer isso.', '', 19865),
(90449, 'ptBR', 'Sintam queimar!', '', 19865),
(90450, 'ptBR', 'A chapa está quente!', '', 19865),
(90451, 'ptBR', 'Eu me erguerei de novo... e de novo.', '', 19865),
(90452, 'ptBR', 'Eu me exauri.', '', 19865),
(90453, 'ptBR', 'Das cinzas às cinzas.', '', 19865),
(90454, 'ptBR', 'Quente demais para você?', '', 19865),
(90455, 'ptBR', 'Hehe, tá legal! Quem pediu uma dose cavalar de mão na fuça?', 'Hehe, tá legal! Quem pediu uma dose cavalar de mão na fuça?', 19865),
(90456, 'ptBR', '', 'Uma cura viria a calhar aqui!', 19865),
(90457, 'ptBR', '', 'Diga Bahh pros seus curadores!', 19865),
(90458, 'ptBR', 'Ninguém encontra Gordawg! Deve ter sido os lacaios de Kalandrios! Encham o ar de terra... sufoquem o vento!', '', 19865),
(90459, 'ptBR', 'A fúria terrena abandonou o trono! Os lacaios de Gordawg devem ser punidos... espalhem a terra pelo vento!', '', 19865),
(90460, 'ptBR', 'A fúria da terra está desaparecida, e os lacaios de Aborius não fazem nada para ajudar o trono! Se as águas se recusarem a fluir... nós as ferveremos!', '', 19865),
(90461, 'ptBR', 'Os lacaios de Gordawg estão fora de controle! Os seguidores de Incineratus queimam descontroladamente! Purifiquem o platô... afoguem e livrem-se dos elementos menores!', '', 19865),
(90462, 'ptBR', '', 'Ah, uma boa brisa fresca.', 19865),
(90463, 'ptBR', '|cFFFF0000|Hspell:155187|h[Bombas]|h|r causam dano a todos os jogadores na área quando o tempo acaba, ou quando são disparadas pelo jogador que as veste.', '|cFFFF0000|Hspell:155187|h[Bombas]|h|r causam dano a todos os jogadores na área quando o tempo acaba, ou quando são disparadas pelo jogador que as veste.', 19865),
(90464, 'ptBR', '|TInterface\\Icons\\ability_foundryraid_traindeath:20|tUm |cFFFF0000|Hspell:156554|h[Trem se Aproximando]|h|r matou você. Evite ficar parado na linha férrea se as portas da linha estiverem abertas.', '', 19865),
(90465, 'ptBR', 'Não venho aqui há milênios.', '', 19865),
(90466, 'ptBR', 'Hahaha.', '', 19865),
(90467, 'ptBR', '|TInterface\\Icons\\ability_whirlwind:20|t |cFFFF0000|Hspell:157943|h[Redemoinho]|h|r matou você. Evite ficar perto de Femo durante um |cFFFF0000|Hspell:157943|h[Redemoinho]|h|r.', '', 19865),
(90468, 'ptBR', '|cFFFF0000|Hspell:176123|h[Fogo Volátil]|h|r causa dano ao jogador com o Fogo Volátil e quaisquer outros jogadores próximos quando expira.', '|cFFFF0000|Hspell:176123|h[Fogo Volátil]|h|r causa dano ao jogador com o Fogo Volátil e quaisquer outros jogadores próximos quando expira.', 19865),
(90469, 'ptBR', '|cFFFF0000|Hspell:155200|h[Queimar]|h|r causa dano ao jogador Fixado pelo Elemental de Escória.', '|cFFFF0000|Hspell:155200|h[Queimar]|h|r causa dano ao jogador Fixado pelo Elemental de Escória.', 19865),
(90470, 'ptBR', '|cFFFF0000|Hspell:155209|h[Impacto]|h|r causa dano a todos os jogadores toda vez que o Coração da Montanha atinge 100 de energia.', '|cFFFF0000|Hspell:155209|h[Impacto]|h|r causa dano a todos os jogadores toda vez que o Coração da Montanha atinge 100 de energia.', 19865),
(90471, 'ptBR', '|cFFFF0000|Hspell:155223|h[Derreter]|h|r causa dano a todos os jogadores na área de efeito a cada segundo, até que eles saiam da área.', '|cFFFF0000|Hspell:155223|h[Derreter]|h|r causa dano a todos os jogadores na área de efeito a cada segundo, até que eles saiam da área.', 19865),
(90472, 'ptBR', '|cFFFF0000|Hspell:155242|h[Calor]|h|r causa mais dano a você dependendo do quão |cFFFF0000|Hspell:155240|h[Temperado]|h|r você estiver e acumula.', '|cFFFF0000|Hspell:155242|h[Calor]|h|r causa mais dano a você dependendo do quão |cFFFF0000|Hspell:155240|h[Temperado]|h|r você estiver e acumula.', 19865),
(90473, 'ptBR', 'A |cFFFF0000|Hspell:155743|h[Poça de Escória]|h|r é ativada uma vez que o Coração da Montanha deixar a Fornalha Explosiva, queimando todos os jogadores que ficarem parados nela.', 'A |cFFFF0000|Hspell:155743|h[Poça de Escória]|h|r é ativada uma vez que o Coração da Montanha deixar a Fornalha Explosiva, queimando todos os jogadores que ficarem parados nela.', 19865),
(90474, 'ptBR', '|cFFFF0000|Hspell:175104|h[Derreter Armadura]|h|r causa mais dano cada vez que você é atingido pelo feitiço. Jogue como tanque contra o Encarregado Feldspar, alternadamente com outros jogadores, para que suas aplicações de Derreter Armadura expirem.', '|cFFFF0000|Hspell:175104|h[Derreter Armadura]|h|r causa mais dano cada vez que você é atingido pelo feitiço. Jogue como tanque contra o Encarregado Feldspar, alternadamente com outros jogadores, para que suas aplicações de Derreter Armadura expirem.', 19865),
(90475, 'ptBR', 'Elementais de Escória tornam-se uma |cFFFF0000|Hspell:176133|h[Bomba de Escória]|h|r quando a vida deles está no fim.', 'Elementais de Escória tornam-se uma |cFFFF0000|Hspell:176133|h[Bomba de Escória]|h|r quando a vida deles está no fim.', 19865),
(90476, 'ptBR', '|cFFFF0000|Hspell:156147|h[O Cutelo]|h|r acumula quanto mais tempo você tanquear o Açougueiro.', '|cFFFF0000|Hspell:156147|h[O Cutelo]|h|r acumula quanto mais tempo você tanquear o Açougueiro.', 19865),
(90477, 'ptBR', '|cFFFF0000|Hspell:156143|h[O Amaciador]|h|r causa mais dano a você, por quanto mais tempo você tanquear o Açougueiro.', '|cFFFF0000|Hspell:156143|h[O Amaciador]|h|r causa mais dano a você, por quanto mais tempo você tanquear o Açougueiro.', 19865),
(90478, 'ptBR', '|cFFFF0000|Hspell:156153|h[Feridas Torrentes]|h|r matarão instantaneamente qualquer jogador com mais de 9 acumulações da penalidade.', '|cFFFF0000|Hspell:156153|h[Feridas Torrentes]|h|r matarão instantaneamente qualquer jogador com mais de 9 acumulações da penalidade.', 19865),
(90479, 'ptBR', '|cFFFF0000|Hspell:156157|h[Cutilada]|h|r divide seu dano entre todos os alvos e sempre mira o maior grupo dentro do alcance corpo a corpo.', '|cFFFF0000|Hspell:156157|h[Cutilada]|h|r divide seu dano entre todos os alvos e sempre mira o maior grupo dentro do alcance corpo a corpo.', 19865),
(90480, 'ptBR', 'Ó Capit$Gão:ã;, m$Geu:inha; Capit$Gão:ã;.', '', 19865),
(90481, 'ptBR', '|cFFFF0000|Hspell:156138|h[Mão Pesada]|h|r ataca o alvo mais próximo do tanque alvo atual do Açougueiro, ou ataca o tanque atual uma segunda vez se não houver nenhum outro tanque em alcance.', '|cFFFF0000|Hspell:156138|h[Mão Pesada]|h|r ataca o alvo mais próximo do tanque alvo atual do Açougueiro, ou ataca o tanque atual uma segunda vez se não houver nenhum outro tanque em alcance.', 19865),
(90482, 'ptBR', 'A terra esmagará seus ossos de mortal!', '', 19865),
(90483, 'ptBR', 'Você ousa se aproximar da fúria da tempestade!?', '', 19865),
(90484, 'ptBR', '%s prepara uma |cFFFF0404|Hspell:168148|h[Barragem de Canhão]|h|r! Proteja-se atrás de cobertura para sobreviver!', '', 19865),
(90485, 'ptBR', 'I DIED!', 'I DIED!', 19865),
(90486, 'ptBR', 'Minhas águas purificarão sua carne mortal patética!', '', 19865),
(90487, 'ptBR', 'Por que não posso lutar?', 'Por que não posso lutar?', 19865),
(90488, 'ptBR', 'Minhas chamas reduzirão seus ossos a cinzas!', '', 19865),
(90489, 'ptBR', '%s começa a canalizar |cFFFF0404|Hspell:157059|h[Runa da Garra da Terra]|h|r, encontre uma runa para se proteger!', '', 19865),
(90490, 'ptBR', '|cFFFF0404|Hspell:163590|h[Musgo Rastejante]|h|r está se espalhando! Use os lança-chamas para controlar seu crescimento!', '', 19865),
(90491, 'ptBR', 'O |cFFFF0404|Hspell:155539|h[Ímpeto Destruidor]|h|r de %s acaba.', '', 19865),
(90492, 'ptBR', 'Você saiu vitorios$Go:a;, gladiad$Gor:a;. Não lhe será permitido lutar novamente até a semana que vem.', '', 19865),
(90493, 'ptBR', 'Os Exarcas são encarregados de liderar o povo draenei. Nós representamos e defendemos os valores da nossa sociedade.', '', 19865),
(90494, 'ptBR', 'Não é o fim do mundo per se, mas com certeza dá pra ver!', '', 19865),
(90495, 'ptBR', 'Mrrgggl!', '', 19865),
(90496, 'ptBR', 'Mrrgl.', '', 19865),
(90497, 'ptBR', 'Mrrrrgl?', '', 19865),
(90498, 'ptBR', 'Mrrgl. Mrrgl.', '', 19865),
(90499, 'ptBR', '', 'A situação em Ashran está ficando perigosa demais. Hoje de manhã, quase tive a cabeça arrancada por um anciente!', 19865),
(90500, 'ptBR', '', 'A Aliança deve tá doida pra pegar esse artefato e soltar as feras em cima da gente.', 19865),
(90501, 'ptBR', '', 'Não se deve abusar da fúria da natureza assim. Eles ainda vão pagar caro por tamanha tolice.', 19865),
(90502, 'ptBR', '', 'As forças primevas de Draenor são selvagens e indomáveis. Elas resistem a toda tentativa de controle.', 19865),
(90503, 'ptBR', '', 'Isso vai dificultar as coisas pra tu no campo de batalha.', 19865),
(90504, 'ptBR', '', 'Não necessariamente. Ainda tenho meus dentes e minhas garras.', 19865),
(90505, 'ptBR', '', 'Ficou sabendo do que aconteceu? Os elfos sangrentos encontraram uma coisa graúda na mina.', 19865),
(90506, 'ptBR', 'Tipo um machadão?', '', 19865),
(90507, 'ptBR', '', 'Não, seu jumento! Parece que é parte do grande artefato que a Aliança está procurando.', 19865),
(90508, 'ptBR', 'Bah! Quem liga pra essas parafernálias poeirentas? Vim aqui pra amassar a cabeça dos meus inimigos!', '', 19865),
(90509, 'ptBR', '', 'Você faz alguma ideia de por que estamos em Ashran?', 19865),
(90510, 'ptBR', 'A única ideia que faço é guerrear contra os humanos de novo. Estou me coçando pra hora da batalha!', '', 19865),
(90511, 'ptBR', '', 'Faz anos que eu não saía para o campo.$B$B<O majestoso arquimago inspira profundamente.>$B$BNada como o cheiro de ar puro e perigo.', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(90512, 'ptBR', '', 'Por mim, seria eu que executaria essa missão. Mas o arquimago Hadggar insistiu que você teria uma abordagem mais delicada.', 19865),
(90513, 'ptBR', '', 'Ainda tenho cicatrizes da primeira vinda dos demônios a Azeroth. Lembro-me do terror, da loucura e da quietude que recai sobre uma cidade arrasada.$B$BFarei tudo que estiver ao meu alcance para impedir que isso aconteça de novo.', 19865),
(90514, 'ptBR', '', 'Não posso compreender o que levaria alguém a se afiliar à Legião.$B$BHá quem tenha sede de poder, mas não saiba como empregá-lo.', 19865),
(90515, 'ptBR', '', 'A aldeia dos sargerai é como uma colmeia.$B$BSe perturbarmos os moradores, seremos atacados. Se a destruirmos com fogo, destruiremos também os preciosos favos de mel.$B$BA única forma de obter a informação que queremos é com sutileza.', 19865),
(90516, 'ptBR', '', 'Falei com o Senhor da Guerra Volrath, hoje. Ele está preocupado com a recusa das tropas de pisar no cemitério.', 19865),
(90517, 'ptBR', 'Às armas! Aos seus postos! Os Senhores do Trovão querem brincar.', '', 19865),
(90518, 'ptBR', 'Ah é? Por que se recusam?', '', 19865),
(90519, 'ptBR', 'Eu já brinquei demais com vocês!', '', 19865),
(90520, 'ptBR', '', 'Os brutos que entraram lá disseram ter visto espíritos estranhos. Disseram que os necromantes estão escravizando os fantasmas dos ogros ancestrais.', 19865),
(90521, 'ptBR', 'Ogros fantasma? Não é à toa que querem distância. Não que eu tenha medo, mas prefiro inimigos nos quais consigo cravar meu machado.', '', 19865),
(90522, 'ptBR', '', 'A traição do exarca Othaar foi inesperada. Como pode um líder dos draeneis se voltar contra a Luz e se unir aos inimigos que perseguiram sua raça?', 19865),
(90523, 'ptBR', 'Já vi o bastante. Lute suas próprias batalhas, ó grande e poderoso rei.', '', 19865),
(90524, 'ptBR', 'Nossa tarefa é cruel, mas necessária.', '', 19865),
(90525, 'ptBR', '', 'Seus aliados novos lhe deram um novo nome e uma nova identidade: "Socrethar". Ele é um inimigo poderoso, e tenho medo do que é capaz.', 19865),
(90526, 'ptBR', '', 'Saudações, comandante. Gostaria de ver algum dos grandes eventos recentes?', 19865),
(90527, 'ptBR', 'Me mostre o que aconteceu na Batalha por Shattrath.', 'Me mostre o que aconteceu na Batalha por Shattrath.', 19865),
(90528, 'ptBR', '', 'Já ouviu falar de mim, $n? Meu nome é Modera, arquimaga do Conselho dos Seis, que governa o Kirin Tor e Dalaran.$B$BEu poderia devastar essa aldeia inteira se quisesse.$B$BMas não estamos aqui para isso. Eu aprendi com o passar dos anos que, às vezes, precisamos de mel para pegar uma mosca.', 19865),
(90529, 'ptBR', 'Lok''tar, comandante. Gostaria de ver algum dos grandes eventos recentes?', '', 19865),
(90530, 'ptBR', '', 'Olha! É $Go:a; $n!', 19865),
(90531, 'ptBR', '', 'Aquel$Ge:a; é $Go:a; $n? Dizem que el$Ge:a; é $Go:a; melhor $c de todos os tempos!', 19865),
(90532, 'ptBR', 'Parece que $Go:a; $n chegou para ajudar a rachar uns crânios da Aliança!', '', 19865),
(90533, 'ptBR', 'Você pode conjurar comida para mim?', 'Você pode conjurar comida para mim?', 19865),
(90534, 'ptBR', '', 'Está meio quente hoje, você não acha?', 19865),
(90535, 'ptBR', 'Esse povo da Aliança se acha muito esperto. Por trás da trégua, eles tão vasculhando estas terras de cima em baixo, atrás de uma arma poderosa, mas não pedem a nossa ajuda.\n\nClaro, dizem eles que a arma é pra Horda de Ferro, mas o que vai impedir de usarem a arma contra a gente, depois que a gente vazar deste mundo?\n\nPor mim, a gente pega a arma e mostra pra eles quem é que manda, tanto neste mundo, quanto no nosso.\n\nPela Horda!', '', 19865),
(90536, 'ptBR', '', 'Chegaram notícias do campo de batalha, chefia!', 19865),
(90537, 'ptBR', 'Tu mandou bem em me trazer as notícias. Agora, volta pra porrada.', '', 19865),
(90538, 'ptBR', '', 'É pra já, chefe!', 19865),
(90539, 'ptBR', '', 'Segundo os relatórios, tem um grupo de arakkoas proscritos hostis na porta do posto.', 19865),
(90540, 'ptBR', 'Como é, arakkoas proscritos? Achei que a gente era aliado aqui.', '', 19865),
(90541, 'ptBR', 'Vou ter que trocar uma palavrinha com nossos amigos dos Parlacorvos pra sacar qual é a desses arakkoas.', '', 19865),
(90542, 'ptBR', '', 'Chefia, os batedores disseram que a Aliança está energizando um anciente gigante pra mandar pra batalha!', 19865),
(90543, 'ptBR', 'Ha! Se estão achando que vão assustar a Horda com uma árvore, eles vão ter uma surpresa!', '', 19865),
(90544, 'ptBR', 'Vamos ver a cara que vão fazer quando a terra sob seus pés se erguer para lutar ao nosso lado!', '', 19865),
(90545, 'ptBR', '', 'Aquele elfo, Belloc, disse que precisa de mais homens para encontrar o grande artefato.', 19865),
(90546, 'ptBR', 'Esse tal Belloc tem sorte de eu não ter perdido minha paciência ainda! Não tenho soldado sobrando pra ficar cavando velharias.', '', 19865),
(90547, 'ptBR', 'Diz pro elfo que ele pode ficar com todos os voluntários que encontrar. E é melhor ele correr, antes que eu perca a paciência com ele!', '', 19865),
(90548, 'ptBR', '', 'Os batedores enviados à mina ôgrica estão relatando coisas esquisitas.', 19865),
(90549, 'ptBR', '', 'Dizem que tem uma criatura gigantesca, na mina, acabando com a raça dos brutos que cruzam o seu caminho.', 19865),
(90550, 'ptBR', 'Eu sou mestre em persuadir, mas parece que os sargerai valorizam a força, e não a eloquência.$B$BA forma mais rápida de ganhar a confiança deles é através da luta. Estou certo de que Modera te mandou para me ajudar por essa razão.', '', 19865),
(90551, 'ptBR', 'Os brutos são fortes, é verdade, mas não são espertos o bastante pra enfrentar um monstro desses. Vou mandar os Caçadores Sombrios para ver com o que estamos lidando.', '', 19865),
(90552, 'ptBR', 'Os Senhores do Trovão vieram nos dar uma lição sobre vingança. Vamos pô-los no seu devido lugar.', '', 19865),
(90553, 'ptBR', 'A primeira investida foi derrotada.', '', 19865),
(90554, 'ptBR', 'Espalhem-se! Não podemos ser flanqueados!', '', 19865),
(90555, 'ptBR', 'Quase pegamos eles!', '', 19865),
(90556, 'ptBR', 'Eles são obstinados, então. É agora, soldados. Pela Aliança!', '', 19865),
(90557, 'ptBR', 'Toque nas Bombas-relógio para mandá-las de volta ao céu!', 'Toque nas Bombas-relógio para mandá-las de volta ao céu!', 19865),
(90558, 'ptBR', 'Lembrem-se: fiquem de boca fechada, assim, se forem atingidos por um raio, não vão morder a língua.', '', 19865),
(90559, 'ptBR', 'Vá embora!', 'Vá embora!', 19865),
(90560, 'ptBR', 'Lágrimas por vir', 'Lágrimas por vir', 19865),
(90561, 'ptBR', 'Morto por dentro', 'Morto por dentro', 19865),
(90562, 'ptBR', 'Precisamos de aliados à frente', 'Precisamos de aliados à frente', 19865),
(90563, 'ptBR', 'Socorro!', 'Socorro!', 19865),
(90564, 'ptBR', 'Visões da morte', 'Visões da morte', 19865),
(90565, 'ptBR', 'Mantenha a calma', 'Mantenha a calma', 19865),
(90566, 'ptBR', 'Saque breve', 'Saque breve', 19865),
(90567, 'ptBR', 'Há milênios, demônios da Legião Ardente vieram ao nosso mundo e deram uma grande dádiva aos nossos líderes.$B$BDois deles, Kil''jaeden e Arquimonde, aceitaram, mas o último líder, o profeta Velen, recusou.$B$BEle e seus seguidores fugiram daquele mundo, sendo caçados para sempre por aqueles que antes lhes haviam estendido a mão.$B$BVelen era TOLO! E nós descendemos desses tolos, que viraram as costas para o paraíso!$B$BNão mais, irmãos! Hoje, nós nos rebelaremos e nos curvaremos aos senhores demoníacos. Eles nos deram outra chance de partilhar desse poder.$B$BEste, irmãos e irmãs, é o nosso VERDADEIRO destino. Hoje, nós trilharemos o caminho dos nossos predecessores, os eredar, e reivindicaremos o que é nosso de direito!', '', 19865),
(90568, 'ptBR', 'O trabalho da Legião não pode ser interrompido. Em Draenor, há quem deseje atrapalhar esses planos, especialmente os descrentes — os draeneis que ainda seguem a Luz.$B$BDestruam nossos semelhantes para que o trabalho dos mestres continue. Derrotem os draeneis para provarmos nossa lealdade à Legião. Se arrasarmos Shattrath, os demônios nos prometem a glória da imortalidade!', '', 19865),
(90569, 'ptBR', 'Nós, draeneis, somos a raça escolhida... civilizados, instruídos, profundamente intelectuais.$B$BNão há tecnologia que nossa mente não possa compreender nem magia que nossos arcanistas não possam dominar.$B$BNossa civilização em Argus era magnífica.$B$BNosso povo nunca foi escravo nem covarde, nunca fugiu de seu potencial.$B$BNosso povo tem o que é preciso para conquistar as estrelas!$B$BUnam-se a mim, irmãos e irmãs, e vamos retomar o que é nosso por direito!', '', 19865),
(90570, 'ptBR', '', 'Quando que o papai vai voltar pra casa?', 19865),
(90574, 'ptBR', '%s começa a lançar |cFFFF0404|Hspell:176464|h[Ondulações no Tempo]|h|r! Proteja-se!', '', 19865),
(90577, 'ptBR', '', 'Papai ainda está caçando?', 19865),
(90579, 'ptBR', 'Quero construir um prédio novo.', 'Quero construir um prédio novo.', 19865),
(90588, 'ptBR', 'Tudo do bom e do melhor para você, comandante.', '', 19865),
(90589, 'ptBR', 'Você pode fazer sua escolha na mesa de desenho, comandante.', '', 19865),
(90590, 'ptBR', 'Fortaleça minha armadura e arma para que não percam a firmeza.', 'Fortaleça minha armadura e arma para que não percam a firmeza.', 19865),
(90591, 'ptBR', 'Ranjit cria uma |cFFFF0000|Hspell:153759|h[Barreira de Vento]|h|r perto de |cFFFF0000$n|r!', 'Ranjit cria uma |cFFFF0000|Hspell:153759|h[Barreira de Vento]|h|r perto de |cFFFF0000$n|r!', 19865),
(90592, 'ptBR', 'Ranjit usa sua técnica secreta: |cFFFF0000|Hspell:156793|h[Quatro Ventos]|h|r!', 'Ranjit usa sua técnica secreta: |cFFFF0000|Hspell:156793|h[Quatro Ventos]|h|r!', 19865),
(90593, 'ptBR', '|TInterface\\Icons\\ability_fixated_state_red:20|tUm Clarão Solar está |cFFFF0000|Hspell:176544|h[Fixado]|h|r em você! Se ele chegar até você vai |cFFFF0000|Hspell:153828|h[Explodir]|h|r!', '', 19865),
(90594, 'ptBR', 'Um Clarão Solar se |cFFFF0000|Hspell:176544|h[Fixou]|h|r em |cFFFF0000$n|r!', 'Um Clarão Solar se |cFFFF0000|Hspell:176544|h[Fixou]|h|r em |cFFFF0000$n|r!', 19865),
(90595, 'ptBR', '|cFFFF0000$n|r tornou-se alvo da |cFFFF0000|Hspell:154043|h[Superarma]|h|r dos Arakkoas!', '|cFFFF0000$n|r tornou-se alvo da |cFFFF0000|Hspell:154043|h[Superarma]|h|r dos Arakkoas!', 19865),
(90596, 'ptBR', '|cFFFF0000$n|r tornou-se o alvo para ser |cFFFF0000|Hspell:153954|h[Jogado do Alto]|h|r!', '|cFFFF0000$n|r tornou-se o alvo para ser |cFFFF0000|Hspell:153954|h[Jogado do Alto]|h|r!', 19865),
(90597, 'ptBR', 'Tremam ante o poder dos Renegados!', '', 19865),
(90598, 'ptBR', 'Tiro e queda.', '', 19865),
(90599, 'ptBR', 'Eu vou lhe descer a lenha.', '', 19865),
(90600, 'ptBR', 'Não se mexa.', '', 19865),
(90601, 'ptBR', 'Você vai sentir uma picadinha.', '', 19865),
(90602, 'ptBR', 'Você já morreu.', '', 19865),
(90603, 'ptBR', 'Vamos dançar.', '', 19865),
(90604, 'ptBR', 'Não canse a minha beleza.', 'Não canse a minha beleza.', 19865),
(90605, 'ptBR', 'Bem na fuça.', '', 19865),
(90606, 'ptBR', 'Você servirá na morte.', '', 19865),
(90607, 'ptBR', 'Que a Dama Sombria olhe por vós.', '', 19865),
(90608, 'ptBR', 'Acabou?', '', 19865),
(90609, 'ptBR', 'Você não vale a pena.', '', 19865),
(90610, 'ptBR', 'Você não presta nem para virar carniçal.', '', 19865),
(90611, 'ptBR', 'Sabia que você não ia durar muito.', '', 19865),
(90612, 'ptBR', 'Você não merece minha misericórdia.', '', 19865),
(90613, 'ptBR', 'Qual é a sua vontade, comandante?', 'Qual é a sua vontade, comandante?', 19865),
(90614, 'ptBR', 'Que a Dama Sombria lhe sorria.', '', 19865),
(90615, 'ptBR', 'Mandarei seus cumprimentos à Dama Sombria.', '', 19865),
(90616, 'ptBR', 'Ao seu dispor.', '', 19865),
(90617, 'ptBR', 'Dê a ordem e considere-a cumprida.', '', 19865),
(90618, 'ptBR', 'Meu arco está pronto.', '', 19865),
(90619, 'ptBR', 'Seu desejo é uma ordem.', '', 19865),
(90620, 'ptBR', 'Sim, comandante?', '', 19865),
(90621, 'ptBR', 'Você pagará... por isso...', '', 19865),
(90622, 'ptBR', '', 'Não se preocupe, não vou demorar.', 19865),
(90623, 'ptBR', '', 'Quer que eu corte aonde primeiro? Que tal... aqui?', 19865),
(90624, 'ptBR', '', 'Vou te mostrar como é que se faz.', 19865),
(90625, 'ptBR', '', 'Vou acabar contigo bem devagarzinho. Quero saborear teus gritos.', 19865),
(90626, 'ptBR', '', 'Tu quer brigar comigo, não quer?', 19865),
(90627, 'ptBR', '', 'Quero ver se tu tem sangue nas ventas.', 19865),
(90628, 'ptBR', '', 'Vou te descer a lenha.', 19865),
(90629, 'ptBR', '', 'Demorou. Eu te mato antes.', 19865),
(90630, 'ptBR', '', 'Ops. Quem fui?', 19865),
(90631, 'ptBR', '', 'Será que dá pra gritar mais alto? Mal consigo te ouvir.', 19865),
(90632, 'ptBR', '', 'Aprenda com um Ferro Negro.', 19865),
(90633, 'ptBR', '', 'Se pá eu te cortei demais.', 19865),
(90634, 'ptBR', '', 'Não acredito que foi tão fácil.', 19865),
(90635, 'ptBR', '', 'Não deu nem pro gasto.', 19865),
(90636, 'ptBR', '', 'Bom, pelo menos tu morreu duma vez.', 19865),
(90637, 'ptBR', '', 'Mais sorte na próxima.', 19865),
(90638, 'ptBR', '', 'O que posso fazer por ti?', 19865),
(90639, 'ptBR', '', 'Bom te ver, comandante.', 19865),
(90640, 'ptBR', '', 'O prazer é meu.', 19865),
(90641, 'ptBR', '', 'Minha lâmina é sua, comandante.', 19865),
(90642, 'ptBR', '', 'Alguma treta pra desembolar, comandante?', 19865),
(90643, 'ptBR', '', 'Pode contar comigo.', 19865),
(90644, 'ptBR', '', 'Ao seu dispor.', 19865),
(90645, 'ptBR', '', 'Diga onde e eu estarei lá.', 19865),
(90646, 'ptBR', '', 'Ah... me pegaram...', 19865),
(90647, 'ptBR', 'De joelhos, escravo!', '', 19865),
(90648, 'ptBR', '100 peças de ouro para o ogro que me trouxer a cabeça dessa criatura ignóbil!', '', 19865),
(90649, 'ptBR', 'Vou lançar uma com recarga grande.', 'Vou lançar uma com recarga grande.', 19865),
(90650, 'ptBR', 'Saudações, Comandante $p.', '', 19865),
(90651, 'ptBR', 'Só mais um lançamento...', '', 19865),
(90652, 'ptBR', 'Um dia ruim de pesca continua sendo bem melhor do que um dia bom no trabalho.', '', 19865),
(90653, 'ptBR', 'Aqui, peixinho, peixinho, peixinho...', '', 19865),
(90654, 'ptBR', 'Está gastando tempo demais pescando? Está aí um bom problema para se ter.', '', 19865),
(90655, 'ptBR', 'Você pode fazer sua escolha na mesa de desenho, comandante.', '', 19865),
(90656, 'ptBR', '', 'Saudações, Comandante $p.', 19865),
(90657, 'ptBR', '$N está sob a nossa proteção.', '', 19865),
(90658, 'ptBR', 'Vocês não vão ferir $geste:esta; $c.', '', 19865),
(90659, 'ptBR', 'Os Guardiões da Forja protegem $geste:esta; $r.', '', 19865),
(90660, 'ptBR', 'Vou te deixar em brasa, coisa fofa!', '', 19865),
(90661, 'ptBR', 'Quem pediu uma dose cavalar de mão na fuça?', '', 19865),
(90662, 'ptBR', 'Litocerne foi um mero contratempo!', '', 19865),
(90663, 'ptBR', 'Podem ir começando sem mim. Preciso conjurar um pouco de água.', '', 19865),
(90664, 'ptBR', 'Mal posso esperar pra descer o sarrafo nesse energúmeno junto com vocês!', '', 19865),
(90665, 'ptBR', 'Vai se preparando pra se defender, desgraceira!', '', 19865),
(90666, 'ptBR', 'Tem uma coisinha que você vai adorar!', '', 19865),
(90667, 'ptBR', 'Quem é o cara? Quem é o cara? Ahn? É isso aí, nós somos os caras!', '', 19865),
(90668, 'ptBR', 'Não deu nem pra suar!', '', 19865),
(90669, 'ptBR', 'Se não for trabalho, vocês podem me ajudar!', '', 19865),
(90670, 'ptBR', 'Depois não digam que não avisei!', '', 19865),
(90671, 'ptBR', 'Testemunhem todo o poder de Millhouse Manavento!', '', 19865),
(90672, 'ptBR', 'Eu sou sua RUÍIIIINA!', '', 19865),
(90673, 'ptBR', 'Mais sorte na próxima, BWAHAHAHA!', '', 19865),
(90674, 'ptBR', 'Salve, comandante! Seu fiel servo, Millhouse Manavento, está a seu dispor!', '', 19865),
(90675, 'ptBR', 'Você não teria acesso a nenhuma arma N.U.C.L.E.A.R. por acaso?', '', 19865),
(90676, 'ptBR', 'Me mostre a direção!', '', 19865),
(90677, 'ptBR', 'Só um minutinho, preciso dar um grau nas magias aqui.', '', 19865),
(90678, 'ptBR', 'Falta muito pra gente destruir o mundo? Hein, hein?', '', 19865),
(90679, 'ptBR', 'Vocês todos serão meus escravos! Quer dizer... oi, tudo bem?', '', 19865),
(90680, 'ptBR', 'Caso você tenha algum artefato valiosíssimo e perdido no tempo sobrando, eu coleciono.', '', 19865),
(90681, 'ptBR', 'Você por acaso já tomou uma porrada de uma minhoca de pedra na cara? Pois é, é tão ruim quanto parece.', '', 19865),
(90682, 'ptBR', 'Me cura! Por tudo que é mais sagrado, me cura! Eu vou morrer!', '', 19865),
(90683, 'ptBR', 'Krud chegou! É melhor o nojentinho que pensa que vai derrubar Krud trazer tributo. Se trazer antes de Krud ficar sem paciência, ganha o direito de ser trucidado por Krud.', '', 19865),
(90684, 'ptBR', 'Há! Cê deve querer muito que Krud te parta no meio. Felicidade em dobro pra Krud!', '', 19865),
(90685, 'ptBR', 'Há! Krud sabia que ninguém tem coragem de encarar Krud. Cê num ser nem metade do lutador que Krud ser.', '', 19865),
(90686, 'ptBR', 'Quando isso acabar, vai ter coveiro levando dias pra descobrir que parte é de que corpo.', '', 19865),
(90687, 'ptBR', 'Patético... Krud pode cortar esse tempo de matança pela metade.', '', 19865),
(90688, 'ptBR', 'Agradeço por poupar Leorajh.', '', 19865),
(90689, 'ptBR', 'Leorajh e a pedra do sol serve bem você. Leorajh traz glória para o clã!', '', 19865),
(90690, 'ptBR', 'Tique... taque... tique... taque...', '', 19865),
(90691, 'ptBR', 'Quem armou a bomba? Eu.', '', 19865),
(90692, 'ptBR', 'Hora de afundar crânios.', '', 19865),
(90693, 'ptBR', 'Você não vai conseguir entrar no Ringue de Sangue de jeito nenhum.', '', 19865),
(90694, 'ptBR', 'Quando começaram a deixar esses verme entrar no campo de prova?', '', 19865),
(90695, 'ptBR', 'Essa luta vai ser rápida.', '', 19865),
(90696, 'ptBR', 'Passei o dia todo matando nojentinhos feito você.', '', 19865),
(90697, 'ptBR', 'HÁ! Achou que ia passar por mim?', '', 19865),
(90698, 'ptBR', 'Cuidado com essa fera, seus idiotas! Vocês não têm ideia do quanto me custou para trazer ela aqui!', '', 19865),
(90699, 'ptBR', 'Parem de ficar olhando e coloquem essa criatura numa jaula!', '', 19865),
(90700, 'ptBR', 'Façam seu trabalho, imbecis! Essa fera vale mais do que a vida de vocês dois!', '', 19865),
(90701, 'ptBR', 'Se a Aliança quer Volrath, vai ter que passar por mim primeiro.', '', 19865),
(90702, 'ptBR', '', 'Bom ver você.', 19865),
(90703, 'ptBR', '', 'Vá com os espíritos, comandante.', 19865),
(90704, 'ptBR', '', 'Vigie as sombras, comandante.', 19865),
(90705, 'ptBR', 'Há muito tempo, antes de ser infestada por saberons, esta aldeia era pacífica. Os saberons invadiram na calada da noite e nos mataram enquanto dormíamos.$B$BTudo que restou do meu povo são nossos ossos sob a terra.', '', 19865),
(90706, 'ptBR', 'Desculpa, $Gguri:guria;, mas eu não posso dar o acesso ao cofre para ti.\n\nÉ aqui que o Dr. Jones está guardando os artefatos dele em segurança. Mesmo que a Liga dos Exploradores esteja deixando aventureiros guardarem os equipamentos no espaço extra, o cofre continua restrito.', '', 19865),
(90707, 'ptBR', 'vira seu |Hitem:118427|h|cFFFFFFFF[Card de Hearthstone Autografado]|r|h, revelando um |cFFFFFFFF[Card de Hearthstone Comum]|r!', 'vira seu |Hitem:118427|h|cFFFFFFFF[Card de Hearthstone Autografado]|r|h, revelando um |cFFFFFFFF[Card de Hearthstone Comum]|r!', 19865),
(90708, 'ptBR', 'Fatiado e fermentado.', '', 19865),
(90709, 'ptBR', 'É isso aí, meninos e meninas, chegou a hora!', '', 19865),
(90710, 'ptBR', 'Não importa quantos cês são! Um só golpe, e derrubo cês todos.', '', 19865),
(90711, 'ptBR', 'vira seu |Hitem:118427|h|cFFFFFFFF[Card de Hearthstone Autografado]|r|h, revelando um |cFF0070dd[Card de Hearthstone Raro]|r!', 'vira seu |Hitem:118427|h|cFFFFFFFF[Card de Hearthstone Autografado]|r|h, revelando um |cFF0070dd[Card de Hearthstone Raro]|r!', 19865),
(90712, 'ptBR', 'vira seu |Hitem:118427|h|cFFFFFFFF[Card de Hearthstone Autografado]|r|h, revelando um |cFFa335ee[Card de Hearthstone Épico]|r!', 'vira seu |Hitem:118427|h|cFFFFFFFF[Card de Hearthstone Autografado]|r|h, revelando um |cFFa335ee[Card de Hearthstone Épico]|r!', 19865),
(90713, 'ptBR', 'Ratos mortos!', '', 19865),
(90714, 'ptBR', 'Essa não foi uma empreitada lucrativa.', '', 19865),
(90715, 'ptBR', 'vira seu |Hitem:118427|h|cFFFFFFFF[Card de Hearthstone Autografado]|r|h, revelando um |cffff8000[Card de Hearthstone Lendário]|r!', 'vira seu |Hitem:118427|h|cFFFFFFFF[Card de Hearthstone Autografado]|r|h, revelando um |cffff8000[Card de Hearthstone Lendário]|r!', 19865),
(90716, 'ptBR', 'Na cara!', '', 19865),
(90717, 'ptBR', 'Come poeira!', '', 19865),
(90718, 'ptBR', 'Eu coloco pra fora poças de vômito mais duronas que cê.', '', 19865),
(90719, 'ptBR', '', 'Hora de você ir embora!', 19865),
(90720, 'ptBR', 'Não sei se beijo... ou se luto com você.', '', 19865),
(90721, 'ptBR', 'Eu tava atrás de uma luta!', '', 19865),
(90722, 'ptBR', 'Vitória ou morte. Não restam mais opções.', '', 19865),
(90723, 'ptBR', 'Eu lutei muito para ter a oportunidade de servir sob o seu comando.$B$BÉ uma honra.', '', 19865),
(90724, 'ptBR', 'Assim será, comandante.', '', 19865),
(90725, 'ptBR', 'Agora mesmo, comandante.', '', 19865),
(90726, 'ptBR', 'Você pode fazer sua escolha na mesa de desenho, comandante.', '', 19865),
(90727, 'ptBR', 'Você pode fazer sua escolha na mesa de desenho, comandante.', '', 19865),
(90728, 'ptBR', 'O biscoito da sorte diz...', '', 19865),
(90729, 'ptBR', 'Ai, rapaz...', '', 19865),
(90730, 'ptBR', 'Horrível, simplesmente horrível.', '', 19865),
(90731, 'ptBR', 'Por favor, nunca mais.', '', 19865),
(90732, 'ptBR', 'O quê?! Como assim, isso foi o máximo, cara.', '', 19865),
(90733, 'ptBR', 'Viu a cara que ele fez?', '', 19865),
(90734, 'ptBR', 'Não tem preço!', '', 19865),
(90735, 'ptBR', 'Belloc! É você?', 'Belloc! É você?', 19865),
(90736, 'ptBR', 'Olá, de novo. Ficamos sabendo que há artefatos ocultos aqui, neste lugar chamado Ashran. Artefatos de um clã remanescente dos ogros do Malho Imponente.$B$BVocê tem alguma ideia de que poder eles podem ter?$B$BE, é claro, Harrison Jones está aqui, assim como aquela Liga dos Exploradores irritante. Não podemos deixar que eles encontrem o artefato primeiro.', '', 19865),
(90737, 'ptBR', 'Acho que precisaremos voltar lá em breve.', '', 19865),
(90738, 'ptBR', 'É, eu sei. Mas aqueles bichos-aves malucos realmente me dão arrepios.', '', 19865),
(90739, 'ptBR', 'A morte lhe dá boas-vindas.', '', 19865),
(90740, 'ptBR', 'Pela luz!', '', 19865),
(90741, 'ptBR', 'Vem cá! Me dá um motivo pra eu me curar.', '', 19865),
(90742, 'ptBR', '... Sigh...', '', 19865),
(90743, 'ptBR', 'Quero ver curar depois dessa.', '', 19865),
(90744, 'ptBR', 'Devia ter trago um curador melhor, camarada.', '', 19865),
(90745, 'ptBR', '... Sigh...', '', 19865),
(90746, 'ptBR', 'É uma honra servir como curador, comandante.', '', 19865),
(90747, 'ptBR', 'Bons ventos te levem.', '', 19865),
(90748, 'ptBR', 'Onde estava o meu tanque...?', '', 19865),
(90749, 'ptBR', 'Olá, Comandante $n.', '', 19865),
(90750, 'ptBR', 'Pelo Lobo do Gelo!', '', 19865),
(90751, 'ptBR', 'Pela honra!', '', 19865),
(90752, 'ptBR', 'À batalha!', '', 19865),
(90753, 'ptBR', 'Lok-tar ogar! Vitória ou morte!', '', 19865),
(90754, 'ptBR', 'Receba meu machado!', '', 19865),
(90755, 'ptBR', 'Por Presa Pétrea!', '', 19865),
(90756, 'ptBR', 'Foi uma boa morte.', '', 19865),
(90757, 'ptBR', 'Morra com dignidade.', '', 19865),
(90758, 'ptBR', 'Lok-tar!', '', 19865),
(90759, 'ptBR', 'Foi uma boa luta!', '', 19865),
(90760, 'ptBR', 'Throm-Ka.', '', 19865),
(90761, 'ptBR', 'Os Lobos do Gelo estão prontos.', '', 19865),
(90762, 'ptBR', 'Lok-Regar.', '', 19865),
(90763, 'ptBR', 'Meu machado está pronto.', '', 19865),
(90764, 'ptBR', 'Nerok anseia pela batalha.', '', 19865),
(90765, 'ptBR', 'A Horda de Ferro vai pagar por meus irmãos e irmãs.', '', 19865),
(90766, 'ptBR', 'Lokra... me perdoe...', '', 19865),
(90767, 'ptBR', '|cFFFF0000AVISO!|r! Você entrou em uma área extremamente perigosa! |cFFFF0000Dê meia volta|r!', '', 19865),
(90768, 'ptBR', 'Depois de matar você, vou levar seus sapatos!', '', 19865),
(90769, 'ptBR', 'Hahahaha!', '', 19865),
(90770, 'ptBR', 'Hora de conhecer o carroção da dor e da carne morta!', '', 19865),
(90771, 'ptBR', 'Mais um crânio pra dependurar.', '', 19865),
(90772, 'ptBR', 'O cinto é meu!', '', 19865),
(90773, 'ptBR', 'O nariz fica comigo.', '', 19865),
(90774, 'ptBR', 'Este crânio é pequeno demais, é inútil. Traga-me outro!', '', 19865),
(90775, 'ptBR', 'Posso ficar com o seu crânio, quando você morrer?', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(90776, 'ptBR', 'Eu farei um totem com os cadáveres dos seus inimigos.', '', 19865),
(90777, 'ptBR', 'Hahahaha... ahem... salve.', '', 19865),
(90778, 'ptBR', 'Não! Eu perdi meu ankh.', '', 19865),
(90779, 'ptBR', '', 'Ah, $gherói:heroína;... Sabia que você viria. Contemple a fonte de sua ruína!', 19865),
(90780, 'ptBR', '', 'Agora vou lhe dar uma prova do novo poder da Horda de Ferro!', 19865),
(90781, 'ptBR', 'Estivemos estudando esse tal "Coração de Gorgorek". Ele guarda diversas semelhanças com certos artefatos titânicos que vimos lá em Azeroth.', '', 19865),
(90782, 'ptBR', 'Temos que chamar peritos para descobrir a origem e o propósito do artefato. Na verdade, talvez seja preciso levar o dispositivo para Azeroth a fim de estudá-lo melhor.', '', 19865),
(90783, 'ptBR', 'O artefato que descobrimos em Gorgrond parece ter as mesmas características deste.$B$BÉ muito provável que seja um fragmento menor deste dispositivo grande, que está intacto.$B$BSe uma mera lasca conseguiu evocar uma criatura colossal para ajudar você, imagine o que este dispositivo seria capaz de fazer...', '', 19865),
(90784, 'ptBR', '', 'Estivemos estudando esse tal "Coração de Gorgorek". Ele guarda diversas semelhanças com certos artefatos titânicos que vimos lá em Azeroth.', 19865),
(90785, 'ptBR', '', 'Temos que chamar peritos para descobrir a origem e o propósito do artefato. Na verdade, talvez seja preciso levar o dispositivo para Azeroth a fim de estudá-lo melhor.', 19865),
(90786, 'ptBR', '', 'O artefato que descobrimos em Gorgrond parece ter as mesmas características deste.$B$BÉ muito provável que seja um fragmento menor deste dispositivo grande, que está intacto.$B$BSe uma mera lasca conseguiu evocar uma criatura colossal para ajudar você, imagine o que este dispositivo seria capaz de fazer...', 19865),
(90787, 'ptBR', '', 'Por que viemos para Lua Negra? Min Loo sabe que eu odeio o escuro...', 19865),
(90788, 'ptBR', '', 'Melhorei nosso mapa: agora cada lugar está marcado com a cor do seu nível de perigo!', 19865),
(90789, 'ptBR', 'Já provou a culinária local? Esses draeneis sabem mesmo cozinhar.', '', 19865),
(90790, 'ptBR', 'Já foi ao Crescente da Lareira? Tem umas tortas deliciosas lá. E a Aldeia Embaari? Lá chegam diariamente produtos frescos de Elodor!', '', 19865),
(90791, 'ptBR', 'Eu gosto daqui do Vale da Lua Negra. É tão pacato e silencioso... diferente daquele lugar.', '', 19865),
(90792, 'ptBR', 'Quando aprimorarmos este barco, substituirei todas as peças pela metade do preço!', '', 19865),
(90793, 'ptBR', '', 'Esse barco é mesmo muito bom!', 19865),
(90794, 'ptBR', 'Zarg gosta de gatinhos. Zarg treinar gatinhos pra ser guerreiros fofinhos. \n\nQue foi? Tá me olhando assim por quê? \n\nTem alguma coisa contra gatinhos?', '', 19865),
(90795, 'ptBR', 'Você precisar falar com Varzok em Orgrimmar! Qualquer guarda lá informa você onde procurar.$b$bTem portal para Orgrimmar na cabana do xamã. Boa sorte!', '', 19865),
(90796, 'ptBR', '$n detonou Ressonância Destrutiva!', '', 19865),
(90797, 'ptBR', 'Já vi os saberons tirarem os ossos dos inocentes. Já vi os restos dos meus irmãos de clã serem cozidos no caldeirão maldito deles. Agora... serão os ossos dos saberons que vão ser profanados e fervidos!', '', 19865),
(90798, 'ptBR', 'Você honrou a memória do meu povo, $c. Leve esta bênção com você em sua jornada. Que ela possa guiar o seu braço e acelerar seu passo.', '', 19865),
(90799, 'ptBR', 'Rapaz, achei que fosse ser um esquema legal, vir aqui com a Sociedade. Como eu estava enganado!', '', 19865),
(90800, 'ptBR', '', 'O que você não gosta aqui? Os tesouros não são ruins.', 19865),
(90801, 'ptBR', 'Os tesouros não são o problema. O problema é que sempre tem um ogro querendo achatar minha cabeça ou um brutamontes da Aliança querendo me enfiar uma espada.', '', 19865),
(90802, 'ptBR', '', 'Não foi você que disse que ria na cara do perigo? Parece que você agora está com medinho daqui.', 19865),
(90803, 'ptBR', 'Não estou com medo, boneca. Acontece que a morte provoca uma queda vertiginosa na margem de lucro.', '', 19865),
(90804, 'ptBR', 'Esses orcs só sabem beber cerveja? O que um goblin tem que fazer pra conseguir uns bons drinques nesta joça?', '', 19865),
(90805, 'ptBR', '', 'Não é ruim. Bate até uma saudade.', 19865),
(90806, 'ptBR', 'Saudade? Como pode esta gororoba despertar saudade?', '', 19865),
(90807, 'ptBR', '', 'O gosto me lembra a água que usávamos para resfriar o maquinário, lá em casa. A parte que transbordava era a única coisa que tinha pra beber.', 19865),
(90808, 'ptBR', 'Nossa... é igualzinho mesmo.', '', 19865),
(90809, 'ptBR', 'Que tal vermos quem está do outro lado dessa loucura?', '', 19865),
(90810, 'ptBR', 'Depois das perdas sofridas durante o ataque ao Portal Negro, grande parte das nossas forças se reagrupou em Ashran. Infelizmente, logo seguiram as desavenças com a Aliança.\n\nVocê também vem em busca de refúgio, ou deseja alimentar ainda mais as chamas da batalha?', '', 19865),
(90811, 'ptBR', 'Justaposição temporal iminente!', '', 19865),
(90812, 'ptBR', '', 'Esses trolls não são tão maus assim. Eles são magrelos e falam engraçado, mas sabem fazer um arremessador de lanças! \n\nMal posso esperar pra furar bucho de anão com isso!', 19865),
(90813, 'ptBR', 'Uau! Funcionou. E não fomos invertidos pelo tempo.', '', 19865),
(90814, 'ptBR', 'A placa diz:\n\n“Eu sou $Go:a; Comandante $n, e essa é a minha loja favorita em Lança de Guerra.”', '', 19865),
(90815, 'ptBR', '', 'Não dá atenção pra essa placa aí, não, chefia. É só uma publicidadezinha de nada.', 19865),
(90816, 'ptBR', '', 'Isto não precisava terminar em violência.', 19865),
(90817, 'ptBR', '', 'Você queimará na Luz.', 19865),
(90818, 'ptBR', '', 'Pelos Sha''tari.', 19865),
(90819, 'ptBR', '', 'Pela Aliança, pelo Rei!', 19865),
(90820, 'ptBR', '', 'Você escolheu o lado errado.', 19865),
(90821, 'ptBR', '', 'Você fracassou na sua missão.', 19865),
(90822, 'ptBR', '', 'Comandante, acho que uma estalagem aumentaria bastante o moral.', 19865),
(90823, 'ptBR', '', 'Comandante, eu fiz uma contagem das defesas e acho que elas precisam ser balanceadas.', 19865),
(90824, 'ptBR', '', 'Comandante! ... Quando o Príncipe virá nos visitar?', 19865),
(90825, 'ptBR', '', 'Se eu escrever uma carta, você a levaria a Ventobravo por mim?', 19865),
(90826, 'ptBR', '', 'Ouvi dizer que vocês têm um príncipe devoto da Luz. Quando ele virá nos visitar?', 19865),
(90827, 'ptBR', '', 'Pela... Luz.', 19865),
(90828, 'ptBR', 'O Espírito do Exarca Hataaru começa a lançar |cFFFF0000|Hspell:176784|h[Campo de Dor]|h|r!', 'O Espírito do Exarca Hataaru começa a lançar |cFFFF0000|Hspell:176784|h[Campo de Dor]|h|r!', 19865),
(90829, 'ptBR', '', 'Vejamos qual é a cara dos seus ossos.', 19865),
(90830, 'ptBR', '', 'Você se importaria em ajudar no meu experimento?', 19865),
(90831, 'ptBR', '', 'Ah, não se mexa. Quero testar um feitiço novo.', 19865),
(90832, 'ptBR', '', 'Você é animal, vegetal, mineral ou é outra coisa?', 19865),
(90833, 'ptBR', '', 'Eu costumo usar fósseis, então pode ser que doa um pouquinho.', 19865),
(90834, 'ptBR', '', 'Ah, então é isso que acontece.', 19865),
(90835, 'ptBR', '', 'Que resultado interessante.', 19865),
(90836, 'ptBR', '', 'Nota mental: $n é muito sensível ao fogo.', 19865),
(90837, 'ptBR', '', 'Ops!', 19865),
(90838, 'ptBR', '', 'Tem toda sorte de balangandã brilhante enterrado aqui.', 19865),
(90839, 'ptBR', '', 'Ei, comandante, quando você morrer, eu posso ficar com a herança?', 19865),
(90840, 'ptBR', '', 'Viva pelo fóssil, torne-se um fóssil.', 19865),
(90841, 'ptBR', 'Róóótulaaas!', 'Róóótulaaas!', 19865),
(90842, 'ptBR', 'Morre! Morre morre morre!', 'Morre! Morre morre morre!', 19865),
(90843, 'ptBR', 'Hmm. Cheiro de carne!', 'Hmm. Cheiro de carne!', 19865),
(90844, 'ptBR', 'Hora do jantar? Hora do jantaaar!', 'Hora do jantar? Hora do jantaaar!', 19865),
(90845, 'ptBR', 'Que gostosinho!', 'Que gostosinho!', 19865),
(90846, 'ptBR', 'Hi hi hi! Sangue!', 'Hi hi hi! Sangue!', 19865),
(90847, 'ptBR', 'A gente mata! Mata mata mata!', 'A gente mata! Mata mata mata!', 19865),
(90848, 'ptBR', 'Não mata?', 'Não mata?', 19865),
(90849, 'ptBR', 'Só vai doer um pouquinho.', '', 19865),
(90850, 'ptBR', 'Por que você não morre?', 'Por que você não morre?', 19865),
(90851, 'ptBR', 'Vou reduzir você a cinzas!', '', 19865),
(90852, 'ptBR', 'Pela Ordem!', '', 19865),
(90853, 'ptBR', 'Ai ai ai ai ai ai!', 'Ai ai ai ai ai ai!', 19865),
(90854, 'ptBR', 'Você queimará por seus crimes!', '', 19865),
(90855, 'ptBR', 'Rukhmar, guie meu punho.', '', 19865),
(90856, 'ptBR', 'Você... você ruim.', 'Você... você ruim.', 19865),
(90857, 'ptBR', 'Não tem lugar para você no nosso futuro.', '', 19865),
(90858, 'ptBR', 'Não-não-não-não-não...', 'Não-não-não-não-não...', 19865),
(90859, 'ptBR', 'O progresso tem um preço.', '', 19865),
(90860, 'ptBR', 'Não tenho tolerância para selvageria.', '', 19865),
(90861, 'ptBR', 'Tolo cego.', '', 19865),
(90862, 'ptBR', 'Um futuro brilhante nos aguarda.', '', 19865),
(90863, 'ptBR', 'Salve, comandante. Espero que esteja tudo em ordem.', '', 19865),
(90864, 'ptBR', 'A luz dos Despertos está às suas ordens.', '', 19865),
(90865, 'ptBR', 'Você está radiante hoje.', '', 19865),
(90866, 'ptBR', 'Estou feliz por estar entre seus aliados.', '', 19865),
(90867, 'ptBR', 'Com licença, comandante, eu estou me sentindo um pouco... presa. Você não teria nenhuma missão para mim?', '', 19865),
(90868, 'ptBR', 'Estou voltando... Rukhmar.', '', 19865),
(90869, 'ptBR', 'Vocês não vão interferir!', 'Vocês não vão interferir!', 19865),
(90870, 'ptBR', 'Você se perdeu?', 'Você se perdeu?', 19865),
(90871, 'ptBR', 'Esses rylaks são propriedade da Horda de Ferro!', 'Esses rylaks são propriedade da Horda de Ferro!', 19865),
(90872, 'ptBR', 'O caminho que você trilha só leva à morte.', 'O caminho que você trilha só leva à morte.', 19865),
(90873, 'ptBR', 'Invasor!', 'Invasor!', 19865),
(90874, 'ptBR', 'Bin huruk thora korro... rra hokumm ura korak.', 'Bin huruk thora korro... rra hokumm ura korak.', 19865),
(90875, 'ptBR', 'Eu não temo a morte.', 'Eu não temo a morte.', 19865),
(90876, 'ptBR', 'Meus irmãos vão me vingar.', 'Meus irmãos vão me vingar.', 19865),
(90877, 'ptBR', 'Ah, ha! Mais adubo!', 'Ah, ha! Mais adubo!', 19865),
(90878, 'ptBR', 'Ninguém perturbará o deus florescente!', 'Ninguém perturbará o deus florescente!', 19865),
(90879, 'ptBR', 'Tire esse... arbusto do nosso jardim.', 'Tire esse... arbusto do nosso jardim.', 19865),
(90880, 'ptBR', 'Seu cadáver alimentará nosso deus!', 'Seu cadáver alimentará nosso deus!', 19865),
(90881, 'ptBR', 'Você sucumbirá à colheita!', 'Você sucumbirá à colheita!', 19865),
(90882, 'ptBR', 'Excelso genessauro, devore-me.', 'Excelso genessauro, devore-me.', 19865),
(90883, 'ptBR', 'Eu darei vida ao meu mestre.', 'Eu darei vida ao meu mestre.', 19865),
(90884, 'ptBR', 'O ciclo... continua...', 'O ciclo... continua...', 19865),
(90906, 'ptBR', 'Mmm... Saboroso!', '', 19865),
(90907, 'ptBR', 'Mira no coração!', 'Mira no coração!', 19865),
(90912, 'ptBR', '', 'Histórias sobre os seus feitos chegam longe, $c. Permita-me recontar algumas das suas maiores proezas.', 19865),
(90913, 'ptBR', '%s abre um tabuleiro de Hearthstone! Quem está pronto para jogar?', '%s abre um tabuleiro de Hearthstone! Quem está pronto para jogar?', 19865),
(90914, 'ptBR', '%s abre um novo pacote de cards de Hearthstone. Hummm, que maravilha esse cheiro de card novo!', '%s abre um novo pacote de cards de Hearthstone. Hummm, que maravilha esse cheiro de card novo!', 19865),
(90915, 'ptBR', '%s acabou de vencer um jogo de Hearthstone!', '%s acabou de vencer um jogo de Hearthstone!', 19865),
(90916, 'ptBR', '|TInterface\\Icons\\spell_burningbladeshaman_molten_torrent.blp:20|t |cFFFF0404|Hspell:154938|h[Torrente Derretida]|h|r matou você. Minimize o dano ficando próximo de diversos aliados.', '', 19865),
(90917, 'ptBR', 'Pra onde foi todo mundo?', '', 19865),
(90918, 'ptBR', '|TInterface\\Icons\\spell_burningbladeshaman_molten_torrent.blp:20|t |cFFFF0404|Hspell:154938|h[Torrente Derretida]|h|r matou você. Ficar perto de um grupo de aliados reduz a quantidade de dano recebido por todos os afetados!', '', 19865),
(90919, 'ptBR', '|TInterface\\Icons\\spell_burningbladeshaman_molten_torrent.blp:20|t |cFFFF0404|Hspell:154938|h[Torrente Derretida]|h|r matou você.', '', 19865),
(90920, 'ptBR', 'Quer espinhos? Eu tenho espinho de sobra. Espinhos combinam com tudo! Vai por mim, não tem erro.', '', 19865),
(90921, 'ptBR', 'O altar tem dezenas de nichos onde os seguidores do Profeta colocaram cristais de memória, lastimando o sacrifício do grande líder. Há centenas de orações e lembranças aqui, de camponeses a exarcas e todo o resto.', '', 19865),
(90922, 'ptBR', 'A remessa da Forja não chegou, então os rapazes saíram cedo.', '', 19865),
(90923, 'ptBR', 'Escute a mensagem final do Profeta.', 'Escute a mensagem final do Profeta.', 19865),
(90924, 'ptBR', 'O lote de armas da Forja não chegou, o que que tá rolando lá em cima?', '', 19865),
(90925, 'ptBR', 'Essas armas não estão imbuídas! Ka''graz tá de férias ou algo assim?', '', 19865),
(90926, 'ptBR', 'Este lugar precisa de mais espinhos.', 'Este lugar precisa de mais espinhos.', 19865),
(90927, 'ptBR', '', 'Histórias sobre os seus feitos chegam longe, $c. Permita-me recontar algumas das suas maiores proezas.', 19865),
(90928, 'ptBR', 'Cara, quem desligou o aquecedor? Tá CONGELANDO aqui!', '', 19865),
(90929, 'ptBR', 'O que é que o Kromog tem? Faz um tempo que ele não resmunga de nada.', '', 19865),
(90930, 'ptBR', 'Agora não! Estes humanos trouxeram uma carne de dar água na boca! Olhe só pra isso! Imagine só rasgar esta carninha suculenta com as suas presas, o estalar dos ossos enquanto você a devora... \n\n<Os olhos do worgen fitam o vazio...>\n\nO que é que você queria mesmo?', '', 19865),
(90931, 'ptBR', 'Quando um Druida luta em forma de árvore, um grito de guerra comum de ouvir é "Vem pro pau!"', '', 19865),
(90932, 'ptBR', 'Talador: A Batalha por Shattrath', 'Talador: A Batalha por Shattrath', 19865),
(90933, 'ptBR', 'Serra Fogofrio: Passo do Trovão', 'Serra Fogofrio: Passo do Trovão', 19865),
(90934, 'ptBR', 'Estas caixas de minério estão se acumulando, os caras na Fornalha Explosiva tão morcegando!', '', 19865),
(90935, 'ptBR', 'Não pergunte as horas a um relojoeiro gnomo faminto. Ele sempre vai responder "Hora de matar a fomêêê!"', '', 19865),
(90936, 'ptBR', 'Talador: Batalha por Shattrath', 'Talador: Batalha por Shattrath', 19865),
(90937, 'ptBR', 'Vale da Lua Negra: Caem as trevas', 'Vale da Lua Negra: Caem as trevas', 19865),
(90938, 'ptBR', 'Eu tentei falar com o Feldspar na linha e ele não está respondendo, aposto que ele tá de papinho com o Encarregado Jorge de novo.', '', 19865),
(90939, 'ptBR', 'Os taurens vivem oferecendo iogurte pras pessoas depois que souberam que "vale por um bifinho".', '', 19865),
(90940, 'ptBR', 'Um antigo profeta ladino costumava dizer: "Sutileza gera sutileza".', '', 19865),
(90941, 'ptBR', 'O que oferecer a um pandaren sedento além de cerveja? Chá-do-Pan, ora.', '', 19865),
(90942, 'ptBR', 'Por que fizeram uma fogueira? Não tão vendo as caixas de munição empilhadas ali!?', '', 19865),
(90943, 'ptBR', 'Porque tá frio!!!', '', 19865),
(90944, 'ptBR', 'Caçadores acham que um dia é do caçador, e o outro é do caçador também.', '', 19865),
(90945, 'ptBR', 'Barreira do Inferno: Para o Portal', 'Barreira do Inferno: Para o Portal', 19865),
(90946, 'ptBR', 'Muitos Taurens assinam a revista "Tetas & Tretas". Os mais sonsos juram que é só pra ler sobre as últimas tretas.', '', 19865),
(90947, 'ptBR', 'Numa festa, nunca faça perguntas sobre magia a um Mago. Existe vida fora do trabalho, sabia?', '', 19865),
(90948, 'ptBR', 'Inscreva-me na fila do Coliseu!', 'Inscreva-me na fila do Coliseu!', 19865),
(90949, 'ptBR', 'Selva de Tanaan: O gosto do ferro', 'Selva de Tanaan: O gosto do ferro', 19865),
(90950, 'ptBR', 'Pra onde vão todos os berloques perdidos? Mistério...', '', 19865),
(90951, 'ptBR', 'O maior vexame pra um Paladino é esquecer de pagar a conta de luz.', '', 19865),
(90952, 'ptBR', 'Nagrand: Justiça para Thrall', 'Nagrand: Justiça para Thrall', 19865),
(90953, 'ptBR', 'Matem os intrusos! A drenagem não pode ser interrompida! (Vamos criar um deus do caos!)', '', 19865),
(90954, 'ptBR', 'Abram os portais para o reino dos vivos! Em breve devoraremos as almas deles!', '', 19865),
(90955, 'ptBR', 'Mal posso esperar para ser forte o suficiente para usar ESTE crânio!', '', 19865),
(90956, 'ptBR', 'A Luz está morrendo dentro de Oshu''gun... dentro em pouco, o caminho estará livre para invadirmos o reino dos vivos!', '', 19865),
(90957, 'ptBR', 'Ah, oi! Kaz me disse que você poderia voltar. Ela passa aqui de vez em quando para ver como eu estou e queimar uns corpos.', '', 19865),
(90958, 'ptBR', 'As legiões do caos são incontáveis! Nada nos deterá!', '', 19865),
(90959, 'ptBR', 'Você sabia que genessauros têm crânios? Eu não sabia. Levou muito tempo para tirar todas as vinhas dele.', '', 19865),
(90960, 'ptBR', 'O caos cresce dentro de Oshu''gun... e com ele se abre o caminho para o reino dos mortais! Haverá um banquete de almas para nós!', '', 19865),
(90961, 'ptBR', 'Saudações, $r.$B$BPosso ver por seu temperamento que você não é $Gum:uma; aventureir$Go:a; comum.$B$BDraenor é um mundo inóspito, e muitos inimigos perigosos espreitam tanto nos palácios como nas criptas. Eles buscam causar uma terrível destruição nesta terra usando armas e magias devastadoras. Proteger esses lugares e seus tesouros pode render excelentes recompensas para você e seus companheiros.$B$BNo entanto, não baixe a guarda nesses lugares, pois outros aventureiros estão em seu encalço e só uma corrida contra o tempo provará que suas habilidades não têm par!$B$BVocê está pront$Go:a; para o novo desafio que Draenor tem a oferecer?', 'Saudações, $r.$B$BPosso ver por seu temperamento que você não é $Gum:uma; aventureir$Go:a; comum.$B$BDraenor é um mundo inóspito, e muitos inimigos perigosos espreitam tanto nos palácios como nas criptas. Eles buscam causar uma terrível destruição nesta terra usando armas e magias devastadoras. Proteger esses lugares e seus tesouros pode render excelentes recompensas para você e seus companheiros.$B$BNo entanto, não baixe a guarda nesses lugares, pois outros aventureiros estão em seu encalço e só uma corrida contra o tempo provará que suas habilidades não têm par!$B$BVocê está pront$Go:a; para o novo desafio que Draenor tem a oferecer?', 19865),
(90962, 'ptBR', 'Conceda-me as bênçãos da bigorna e da forja.', 'Conceda-me as bênçãos da bigorna e da forja.', 19865),
(90963, 'ptBR', 'Daremos seus ossos para os lobos roerem.', '', 19865),
(90964, 'ptBR', 'Você não tem como derrotar o espírito do Brado Guerreiro!', '', 19865),
(90965, 'ptBR', 'Curvem-se ante o poder irresistível dos elementos!', '', 19865),
(90966, 'ptBR', 'Que momento oportuno. Meu último brinquedo teve que partir.', '', 19865),
(90967, 'ptBR', 'Eu retorno à terra, mas me erguerei novamente em chamas!', '', 19865),
(90968, 'ptBR', 'Vir ao nosso acampamento já foi uma imprudência, mas me enfrentar é puro suicídio.', '', 19865),
(90969, 'ptBR', 'É uma emboscada!', '', 19865),
(90970, 'ptBR', 'Eu quero ouvir você gritar enquanto eu arranco a carne dos seus ossos!', '', 19865),
(90971, 'ptBR', 'Grite para eu ouvir!', 'Grite para eu ouvir!', 19865),
(90972, 'ptBR', 'Quero ver você sangrar.', 'Quero ver você sangrar.', 19865),
(90973, 'ptBR', 'Sangue e dor!', 'Sangue e dor!', 19865),
(90974, 'ptBR', 'Vou despedaçar você lentamente.', 'Vou despedaçar você lentamente.', 19865),
(90975, 'ptBR', 'Que bela pele, acho que vou guardar depois que você morrer.', '', 19865),
(90976, 'ptBR', 'Vitória ou morte!', 'Vitória ou morte!', 19865),
(90977, 'ptBR', 'Pela glória do Brado Guerreiro!', 'Pela glória do Brado Guerreiro!', 19865),
(90978, 'ptBR', 'O poder do Brado Guerreiro destruirá você!', 'O poder do Brado Guerreiro destruirá você!', 19865),
(90979, 'ptBR', 'Como você chegou aqui!?', '', 19865),
(90980, 'ptBR', 'O que você está fazendo aqui?!', '', 19865),
(90981, 'ptBR', 'Esta terra é nossa!', 'Esta terra é nossa!', 19865),
(90982, 'ptBR', 'Como ousa se opor ao Brado Guerreiro!?', 'Como ousa se opor ao Brado Guerreiro!?', 19865),
(90983, 'ptBR', 'Sangue e glória!', 'Sangue e glória!', 19865),
(90984, 'ptBR', 'Morte aos nossos inimigos!', 'Morte aos nossos inimigos!', 19865),
(90985, 'ptBR', 'Você não deveria estar aqui!', 'Você não deveria estar aqui!', 19865),
(90986, 'ptBR', 'Deixe-nos com nossa aflição!', 'Deixe-nos com nossa aflição!', 19865),
(90987, 'ptBR', '', 'Por Draenor!', 19865),
(90988, 'ptBR', '', 'Tente flanqueá-los...', 19865),
(90989, 'ptBR', '', 'Não se deixem abalar!', 19865),
(90990, 'ptBR', '', 'A Exarca Naielle manda seus cumprimentos.', 19865),
(90991, 'ptBR', '', 'Despachado.', 19865),
(90992, 'ptBR', 'A dor... faça ela parar!', 'A dor... faça ela parar!', 19865),
(90993, 'ptBR', '', 'Fique longe de Lua Negra!', 19865),
(90994, 'ptBR', '', 'Os rangarias estão à sua disposição.', 19865),
(90995, 'ptBR', '', 'Que tal posicionar alguns francoatiradores nas árvores, em volta da fortaleza?', 19865),
(90996, 'ptBR', 'Vou arrancar a pele dos seus ossos!', 'Vou arrancar a pele dos seus ossos!', 19865),
(90997, 'ptBR', '', 'Eu farei a ronda durante o turno da noite.', 19865),
(90998, 'ptBR', '', 'A mata nos esconde do inimigo, mas pode mascarar um ataque. Temos que permanecer vigilantes.', 19865),
(90999, 'ptBR', 'Você vai pagar por ter vindo aqui!', 'Você vai pagar por ter vindo aqui!', 19865),
(91000, 'ptBR', '', 'Estou... sangrando...', 19865),
(91001, 'ptBR', 'Morra!', 'Morra!', 19865),
(91002, 'ptBR', 'Faça a vozes cessarem!', 'Faça a vozes cessarem!', 19865),
(91003, 'ptBR', 'Estou posicionando!', '', 19865),
(91004, 'ptBR', 'Protejam a prefeitura!', '', 19865),
(91005, 'ptBR', 'Conduza os trabalhadores a um lugar seguro.', '', 19865),
(91006, 'ptBR', 'Daqui não passarão!', '', 19865),
(91007, 'ptBR', 'Posicione as defesas. Inicie o contra-ataque.', '', 19865),
(91008, 'ptBR', 'Alvo eliminado.', '', 19865),
(91009, 'ptBR', 'Você já era!', '', 19865),
(91010, 'ptBR', 'Desapareça!', '', 19865),
(91011, 'ptBR', 'Meu equipamento é superior.', '', 19865),
(91012, 'ptBR', '', 'Você luta com muita experiência, Thrall. Por que não tem uma parceira?', 19865),
(91013, 'ptBR', 'Comandante, eu enviei os diagramas para a fortificação das muralhas.', '', 19865),
(91014, 'ptBR', 'Pela glória da Horda de Ferro!', 'Pela glória da Horda de Ferro!', 19865),
(91015, 'ptBR', 'Precisa consertar alguma coisa?', '', 19865),
(91016, 'ptBR', 'Nosso poder vai esmagar vocês!', 'Nosso poder vai esmagar vocês!', 19865),
(91017, 'ptBR', '', 'Você... quis que ela ficasse? Estamos em guerra! Mais do que nunca, é nessas horas que a família tem que ficar junta!', 19865),
(91019, 'ptBR', 'Seus seguidores precisam de equipamentos melhores. Farei o possível para obter peças novas.', '', 19865),
(91020, 'ptBR', 'Você ousa desafiar nosso poder?!', 'Você ousa desafiar nosso poder?!', 19865),
(91021, 'ptBR', '', 'Você é um orc verde estranho.', 19865),
(91022, 'ptBR', 'Sua morte será a minha glória!', 'Sua morte será a minha glória!', 19865),
(91024, 'ptBR', 'Eu andei trocando diagramas com os engenheiros de Azeroth. A tecnologia gnômica é... única.', '', 19865),
(91025, 'ptBR', 'Tanto a construir. Tão pouco tempo!', '', 19865),
(91026, 'ptBR', 'Eles me pegaram...', '', 19865),
(91027, 'ptBR', 'A Horda de Ferro destroçará você!', 'A Horda de Ferro destroçará você!', 19865),
(91028, 'ptBR', 'Corra para a morte!', 'Corra para a morte!', 19865),
(91030, 'ptBR', '', 'Que a Luz nos proteja.', 19865),
(91031, 'ptBR', '', 'Os fiéis jamais tombarão!', 19865),
(91032, 'ptBR', '', 'Que a Luz guie meus punhos...', 19865),
(91033, 'ptBR', '', 'Nós jamais vacilaremos!', 19865),
(91034, 'ptBR', '', 'Fique atrás de mim.', 19865),
(91035, 'ptBR', 'Vou esmigalhar os seus ossos!', 'Vou esmigalhar os seus ossos!', 19865),
(91036, 'ptBR', '', 'A justiça foi feita.', 19865),
(91038, 'ptBR', 'Eu tenho. Eu deixei que minha parceira ficasse em casa para cuidar dos nossos pequenos.', '', 19865),
(91039, 'ptBR', '', 'Temos que continuar lutando.', 19865),
(91040, 'ptBR', '', 'Ainda não acabou.', 19865),
(91041, 'ptBR', 'Eu lhe trago o seu fim!', 'Eu lhe trago o seu fim!', 19865),
(91042, 'ptBR', '', 'A Luz jamais nos abandonará.', 19865),
(91043, 'ptBR', 'Eu... nunca vi a questão dessa forma.', '', 19865),
(91045, 'ptBR', '', 'É bom ver você, comandante.', 19865),
(91046, 'ptBR', '', 'Estou atendendo os feridos desde o último ataque.', 19865),
(91048, 'ptBR', '', 'Temos que proteger o coração de Draenor.', 19865),
(91049, 'ptBR', '', 'Você ergueu um bastião de tranquilidade em meio ao caos da guerra. Obrigada, comandante.', 19865),
(91052, 'ptBR', '', 'Entrego meu corpo à Luz!', 19865),
(91053, 'ptBR', 'Horrores Primordiais mortos: $1i (+$2i VP)', '', 19865),
(91054, 'ptBR', 'Perdemos o coração, mas ganhamos esta batalha. A guarnição está segura... por enquanto.', '', 19865),
(91055, 'ptBR', 'Machadeiros do Caos da Lua Negra mortos: $1i (+$2i VP)', '', 19865),
(91056, 'ptBR', 'Ritualistas da Lua Negra mortos: $1i (+$2i VP)', '', 19865),
(91057, 'ptBR', 'Meu assistente morreu? Ah, cara... que chato. Isso já está fora da minha alçada. É melhor você falar com Zog.', '', 19865),
(91058, 'ptBR', 'Profetas da Lua Negra mortos: $1i (+$2i VP)', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(91059, 'ptBR', 'Amarra-caos da Lua Negra mortos: $1i (+$2i VP)', '', 19865),
(91060, 'ptBR', 'Essências do Caos mortas: $1i (+$2i VP)', '', 19865),
(91061, 'ptBR', 'Taumaturgos da Lua Negra mortos: $1i (+$2i VP)', '', 19865),
(91062, 'ptBR', 'Onde posso substituir um anel perdido ou adquirir outro?', 'Onde posso substituir um anel perdido ou adquirir outro?', 19865),
(91063, 'ptBR', '', 'A despeito do caos, o entardecer aqui é bastante reconfortante.', 19865),
(91064, 'ptBR', 'Impossível! Seu anel é uma obra-prima, feita a mão, com sofisticada habilidade arcana. É inestimável e insubstituível!$B$BPor outro lado, Zuza Chiamuito, que fica aqui em frente à minha torre, é especialista em conseguir o impossível. Talvez se você molhar a mão dele com ouro...$B$BMas eu não posso garantir nada.', '', 19865),
(91065, 'ptBR', 'Oi, $gbonitão:moça;. Posso lhe ajudar a reencontrar companheiros perdidos.', 'Oi, $gbonitão:moça;. Posso lhe ajudar a reencontrar companheiros perdidos.', 19865),
(91066, 'ptBR', 'O caos me chama...', 'O caos me chama...', 19865),
(91067, 'ptBR', 'Nada pode me deter!', '', 19865),
(91068, 'ptBR', 'Volte à terra, cão!', '', 19865),
(91069, 'ptBR', 'Retorne à luz!', '', 19865),
(91070, 'ptBR', 'Você teve seu julgamento.', '', 19865),
(91071, 'ptBR', 'Por Luaprata!', '', 19865),
(91072, 'ptBR', '', 'Ouvi dizer que você foi graças a você que um dos meus filhos voltou para mim, $p. Você tem minha eterna gratidão.$B$BEmbora eu tenha me emocionado ao rever Ga''nar, ele estava destroçado por tanto pesar e sofrimento.$B$BEu já vi algo parecido no irmão mais velho dele, Fenris, antes de o perdermos para sempre.', 19865),
(91073, 'ptBR', 'Parece que estou olhando para a eternidade...', '', 19865),
(91074, 'ptBR', '<O simples fato de estar na presença do naaru enche você de uma sensação de paz. Você também sente outra coisa: um olhar, vigiando e protegendo. Talvez o profeta Velen viva para sempre na luz do naaru purificado.>', '', 19865),
(91075, 'ptBR', 'Eu cresci ouvindo histórias da Serra Fogofrio, o lar ancestral dos Lobo do Gelo.$B$BNunca pensei que fosse ver como o clã era no auge, com Durotan no comando.$B$BEle é... mais baixo... do que eu pensava. O fardo da liderança pesa muito sobre os ombros dele.', '', 19865),
(91076, 'ptBR', 'Dê meia-volta, $c. Você só encontrará sofrimento aqui.', 'Dê meia-volta, $c. Você só encontrará sofrimento aqui.', 19865),
(91077, 'ptBR', 'As trevas chamam... não consigo resistir.', 'As trevas chamam... não consigo resistir.', 19865),
(91078, 'ptBR', 'Oshu''gun aguarda...', 'Oshu''gun aguarda...', 19865),
(91079, 'ptBR', 'O chamado do caos... posso ouvi-lo...', 'O chamado do caos... posso ouvi-lo...', 19865),
(91080, 'ptBR', 'O caos... chama...', 'O caos... chama...', 19865),
(91082, 'ptBR', 'Implacável!', '', 19865),
(91083, 'ptBR', 'Estilhaçando!', '', 19865),
(91084, 'ptBR', 'Se você tiver a grana, eu tenho o transporte!', '', 19865),
(91085, 'ptBR', 'Eu posso levar você para qualquer lugar... pelo preço certo, é claro!', '', 19865),
(91086, 'ptBR', 'Golpe do Punho Galático!', '', 19865),
(91087, 'ptBR', 'Você não tem disciplina!', '', 19865),
(91088, 'ptBR', 'Aha ha ha ha!', '', 19865),
(91089, 'ptBR', '|cFFFF0000|Hspell:177150|h[Grito Estrondoso]|h|r matou você. Saia do campo de visão. Ou afaste-se. Quanto mais longe você estiver de Kor''lok, menor será o dano recebido de Grito Estrondoso!', '', 19865),
(91090, 'ptBR', '', 'Por Gnomeregan!', 19865),
(91091, 'ptBR', 'Só não toque nas minhas tranças, por favor...', 'Só não toque nas minhas tranças, por favor...', 19865),
(91092, 'ptBR', '', 'Tema o poder dos gnomos!', 19865),
(91093, 'ptBR', '', 'Poder gnômico!', 19865),
(91094, 'ptBR', '', 'Pequena e sorrateira!', 19865),
(91095, 'ptBR', '', 'Aqueles goblins do Bondebico são desprezíveis. Fazem qualquer coisa por uns trocados!', 19865),
(91096, 'ptBR', 'O que fizeram desta vez?', '', 19865),
(91097, 'ptBR', 'Carne fresca!', '', 19865),
(91098, 'ptBR', 'Ninguém sai vivo.', '', 19865),
(91099, 'ptBR', 'A dor é a lição.', '', 19865),
(91100, 'ptBR', 'Essa é minha!', '', 19865),
(91101, 'ptBR', 'Corra! É mais divertido assim...', '', 19865),
(91102, 'ptBR', '', 'Estão vendendo lembrancinhas!', 19865),
(91103, 'ptBR', 'Sua vida me pertence!', '', 19865),
(91104, 'ptBR', 'Vou fazer você em pedaços!', '', 19865),
(91105, 'ptBR', '|TInterface\\Icons\\warrior_disruptingshout.blp:20|t %s começa a lançar |cFFFF0000|Hspell:177155|h[Brado Interruptivo]|h|r!', '', 19865),
(91106, 'ptBR', 'Mostre seu sangue!', '', 19865),
(91107, 'ptBR', 'Mal nos recuperamos do ataque ao portal negro e eles abriram uma barraquinha de souvenir? Você só pode estar brincando.', '', 19865),
(91108, 'ptBR', 'Eu morro livre!', '', 19865),
(91109, 'ptBR', 'Eu não temo a morte!', '', 19865),
(91110, 'ptBR', 'Não me arrependo de nada!', '', 19865),
(91111, 'ptBR', 'A liberdade... era uma mentira.', '', 19865),
(91112, 'ptBR', '', 'Antes fosse brincadeira. Eles estão fabricando joias com fragmentos de artefato e vendendo. Quanta audácia tratar uma relíquia desta forma!', 19865),
(91113, 'ptBR', 'Rendição... jamais...', '', 19865),
(91114, 'ptBR', '', 'Belloc descobriu alguma coisa sobre o paradeiro do artefato misterioso?', 19865),
(91115, 'ptBR', '|TInterface\\Icons\\ability_warrior_savageblow.blp:20|t %s começa a lançar |cFFFF0000|Hspell:177147|h[Cutilada Mortal]|h|r!', '', 19865),
(91116, 'ptBR', 'Ferro e sangue!', '', 19865),
(91117, 'ptBR', 'Você não pode resistir ao ferro!', '', 19865),
(91118, 'ptBR', 'Coração de ferro, vontade de ferro!', '', 19865),
(91119, 'ptBR', 'Fogofrio é nossa!', '', 19865),
(91120, 'ptBR', 'Ele tem umas pistas, mas nada de muito concreto ainda.', '', 19865),
(91121, 'ptBR', '', 'Temos que correr para encontrá-lo, antes que o Dr. Jones bote as mãos nele.', 19865),
(91122, 'ptBR', 'Concordo, não gosto nem de imaginar o que a Aliança faria em posse de uma arma tão poderosa. Temos que solicitar reforços, ou nossa causa estará perdida.', '', 19865),
(91123, 'ptBR', 'Morte às raças inferiores!', '', 19865),
(91124, 'ptBR', 'Os céus são nossos!', '', 19865),
(91125, 'ptBR', 'Morra, verme!', '', 19865),
(91126, 'ptBR', 'Pela glória de Rukhmar!', '', 19865),
(91127, 'ptBR', 'Por Beira-céu!', '', 19865),
(91128, 'ptBR', 'Então qual você acha que é a natureza desse famoso artefato?', '', 19865),
(91129, 'ptBR', 'Ajoelhe-se perante o que é superior!', '', 19865),
(91130, 'ptBR', 'Você não escapará de mim!', '', 19865),
(91131, 'ptBR', '', 'Se for tão poderoso quanto especula o dr. Jones, pode muito bem ser de origem titânica.', 19865),
(91132, 'ptBR', 'Ra-kawww!', '', 19865),
(91133, 'ptBR', 'Isso parece meio improvável. Não vi qualquer evidência de ligação dos titãs com este mundo.', '', 19865),
(91134, 'ptBR', 'Como... ?', '', 19865),
(91135, 'ptBR', 'Não nas suas... mãos...', '', 19865),
(91136, 'ptBR', '', 'Pode ser, mas não seria fantástico descobrir que os titãs chegaram até mesmo a Draenor? Pense nas implicações!', 19865),
(91137, 'ptBR', '', 'Outro troféu para minha parede.', 19865),
(91138, 'ptBR', 'O negócio foi difícil lá no Portal Negro. Como tu está se sentindo?', '', 19865),
(91139, 'ptBR', '', 'Um pouco cansada, mas não é a primeira vez em que passo raspando. E estou simplesmente empolgada com o fato de o nosso posto ter uma história tão fascinante pra ser descoberta.', 19865),
(91140, 'ptBR', 'Bah, mas tem. Quer dizer... Quando essa história não está te campeando com um machado!', '', 19865),
(91141, 'ptBR', 'Meu voo... terminou...', '', 19865),
(91142, 'ptBR', 'Eu morro por Beira-céu.', '', 19865),
(91143, 'ptBR', '', 'Meu mascote tem fome.', 19865),
(91144, 'ptBR', '', 'Alvo atingido!', 19865),
(91145, 'ptBR', 'Lorde Mes tem fome.', '', 19865),
(91146, 'ptBR', 'Absolutamente patético.', '', 19865),
(91147, 'ptBR', 'Kolrigg! Você está bem?', '', 19865),
(91148, 'ptBR', 'A morte não pode ser detida.', '', 19865),
(91149, 'ptBR', 'Lunzul! Atenção, soldado!', '', 19865),
(91150, 'ptBR', 'Você não demonstra qualquer habilidade.', '', 19865),
(91151, 'ptBR', 'Sua força de vontade derrete diante dos meus olhos.', '', 19865),
(91152, 'ptBR', 'Ladrões!', 'Ladrões!', 19865),
(91153, 'ptBR', 'Como ousa desafiar os Seguidores?', 'Como ousa desafiar os Seguidores?', 19865),
(91154, 'ptBR', 'Contemplem a fúria de Rukhmar!', 'Contemplem a fúria de Rukhmar!', 19865),
(91155, 'ptBR', 'Inferiores imundos!', 'Inferiores imundos!', 19865),
(91156, 'ptBR', 'Rukhmar... tenha piedade...', 'Rukhmar... tenha piedade...', 19865),
(91157, 'ptBR', 'Rukhmar... eu fracassei...', 'Rukhmar... eu fracassei...', 19865),
(91158, 'ptBR', 'Os Seguidores nunca se esquecem...', 'Os Seguidores nunca se esquecem...', 19865),
(91159, 'ptBR', 'Exterminem todos!', 'Exterminem todos!', 19865),
(91160, 'ptBR', 'Expurguem esses intrusos de nosso meio!', 'Expurguem esses intrusos de nosso meio!', 19865),
(91161, 'ptBR', 'Você vai morrer como os proscritos!', 'Você vai morrer como os proscritos!', 19865),
(91162, 'ptBR', 'Os inferiores não merecem piedade.', 'Os inferiores não merecem piedade.', 19865),
(91163, 'ptBR', 'Esta não é sua luta, $gforasteiro:forasteira;.', 'Esta não é sua luta, $gforasteiro:forasteira;.', 19865),
(91164, 'ptBR', 'Você é uma praga no mundo.', 'Você é uma praga no mundo.', 19865),
(91165, 'ptBR', 'Minhoca da terra patética!', 'Minhoca da terra patética!', 19865),
(91166, 'ptBR', 'Você vai queimar com os proscritos!', 'Você vai queimar com os proscritos!', 19865),
(91167, 'ptBR', 'Todos vocês queimarão...', 'Todos vocês queimarão...', 19865),
(91168, 'ptBR', 'Não confie nos proscritos...', 'Não confie nos proscritos...', 19865),
(91169, 'ptBR', 'A maldição deles vai lhe corroer...', 'A maldição deles vai lhe corroer...', 19865),
(91170, 'ptBR', 'Essa não era... a vontade de Rukhmar...', 'Essa não era... a vontade de Rukhmar...', 19865),
(91171, 'ptBR', 'Invasores!', 'Invasores!', 19865),
(91172, 'ptBR', 'Aqui terra de ogro! Você não ser ogro!', 'Aqui terra de ogro! Você não ser ogro!', 19865),
(91173, 'ptBR', 'Abaixa a cabeça pro Morkurk!', 'Abaixa a cabeça pro Morkurk!', 19865),
(91174, 'ptBR', 'Hah! Tão fracote!', 'Hah! Tão fracote!', 19865),
(91175, 'ptBR', 'Eu colocar sua cabeça na minha coleção!', 'Eu colocar sua cabeça na minha coleção!', 19865),
(91176, 'ptBR', 'Aproveite o vazio.', '', 19865),
(91177, 'ptBR', 'Sua cabeça bonita. Ser bom troféu!', 'Sua cabeça bonita. Ser bom troféu!', 19865),
(91178, 'ptBR', 'De que buraco você saiu?', 'De que buraco você saiu?', 19865),
(91179, 'ptBR', 'Você forte... pra corpo tão pequeno...', 'Você forte... pra corpo tão pequeno...', 19865),
(91180, 'ptBR', 'Como você fazer isso?', 'Como você fazer isso?', 19865),
(91181, 'ptBR', 'Morkurk quebrar você já já!', 'Morkurk quebrar você já já!', 19865),
(91182, 'ptBR', 'Ah... uma alma nova!', 'Ah... uma alma nova!', 19865),
(91183, 'ptBR', 'Mais uma alma para Teron''gor!', 'Mais uma alma para Teron''gor!', 19865),
(91184, 'ptBR', 'Contemplem o poder de Gul''dan!', 'Contemplem o poder de Gul''dan!', 19865),
(91185, 'ptBR', 'Teron''gor prevalecerá!', 'Teron''gor prevalecerá!', 19865),
(91186, 'ptBR', 'Teron''gor... minha alma lhe pertence...', 'Teron''gor... minha alma lhe pertence...', 19865),
(91187, 'ptBR', 'Isso... não muda... nada...', 'Isso... não muda... nada...', 19865),
(91188, 'ptBR', 'Você se juntará a mim logo, logo.', 'Você se juntará a mim logo, logo.', 19865),
(91189, 'ptBR', 'Você já perdeu...', 'Você já perdeu...', 19865),
(91190, 'ptBR', 'Almas deliciosas...', 'Almas deliciosas...', 19865),
(91191, 'ptBR', 'Mongretoide tem fome!', 'Mongretoide tem fome!', 19865),
(91192, 'ptBR', 'Somos a porta para o esquecimento.', 'Somos a porta para o esquecimento.', 19865),
(91193, 'ptBR', 'Outra alma para ceifar.', 'Outra alma para ceifar.', 19865),
(91194, 'ptBR', 'Esfolem todos eles!', 'Esfolem todos eles!', 19865),
(91195, 'ptBR', 'Mas que ânsia de encontrar a morte você tem...', 'Mas que ânsia de encontrar a morte você tem...', 19865),
(91196, 'ptBR', 'Sangue de mortal... que delícia...', 'Sangue de mortal... que delícia...', 19865),
(91197, 'ptBR', 'A-kreesh!', 'A-kreesh!', 19865),
(91198, 'ptBR', 'A-rul shach kigon!', 'A-rul shach kigon!', 19865),
(91199, 'ptBR', 'Katra zil shukil!', 'Katra zil shukil!', 19865),
(91200, 'ptBR', 'Reesh, hokta!', 'Reesh, hokta!', 19865),
(91201, 'ptBR', 'Shaza-kiel!', 'Shaza-kiel!', 19865),
(91202, 'ptBR', 'Eu voltarei... a viver...', 'Eu voltarei... a viver...', 19865),
(91203, 'ptBR', 'Você há de sucumbir... um dia...', 'Você há de sucumbir... um dia...', 19865),
(91204, 'ptBR', 'Mortal desprezível!', 'Mortal desprezível!', 19865),
(91205, 'ptBR', 'Anakh kyree!', 'Anakh kyree!', 19865),
(91206, 'ptBR', 'Gor''om haguul!', 'Gor''om haguul!', 19865),
(91207, 'ptBR', 'Kirel narak!', 'Kirel narak!', 19865),
(91208, 'ptBR', 'A invasão começou!', 'A invasão começou!', 19865),
(91209, 'ptBR', 'Todos serão consumidos pela Legião!', 'Todos serão consumidos pela Legião!', 19865),
(91210, 'ptBR', 'Inundem esta cidade de sangue!', 'Inundem esta cidade de sangue!', 19865),
(91211, 'ptBR', 'Auchindoun ruirá!', 'Auchindoun ruirá!', 19865),
(91212, 'ptBR', 'Esta cidade pertence à Legião!', 'Esta cidade pertence à Legião!', 19865),
(91213, 'ptBR', 'Aqui você só encontrará a morte.', 'Aqui você só encontrará a morte.', 19865),
(91214, 'ptBR', 'Eu vejo... escuridão eterna...', 'Eu vejo... escuridão eterna...', 19865),
(91215, 'ptBR', 'Você não conquistou nada.', 'Você não conquistou nada.', 19865),
(91216, 'ptBR', 'Gul''dan destroçará sua alma...', 'Gul''dan destroçará sua alma...', 19865),
(91217, 'ptBR', 'Desapareça deste lugar!', 'Desapareça deste lugar!', 19865),
(91218, 'ptBR', 'Vocês não deveriam ter vindo aqui.', 'Vocês não deveriam ter vindo aqui.', 19865),
(91219, 'ptBR', 'Não se intrometa em nossos planos!', 'Não se intrometa em nossos planos!', 19865),
(91220, 'ptBR', 'Socrethar exige sua alma!', 'Socrethar exige sua alma!', 19865),
(91221, 'ptBR', 'A Legião nos guia!', 'A Legião nos guia!', 19865),
(91222, 'ptBR', 'Os Sargerai... prevalecerão...', 'Os Sargerai... prevalecerão...', 19865),
(91223, 'ptBR', 'Fizemos o que era... necessário...', 'Fizemos o que era... necessário...', 19865),
(91224, 'ptBR', 'Não foi isso que nos prometeram...', 'Não foi isso que nos prometeram...', 19865),
(91225, 'ptBR', 'Este mundo está pronto para ser conquistado!', 'Este mundo está pronto para ser conquistado!', 19865),
(91226, 'ptBR', 'Este mundo arderá em chamas como todos os outros.', 'Este mundo arderá em chamas como todos os outros.', 19865),
(91227, 'ptBR', 'Queime no fogo esmeralda!', 'Queime no fogo esmeralda!', 19865),
(91228, 'ptBR', 'Que este mundo se acabe em sangue!', 'Que este mundo se acabe em sangue!', 19865),
(91229, 'ptBR', 'Curve-se ou encare a destruição!', 'Curve-se ou encare a destruição!', 19865),
(91230, 'ptBR', 'A Legião é eterna.', 'A Legião é eterna.', 19865),
(91231, 'ptBR', 'Você cairá por terra... um dia...', 'Você cairá por terra... um dia...', 19865),
(91232, 'ptBR', 'Você só está adiando o inevitável.', 'Você só está adiando o inevitável.', 19865),
(91233, 'ptBR', 'Intrusos!', 'Intrusos!', 19865),
(91234, 'ptBR', 'Entrem em formação!', 'Entrem em formação!', 19865),
(91235, 'ptBR', 'Rechacem os atacantes!', 'Rechacem os atacantes!', 19865),
(91236, 'ptBR', 'Meu ódio... queima...', 'Meu ódio... queima...', 19865),
(91237, 'ptBR', 'Você vai sofrer o mesmo destino que nós!', 'Você vai sofrer o mesmo destino que nós!', 19865),
(91238, 'ptBR', 'Traidores!', 'Traidores!', 19865),
(91239, 'ptBR', 'Renda-se ou morra!', 'Renda-se ou morra!', 19865),
(91240, 'ptBR', 'Protejam a guarnição!', 'Protejam a guarnição!', 19865),
(91241, 'ptBR', 'Tão... frio...', 'Tão... frio...', 19865),
(91242, 'ptBR', 'Estranho. Não sinto dor...', 'Estranho. Não sinto dor...', 19865),
(91243, 'ptBR', 'Meu espírito... está livre...', 'Meu espírito... está livre...', 19865),
(91244, 'ptBR', 'Estou... em paz...', 'Estou... em paz...', 19865),
(91245, 'ptBR', 'Este é o nosso abatedouro!', 'Este é o nosso abatedouro!', 19865),
(91246, 'ptBR', 'Tomara que você lute melhor que esses pássaros!', 'Tomara que você lute melhor que esses pássaros!', 19865),
(91247, 'ptBR', 'Seu couro vai dar um belo cinto.', 'Seu couro vai dar um belo cinto.', 19865),
(91248, 'ptBR', 'Finalmente, um desafio!', 'Finalmente, um desafio!', 19865),
(91249, 'ptBR', 'Vamos, implore por misericórdia!', 'Vamos, implore por misericórdia!', 19865),
(91250, 'ptBR', 'Vou te dar uma cicatriz para se orgulhar!', 'Vou te dar uma cicatriz para se orgulhar!', 19865),
(91251, 'ptBR', 'Vira-lata $gsortudo:sortuda;!', 'Vira-lata $gsortudo:sortuda;!', 19865),
(91252, 'ptBR', 'Deixe-me sofrer!', 'Deixe-me sofrer!', 19865),
(91253, 'ptBR', 'Karrath vai ficar zangado...', 'Karrath vai ficar zangado...', 19865),
(91254, 'ptBR', 'Dor... tão... gloriosa...', 'Dor... tão... gloriosa...', 19865),
(91255, 'ptBR', 'Hora do recreio!', 'Hora do recreio!', 19865),
(91256, 'ptBR', 'Tenho um gancho vazio só te esperando.', 'Tenho um gancho vazio só te esperando.', 19865),
(91257, 'ptBR', 'Você deve estar se sentindo com sorte.', 'Você deve estar se sentindo com sorte.', 19865),
(91258, 'ptBR', 'Veio se unir às feras?', 'Veio se unir às feras?', 19865),
(91259, 'ptBR', 'Excelente. Algo para esfolar!', 'Excelente. Algo para esfolar!', 19865),
(91260, 'ptBR', 'quero ouvir você gritar!', 'quero ouvir você gritar!', 19865),
(91261, 'ptBR', 'Isso... isso é dor de verdade...', 'Isso... isso é dor de verdade...', 19865),
(91262, 'ptBR', 'Você não sairá daqui com vida.', 'Você não sairá daqui com vida.', 19865),
(91263, 'ptBR', 'Nunca me senti... tão...vivo...', 'Nunca me senti... tão...vivo...', 19865),
(91264, 'ptBR', 'Pendure-me no gancho...', 'Pendure-me no gancho...', 19865),
(91265, 'ptBR', '$gEsse aqui é meu: Essa aqui é minha;!', '$gEsse aqui é meu: Essa aqui é minha;!', 19865),
(91266, 'ptBR', 'Igualzinho à arena!', 'Igualzinho à arena!', 19865),
(91267, 'ptBR', 'Vou fazer você sangrar bem!', 'Vou fazer você sangrar bem!', 19865),
(91268, 'ptBR', 'Você deve ser masoquista.', 'Você deve ser masoquista.', 19865),
(91269, 'ptBR', 'Morra, fracote!', 'Morra, fracote!', 19865),
(91270, 'ptBR', '', 'Sinta a fúria!', 19865),
(91271, 'ptBR', '', 'Pequena em estatura, grande em talento!', 19865),
(91272, 'ptBR', '', 'Vocês me entediam.', 19865),
(91273, 'ptBR', 'Meu poder é ilimitado!', '', 19865),
(91274, 'ptBR', 'Bwahahahaha!', '', 19865),
(91275, 'ptBR', 'T-t-t-t-tornado de aço!', '', 19865),
(91276, 'ptBR', 'Aqui não!', '', 19865),
(91277, 'ptBR', '', 'Nem se dê ao trabalho de tentar duelar com o Zurgo. Ele é um péssimo perdedor.$B$BNão diga a ele que eu falei isso.', 19865),
(91278, 'ptBR', 'Ordens são ordens.', '', 19865),
(91279, 'ptBR', 'Se ao menos Max estivesse aqui...', '', 19865),
(91280, 'ptBR', 'Eu disse à Maris Trilha Brava que iria explorar qualquer parte de Ashran que não fosse aquela área do altar. De ogros eu posso cuidar, mas dos fantasmas deles? Desculpa, mas isso me dá arrepios.', '', 19865),
(91281, 'ptBR', 'Não sei como você consegue aguentar falar com aquele animal do Zurgo. Ele é tão rude! Mesmo para um orc!', '', 19865),
(91282, 'ptBR', 'Você é peso morto.', '', 19865),
(91283, 'ptBR', 'Quanto a você, bem... você é fácil.', '', 19865),
(91284, 'ptBR', 'Eu estava carregando um saco cheio de fragmentos de artefatos aqui para Lança de Guerra quando a escória da Aliança tomou tudo de mim. Cuidado lá fora, $n.', '', 19865),
(91285, 'ptBR', 'Se me atrasar, eu derrubo você.', '', 19865),
(91286, 'ptBR', 'Eu raio!', '', 19865),
(91287, 'ptBR', 'Você não raio! Você trovão! Força da natureza e energia.', '', 19865),
(91288, 'ptBR', 'Oh! Sim. Eu trovão, naturalmente.', '', 19865),
(91289, 'ptBR', 'Sim, é natural pra você.', '', 19865),
(91290, 'ptBR', 'Mas você raio, nós juntos... sai faísca!', '', 19865),
(91291, 'ptBR', 'MATAAAAAAR!', '', 19865),
(91292, 'ptBR', 'MORRRAAAAA!', '', 19865),
(91293, 'ptBR', 'MOOORTEEEEE!', '', 19865),
(91294, 'ptBR', 'O teste falhou!', '', 19865),
(91295, 'ptBR', 'Suas habilidades não são estão no mesmo nível.', '', 19865),
(91296, 'ptBR', 'Considero seu esforço incompleto.', '', 19865),
(91297, 'ptBR', 'Você não é nada para mim.', '', 19865),
(91298, 'ptBR', 'Você fracassou.', '', 19865),
(91299, 'ptBR', 'Sufoque nas sombras.', '', 19865),
(91300, 'ptBR', 'Saudações, comandante. Alguns recrutas voluntários ainda podem querer se juntar à nossa guarnição. Eu vou reunir os contratos para você analisar quando tiver tempo.', 'Saudações, comandante. Alguns recrutas voluntários ainda podem querer se juntar à nossa guarnição. Eu vou reunir os contratos para você analisar quando tiver tempo.', 19865),
(91301, 'ptBR', 'Não tenho tempo para conversar. O grão-marechal Tremulâmina precisa desesperadamente de tanques para ajudar na batalha contra a Horda.$B$BOnde foi que eu coloquei aquela Chave de Arco Voltaico?...', '', 19865),
(91302, 'ptBR', '', 'Se você vir alguém da Horda por aqui, use um dos sinalizadores da Bixxie Roquestruxa. Com certeza os membros da Aliança na área virão para ajudar.', 19865),
(91303, 'ptBR', 'Temos uma série de animais precisando de adestramento. Eles não são tão resistentes quanto as suas cavalgaduras e ficarão cansados após algumas batalhas.', '', 19865),
(91304, 'ptBR', 'Sobrou algum animal para treinar?', 'Sobrou algum animal para treinar?', 19865),
(91305, 'ptBR', 'Eu gostaria do talbuque em treinamento.', 'Eu gostaria do talbuque em treinamento.', 19865),
(91306, 'ptBR', 'Eu gostaria do fenoceronte em treinamento.', 'Eu gostaria do fenoceronte em treinamento.', 19865),
(91307, 'ptBR', 'Eu gostaria do javali em treinamento.', 'Eu gostaria do javali em treinamento.', 19865),
(91308, 'ptBR', 'Eu gostaria do elekk em treinamento.', 'Eu gostaria do elekk em treinamento.', 19865),
(91309, 'ptBR', 'Eu gostaria do lobo em treinamento.', 'Eu gostaria do lobo em treinamento.', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(91310, 'ptBR', 'Eu gostaria da fera-do-rio em treinamento.', 'Eu gostaria da fera-do-rio em treinamento.', 19865),
(91311, 'ptBR', '', 'Harrison Jones está convencido de que o Artefato pode estar nas minas. Se isso for verdade, o próximo estágio da batalha será travado no subterrâneo.$B$BQue perigos novos nos esperam por lá? É isso que eu preciso descobrir.', 19865),
(91312, 'ptBR', '', 'Enquanto a batalha contra a Horda se concentra de fato no que estamos chamando de Estrada da Glória, também precisamos concentrar nossos esforços na tentativa de encontrar o Artefato. Quem sabe onde ele pode estar?$B$BRevire tudo, não deixe pedra sobre pedra. Precisamos encontrar o Artefato antes da Horda.', 19865),
(91313, 'ptBR', 'Como podemos vencer essa batalha contra a Horda sem máquinas de cerco?', '', 19865),
(91314, 'ptBR', 'Se tivéssemos uma aeronave... Poderíamos acabar com Lança de Guerra a partir do céu!', '', 19865),
(91315, 'ptBR', 'Precisamos concentrar todos os nossos esforços nas minas. Concordo com o Dr Jones: o Artefato tem que estar lá. Tem que estar!', '', 19865),
(91316, 'ptBR', 'É como nós temíamos: precisamos entrar nas minas. Quem sabe que perigos antigos há lá?...', '', 19865),
(91317, 'ptBR', 'Trégua? Com a Aliança?! Nunca!', '', 19865),
(91318, 'ptBR', 'Espiões ladinos nos informaram que a Aliança está construindo maquinário usado para perfurar rocha. Você acha que é para as minas?', '', 19865),
(91319, 'ptBR', 'Você já viu quantos Cavaleiros da Morte tem nas nossas fileiras? Por que ainda não conseguimos entrar em Escudo Tonante? Eles não estão usando Peste Necrótica?', '', 19865),
(91320, 'ptBR', 'Se ao menos conseguíssemos trazer um Zepelim pelo portal... Poderíamos acabar com Escudo Tonante a partir dos céus!', '', 19865),
(91321, 'ptBR', 'Seu sofrimento será lendário.', '', 19865),
(91322, 'ptBR', 'Levantem-se, lacaios! Rasguem a carne deles.', '', 19865),
(91323, 'ptBR', 'VERMES! REDUZIREI SEU MUNDO A CINZAS!', '', 19865),
(91324, 'ptBR', 'A trilha de guerra de Orgrim acaba aqui. Vou cuidar para que meu velho amigo tenha o destino que merece.', '', 19865),
(91325, 'ptBR', 'Shattrath não sucumbirá novamente. Vamos dar cabo desses cães da Horda de Ferro.', '', 19865),
(91326, 'ptBR', '', 'Tudo o que Maraad fez... foi para proteger nosso povo.', 19865),
(91327, 'ptBR', '', 'Ele pagou o preço supremo pela nossa liberdade. Nunca esqueceremos seu sacrifício.', 19865),
(91328, 'ptBR', '', 'Agradeço tudo o que fez, $n. Sem você... nenhum de nós teria sobrevivido.', 19865),
(91329, 'ptBR', 'Orgrim fez o que achava correto. Ele não sabia o caminho que trilhava.', '', 19865),
(91330, 'ptBR', 'Nunca me esquecerei de você... velho amigo.', '', 19865),
(91331, 'ptBR', 'Não esquecerei sua ajuda, $n. Sem isso, Mão Negra teria acabado com todos nós.', '', 19865),
(91332, 'ptBR', 'Agradeço muito! Nunca teríamos derrotado o golem sozinhos.', 'Agradeço muito! Nunca teríamos derrotado o golem sozinhos.', 19865),
(91333, 'ptBR', 'O que posso fazer por ti?', '', 19865),
(91334, 'ptBR', 'Você não ser $gbom:boa; pro ringue!', 'Você não ser $gbom:boa; pro ringue!', 19865),
(91335, 'ptBR', 'Eu esmagar você!', 'Eu esmagar você!', 19865),
(91336, 'ptBR', 'Ah! Você não ser $ggladiador:gladiadora;!', 'Ah! Você não ser $ggladiador:gladiadora;!', 19865),
(91337, 'ptBR', 'Você veio pro lugar errado, tampinha!', 'Você veio pro lugar errado, tampinha!', 19865),
(91338, 'ptBR', 'Mim esmaga você!', 'Mim esmaga você!', 19865),
(91339, 'ptBR', 'Você morrer na arena...', 'Você morrer na arena...', 19865),
(91340, 'ptBR', 'Eu forte... você mais forte...', 'Eu forte... você mais forte...', 19865),
(91341, 'ptBR', 'Mim... esmaga... você...', 'Mim... esmaga... você...', 19865),
(91342, 'ptBR', 'Por Auchindoun!', 'Por Auchindoun!', 19865),
(91343, 'ptBR', 'Que a luz nos dê forças!', 'Que a luz nos dê forças!', 19865),
(91344, 'ptBR', 'Que os espíritos olhem por nós!', 'Que os espíritos olhem por nós!', 19865),
(91345, 'ptBR', 'Enfrentaremos a escuridão.', 'Enfrentaremos a escuridão.', 19865),
(91346, 'ptBR', 'Em frente, marchem! Por Auchindoun!', 'Em frente, marchem! Por Auchindoun!', 19865),
(91347, 'ptBR', 'A Luz... se esvai...', 'A Luz... se esvai...', 19865),
(91348, 'ptBR', 'Auchindoun me recebe...', 'Auchindoun me recebe...', 19865),
(91349, 'ptBR', 'As trevas chegam para todos nós...', 'As trevas chegam para todos nós...', 19865),
(91350, 'ptBR', 'Quer ver um truque de mágica?', '', 19865),
(91352, 'ptBR', 'Isso deve ser divertido.', '', 19865),
(91353, 'ptBR', 'Espero que sua armadura seja resistente ao fogo.', '', 19865),
(91354, 'ptBR', 'Você vai sentir uma leve ardência.', '', 19865),
(91355, 'ptBR', 'Eu tentei lhe avisar.', '', 19865),
(91356, 'ptBR', 'Tá ficando quente aqui? Ou é comigo?', '', 19865),
(91357, 'ptBR', 'Ora ora, não vá se exaurir.', '', 19865),
(91358, 'ptBR', 'Era inevitável, realmente.', '', 19865),
(91359, 'ptBR', 'É um prazer ver você, comandante.', '', 19865),
(91360, 'ptBR', 'Precisa que eu lance algum feitiço, comandante? Ou que eu abra algum portal? Quer que eu execute um esquema diabólico qualquer?', '', 19865),
(91361, 'ptBR', 'Uma bela hora para um passeio pela guarnição, comandante.', '', 19865),
(91362, 'ptBR', 'Sinto-me honrado como sempre, comandante.', '', 19865),
(91363, 'ptBR', 'Vou... ficar frio...', '', 19865),
(91364, 'ptBR', 'Fui apagado...', '', 19865),
(91365, 'ptBR', '', 'Não vou te dar mole!', 19865),
(91366, 'ptBR', '', 'Quer pegar pesado, é?', 19865),
(91367, 'ptBR', '', 'É fria!', 19865),
(91368, 'ptBR', '', 'Detectei um. Ali!', 19865),
(91369, 'ptBR', '', 'Você recebeu o que merecia.', 19865),
(91370, 'ptBR', '', 'Você não é tão forte.', 19865),
(91371, 'ptBR', '', 'Talvez você pensará duas vezes da próxima vez! Peraí...', 19865),
(91372, 'ptBR', '', 'Consegui! Matei um!', 19865),
(91373, 'ptBR', '', 'Ei, comandante! Tem alguma missão para mim? Estou pronta!', 19865),
(91374, 'ptBR', '', 'Bom ver você!', 19865),
(91375, 'ptBR', '', 'Posso fazer alguma coisa por você, comandante?', 19865),
(91376, 'ptBR', '', 'Comandante! É uma honra.', 19865),
(91377, 'ptBR', '', 'Tá ficando quente aqui dentro? Ou é comigo...', 19865),
(91378, 'ptBR', '', 'Eu... dei o meu melhor...', 19865),
(91379, 'ptBR', '', 'Sinto muito, comandante...', 19865),
(91380, 'ptBR', '(Domínio das Feras) Mostrar as Umbrósias a Gara.', '(Domínio das Feras) Mostrar as Umbrósias a Gara.', 19865),
(91381, 'ptBR', '<Gara fareja as frutinhas, e depois olha para você com expectativa.>', '', 19865),
(91382, 'ptBR', 'Minha alma... se sente em paz... obrigado.', 'Minha alma... se sente em paz... obrigada.', 19865),
(91383, 'ptBR', '(Domínio das Feras) Não sou do clã Lua Negra, quero ajudar esse lobo!', '(Domínio das Feras) Não sou do clã Lua Negra, quero ajudar esse lobo!', 19865),
(91384, 'ptBR', 'Gara era minha loba, antes de abandonarmos o xamanismo por essas... magias sombrias. Ela nem olahva mais para mim, não depois que fui maculado pelo caos.', 'Gara era minha loba, antes de abandonarmos o xamanismo por essas... magias sombrias. Ela nem olahva mais para mim, não depois que fui maculada pelo caos.', 19865),
(91385, 'ptBR', 'Como você ousa dar paz à alma dela? A alma de Om''ra pertence ao CAOS!', '', 19865),
(91386, 'ptBR', 'Tomarei este como compensação!', '', 19865),
(91387, 'ptBR', 'Sua alma preencherá o caos!', '', 19865),
(91388, 'ptBR', 'Você jamais escapará do caos! Suas almas serão devoradas!', '', 19865),
(91389, 'ptBR', 'Ela está sendo engolida pelo caos! Você precisa ajudá-la! Só há um jeito, dome-a agora! Talvez você encontre uma forma de reverter o processo, e colocar a alma dela para descansar, como fez comigo!', 'Ela está sendo engolida pelo caos! Você precisa ajudá-la! Só há um jeito, dome-a agora! Talvez você encontre uma forma de reverter o processo, e colocar a alma dela para descansar, como fez comigo!', 19865),
(91390, 'ptBR', 'Você conseguiu... obrigada. Adeus, Gara, minha alma pode descansar, agora. Espero... que você também encontre essa paz um dia. Me desculpe, minha queria Gara.', 'Você conseguiu... obrigada. Adeus, Gara, minha alma pode descansar, agora. Espero... que você também encontre essa paz um dia. Me desculpe, minha queria Gara.', 19865),
(91391, 'ptBR', 'Você usa Coibição instintivamente para evitar o ataque!', 'Você usa Coibição instintivamente para evitar o ataque!', 19865),
(91392, 'ptBR', 'Sua habilidade de rastreamento permite que você permaneça neste reino!', 'Sua habilidade de rastreamento permite que você permaneça neste reino!', 19865),
(91393, 'ptBR', 'Você vai para o Reino do Caos!', 'Você vai para o Reino do Caos!', 19865),
(91394, 'ptBR', 'Eu consumirei tudo!', '', 19865),
(91395, 'ptBR', 'A luta contra o clã do Brado Guerreiro é honrosa, mas acho que Rosarães não ficou contente com a mudança de prioridades aqui em Nagrand.', '', 19865),
(91396, 'ptBR', 'Tol$go:a;! Como ousa desafiar o poder dos Folhas-más? Morra!', '', 19865),
(91397, 'ptBR', 'O inverno... chegou... para mim...', '', 19865),
(91398, 'ptBR', 'O mestre... queimará sua alma!', '', 19865),
(91399, 'ptBR', 'A hora se aproxima... logo você morrerá...', '', 19865),
(91400, 'ptBR', 'Nosso mestre vai devorar sua alma...', '', 19865),
(91401, 'ptBR', 'Não consigo impedir a destruição...', '', 19865),
(91402, 'ptBR', 'Nãããão... é você quem deve morrer!', '', 19865),
(91403, 'ptBR', 'Não! Não... nãão... as trevas...', '', 19865),
(91404, 'ptBR', 'O caos está vindo... para destruir todos vocês!', '', 19865),
(91405, 'ptBR', 'Idiota... nós já... vencemos...', '', 19865),
(91406, 'ptBR', 'Ei... o que estava esperando? Gélido Lamento ou coisa do tipo?', '', 19865),
(91407, 'ptBR', 'Colocando no devido lugar.', '', 19865),
(91408, 'ptBR', 'Sem um fio de cabelo fora do lugar.', '', 19865),
(91409, 'ptBR', 'É por isso que eu estou aqui.', '', 19865),
(91410, 'ptBR', '', 'Vocês não são bem-vindos aqui!', 19865),
(91411, 'ptBR', '', 'Não estou impressionada.', 19865),
(91412, 'ptBR', '', 'Você não tinha chance.', 19865),
(91413, 'ptBR', 'Gostaria de voltar para o ninho.', 'Gostaria de voltar para o ninho.', 19865),
(91414, 'ptBR', 'Grrrawr! Tenho sede de sangue!', '', 19865),
(91415, 'ptBR', 'Está bom, então.', '', 19865),
(91416, 'ptBR', 'Ops! Desculpe.', '', 19865),
(91417, 'ptBR', 'Globalizado!', '', 19865),
(91418, 'ptBR', 'Fazendo jogadas!', '', 19865),
(91419, 'ptBR', 'Quero emitir uma ordem de serviço de couro.', 'Quero emitir uma ordem de serviço de couro.', 19865),
(91420, 'ptBR', 'Quero emitir uma grande ordem de serviço de couro.', 'Quero emitir uma grande ordem de serviço de couro.', 19865),
(91421, 'ptBR', 'Quero emitir uma ordem de serviço de carne.', 'Quero emitir uma ordem de serviço de carne.', 19865),
(91422, 'ptBR', 'Quero emitir uma grande ordem de serviço de carne.', 'Quero emitir uma grande ordem de serviço de carne.', 19865),
(91423, 'ptBR', 'Quero emitir uma ordem de serviço de pelegos.', 'Quero emitir uma ordem de serviço de pelegos.', 19865),
(91424, 'ptBR', 'Quero emitir uma grande ordem de serviço de pelegos.', 'Quero emitir uma grande ordem de serviço de pelegos.', 19865),
(91425, 'ptBR', '<O doutor fede a assoalho de taverna e está com cara de quem atravessou dez quilômetros de chão ruim. Está lívido, se esforçando a olhos vistos para não vomitar em cima de você.>$b$bEi, co-man-dan-te! <Burp!> A noitada de ontem, no Beliscapito, foi a maior doideira. Mas eu cheguei em casa bem! Tô pronto pro serviço, sim senhor. <Arroto!> Cara, você deu uma geral nesta guarnição de ontem pra hoje, hein? Colocou uns espinhos... umas peles... neve? De onde veio essa neve? Acho melhor eu me sentar.', '', 19865),
(91426, 'ptBR', 'Jeron Quedabrasa foi derrotado pela Aliança!', '', 19865),
(91427, 'ptBR', 'Rylai Desalento foi massacrada pela Horda!', '', 19865),
(91428, 'ptBR', 'Quer uma análise? Posso entregar no fim da semana.', '', 19865),
(91429, 'ptBR', 'Que acha de a gente ir para a praia tomar um chope quando terminar aqui?', '', 19865),
(91430, 'ptBR', 'Se você passar pela Mata Sombria, fique de olho nas Flores da Canção desabrochantes. Elas têm poderosas propriedades mágicas.$B$BNo entanto, você pode precisar rechaçar alguns arakkoa para consegui-las.', '', 19865),
(91431, 'ptBR', 'O que tem a dizer sobre as montarias em treinamento?', 'O que tem a dizer sobre as montarias em treinamento?', 19865),
(91432, 'ptBR', 'Os elfos noturnos estão tentando ressuscitar um anciente para usarem contra nós com o poder dos artefatos encontrados aqui em Ashran.$B$BSe você vir membros da Aliança lá fora, tome quaisquer fragmentos que eles estejam carregando, à força, se necessário.', '', 19865),
(91433, 'ptBR', 'Seguimos as suas ordens, estamos capturando animais e adestrando como montarias para a guarnição. Sinta-se à vontade para pegar uma por hoje. Pegue o apito comigo.$B$BLembre-se de que elas não são tão treinadas quanto a sua montaria e vão se cansar com poucas batalhas.', '', 19865),
(91434, 'ptBR', 'Seguimos as suas ordens, estamos capturando animais e adestrando como montarias para a guarnição. Sinta-se à vontade para pegar uma por hoje. É só me falar qual apito você quer.$B$BLembre-se de que elas não são tão treinadas quanto a sua montaria e vão se cansar com poucas batalhas.', '', 19865),
(91435, 'ptBR', '', 'As chamas dos braseiros perto do Círculo da Conquista podem parecer comuns à primeira vista. Contudo, creio que tenham sido encantadas com a antiga magia dos Malho Imponente.$B$BEu me senti estranhamente atraída por elas. Ao tocar uma delas, fiquei subitamente repleta de energia mágica.', 19865),
(91436, 'ptBR', '', 'Proteja nossos sacerdotes da Estrada da Glória se os vir sendo atacados.$B$BEu mesma os treinei. O poder de cura deles não tem rival desse lado do Portal Negro.', 19865),
(91437, 'ptBR', 'Eu estou SUPERempolgado de estar aqui hoje!', '', 19865),
(91442, 'ptBR', '|TInterface\\Icons\\spell_sandexplosion.blp:20|tTem uma |cFFFF0000|Hspell:155187|h[Bomba]|h|r em você!', '|TInterface\\Icons\\spell_sandexplosion.blp:20|tTem uma |cFFFF0000|Hspell:155187|h[Bomba]|h|r em você!', 19865),
(91443, 'ptBR', '|TInterface\\Icons\\Spell_Fire_LavaSpawn.blp:20|tUm Bradachamas atacou você com |cFFFF0000|Hspell:176121|h[Fogo Volátil]|h|r!', '|TInterface\\Icons\\Spell_Fire_LavaSpawn.blp:20|tUm Bradachamas atacou você com |cFFFF0000|Hspell:176121|h[Fogo Volátil]|h|r!', 19865),
(91444, 'ptBR', '|TInterface\\Icons\\ability_rhyolith_magmaflow_whole.blp:20|tO Encarregado Feldspar vai criar uma |cFFFF0000|Hspell:156934|h[Ruptura]|h|r sob os seus pés!', '|TInterface\\Icons\\ability_rhyolith_magmaflow_whole.blp:20|tO Encarregado Feldspar vai criar uma |cFFFF0000|Hspell:156934|h[Ruptura]|h|r sob os seus pés!', 19865),
(91445, 'ptBR', '|TInterface\\Icons\\ability_foundryraid_melt.blp:20|tO Coração da Montanha vai |cFFFF0000|Hspell:155225|h[Derreter]|h|r o chão sob seus pés!', '|TInterface\\Icons\\ability_foundryraid_melt.blp:20|tO Coração da Montanha vai |cFFFF0000|Hspell:155225|h[Derreter]|h|r o chão sob seus pés!', 19865),
(91446, 'ptBR', '|TInterface\\Icons\\ability_garrosh_hellscreams_warsong.blp:20|t%s começa a lançar |cFFF00000|Hspell:160838|h[Rugido Perturbador]|h|r!', '', 19865),
(91451, 'ptBR', '', '|TInterface\\Icons\\ability_warrior_dragonroar.blp:20|t %s começa a lançar |cFFFF0000|Hspell:177477|h[Rugido do Dragão]|h|r!', 19865),
(91452, 'ptBR', '', 'Tá precisando de quê?', 19865),
(91453, 'ptBR', 'E para onde você gostaria de ir?', 'E para onde você gostaria de ir?', 19865),
(91454, 'ptBR', 'Se você está procurando informações sobre batalhas de mascotes, procure Suelen Redada.\n\nAcho, que ela está hospedada no porão da estalagem. Vamos torcer para que ela consiga impedir que as mascotes dela se afastem demais daqui.', 'Se você está procurando informações sobre batalhas de mascotes, procure Suelen Redada.\n\nAcho, que ela está hospedada no porão da estalagem. Vamos torcer para que ela consiga impedir que as mascotes dela se afastem demais daqui.', 19865),
(91455, 'ptBR', 'Uma dupla de etéreos abriu uma loja no andar de baixo do Aclive de Andromath.\n\nProcure-os se quiser usar seus serviços de Transmogrificação ou Cofre Etéreo.', 'Uma dupla de etéreos abriu uma loja no andar de baixo do Aclive de Andromath.\n\nProcure-os se quiser usar seus serviços de Transmogrificação ou Cofre Etéreo.', 19865),
(91456, 'ptBR', 'Quando estiver tentando fazer ou gastar algum dinheiro, a família Tyron e os associados devem ajudar.\n\nEles abriram uma loja logo depois da Prefeitura, ao lado dos arakkoas refugiados.', 'Quando estiver tentando fazer ou gastar algum dinheiro, a família Tyron e os associados devem ajudar.\n\nEles abriram uma loja logo depois da Prefeitura, ao lado dos arakkoas refugiados.', 19865),
(91457, 'ptBR', 'Os anões da Liga dos Exploradores têm permitido que aventureiros usem o espaço extra na Câmara dos Barbabronze para guardar seus pertences em excesso\n\nÉ o prédio grande de metal com o canhão em cima no meio da cidade. Não dá para não ver.', 'Os anões da Liga dos Exploradores têm permitido que aventureiros usem o espaço extra na Câmara dos Barbabronze para guardar seus pertences em excesso\n\nÉ o prédio grande de metal com o canhão em cima no meio da cidade. Não dá para não ver.', 19865),
(91458, 'ptBR', 'Se você precisar viajar de grifo, vai querer palar com o nosso Mestre de Grifos, Ernst ten Bosch.\n\nEle fica no topo da colina logo depois do salão de refeições.', 'Se você precisar viajar de grifo, vai querer palar com o nosso Mestre de Grifos, Ernst ten Bosch.\n\nEle fica no topo da colina logo depois do salão de refeições.', 19865),
(91459, 'ptBR', 'Se você estiver querendo relaxar, é melhor descer até a Estalagem Pouso do Herói. Jaesia deve lhe conseguir um quarto e uma caneca de cerveja.\n\nÉ só pegar a rua depois da muralha de pedra e seguir para oeste. E pronto.', 'Se você estiver querendo relaxar, é melhor descer até a Estalagem Pouso do Herói. Jaesia deve lhe conseguir um quarto e uma caneca de cerveja.\n\nÉ só pegar a rua depois da muralha de pedra e seguir para oeste. E pronto.', 19865),
(91460, 'ptBR', 'Na verdade temos algumas caixas de correio por aqui. Você estava procurando alguma em específico?', 'Na verdade temos algumas caixas de correio por aqui. Você estava procurando alguma em específico?', 19865),
(91461, 'ptBR', 'Essa caixa de correio fica em frente à Câmara dos Barbabronze no meio da cidade.\n\nÉ o prédio grande de metal com um canhão em cima.', 'Essa caixa de correio fica em frente à Câmara dos Barbabronze no meio da cidade.\n\nÉ o prédio grande de metal com um canhão em cima.', 19865),
(91462, 'ptBR', 'Essa caixa de correio fica ao lado da porta da Estalagem Pouso do Herói.\n\nBasta seguir a rua, passar a muralha de pedra e seguir para oeste. Você vai chegar certinho na estalagem, no pé da colina.', 'Essa caixa de correio fica ao lado da porta da Estalagem Pouso do Herói.\n\nBasta seguir a rua, passar a muralha de pedra e seguir para oeste. Você vai chegar certinho na estalagem, no pé da colina.', 19865),
(91463, 'ptBR', 'Prefeitura', 'Prefeitura', 19865),
(91464, 'ptBR', 'Há outra caixa de correio em frente à Prefeitura.\n\nPasta ir para a parte sul da cidade. A Prefeitura é logo depois do monumento central.', 'Há outra caixa de correio em frente à Prefeitura.\n\nPasta ir para a parte sul da cidade. A Prefeitura é logo depois do monumento central.', 19865),
(91465, 'ptBR', 'Nossos magos abriram portais para diversos locais em alguns lugares na cidade.\n\nPara onde você gostaria de ir?', 'Nossos magos abriram portais para diversos locais em alguns lugares na cidade.\n\nPara onde você gostaria de ir?', 19865),
(91466, 'ptBR', 'Darnassus', 'Darnassus', 19865),
(91467, 'ptBR', 'O portal para Darnassus fica perto do poço lunar dos elfos noturnos, no lado leste de Escudo Tonante.\n\nSiga a rua depois da casa de leilões para chegar lá.', 'O portal para Darnassus fica perto do poço lunar dos elfos noturnos, no lado leste de Escudo Tonante.\n\nSiga a rua depois da casa de leilões para chegar lá.', 19865),
(91468, 'ptBR', 'Altaforja', 'Altaforja', 19865),
(91469, 'ptBR', 'Sem surpresas, o portal para Altaforja foi aberto ao lado da Câmara dos Barbabronze. Ele está do lado sul do prédio.\n\nÉ o prédio grande de metal com um canhão em cima no meio da cidade.', 'Sem surpresas, o portal para Altaforja foi aberto ao lado da Câmara dos Barbabronze. Ele está do lado sul do prédio.\n\nÉ o prédio grande de metal com um canhão em cima no meio da cidade.', 19865),
(91470, 'ptBR', 'Ventobravo', 'Ventobravo', 19865),
(91471, 'ptBR', 'O portal para Ventobravo foi aberto em frente ao Aclive de Andromath.\n\nSe você seguir a rua depois da Câmara dos Barbabronze, vai dar direto na torre.', 'O portal para Ventobravo foi aberto em frente ao Aclive de Andromath.\n\nSe você seguir a rua depois da Câmara dos Barbabronze, vai dar direto na torre.', 19865),
(91472, 'ptBR', 'Você procura treinamento em que profissão, especificamente?', 'Você procura treinamento em que profissão, especificamente?', 19865),
(91473, 'ptBR', 'Parece que a Horda de Ferro está fazendo a jogada dela. Soldados! Levem os aldeões a um lugar seguro!', '', 19865),
(91474, 'ptBR', 'Os segredos da alquimia de Draenor são bem conhecidos por nosso alquimista local, Jaiden Trask.\n\nEle fica em frente à Estalagem Pouso do Herói, na parte sul da cidade.', 'Os segredos da alquimia de Draenor são bem conhecidos por nosso alquimista local, Jaiden Trask.\n\nEle fica em frente à Estalagem Pouso do Herói, na parte sul da cidade.', 19865),
(91475, 'ptBR', 'Nossa arqueóloga local, Manda Darlowe, abriu um negócio perto do quartel no centro de Escudo Tonante.\n\nEla está acompanhada de um arakkoa estranho que também pode conseguir ajudar nas suas empreitadas.', 'Nossa arqueóloga local, Manda Darlowe, abriu um negócio perto do quartel no centro de Escudo Tonante.\n\nEla está acompanhada de um arakkoa estranho que também pode conseguir ajudar nas suas empreitadas.', 19865),
(91476, 'ptBR', 'Eu também!', 'Eu também!', 19865),
(91477, 'ptBR', 'Aimê Auraforja é nossa especialista local em ferraria.\n\nEla e a equipe dela ficam na forja ao, ar livre em frente à Câmara dos Barbabronze no centro de Escudo Tonante.', 'Aimê Auraforja é nossa especialista local em ferraria.\n\nEla e a equipe dela ficam na forja ao, ar livre em frente à Câmara dos Barbabronze no centro de Escudo Tonante.', 19865),
(91478, 'ptBR', 'Se você estiver atrás do melhor cozinheiro da cidade, procure Elton Nero na Estalagem Pouso do Herói.\n\nEle pode parecer meio bobo com aqueles utensílios e geringonças, mas sabe preparar alguns pratos realmente bons.', 'Se você estiver atrás do melhor cozinheiro da cidade, procure Elton Nero na Estalagem Pouso do Herói.\n\nEle pode parecer meio bobo com aqueles utensílios e geringonças, mas sabe preparar alguns pratos realmente bons.', 19865),
(91479, 'ptBR', 'Espero que você tenha sorte hoje!', '', 19865),
(91480, 'ptBR', 'Se você quer treinar encantamento, Bil Chispatônica é o encantador mais competente de Escudo Tonante. Só tenha cuidado com o que ele oferecer como “desconto”.\n\nEle e o associado dele, Bob, ficam atrás da Casa de Leilões anunciando mercadorias.', 'Se você quer treinar encantamento, Bil Chispatônica é o encantador mais competente de Escudo Tonante. Só tenha cuidado com o que ele oferecer como “desconto”.\n\nEle e o associado dele, Bob, ficam atrás da Casa de Leilões anunciando mercadorias.', 19865),
(91481, 'ptBR', '', '|TInterface\\Icons\\Spell_Shadow_SoulLeech_2.blp:20|t %s começa a lançar |cFFF00000|Hspell:153477|h[Receptáculo de Alma]|h|r!', 19865),
(91482, 'ptBR', 'Nossa principal engenheira em Escudo Tonante é Hilda Zapetrape.\n\nEla fica na Ala de Engenharia no centro da cidade.', 'Nossa principal engenheira em Escudo Tonante é Hilda Zapetrape.\n\nEla fica na Ala de Engenharia no centro da cidade.', 19865),
(91483, 'ptBR', '|TInterface\\Icons\\inv_elemental_crystal_fire.blp:20|tVocê tornou-se alvo de uma |cFFFF0000|Hspell:160282|h[Detonação Solar]|h|r! Afaste-se de seus aliados!', '|TInterface\\Icons\\inv_elemental_crystal_fire.blp:20|tVocê tornou-se alvo de uma |cFFFF0000|Hspell:160282|h[Detonação Solar]|h|r! Afaste-se de seus aliados!', 19865),
(91484, 'ptBR', '$n cria um Berloque de Ciclone!', '$n cria um Berloque de Ciclone!', 19865),
(91485, 'ptBR', 'Flaméolo do Senhor do Trovão mortos: $1i (+$2i VP)', 'Flaméolo do Senhor do Trovão mortos: $1i (+$2i VP)', 19865),
(91486, 'ptBR', 'Um Tanque de Chamas se aproxima!', 'Um Tanque de Chamas se aproxima!', 19865),
(91487, 'ptBR', 'A batalha pelo cemitério começa em 3 minutos!', '', 19865),
(91488, 'ptBR', 'Finalmente... posso descansar...', 'Finalmente... posso descansar...', 19865),
(91489, 'ptBR', 'O tormento acabou...', 'O tormento acabou...', 19865),
(91490, 'ptBR', 'Obrigado por essa gentileza...', 'Obrigada por essa gentileza...', 19865),
(91491, 'ptBR', 'Por favor... não deixe que sejamos esquecidos...', 'Por favor... não deixe que sejamos esquecidos...', 19865),
(91492, 'ptBR', 'O ataque dos saberons acabou. Pode ir agora e descanse em paz.', 'O ataque dos saberons acabou. Pode ir agora e descanse em paz.', 19865),
(91493, 'ptBR', 'Por favor! Você tem que nos ajudar! Os saberons chegaram! Nossas vidas estão em risco!', 'Por favor! Você tem que nos ajudar! Os saberons chegaram! Nossas vidas estão em risco!', 19865),
(91494, 'ptBR', '|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t %s começa a lançar |cFFFF0000|Hspell:170905|h[Socar Terra]|h|r!', '', 19865),
(91495, 'ptBR', 'Você não faz parte de um grupo.', '', 19865),
(91496, 'ptBR', 'Se você tiver problemas com a Aliança lá fora, use um dos sinalizadores do Frizzo Foguetelouco.$B$BNão podemos ajudar você se não soubermos onde você está.', '', 19865),
(91497, 'ptBR', '<Gara eriça as orelhas, mas seu olhar pemanece fixado no túmulo.>', '', 19865),
(91498, 'ptBR', 'O Senhor do Vidro, um deus do caos que chama a si mesmo de Xan, aprisionou minha alma no reino do caos. Fragmentos dela foram... arrancados... para uso da Lua Negra aqui nos sacrários.', 'O Senhor do Vidro, um deus do caos que chama a si mesmo de Xan, aprisionou minha alma no reino do caos. Fragmentos dela foram... arrancados... para uso da Lua Negra aqui nos sacrários.', 19865),
(91499, 'ptBR', 'Mas ela não saiu do meu lado, Gara. Não até que a imagem correta fosse queimada, para que minha alma pudesse descansar.', 'Mas ela não saiu do meu lado, Gara. Não até que a imagem correta fosse queimada, para que minha alma pudesse descansar.', 19865),
(91500, 'ptBR', 'Obrigada por libertar nós duas.', 'Obrigada por libertar nós duas.', 19865),
(91501, 'ptBR', 'Por favor, leve-me até as Agulhas de Arak.', 'Por favor, leve-me até as Agulhas de Arak.', 19865),
(91502, 'ptBR', '%s começa a canalizar |cFFFF0404|Hspell:159996|h[Esporos Infectantes]|h|r!', '', 19865),
(91510, 'ptBR', 'Telys Tratacinhas é a nossa especialista local em primeiros socorros.\n\nEla e sua aprendiz cuidam dos feridos no quartel.', 'Telys Tratacinhas é a nossa especialista local em primeiros socorros.\n\nEla e sua aprendiz cuidam dos feridos no quartel.', 19865),
(91511, 'ptBR', 'Zinho Moinho é o melhor com vara e anzol aqui em Escudo Tonante. Procure-o para tratar do que precisar em pescaria.\n\nGeralmente ele fica perto da própria casa à beira d’água, logo atrás da Prefeitura e da Casa de Leilões.', 'Zinho Moinho é o melhor com vara e anzol aqui em Escudo Tonante. Procure-o para tratar do que precisar em pescaria.\n\nGeralmente ele fica perto da própria casa à beira d’água, logo atrás da Prefeitura e da Casa de Leilões.', 19865),
(91512, 'ptBR', 'A principal herborista de Escudo Tonante, Jie Selvabroto, veio de Pandária para estudar a flora nativa de Draenor.\n\nEla fica em frente à Estalagem Pouso do Herói, se você precisar aprender alguma coisa de Herborismo.', 'A principal herborista de Escudo Tonante, Jie Selvabroto, veio de Pandária para estudar a flora nativa de Draenor.\n\nEla fica em frente à Estalagem Pouso do Herói, se você precisar aprender alguma coisa de Herborismo.', 19865),
(91513, 'ptBR', 'Na Torre dos Magos você encontrará a Escriba Chi-Yuan.\n\nEla é a melhor escriba de Ashran, e pode treinar você no que for necessário em escrivania.', 'Na Torre dos Magos você encontrará a Escriba Chi-Yuan.\n\nEla é a melhor escriba de Ashran, e pode treinar você no que for necessário em escrivania.', 19865),
(91514, 'ptBR', 'Os Artífices dos draeneis estão dando uma mãozinha nas nossas operações em Escudo Tonante.\n\nSe você busca treinamento em joalheria, encontre a Artífice Nissea no acampamento draeneico, logo a oeste do centro de Escudo Tonante.', 'Os Artífices dos draeneis estão dando uma mãozinha nas nossas operações em Escudo Tonante.\n\nSe você busca treinamento em joalheria, encontre a Artífice Nissea no acampamento draeneico, logo a oeste do centro de Escudo Tonante.', 19865),
(91515, 'ptBR', 'Jistun Penafina é nosso especialista local em couraria. \n\nA barraca dele fica perto da Câmara dos Barbabronze, no centro da cidade.', 'Jistun Penafina é nosso especialista local em couraria. \n\nA barraca dele fica perto da Câmara dos Barbabronze, no centro da cidade.', 19865),
(91516, 'ptBR', 'Se você precisar de ajuda com mineração, fale com Jomão di Corrente. Ele é o especialista por essas bandas. \n\nEle fica em frente à Ala de Engenharia, no centro da cidade.', 'Se você precisar de ajuda com mineração, fale com Jomão di Corrente. Ele é o especialista por essas bandas. \n\nEle fica em frente à Ala de Engenharia, no centro da cidade.', 19865),
(91517, 'ptBR', 'O Rangari Laandon tem compartilhado seu conhecimento de esfolamento com nossas forças aqui em Escudo Tonante. \n\nEle fica na barraca de couraria, perto da Câmara dos Barbabronze, no centro da cidade.', 'O Rangari Laandon tem compartilhado seu conhecimento de esfolamento com nossas forças aqui em Escudo Tonante. \n\nEle fica na barraca de couraria, perto da Câmara dos Barbabronze, no centro da cidade.', 19865),
(91518, 'ptBR', 'Josué Felinto é o melhor alfaiate de toda Draenor. Não há ninguém melhor para ajudar você com agulha e linha. \n\nEle fica na própria barraca no centro comercial da cidade. É só procurar modelos com roupas extravagantes. É fácil de achar.', 'Josué Felinto é o melhor alfaiate de toda Draenor. Não há ninguém melhor para ajudar você com agulha e linha. \n\nEle fica na própria barraca no centro comercial da cidade. É só procurar modelos com roupas extravagantes. É fácil de achar.', 19865),
(91519, 'ptBR', 'A Ordem dos Despertos abriu um estabelecimento em frente à Casa de Leilões, na parte sul de Escudo Tonante. \n\nOuvi dizer que estão oferecendo grandes recompensas a qualquer aventureiro que possa ajudá-los na busca por relíquias Apexis.', 'A Ordem dos Despertos abriu um estabelecimento em frente à Casa de Leilões, na parte sul de Escudo Tonante. \n\nOuvi dizer que estão oferecendo grandes recompensas a qualquer aventureiro que possa ajudá-los na busca por relíquias Apexis.', 19865),
(91520, 'ptBR', 'Diversas facções de Draenor se reuniram na Prefeitura para oferecer ajuda em Ashran. \n\nEles têm até mesmo mercadorias à venda para quem tiver reputação suficiente.', 'Diversas facções de Draenor se reuniram na Prefeitura para oferecer ajuda em Ashran. \n\nEles têm até mesmo mercadorias à venda para quem tiver reputação suficiente.', 19865),
(91521, 'ptBR', 'Cyd Figueyra abriu uma loja no centro de Escudo Tonante, perto de muitos de nossos treinadores de profissões. \n\nSe você estiver precisando de materiais para seu ofício, procure-o lá.', 'Cyd Figueyra abriu uma loja no centro de Escudo Tonante, perto de muitos de nossos treinadores de profissões. \n\nSe você estiver precisando de materiais para seu ofício, procure-o lá.', 19865),
(91522, 'ptBR', 'O Comerciante Caerel fornece diversos produtos para aventureir$Go:a;s como você. \n\nO carroção dele fica perto da prefeitura, ao lado do monumento central.', 'O Comerciante Caerel fornece diversos produtos para aventureir$Go:a;s como você. \n\nO carroção dele fica perto da prefeitura, ao lado do monumento central.', 19865),
(91523, 'ptBR', 'Se você quiser hospedar seus animais, procure Orville Manfred ao lado da estalagem na parte sul de Escudo Tonante. \n\nA despeito da aparência feroz, ouvi falar que ele cuida bem dos animais.', 'Se você quiser hospedar seus animais, procure Orville Manfred ao lado da estalagem na parte sul de Escudo Tonante. \n\nA despeito da aparência feroz, ouvi falar que ele cuida bem dos animais.', 19865),
(91524, 'ptBR', 'Temos muitos comerciantes que abriram lojas aqui em Escudo Tonante. Quem você está procurando?', 'Temos muitos comerciantes que abriram lojas aqui em Escudo Tonante. Quem você está procurando?', 19865),
(91525, 'ptBR', 'Comerciante de Estilhaço Apexis', 'Comerciante de Estilhaço Apexis', 19865),
(91526, 'ptBR', 'Comerciantes de Reputação', 'Comerciantes de Reputação', 19865),
(91527, 'ptBR', 'Soe o alarme! Deve ser uma invasão de Primevos.', '', 19865),
(91532, 'ptBR', 'Esfregando', 'Esfregando', 19865),
(91533, 'ptBR', 'Cascasseca lança |TInterface\\Icons\\Spell_Nature_ElementalShields.blp:20|t |cFFFF0404|Hspell:164294|h[Crescimento Desenfreado]|h|r em você!', 'Cascasseca lança |TInterface\\Icons\\Spell_Nature_ElementalShields.blp:20|t |cFFFF0404|Hspell:164294|h[Crescimento Desenfreado]|h|r em você!', 19865),
(91534, 'ptBR', '%s começa a soprar |cFFFF0404|Hspell:155031|h[Fogo Devorador]|h|r!', '', 19865),
(91535, 'ptBR', 'Gostaria de alguma coisa?', 'Gostaria de alguma coisa?', 19865),
(91536, 'ptBR', 'Mascotes de batalha? Fale come Zarg Smaggaosso. Ele é o orc dos gatinhos e fica a norte do grande totem. \n\nÉ, é isso mesmo que você ouviu, o orc dos gatinhos.', 'Mascotes de batalha? Fale come Zarg Smaggaosso. Ele é o orc dos gatinhos e fica a norte do grande totem. \n\nÉ, é isso mesmo que você ouviu, o orc dos gatinhos.', 19865),
(91537, 'ptBR', 'Alguns etéreos abriram lojas na Torre dos Elementos. \n\nNão sei qual é o esquema deles em Ashran, mas eles prestam bons serviços.', 'Alguns etéreos abriram lojas na Torre dos Elementos. \n\nNão sei qual é o esquema deles em Ashran, mas eles prestam bons serviços.', 19865),
(91538, 'ptBR', 'Se quiser tentar a sorte no mercado, vá à Casa de Leilões. \n\nEla fica no distrito taureno, na parte norte de Lança de Guerra.', 'Se quiser tentar a sorte no mercado, vá à Casa de Leilões. \n\nEla fica no distrito taureno, na parte norte de Lança de Guerra.', 19865),
(91539, 'ptBR', 'Você pode guardar seus equipamentos extra em segurança com os banqueiros da Fortaleza Lança de Guerra. Ninguém é louco o bastante para tentar roubar aquele lugar! \n\nÉ o prédio grandão, a sul do totem, não tem erro.', 'Você pode guardar seus equipamentos extra em segurança com os banqueiros da Fortaleza Lança de Guerra. Ninguém é louco o bastante para tentar roubar aquele lugar! \n\nÉ o prédio grandão, a sul do totem, não tem erro.', 19865),
(91540, 'ptBR', 'Tem alguns mestres de mantícoras em Lança de Guerra, caso precise viajar depressa. \n\nProcure Ilalu, no topo do morro, atrás da taberna, se precisar viajar.', 'Tem alguns mestres de mantícoras em Lança de Guerra, caso precise viajar depressa. \n\nProcure Ilalu, no topo do morro, atrás da taberna, se precisar viajar.', 19865),
(91541, 'ptBR', 'Quando quiser descansar, dirija-se à Taberna Lança Quebrada. \n\nEla fica na beira da estrada, saindo do grande totem rumo ao norte.', 'Quando quiser descansar, dirija-se à Taberna Lança Quebrada. \n\nEla fica na beira da estrada, saindo do grande totem rumo ao norte.', 19865),
(91542, 'ptBR', 'Temos várias caixas de correio. Qual você quer ver?', 'Temos várias caixas de correio. Qual você quer ver?', 19865),
(91543, 'ptBR', 'Tem uma bem na frente da Taberna Lança Quebrada. \n\nEla fica na beira da estrada, saindo do grande totem rumo ao norte.', 'Tem uma bem na frente da Taberna Lança Quebrada. \n\nEla fica na beira da estrada, saindo do grande totem rumo ao norte.', 19865),
(91544, 'ptBR', 'Tem uma caixa de correiro bem na frente da Casa de Leilões, no distrito taureno.\n\nFica a norte da fogueira.', 'Tem uma caixa de correiro bem na frente da Casa de Leilões, no distrito taureno.\n\nFica a norte da fogueira.', 19865),
(91545, 'ptBR', 'Os banqueiros instalaram uma caixa de correio na frente da Fortaleza Lança de Guerra, fique à vontade para usá-la. \n\nÉ o prédio grandão, a sul do totem.', 'Os banqueiros instalaram uma caixa de correio na frente da Fortaleza Lança de Guerra, fique à vontade para usá-la. \n\nÉ o prédio grandão, a sul do totem.', 19865),
(91546, 'ptBR', 'Os goblins instalaram uma caixa de correio na frente da Garagem do Gallywix. \n\nÉ o maior prédio do distrito goblínico, na ala leste da cidade.', 'Os goblins instalaram uma caixa de correio na frente da Garagem do Gallywix. \n\nÉ o maior prédio do distrito goblínico, na ala leste da cidade.', 19865),
(91547, 'ptBR', 'Os magos abriram portais que levam a um punhado de lugares diferentes. Qual você quer?', 'Os magos abriram portais que levam a um punhado de lugares diferentes. Qual você quer?', 19865),
(91548, 'ptBR', 'O portal para Orgrimmar fica na Torre dos Elementos. \n\nSaia do grande totem rumo ao leste.', 'O portal para Orgrimmar fica na Torre dos Elementos. \n\nSaia do grande totem rumo ao leste.', 19865),
(91549, 'ptBR', 'O portal para o Penhasco do Trovão está no distrito taureno.\n\nFica bem ao lado da Casa de Leilões.', 'O portal para o Penhasco do Trovão está no distrito taureno.\n\nFica bem ao lado da Casa de Leilões.', 19865),
(91550, 'ptBR', 'Os Renegados abriram um portal para a Cidade Baixa no seu distrito. \n\nEle se encontra abaixo da cabana da alquimia.', 'Os Renegados abriram um portal para a Cidade Baixa no seu distrito. \n\nEle se encontra abaixo da cabana da alquimia.', 19865),
(91551, 'ptBR', 'Você precisa de ajuda em que tipo de profissão?', 'Você precisa de ajuda em que tipo de profissão?', 19865),
(91552, 'ptBR', 'Se quiser criar uma peste nova, não tem ninguém melhor do que os Renegados. \n\nProcure Kristoph Cossey no distrito dos renegados, na cabana da alquimia.', 'Se quiser criar uma peste nova, não tem ninguém melhor do que os Renegados. \n\nProcure Kristoph Cossey no distrito dos renegados, na cabana da alquimia.', 19865),
(91553, 'ptBR', 'A Sociedade de Preservação de Bondebico é a melhor pedida quando o assunto é Arqueologia. \n\nEles ficam numa garagenzinha, no distrito goblínico. Fale com Joaquina Virabrequina.', 'A Sociedade de Preservação de Bondebico é a melhor pedida quando o assunto é Arqueologia. \n\nEles ficam numa garagenzinha, no distrito goblínico. Fale com Joaquina Virabrequina.', 19865),
(91554, 'ptBR', 'Matias Polepolias é o maior entendido de ferraria por estas bandas. \n\nEles ficam no distrito goblínico, atrás da Garagem do Gallywix.', 'Matias Polepolias é o maior entendido de ferraria por estas bandas. \n\nEles ficam no distrito goblínico, atrás da Garagem do Gallywix.', 19865),
(91556, 'ptBR', 'O melhor cozinheiro de Lança de Guerra é Gui Fogolhos, sem dúvida nenhuma. Ele que faz o rango da Taberna Lança Quebrada. \n\nNormalmente, ele fica a cargo da cozinha, no subsolo da taberna.', 'O melhor cozinheiro de Lança de Guerra é Gui Fogolhos, sem dúvida nenhuma. Ele que faz o rango da Taberna Lança Quebrada. \n\nNormalmente, ele fica a cargo da cozinha, no subsolo da taberna.', 19865),
(91557, 'ptBR', 'Os trolls estão cuidando da parte encantamentos, em Lança de Guerra. \n\nFale com Hane''ke, no Gabinete do Encantador, no distrito trólico. Ele poderá lhe ajudar.', 'Os trolls estão cuidando da parte encantamentos, em Lança de Guerra. \n\nFale com Hane''ke, no Gabinete do Encantador, no distrito trólico. Ele poderá lhe ajudar.', 19865),
(91559, 'ptBR', 'Tem instalações boas de engenharia na Garagem do Gallywix, no distrito goblínico. É o maior prédio da região.\n\nUma vez lá, fale com Han Saltafoguete se quiser treinar.', 'Tem instalações boas de engenharia na Garagem do Gallywix, no distrito goblínico. É o maior prédio da região.\n\nUma vez lá, fale com Han Saltafoguete se quiser treinar.', 19865),
(91560, 'ptBR', 'O pandaren Wei Benconserta está tratando os brutos. Ele deve ser a maior referência de primeiros socorros, aqui. \n\nEle fica no Quartel. É só seguir o som dos orcs treinando.', 'O pandaren Wei Benconserta está tratando os brutos. Ele deve ser a maior referência de primeiros socorros, aqui. \n\nEle fica no Quartel. É só seguir o som dos orcs treinando.', 19865),
(91561, 'ptBR', 'Brix Lançafoguete é o goblin com maior conhecimento de pesca por estas bandas. \n\nA ilhazinha dele fica na beira da costa, a norte do distrito goblínico.', 'Brix Lançafoguete é o goblin com maior conhecimento de pesca por estas bandas. \n\nA ilhazinha dele fica na beira da costa, a norte do distrito goblínico.', 19865),
(91562, 'ptBR', 'Se precisar da ajuda de um herborista, vá ao distrito dos mortos-vivos. \n\nAnthony Molequinho fica por lá, ao lado da cabana da alquimia. Ele entende do riscado.', 'Se precisar da ajuda de um herborista, vá ao distrito dos mortos-vivos. \n\nAnthony Molequinho fica por lá, ao lado da cabana da alquimia. Ele entende do riscado.', 19865),
(91563, 'ptBR', 'O melhor escriba de Lança de Guerra é Joro''man, que vive no distrito trólico. \n\nPelo seu próprio bem, espero que ele não escreva como fala.', 'O melhor escriba de Lança de Guerra é Joro''man, que vive no distrito trólico. \n\nPelo seu próprio bem, espero que ele não escreva como fala.', 19865),
(91564, 'ptBR', 'Um pequeno grupo de Elfos Sangrentos levantou acampamento em frente aos taurens. \n\nLá, você encontrará um joalheiro que atende por Alexandris Celeraço.', 'Um pequeno grupo de Elfos Sangrentos levantou acampamento em frente aos taurens. \n\nLá, você encontrará um joalheiro que atende por Alexandris Celeraço.', 19865),
(91565, 'ptBR', 'Os taurens que vieram conosco parecem ter maior domínio da couraria. \n\nFale com Burga Couro Forte, no distrito taureno, para obter treinamento.', 'Os taurens que vieram conosco parecem ter maior domínio da couraria. \n\nFale com Burga Couro Forte, no distrito taureno, para obter treinamento.', 19865),
(91566, 'ptBR', 'Se está em busca de um bom mineiro, procure Murg Rachapedra. Ele é tão bom que o promoveram de peão para encarregado das operações de mineração em Lança de Guerra. \n\nDa última vez que o vi, acho que ele estava trabalhando nas rochas a leste do distrito goblínico.', 'Se está em busca de um bom mineiro, procure Murg Rachapedra. Ele é tão bom que o promoveram de peão para encarregado das operações de mineração em Lança de Guerra. \n\nDa última vez que o vi, acho que ele estava trabalhando nas rochas a leste do distrito goblínico.', 19865),
(91567, 'ptBR', 'Os Filhos da Caça já esfolaram praticamente todas as feras de Draenor, então, se precisar de treinamento, fale com eles. \n\nKondal fica curtindo os pelegos, no distrito taureno.', 'Os Filhos da Caça já esfolaram praticamente todas as feras de Draenor, então, se precisar de treinamento, fale com eles. \n\nKondal fica curtindo os pelegos, no distrito taureno.', 19865),
(91568, 'ptBR', 'Particularmente, prefiro peles e couro, mas se você preferir trabalhar com tecidos macios, procure a elfa sangrenta Saesha Pratassang. \n\nEla está junto dos seus, em frente ao distrito taureno.', 'Particularmente, prefiro peles e couro, mas se você preferir trabalhar com tecidos macios, procure a elfa sangrenta Saesha Pratassang. \n\nEla está junto dos seus, em frente ao distrito taureno.', 19865),
(91569, 'ptBR', 'Os pássaros se instalaram perto da área de treinamento, na porção sul da cidade. \n\nDizem que estão procurando relíquias ancestrais e trouxeram itens fantásticos para trocar pelas tais relíquias.', 'Os pássaros se instalaram perto da área de treinamento, na porção sul da cidade. \n\nDizem que estão procurando relíquias ancestrais e trouxeram itens fantásticos para trocar pelas tais relíquias.', 19865),
(91570, 'ptBR', 'Tem um punhado de facções instaladas na Fortaleza Lança de Guerra. \n\nOuvi dizer que também fazem comércio, embora não negociem com qualquer um.', 'Tem um punhado de facções instaladas na Fortaleza Lança de Guerra. \n\nOuvi dizer que também fazem comércio, embora não negociem com qualquer um.', 19865),
(91571, 'ptBR', 'Bren Purossol, do distrito taureno, está trabalhando para manter os comerciantes abastecidos. \n\nFale com ele, caso precise fabricar alguma coisa.', 'Bren Purossol, do distrito taureno, está trabalhando para manter os comerciantes abastecidos. \n\nFale com ele, caso precise fabricar alguma coisa.', 19865),
(91572, 'ptBR', 'Em frente à Taberna Lança Quebrada, fica o comércio de Jasa. \n\nLá, você encontrará tudo de que um aventureiro precisa.', 'Em frente à Taberna Lança Quebrada, fica o comércio de Jasa. \n\nLá, você encontrará tudo de que um aventureiro precisa.', 19865),
(91573, 'ptBR', 'Ujia cuida dos bichos de quase todo mundo da cidade. Só tome cuidado com os raptores. \n\nEla fica em frente à caverna do distrito trólico.', 'Ujia cuida dos bichos de quase todo mundo da cidade. Só tome cuidado com os raptores. \n\nEla fica em frente à caverna do distrito trólico.', 19865),
(91574, 'ptBR', 'Deseja comprar alguma coisa? Gostaria de quê?', 'Deseja comprar alguma coisa? Gostaria de quê?', 19865),
(91579, 'ptBR', 'Garagem do Gallywix', 'Garagem do Gallywix', 19865),
(91580, 'ptBR', 'Orgrimmar', 'Orgrimmar', 19865),
(91581, 'ptBR', 'Penhasco do Trovão', 'Penhasco do Trovão', 19865),
(91582, 'ptBR', 'Cidade Baixa', 'Cidade Baixa', 19865),
(91588, 'ptBR', 'Teste 2 | Lançador: %s  | Alvo: $n', 'Teste 2 | Lançador: %s  | Alvo: $n', 19865),
(91590, 'ptBR', 'Levar Karrath Carpunhal a um Pilar de Fogo ativo desativará seu Impulso Berserker.', 'Levar Karrath Carpunhal a um Pilar de Fogo ativo desativará seu Impulso Berserker.', 19865),
(91603, 'ptBR', 'Adivinhos mortos: $1i (+$2i VP)', '', 19865);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(91604, 'ptBR', '|TInterface\\Icons\\ability_mage_livingbomb.blp:20|tHá uma |cFFFF0000|Hspell:176670|h[Bomba Viva]|h|r em você!', '|TInterface\\Icons\\ability_mage_livingbomb.blp:20|tHá uma |cFFFF0000|Hspell:176670|h[Bomba Viva]|h|r em você!', 19865),
(91605, 'ptBR', 'Adagas Mortais mortos: $1i (+$2i VP)', '', 19865),
(91606, 'ptBR', '|TInterface\\Icons\\spell_shaman_improvedfirenova.blp:20|tO Coração da Montanha está prestes a liberar um |cFFFF0000|Hspell:155209|h[Impacto]|h|r de calor intenso!', '|TInterface\\Icons\\spell_shaman_improvedfirenova.blp:20|tO Coração da Montanha está prestes a liberar um |cFFFF0000|Hspell:155209|h[Impacto]|h|r de calor intenso!', 19865),
(91609, 'ptBR', 'Não deixem que eles passem por nós!', '', 19865),
(91624, 'ptBR', 'Não deixe que o céu escuro engane você. Este é um bom dia.', '', 19865),
(91625, 'ptBR', 'Mostre ao Concílio das Sombras maculado por demônios a força da liberdade!', '', 19865),
(91626, 'ptBR', '', 'O último paradeiro conhecido de Greblin Chiadeira foi o Precipício Alquebrado. Talvez seja bom você pegar um voo para lá antes que seja tarde.', 19865),
(91635, 'ptBR', 'É chegada a hora, guerreiros. Vamos ver como cai esse gronn.', '', 19865),
(91636, 'ptBR', 'Eles são obstinados, então. É agora, guerreiros. Pela Horda!', '', 19865),
(91637, 'ptBR', 'Por favor! Misericórdia! Ah, a humilhação...', 'Por favor! Misericórdia! Ah, a humilhação...', 19865),
(91639, 'ptBR', 'Vou continuar escavando em busca de artefatos. Agradeço mais uma vez a sua ajuda.', '', 19865),
(91640, 'ptBR', '', 'Você ajudou muito, $n. Agora entendo por que todo mundo aqui segue você para todo lado. Você realmente está à altura da sua fama.', 19865),
(91641, 'ptBR', 'Nada mau pra um bando de nojentinhos! Vem encarar Krud quando cês quer morrer!', '', 19865),
(91643, 'ptBR', 'Onde eu coloco esta caixa?', '', 19865),
(91644, 'ptBR', 'Flores Esporíferas: $1i (+$2i VP)', '', 19865),
(91645, 'ptBR', 'E por que eu tenho que carregar todas as caixas?', '', 19865),
(91646, 'ptBR', 'Logo ali. Por que você fica perguntando? Você sempre leva as caixas daqui para lá!', '', 19865),
(91647, 'ptBR', 'Pare de peguntar e volte ao trabalho.', '', 19865),
(91648, 'ptBR', 'Uma Flor Esporífera está bloqueando sua estrada!', 'Uma Flor Esporífera está bloqueando sua estrada!', 19865),
(91702, 'ptBR', 'Acertou na mosca!', 'Acertou na mosca!', 19865),
(91703, 'ptBR', 'Nada mal mesmo!', 'Nada mal mesmo!', 19865),
(91704, 'ptBR', 'Bagulho bom!', 'Bagulho bom!', 19865),
(91705, 'ptBR', 'Ah, valeu a viagem!', 'Ah, valeu a viagem!', 19865),
(91706, 'ptBR', 'Ei, isso é cerveja de pandaren?!', 'Ei, isso é cerveja de pandaren?!', 19865),
(91707, 'ptBR', '|c00FFFF00|Hspell:178019|h[Evento: Colete Minério Potencializado]|h|r começará na Pedreira Candente em 3 minutos.', '', 19865),
(91708, 'ptBR', '|c00FFFF00|Hspell:178022|h[Evento: Corrida no Estádio]|h|r começará no Anfiteatro da Aniquilação em 3 minutos.', '', 19865),
(91709, 'ptBR', '|c00FFFF00|Hspell:178020|h[Evento: Espíritos Revividos]|h|r começará no Cemitério Cinzamalho em 3 minutos.', '', 19865),
(91710, 'ptBR', '|c00FFFF00|Hspell:178021|h[Evento: Fogueiras de Ogro]|h|r começará no Aclive do Brutamontes em 3 minutos.', '', 19865),
(91728, 'ptBR', 'Se Azuka conseguir recuperar o coração, não há como saber que tipo de maldade ela lançará sobre o nosso povo.', '', 19865),
(91729, 'ptBR', 'Se você vir aquele bruto inútil, você poderia avisar que estou procurando por ele?', '', 19865),
(91739, 'ptBR', 'Nosso povo está sendo mantido prisioneiro, $r. Por favor, nos ajude a libertá-los. Vá para as ruínas e liberte nossos irmãos dos opressores. Levá-los à batalha vai ajudar muito nossos esforços. Mas eles têm que chegar em segurança até os Áugures Sombrios!', '', 19865),
(91740, 'ptBR', 'Eu resgatei esses proscritos, leve-os a um local seguro.', 'Eu resgatei esses proscritos, leve-os a um local seguro.', 19865),
(91741, 'ptBR', 'Sim, muito bom! Você libertou mais proscritos dos nossos irmãos opressores. Rápido, temos que levá-los para um local seguro.', '', 19865),
(91742, 'ptBR', 'Libertar os proscritos, liderá-los em batalha, escoltá-los até os Áugures Sombrios, não deixar que morram. Entendido.', 'Libertar os proscritos, liderá-los em batalha, escoltá-los até os Áugures Sombrios, não deixar que morram. Entendido.', 19865),
(91757, 'ptBR', 'Socorro! Estou vivo!', 'Socorro! Estou viva!', 19865),
(91758, 'ptBR', 'Recuar!', '', 19865),
(91759, 'ptBR', '', 'Corra!', 19865),
(91760, 'ptBR', 'Recuar!', '', 19865),
(91761, 'ptBR', '', 'Corra!', 19865),
(91762, 'ptBR', 'Atacar!', '', 19865),
(91763, 'ptBR', '', 'À luta!', 19865),
(91764, 'ptBR', '', 'Por Durotar!', 19865),
(91765, 'ptBR', 'Matem todos!', '', 19865),
(91766, 'ptBR', 'Bom trabalho, Aliança! Se agora capturarmos a Torre Quedabrasa, nossas Sentinelas poderão eliminar os |c00FFFF00|Hspell:178362|h[Gladiadores da Lança de Guerra]|h|r. A vitória está perto!', 'Bom trabalho, Aliança! Se agora capturarmos a Torre Quedabrasa, nossas Sentinelas poderão eliminar os |c00FFFF00|Hspell:178362|h[Gladiadores da Lança de Guerra]|h|r. A vitória está perto!', 19865),
(91767, 'ptBR', 'Lok''tar ogar! Precisamos capturar esse último ponto, e nossos Caçadores de Cabeças podem eliminar aqueles |c00FFFF00|Hspell:178363|h[Gladiadores de Escudo Tonante]|h|r. Aí vamos poder invadir a Bastilha Escudo Tonante. Tremulâmina morre hoje!', 'Lok''tar ogar! Precisamos capturar esse último ponto, e nossos Caçadores de Cabeças podem eliminar aqueles |c00FFFF00|Hspell:178363|h[Gladiadores de Escudo Tonante]|h|r. Aí vamos poder invadir a Bastilha Escudo Tonante. Tremulâmina morre hoje!', 19865),
(91774, 'ptBR', '|TInterface\\Icons\\ability_warrior_rampage.blp:20|t %s começa a lançar |cFFFF0000|Hspell:164426|h[Provocação Imprudente]|h|r!', '', 19865),
(91788, 'ptBR', 'Essa derrota nos envergonha. Recuar!', '', 19865),
(91789, 'ptBR', '', 'A prudência é a parte mais elevada da coragem. Agora fuja!', 19865),
(91795, 'ptBR', '', '|TInterface\\Icons\\ability_deathwing_bloodcorruption_earth.blp:20|t%s começa a lançar |cFFFF0000|Hspell:163689|h[Esfera Sanguínea]|h|r!', 19865),
(91802, 'ptBR', '', 'Eu perdi dois filhos hoje. Quero que essa guerra termine antes que mais irmãos dos clãs sucumbam à Horda de Ferro.$b$bO meu caminho é o do curador. Minha dádiva é ajudar os feridos na vida ou na batalha.$b$bSe quiser minha ajuda, eu emprestarei meus talentos de cura às suas forças.', 19865),
(91803, 'ptBR', 'Grande Mãe Geyah, eu escolho você!', 'Grande Mãe Geyah, eu escolho você!', 19865),
(91804, 'ptBR', 'Você me superou no campo de batalha mais de uma vez, e isso não é pouca coisa.$b$bMas eu posso fazer muita coisa que você nem imagina. Os espíritos decidiram me conceder seus poderes mais frios e severos. Os elementos são meus aliados e serão o fim dos inimigos.$b$bSeria uma honra servir ao seu lado.', '', 19865),
(91805, 'ptBR', 'Kal''gor, o Honorável, eu escolho você!', 'Kal''gor, o Honorável, eu escolho você!', 19865),
(91806, 'ptBR', 'Lokra, eu escolho você', 'Lokra, eu escolho você', 19865),
(91807, 'ptBR', '', 'Você me viu na pior, $n. Meu marido tirado de mim... meu lobo assassinado por Fenris, o covarde. Eu conheço bem o preço da guerra.$B$BTemos que dar cabo da Horda de Ferro. Conceda-me um lugar ao seu lado no campo de batalha e eu vou providenciar para que os elementos façam chover vingança nos seus inimigos.$b$bBasta aceitar o meu machado e eu irei.', 19865),
(91822, 'ptBR', 'Siga Maraad', '', 19865),
(91841, 'ptBR', '%s respira fundo.', '%s respira fundo.', 19865),
(91842, 'ptBR', 'Comandante, Morthis Sussurasa, dos Druidas do Gadanho, estava procurando você. Ele está embaixo da grande árvore ao sul.', '', 19865),
(91850, 'ptBR', 'Zug! Você vai ao Grande Salão?', 'Zug! Você vai ao Grande Salão?', 19865),
(91851, 'ptBR', 'Zug zug!', 'Zug zug!', 19865),
(91853, 'ptBR', 'Pela Horda!', '', 19865),
(91854, 'ptBR', 'Sangue e Honra!', '', 19865),
(91855, 'ptBR', 'Expulsem-nos! Não se contenham!', '', 19865),
(91856, 'ptBR', 'Pela Aliança!', '', 19865),
(91857, 'ptBR', 'Não fraquejem!', '', 19865),
(91858, 'ptBR', 'Continuem atacando! Avancem!', '', 19865),
(91860, 'ptBR', 'A Aliança atacou a Ferraria!', '', 19865),
(91861, 'ptBR', 'A Horda atacou a Ferraria!', '', 19865),
(91862, 'ptBR', 'A Aliança tomou a Ferraria!', '', 19865),
(91863, 'ptBR', 'A Horda tomou a Ferraria!', '', 19865),
(91864, 'ptBR', 'A Horda defendeu a Ferraria!', '', 19865),
(91865, 'ptBR', 'A Aliança defendeu a Ferraria!', '', 19865),
(91866, 'ptBR', 'A Aliança atacou a Fazenda!', '', 19865),
(91867, 'ptBR', 'A Horda atacou a Fazenda!', '', 19865),
(91868, 'ptBR', 'A Aliança tomou a Fazenda!', '', 19865),
(91869, 'ptBR', 'A Horda tomou a Fazenda!', '', 19865),
(91870, 'ptBR', 'A Aliança defendeu a Fazenda!', '', 19865),
(91871, 'ptBR', 'A Horda defendeu a Fazenda!', '', 19865),
(91872, 'ptBR', 'A Aliança atacou a mina!', '', 19865),
(91873, 'ptBR', 'A Horda atacou a mina!', '', 19865),
(91874, 'ptBR', 'A Aliança tomou a mina!', '', 19865),
(91875, 'ptBR', 'A Horda tomou a mina!', '', 19865),
(91876, 'ptBR', 'A Aliança defendeu a mina!', '', 19865),
(91877, 'ptBR', 'A Horda defendeu a mina!', '', 19865),
(91878, 'ptBR', 'A Aliança atacou a Serraria!', '', 19865),
(91879, 'ptBR', 'A Horda atacou a Serraria!', '', 19865),
(91880, 'ptBR', 'A Aliança tomou a Serraria!', '', 19865),
(91881, 'ptBR', 'A Horda tomou a Serraria!', '', 19865),
(91882, 'ptBR', 'A Aliança defendeu a Serraria!', '', 19865),
(91883, 'ptBR', 'A Horda defendeu a Serraria!', '', 19865),
(91884, 'ptBR', 'A Aliança atacou os Estábulos!', '', 19865),
(91885, 'ptBR', 'A Horda atacou os Estábulos!', '', 19865),
(91886, 'ptBR', 'A Horda defendeu os Estábulos!', '', 19865),
(91887, 'ptBR', 'A Aliança defendeu os Estábulos!', '', 19865),
(91888, 'ptBR', 'A Aliança tomou os Estábulos!', '', 19865),
(91889, 'ptBR', 'A Horda tomou os Estábulos!', '', 19865),
(91893, 'ptBR', 'Ufa, que bom que achei você a tempo! Sei que você está ansioso, $gherói:heroina;, mas é melhor ficarmos mais fortes antes de encarar os perigos da Selva de Tanaan.', 'Ufa, que bom que achei você a tempo! Sei que você está ansioso, $gherói:heroina;, mas é melhor ficarmos mais fortes antes de encarar os perigos da Selva de Tanaan.', 19865),
(91894, 'ptBR', 'Um espião da Aliança se infiltrou em meio ao caos!', 'Um espião da Aliança se infiltrou em meio ao caos!', 19865),
(91895, 'ptBR', 'Que possamos entrar na batalha!', '', 19865),
(91896, 'ptBR', 'Pelo Lobo do Gelo!', '', 19865),
(91897, 'ptBR', 'Pel$Go:a; comandante $p!', '', 19865),
(91898, 'ptBR', 'Um... fim... glorioso.', '', 19865),
(91899, 'ptBR', 'Que os espíritos tenham piedade de você.', '', 19865),
(91900, 'ptBR', 'Os espíritos vão despedaçar vocês!', '', 19865),
(91901, 'ptBR', 'Vocês fracassaram!', '', 19865),
(91902, 'ptBR', 'Lok-narosh.', '', 19865),
(91903, 'ptBR', 'Que os espíritos tragam a vitória.', '', 19865),
(91904, 'ptBR', '', 'Você ouviu falar do meu filho, Durotan?', 19865),
(91905, 'ptBR', '', 'Será que essa guerra não vai acabar nunca?', 19865),
(91906, 'ptBR', '', 'Como está meu filho, Durotan?', 19865),
(91907, 'ptBR', '', 'Não precisava ser assim.', 19865),
(91908, 'ptBR', '', 'Essa gente está protegida.', 19865),
(91909, 'ptBR', '', 'Você não vai mais prejudicar nosso povo.', 19865),
(91910, 'ptBR', '', 'Lamento que tenha acabado assim.', 19865),
(91911, 'ptBR', '', 'Garad... estou a caminho...', 19865),
(91912, 'ptBR', '', 'Você não vai ferir nosso povo.', 19865),
(91917, 'ptBR', 'A Horda tomou o controle das Ruínas Draeneicas!', '', 19865),
(91918, 'ptBR', '$n defendeu as Ruínas Draeneicas!', '', 19865),
(91919, 'ptBR', '$n defendeu a Torre dos Elfos Sangrentos!', '', 19865),
